INSERT INTO `ai_prep_question_bank` (`category`, `subject`, `concept`, `difficulty_level`, `scope`, `time_limit_seconds`, `question_text`, `ground_truth`, `is_active`)
VALUES
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'How do you design ML systems to ensure they generalize well to unseen data using techniques like data splitting and validation?', '{"key_points": [{"id": "KP1", "description": "Validation Design & Data Partitioning Protocols: Establishes strict separation between training, validation, and untouched test holdouts.", "required": true, "acceptable_evidence": ["Technical keywords: cross-validation, stratified k-fold, data partitioning, train.", "Explains the three-way split (train/validation/test) and explicitly reserves the test set strictly for final generalization assessment without tuning.", "Applies stratified k-fold cross-validation for imbalanced classification tasks to maintain target distribution parity across folds."]}, {"id": "KP2", "description": "Enforce fit-transform lifecycle boundaries where feature scalers and imputers are fitted only on train folds and transformed on validation/test.", "required": true, "acceptable_evidence": ["Technical keywords: scikit-learn Pipeline, fit_transform isolation, cross-validation data leakage, StandardScaler, SimpleImputer, train-test hygiene.", "Enforces fit-transform lifecycle boundaries where feature scalers and imputers are fitted only on train folds and transformed on validation/test.", "Uses scikit-learn Pipeline (Pipeline(steps=[(''imputer'', SimpleImputer()), (''scaler'', StandardScaler()), (''model'', Ridge())])) inside cross_val_score to prevent data leakage."]}, {"id": "KP3", "description": "Temporal & Grouped Leakage Prevention: Preserves temporal causality and entity isolation during data splitting.", "required": true, "acceptable_evidence": ["Technical keywords: GroupKFold, walk-forward validation, target leakage, look-ahead bias.", "Uses rolling-window or time-series split (walk-forward validation) for temporal data to avoid look-ahead bias and future leakage.", "Employs GroupKFold when grouping by user, customer, or patient ID to ensure no individual entity appears in both train and evaluation folds.", "Identifies and mitigates indirect target leakage caused by data generation pipelines or post-event feature artifacts."]}, {"id": "KP4", "description": "Error Analysis & Out-of-Distribution Monitoring: Diagnoses variance/bias trade-offs and plans post-deployment distribution tracking.", "required": false, "acceptable_evidence": ["Technical keywords: overfitting, underfitting, PSI, Wasserstein distance.", "Conducts slice-based error analysis across user demographic or volume cohorts to detect localized overfitting.", "Compares train vs validation loss curves to diagnose high variance (overfitting) versus high bias (underfitting).", "Defines production distribution drift monitoring (PSI, KS-test, Wasserstein distance) as the post-launch extension of validation."]}], "critical_failures": ["Recommends tuning hyperparameters repeatedly against the final test set and reporting that score as unbiased.", "Fails to address data leakage when handling time-series or multi-record user data."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'How do you design a system to proactively assist users and reduce ticket creation using AI?', '{"key_points": [{"id": "KP1", "description": "Proactive Telemetry Ingestion & Intent Detection: Identifies user struggle signals and matches real-time UI/error events to known resolution workflows.", "required": true, "acceptable_evidence": ["Technical keywords: UI, AI, proactive telemetry, side telemetry.", "Monitors client-side telemetry, repeated failed actions, or error logs to trigger proactive AI prompts before ticket submission.", "Classifies user intent using real-time embedding similarity or lightweight classifier against historical support ticket clusters."]}, {"id": "KP2", "description": "Interprets draft ticket inputs in real time to suggest auto-resolutions or self-service documentation inline.", "required": true, "acceptable_evidence": ["Technical keywords: real-time deflection, debounce keystrokes, hybrid retrieval, Milvus vector search, knowledge base match, proactive resolution.", "Interprets draft ticket inputs in real time to suggest auto-resolutions or self-service documentation inline.", "Debounces user input on the frontend and queries a vector store using hybrid BM25 + dense search to surface top-3 matching KB articles before submission."]}, {"id": "KP3", "description": "Contextual Grounding & Autonomous Resolution Workflows: Resolves common issues via targeted retrieval and governed tool execution.", "required": true, "acceptable_evidence": ["Technical keywords: tool calling, contextual grounding, targeted retrieval, resending verification emails.", "Retrieves relevant knowledge base articles and recent system status updates using hybrid semantic search.", "Executes pre-authorized automated recovery actions (e.g., resending verification emails, resetting sync sessions) via governed tool calling.", "Personalizes recommendations using recent account history and permissions without asking repetitive questions."]}, {"id": "KP4", "description": "Graceful Escalation & Deflection Impact Measurement: Routes complex failures to human agents and measures resolution efficacy.", "required": false, "acceptable_evidence": ["Technical keywords: CSAT, graceful, impact, AI.", "Establishes clear confidence thresholds below which the AI seamlessly escalates to a human agent with pre-populated case summaries.", "Tracks deflection metrics (ticket deflection rate, self-service resolution percentage, CSAT) versus human escalation volumes.", "Gathers user feedback on automated suggestions to continuously identify documentation gaps."]}], "critical_failures": ["Proposes an ungrounded chatbot that traps users in repetitive loops without escalation pathways to human support.", "Allows the AI assistant to perform destructive or high-risk account modifications without authorization or schema validation."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'HARD', 'BROAD', 210, 'How do you design a system to track and utilize conversation history and user behavior for improved personalization?', '{"key_points": [{"id": "KP1", "description": "Tiered Memory Architecture & Storage Partitioning: Decouples short-term session state from durable long-term semantic memory.", "required": true, "acceptable_evidence": ["Technical keywords: semantic memory, Redis, tiered memory, session state.", "Separates ephemeral conversation buffers (Redis, DynamoDB session store) from durable user profiles (relational/vector stores).", "Extracts factual user preferences, recurring entities, and constraints asynchronously into persistent knowledge graphs or vector indices."]}, {"id": "KP2", "description": "Maintain user session checkpointing to restore context across app restarts or multi-device transitions.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph checkpointer, thread_id, Redis session store, state persistence, cross-device sync, conversation history.", "Maintains user session checkpointing to restore context across app restarts or multi-device transitions.", "Persists conversation state in PostgreSQL or Redis using LangGraph checkpointer threads (thread_id=user_session_id), enabling seamless context resumption across client reloads."]}, {"id": "KP3", "description": "Context Engineering & Token Optimization Pipeline: Dynamically selects, ranks, and compresses conversation history to respect model context windows.", "required": true, "acceptable_evidence": ["Technical keywords: XML, context, engineering, token.", "Implements rolling window summarization and semantic message pruning to keep prompt sizes bounded.", "Utilizes hybrid retrieval (recency weighting + semantic similarity) to inject only relevant historical turns into active prompts.", "Formats memory injection with explicit XML/Markdown boundaries separating system instructions, profile facts, and conversation history."]}, {"id": "KP4", "description": "Memory Hygiene, Decay & Privacy Isolation: Manages contradictory facts, temporal memory decay, and strict user privacy boundaries.", "required": false, "acceptable_evidence": ["Technical keywords: temporal memory, tenant isolation, user memory.", "Implements update and conflict resolution logic when new user preferences supersede obsolete past statements.", "Applies temporal decay scoring so ancient behavioral signals have less weight than recent explicit instructions.", "Enforces hard multi-tenant isolation ensuring user memory cannot leak across user or organizational boundaries."]}], "critical_failures": ["Appends raw, unbounded conversation history directly into prompts without budgeting, causing prompt overflow.", "Fails to enforce user/tenant isolation, exposing user conversation history or preferences across account boundaries."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Infrastructure as Code & Security', 'MEDIUM', 'BROAD', 150, 'How do you design authentication and authorization mechanisms for systems accessed from multiple platforms?', '{"key_points": [{"id": "KP1", "description": "Standardized Token-Based Identity Architecture: Employs industry-standard OAuth 2.0 / OpenID Connect flows with secure token lifecycle management.", "required": true, "acceptable_evidence": ["Technical keywords: OAuth 2.0, OpenID Connect, PKCE, standardized token.", "Implements OAuth 2.0 Authorization Code flow with PKCE (Proof Key for Code Exchange) across mobile, desktop, and single-page apps.", "Issues short-lived access tokens (JWTs) paired with securely rotated refresh tokens stored in platform-appropriate secure storage."]}, {"id": "KP2", "description": "Centralizes identity verification through an Identity Provider (IdP) supporting SSO, social logins, and MFA.", "required": true, "acceptable_evidence": ["Technical keywords: OAuth2, OpenID Connect, IdP, Auth0, Keycloak, JWT access tokens, PKCE flow, MFA.", "Centralizes identity verification through an Identity Provider (IdP) supporting SSO, social logins, and MFA.", "Configures OAuth2 / OpenID Connect (OIDC) with Auth0 or Keycloak, issuing signed JWT access and refresh tokens to mobile, web, and desktop clients."]}, {"id": "KP3", "description": "Centralized Authorization & Policy Enforcement Boundary: Enforces fine-grained permissions at server gateways rather than trusting client state.", "required": true, "acceptable_evidence": ["Technical keywords: RBAC, ABAC, API, client state.", "Enforces RBAC (Role-Based Access Control) or ABAC (Attribute-Based Access Control) at API gateways and service boundaries.", "Validates cryptographic token signatures, issuer, expiry, and scopes on every incoming backend request.", "Never relies on client-side permission checks for security-critical actions, treating all mobile/web clients as untrusted."]}, {"id": "KP4", "description": "Platform-Specific Credential Hardening & Revocation: Secures token persistence and handles session invalidation across clients.", "required": false, "acceptable_evidence": ["Technical keywords: iOS Keychain, Android Keystore, Redis, EncryptedSharedPreferences.", "Leverages native secure enclaves (iOS Keychain, Android Keystore, EncryptedSharedPreferences) for mobile token storage, and HttpOnly Secure cookies for web.", "Implements global session revocation and token blacklisting using Redis distributed caches for compromised credentials.", "Instruments security audit logging and anomaly detection for impossible travel or concurrent multi-device logins."]}], "critical_failures": ["Stores sensitive JWT tokens in unencrypted localStorage on web or plain text files on mobile apps.", "Delegates authorization decisions to client applications without server-side validation."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How do you determine which half of a rotated sorted array is sorted during binary search, and how does that guide pointer movement?', '{"key_points": [{"id": "KP1", "description": "Sorted Half Identification Invariant: Compares midpoint value against boundary endpoints to deduce sorted monotonicity.", "required": true, "acceptable_evidence": ["Technical keywords: or nums[right], sorted, identification, invariant.", "Compares nums[mid] with nums[left] (or nums[right]): if nums[left] <= nums[mid], the left half [left, mid] is strictly sorted.", "Conversely, if nums[mid] < nums[right], the right half [mid, right] is guaranteed to be sorted."]}, {"id": "KP2", "description": "Explain the invariant that in any single rotation, at least one half of the array divided by the midpoint is always continuously sorted.", "required": true, "acceptable_evidence": ["Technical keywords: rotated sorted array, binary search invariant, nums[left] <= nums[mid], O(log N) search, boundary pointers.", "Explains the invariant that in any single rotation, at least one half of the array divided by the midpoint is always continuously sorted.", "Compares nums[left] with nums[mid]: if nums[left] <= nums[mid], the left half is monotonically sorted; otherwise the right half is sorted, guiding where target lies."]}, {"id": "KP3", "description": "Target Range Check & Pointer Movement: Narrows search interval by checking if the target lies within the identified sorted boundary.", "required": true, "acceptable_evidence": ["Technical keywords: narrows search, right - left, target, range.", "If left half is sorted, checks if nums[left] <= target < nums[mid]: if true, sets right = mid - 1; otherwise sets left = mid + 1.", "If right half is sorted, checks if nums[mid] < target <= nums[right]: if true, sets left = mid + 1; otherwise sets right = mid - 1.", "Handles convergence correctly with mid = left + (right - left) // 2 avoiding integer overflow."]}, {"id": "KP4", "description": "Edge Case Analysis & Complexity Guarantees: Explains behavior on duplicates, single elements, and asymptotic complexity.", "required": false, "acceptable_evidence": ["Technical keywords: time complexity, space complexity, O(1), O(log n).", "States time complexity is O(log n) when elements are distinct and space complexity is O(1).", "Notes that duplicate elements (nums[left] == nums[mid] == nums[right]) force linear degradation to O(n) as boundaries must be incremented/decremented.", "Handles single-element arrays and already-sorted (unrotated) arrays without branching errors."]}], "critical_failures": ["Fails to verify if target lies within the sorted half''s boundaries, updating pointers arbitrarily.", "Incorrectly claims binary search cannot achieve O(log n) on rotated sorted arrays."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How do you ensure that the models and systems you build comply with organizational standards, including security, bias, and governance?', '{"key_points": [{"id": "KP1", "description": "Multi-Stage Governance Lifecycle & Approval Gates: Integrates policy validation, model registries, and stage-gate approval workflows.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, stage governance.", "Implements versioned model artifact registries (e.g., MLflow, Model Cards) documenting training data provenance, intended use, and limitations.", "Embeds automated CI/CD policy gates requiring security, fairness, and performance benchmark sign-offs prior to production promotion."]}, {"id": "KP2", "description": "Define clear ownership boundaries, RACI matrices, and audit logging for all deployment and retraining events.", "required": true, "acceptable_evidence": ["Technical keywords: RACI matrix, AI governance framework, MLflow audit log, model card, compliance registry.", "Defines clear ownership boundaries, RACI matrices, and audit logging for all deployment and retraining events.", "Defines a formal RACI governance framework where data science owns model cards, InfoSec signs off on privacy scans, and deployment events are logged in MLflow."]}, {"id": "KP3", "description": "Fairness, Bias Auditing & Disparate Impact Evaluation: Measures model behavior across protected subgroups and implements mitigation strategies.", "required": true, "acceptable_evidence": ["Technical keywords: fairness metrics, demographic parity, equalized odds, disparate impact ratio.", "Calculates fairness metrics (e.g., demographic parity, equalized odds, disparate impact ratio) across demographic or business slices.", "Mitigates dataset bias through balanced re-sampling, synthetic data augmentation, or adversarial debiasing techniques.", "Maintains counterfactual evaluation test suites to verify outputs do not shift inappropriately when protected attributes change."]}, {"id": "KP4", "description": "Security Hardening, Compliance Auditing & Lineage: Secures model inference against adversarial attacks and complies with privacy regulations.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, differential privacy, GDPR, HIPAA.", "Conducts red-teaming and prompt-injection penetration testing before release to safeguard against model jailbreaks.", "Applies PII anonymization, data masking, and differential privacy to meet regulatory standards (GDPR, HIPAA, SOC 2).", "Maintains comprehensive audit trails capturing inputs, model versions, tool calls, and human-in-the-loop overrides."]}], "critical_failures": ["Relies solely on overall aggregate model accuracy without auditing subgroup performance or bias.", "Deploys models to production without automated guardrails or compliance approval verification."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you ensure that your implementation adheres to a given requirements document?', '{"key_points": [{"id": "KP1", "description": "Requirements Decomposition & Acceptance Criteria Formalization: Deconstructs specifications into measurable, testable functional and non-functional requirements.", "required": true, "acceptable_evidence": ["Technical keywords: Requirements Traceability Matrix, RTM, Given-When-Then, PRD.", "Translates ambiguous PRD narratives into precise Given-When-Then acceptance criteria and verifiable behavioral contracts.", "Distinguishes functional capabilities from non-functional constraints (latency budgets, throughput, uptime, security standards).", "Maintains a Requirements Traceability Matrix (RTM) mapping business specifications to technical tickets and test cases."]}, {"id": "KP2", "description": "Automated Verification & Test-Driven Validation: Builds tiered automated test suites covering positive, boundary, and edge conditions.", "required": true, "acceptable_evidence": ["Technical keywords: CI, driven validation, input schemas.", "Implements unit, integration, and contract tests directly reflecting specified input schemas and error response codes.", "Automates regression suites in CI pipelines to prevent functional divergence during iterative development.", "Conducts end-to-end integration tests simulating real user journeys against staging environments."]}, {"id": "KP3", "description": "Stakeholder Reviews & Verification Sign-Off: Facilitates sprint demos, design reviews, and formal user acceptance testing (UAT).", "required": false, "acceptable_evidence": ["Technical keywords: User Acceptance Testing, UAT, QA, conducts architecture.", "Conducts architecture design reviews (ADRs) and code reviews against the requirements document prior to merging.", "Collaborates with Product Managers and QA engineers during formal UAT to validate edge-case handling.", "Documents delta rationale and obtains formal scope sign-off when technical realities necessitate deviations from the initial spec."]}], "critical_failures": ["Implements software without verifiable acceptance criteria or automated test coverage.", "Unilaterally alters core business requirements without documenting technical rationale or consulting stakeholders."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you evaluate opportunities in early-stage or high-growth companies, and what aspects of such environments appeal to you?', '{"key_points": [{"id": "KP1", "description": "Commercial & Technical Due Diligence: Analyzes product-market fit, founding team pedigree, market size, and business runway.", "required": true, "acceptable_evidence": ["Technical keywords: product-market fit, ARR, 18-24+ months.", "Evaluates product-market fit indicators (retention curves, customer growth, ARR velocity, net promoter score).", "Assesses executive leadership experience, technical vision, investor capitalization, and financial runway (18-24+ months)."]}, {"id": "KP2", "description": "Analyze competitive moat, technological defensibility, and regulatory tailwinds in the target industry.", "required": true, "acceptable_evidence": ["Technical keywords: technological defensibility, proprietary data flywheel, competitive moat, network effects, venture growth.", "Analyzes competitive moat, technological defensibility, and regulatory tailwinds in the target industry.", "Analyzes whether prospective startups possess a defensible proprietary data flywheel, deep vertical workflow lock-in, or proprietary domain fine-tuning."]}, {"id": "KP3", "description": "Thriving in Ambiguity & Ownership Alignment: Demonstrates enthusiasm for rapid iteration, end-to-end agency, and wearing multiple hats.", "required": true, "acceptable_evidence": ["Technical keywords: DevOps, customer support, documentation.", "Articulates a clear preference for broad scope of impact, flat hierarchies, and high agency over rigid corporate bureaucracy.", "Cites past experience navigating shifting priorities, rapid prototyping, and delivering MVPs under tight constraints.", "Demonstrates willingness to tackle unglamorous foundational work (DevOps, customer support, documentation) when necessary."]}, {"id": "KP4", "description": "Calculated Risk Assessment & Career Growth Strategy: Balances equity upside against career development and team culture.", "required": false, "acceptable_evidence": ["Technical keywords: calculated, career, growth, strategy.", "Evaluates equity compensation packages thoughtfully (strike price, 409A valuation, liquidation preferences, dilution risks).", "Assesses team mentorship, engineering rigor, and opportunities for accelerated technical leadership.", "Shows self-awareness regarding personal risk tolerance and resilience through startup pivot cycles."]}], "critical_failures": ["Shows intolerance for changing priorities, ambiguity, or broad cross-functional responsibilities.", "Evaluates startups purely on superficial hype without inquiring about product-market fit or runway."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you evaluate opportunities that require immediate relocation versus delayed relocation?', '{"key_points": [{"id": "KP1", "description": "Pragmatic Readiness & Feasibility Analysis: Evaluates logistics, housing, cost-of-living adjustments, and family commitments.", "required": true, "acceptable_evidence": ["Technical keywords: lease agreements, schooling, transit, moving lead times.", "Analyzes cost of living differentials, tax implications, and compensation parity between locations.", "Evaluates personal and family logistics (lease agreements, schooling, transit, moving lead times)."]}, {"id": "KP2", "description": "Assesses employer relocation packages and corporate support infrastructure.", "required": true, "acceptable_evidence": ["Technical keywords: corporate relocation package, temporary housing stipend, remote-to-onsite transition, tax residency.", "Assesses employer relocation packages and corporate support infrastructure.", "Assesses corporate relocation benefits (lump sum stipend, temporary housing, travel reimbursement) and aligns start dates with lease and family logistics."]}, {"id": "KP3", "description": "Operational Continuity & Onboarding Effectiveness: Ensures productivity is maintained whether relocating immediately or working remotely initially.", "required": true, "acceptable_evidence": ["Technical keywords: integration trade-offs, continuity, onboarding, effectiveness.", "Proposes clear remote onboarding milestones if relocation is phased or delayed to ensure immediate team impact.", "Communicates realistic timelines to hiring managers and recruiters rather than making unfeasible commitments.", "Demonstrates understanding of in-person collaboration value versus temporary remote integration trade-offs."]}, {"id": "KP4", "description": "Professional Transparency & Contingency Planning: Communicates openly about dependencies, legal requirements, and transition milestones.", "required": false, "acceptable_evidence": ["Technical keywords: regional compliance, professional, contingency, planning.", "Identifies any visa, legal, or regional compliance constraints impacting physical start dates early.", "Builds contingency buffers for moving complications, lease transitions, or travel delays.", "Maintains proactive communication with the hiring manager throughout the transition window."]}], "critical_failures": ["Makes unrealistic relocation promises that fail during onboarding, disrupting project staffing.", "Fails to account for basic cost-of-living or relocation logistical realities."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you evaluate your system before production, including the creation and use of a golden dataset?', '{"key_points": [{"id": "KP1", "description": "Golden Dataset Construction & Contamination Control: Curates a versioned, representative benchmark dataset reflecting production distributions and edge cases.", "required": true, "acceptable_evidence": ["Technical keywords: data leakage, golden dataset, benchmark contamination, DVC.", "Samples diverse user queries, long-tail edge cases, and adversarial prompts annotated with expert ground truth.", "Ensures strict isolation between training/tuning data and the golden dataset to prevent data leakage and benchmark contamination.", "Versions evaluation datasets alongside code releases (using tools like DVC or Git LFS) to ensure benchmark reproducibility."]}, {"id": "KP2", "description": "Comprehensive Multi-Metric Benchmark Suite: Evaluates accuracy, relevance, safety, latency, and cost across standard metrics.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, context relevance, groundedness, LLM-as-a-judge.", "Applies task-specific evaluation metrics (e.g., RAG triad: context relevance, groundedness, answer relevance; or accuracy/F1/BLEU).", "Benchmarks non-functional dimensions including p95 latency, token throughput, and per-query operational costs.", "Calibrates automated LLM-as-a-judge scorers against human expert annotations to verify evaluation reliability."]}, {"id": "KP3", "description": "Automated Regression Gates & Canary Validation: Embeds golden dataset evaluations into CI/CD release pipelines and canary deployments.", "required": false, "acceptable_evidence": ["Technical keywords: shadow traffic, CI/CD, CI, CD.", "Establishes automated release gating thresholds where test runs failing golden regression suites block deployment.", "Executes shadow traffic or canary rollouts comparing golden evaluation scores against live staging traffic.", "Maintains failure analysis dashboards to inspect regressions on specific categories or customer segments."]}], "critical_failures": ["Evaluates systems using only ad-hoc subjective testing without a structured, versioned golden dataset.", "Leaks golden dataset examples into prompt few-shot examples or model fine-tuning sets."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you handle ambiguous problem spaces when building AI/ML platforms?', '{"key_points": [{"id": "KP1", "description": "Problem Decomposition & Measurable Proxy Framing: Converts ill-defined business objectives into bounded mathematical and engineering objectives.", "required": true, "acceptable_evidence": ["Technical keywords: proxy metrics, problem, decomposition, measurable.", "Interviews domain stakeholders to translate vague desires into clear inputs, expected outputs, and constraints.", "Establishes measurable proxy metrics and business KPIs that correlate with end-user satisfaction.", "Defines explicit non-goals to scope the initial platform boundary and avoid premature over-engineering."]}, {"id": "KP2", "description": "Hypothesis-Driven Prototyping & Rapid Baselines: Builds lightweight rule-based or heuristic baselines before deploying complex models.", "required": true, "acceptable_evidence": ["Technical keywords: feedback loops, hypothesis, driven, prototyping.", "Deploys simple deterministic heuristics or off-the-shelf foundation models to establish performance lower bounds quickly.", "Conducts rapid proof-of-concept experiments on small representative datasets to validate technical feasibility.", "Iterates rapidly with fast feedback loops from early internal pilot users to uncover hidden assumptions."]}, {"id": "KP3", "description": "Modular & Extensible Platform Abstraction: Designs swappable components allowing models and tools to evolve without rewriting infrastructure.", "required": false, "acceptable_evidence": ["Technical keywords: capturing trade-offs, data ingestion, ADRs.", "Architects decoupled layers (data ingestion, orchestration, model inference, evaluation) with standardized interfaces.", "Documents architectural decision records (ADRs) capturing trade-offs, uncertainties, and pivot triggers.", "Instruments comprehensive telemetry from day one to observe real-world usage patterns and guide prioritization."]}], "critical_failures": ["Attempts to build a massive, rigid enterprise platform without first clarifying user needs or building an MVP.", "Fails to establish baseline metrics, making it impossible to assess whether complex models add value."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How do you handle conversational context and memory in AI systems?', '{"key_points": [{"id": "KP1", "description": "Session State Storage & Tiered Memory Design: Distinguishes fast conversational session caches from persistent semantic knowledge.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, Redis, session_id, session state.", "Utilizes low-latency key-value stores (e.g., Redis) for active conversational session state keyed by session_id.", "Maintains durable persistent storage for user profile facts, preferences, and long-term interaction history.", "Separates raw message logs from structured state representations (e.g., LangGraph state schemas)."]}, {"id": "KP2", "description": "Context Compression & Window Budget Management: Employs sliding windows, message pruning, and recursive summarization.", "required": true, "acceptable_evidence": ["Technical keywords: hard token, sufficient tokens, context, window.", "Implements sliding-window buffers keeping the most recent k turns while summarizing older interactions.", "Enforces hard token budget limits reserving sufficient tokens for dynamic retrieval, tool outputs, and model generation.", "Uses semantic search over past conversation vectors to inject only query-relevant historical turns into current prompts."]}, {"id": "KP3", "description": "Context Hygiene, Disambiguation & Safety Filtering: Prevents conflicting memories and sanitizes historical context against prompt injection.", "required": false, "acceptable_evidence": ["Technical keywords: prompt injection, vector retrieval, conversational memory.", "Resolves co-references and pronoun ambiguities before vector retrieval using lightweight rewrite steps.", "Sanitizes retrieved historical context to prevent malicious instructions injected in earlier turns from persisting.", "Allows users to inspect, edit, or reset conversational memory in compliance with data privacy mandates."]}], "critical_failures": ["Treats conversational memory as an unbounded message array passed directly into LLM prompts without compression.", "Fails to isolate user sessions, leading to cross-talk or data leakage between different users."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you handle feedback after an interview, especially regarding communication and proactiveness?', '{"key_points": [{"id": "KP1", "description": "Growth Mindset & Non-Defensive Feedback Reception: Receives constructive critique with emotional maturity, curiosity, and professional composure.", "required": true, "acceptable_evidence": ["Technical keywords: growth, mindset, defensive, feedback.", "Welcomes critical feedback without becoming defensive, argumentative, or dismissive.", "Expresses genuine appreciation for the interviewer or recruiter''s time and actionable insights.", "Asks clarifying questions to understand specific moments where communication fell short or proactiveness was lacking."]}, {"id": "KP2", "description": "Root Cause Self-Reflection & Behavioral Analysis: Retrospectively analyzes the interview interaction to diagnose specific communication gaps.", "required": true, "acceptable_evidence": ["Technical keywords: cause, reflection, behavioral, retrospectively.", "Conducts a structured personal retrospective on interview pacing, active listening, and technical articulation.", "Identifies whether failures stemmed from excessive technical rambling, insufficient clarifying questions, or passive waiting.", "Distinguishes core behavioral weaknesses from situational nerves or mismatched expectations."]}, {"id": "KP3", "description": "Concrete Remediation & Habitual Implementation: Devises and applies deliberate practice strategies to enhance collaborative communication.", "required": false, "acceptable_evidence": ["Technical keywords: STAR, Situation, Task, Action.", "Practices mock interviews with peers focusing on thinking out loud, checking in, and concise structured explanations.", "Adopts frameworks such as STAR (Situation, Task, Action, Result) or top-down executive communication (Minto Pyramid).", "Follows up professionally with recruiters, acknowledging the feedback and sharing steps taken to address it."]}], "critical_failures": ["Reacts defensively or blames the interviewer/process rather than reflecting on personal performance.", "Demonstrates passive indifference to feedback with no commitment to iterative self-improvement."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'BROAD', 210, 'How do you handle production issues that did not appear in lower environments, and what steps do you take to diagnose and resolve them?', '{"key_points": [{"id": "KP1", "description": "Rapid Triage & Blast Radius Mitigation: Prioritizes immediate service stabilization via rollbacks, traffic rerouting, or feature flags before deep debugging.", "required": true, "acceptable_evidence": ["Technical keywords: feature flags, SLA, rapid, blast.", "Executes immediate containment actions (rolling back recent releases, toggling feature flags, enabling circuit breakers) to restore user SLA.", "Communicates incident status transparently across engineering, leadership, and customer success channels."]}, {"id": "KP2", "description": "Captures point-in-time forensic snapshots (heap dumps, error logs, request payloads) before restarting or scaling nodes.", "required": true, "acceptable_evidence": ["Technical keywords: forensic heap dump, Kubernetes preStop hook, core dump, production diagnostic snapshot, root cause isolation.", "Captures point-in-time forensic snapshots (heap dumps, error logs, request payloads) before restarting or scaling nodes.", "Triggers automated core dumps and preserves pod container state via Kubernetes preStop hooks before crashing pods are terminated."]}, {"id": "KP3", "description": "Observability Deep Dive & Distributed Tracing: Pinpoints discrepancies using distributed APM traces, correlation IDs, and log aggregation.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, distributed tracing, Datadog, APM.", "Traces failing requests using unique distributed correlation IDs across microservice boundaries (OpenTelemetry, Datadog).", "Analyzes high-cardinality metrics to isolate specific tenant, region, or device cohorts experiencing elevated failure rates."]}, {"id": "KP4", "description": "Inspects database connection pools, thread contention, downstream API rate limits, and memory exhaustion under live concurrency.", "required": false, "acceptable_evidence": ["Technical keywords: HikariCP, PgBouncer, connection pool exhaustion, thread starvation, JVM GC pause, live concurrency load.", "Inspects database connection pools, thread contention, downstream API rate limits, and memory exhaustion under live concurrency.", "Monitors HikariCP/PgBouncer connection pool saturation and JVM garbage collection pauses in Grafana to diagnose thread starvation under production load."]}, {"id": "KP5", "description": "Environment Parity Analysis & Blameless Post-Mortem: Identifies why lower environments diverged and hardens testing pipelines.", "required": false, "acceptable_evidence": ["Technical keywords: blameless post-mortem, configuration drift, environment, parity.", "Audits configuration drift, network topologies, data scale/skew, and permission differences between staging and production.", "Backports production edge-case traffic patterns or sanitized datasets into staging integration suites.", "Conducts a blameless post-mortem documenting root causes, contributing factors, and trackable preventative action items."]}], "critical_failures": ["Leaves production broken for hours attempting live code surgery without rolling back or mitigating user impact.", "Ignores environment drift and closes incidents without adding regression tests or identifying why lower environments missed it."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you handle requests from engineers who want to experiment with new AI tools?', '{"key_points": [{"id": "KP1", "description": "Safe Sandboxing & Innovation Enablement: Encourages exploration by providing isolated sandbox environments with clear usage guidelines.", "required": true, "acceptable_evidence": ["Technical keywords: AI, safe sandboxing, innovation, enablement.", "Establishes dedicated developer sandboxes with non-production data where engineers can safely test emerging AI libraries and tools.", "Fosters an engineering culture of experimentation through hackathons, brown-bag demos, and proof-of-concept time allocations.", "Creates a clear, lightweight intake process for requesting evaluations of new commercial or open-source tools."]}, {"id": "KP2", "description": "Security, IP & Compliance Safeguards: Protects proprietary source code and customer data from unauthorized vendor ingestion.", "required": true, "acceptable_evidence": ["Technical keywords: Zero Data Retention, ZDR, VPC, IP.", "Enforces strict policies preventing proprietary codebase or customer PII from being submitted to unvetted public cloud endpoints.", "Collaborates with Legal, Security, and Compliance teams to review vendor terms of service regarding data retention and model retraining.", "Requires Enterprise Zero Data Retention (ZDR) agreements or on-premises/VPC deployments for corporate code analysis tools."]}, {"id": "KP3", "description": "Structured Evaluation Criteria & ROI Justification: Establishes objective benchmarks to assess whether tools warrant enterprise adoption.", "required": false, "acceptable_evidence": ["Technical keywords: Total Cost of Ownership, ROI, criteria, justification.", "Sets measurable evaluation criteria (developer velocity gain, code quality impact, error rate reduction, total cost of ownership).", "Runs structured 30-day pilot programs with representative cohorts to gather quantitative and qualitative feedback.", "Standardizes supported toolchains to prevent excessive vendor sprawl and maintenance fragmentation."]}], "critical_failures": ["Blanket rejects all experimentation, stifling engineering morale and technological advancement.", "Allows unmonitored use of unvetted third-party AI tools with proprietary source code or confidential customer data."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you handle sensitive data such as PII when building AI systems?', '{"key_points": [{"id": "KP1", "description": "Automated Ingestion-Stage PII Detection & Redaction: Detects and anonymizes sensitive entities before data reaches vector stores or models.", "required": true, "acceptable_evidence": ["Technical keywords: Microsoft Presidio, pseudonymization, PII, NER.", "Utilizes NER and regex-based tools (e.g., Microsoft Presidio, AWS Comprehend) to detect SSNs, emails, phone numbers, and names at the API gateway.", "Replaces sensitive entities with cryptographic surrogate tokens (pseudonymization) or generic entity placeholders (redaction).", "Stores re-identification token vaults in encrypted, highly restricted key stores with strict role-based access."]}, {"id": "KP2", "description": "Model Boundary Protection & Vendor Contracts: Guarantees prompt payloads sent to LLM providers are purged of PII and protected from model training.", "required": true, "acceptable_evidence": ["Technical keywords: output guardrails, Zero Data Retention, ZDR, LLM.", "Secures commercial LLM enterprise agreements guaranteeing Zero Data Retention (ZDR) and non-training guarantees on prompt data.", "Deploys local/VPC-hosted open-source models for highly sensitive workflows where data egress is forbidden.", "Applies output guardrails to prevent generative models from regurgitating memorized private data in responses."]}, {"id": "KP3", "description": "Access Control, Encryption & Regulatory Compliance: Implements encryption, auditability, and compliance with privacy legislation.", "required": false, "acceptable_evidence": ["Technical keywords: GDPR, CCPA, TLS 1.3, AES-256.", "Enforces AES-256 encryption at rest and TLS 1.3 in transit across all data pipelines, databases, and vector stores.", "Implements right-to-be-forgotten deletion workflows complying with GDPR/CCPA to purge user embeddings and conversation logs.", "Maintains tamper-evident audit logs capturing who accessed sensitive fields and when."]}], "critical_failures": ["Sends unmasked customer PII to third-party public AI APIs without sanitization or privacy agreements.", "Stores unencrypted sensitive identity fields in searchable vector databases or plaintext prompt logs."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you handle situations where you are blamed for something you did not do?', '{"key_points": [{"id": "KP1", "description": "Emotional Composure & Objective Triage: Remains calm, de-escalates tension, and focuses on understanding the problem rather than reacting defensively.", "required": true, "acceptable_evidence": ["Technical keywords: emotional, composure, objective, remains.", "Maintains professional composure without responding with anger, hostility, or counter-accusations.", "Listens actively to the accuser''s perspective to understand what failure or impact triggered the concern."]}, {"id": "KP2", "description": "Focuses the immediate conversation on resolving the underlying technical or operational failure first.", "required": true, "acceptable_evidence": ["Technical keywords: blameless retrospective, objective telemetry, root cause analysis, incident timeline, blameless culture.", "Focuses the immediate conversation on resolving the underlying technical or operational failure first.", "De-escalates emotion by anchoring on objective telemetry (Datadog logs, Git blame history, deployment timestamps) to uncover systemic root causes collaboratively."]}, {"id": "KP3", "description": "Fact-Based & Transparent Clarification: Relies on verifiable artifacts (git commits, deployment logs, PR reviews, PRDs) to clarify responsibility.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, PR, CI, CD.", "Presents objective data (commit histories, CI/CD run logs, ticket assignment records, architecture review approvals) neutrally.", "Explains the sequence of events factually without attempting to humiliate or blame alternative colleagues.", "Takes appropriate ownership of any adjacent responsibilities or communication gaps that may have contributed to confusion."]}, {"id": "KP4", "description": "Blameless Systemic Improvement & Relationship Repair: Advances team processes to prevent ambiguity and restores interpersonal trust.", "required": false, "acceptable_evidence": ["Technical keywords: blameless post-mortem, RACI, PR.", "Advocates for blameless post-mortem cultures that focus on process and automated guardrail failures rather than individual scapegoating.", "Initiates a private one-on-one conversation with the accuser to resolve misunderstandings and realign working dynamics.", "Introduces clearer RACI definitions, PR review checklists, or audit logs to ensure transparent future accountability."]}], "critical_failures": ["Engages in hostile public arguments or personal attacks in team channels.", "Passive-aggressively refuses to help solve the problem because ''it wasn''t my fault''."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you handle situations where you are delayed in responding to recruiter requests or interview follow-ups?', '{"key_points": [{"id": "KP1", "description": "Immediate Ownership & Sincere Acknowledgment: Reconnects proactively with an honest apology without convoluted excuses.", "required": true, "acceptable_evidence": ["Technical keywords: immediate, sincere, acknowledgment, reconnects.", "Acknowledges the delay promptly as soon as realized, offering a brief, professional apology.", "Avoids defensive, dramatic, or convoluted excuses, maintaining concise executive communication."]}, {"id": "KP2", "description": "Expresses continued enthusiasm and respect for the company, team, and recruiting coordinator''s schedule.", "required": true, "acceptable_evidence": ["Technical keywords: candidate etiquette, proactive communication, interview scheduling, stakeholder management.", "Expresses continued enthusiasm and respect for the company, team, and recruiting coordinator''s schedule.", "Sends a courteous, concise update acknowledging the delay, clarifying unexpected conflicts, and reaffirming strong enthusiasm for the role and team."]}, {"id": "KP3", "description": "Complete Delivery & Reduced Communication Friction: Provides all requested deliverables immediately to accelerate next steps.", "required": true, "acceptable_evidence": ["Technical keywords: LinkedIn, email, phone.", "Submits all pending items (take-home assignment, scheduling availability, compensation info) comprehensively in the reply.", "Provides flexible and broad calendar availability blocks to accommodate the recruiter''s scheduling backlog.", "Confirms preferred communication channels (email, phone, LinkedIn) to prevent future communication misses."]}, {"id": "KP4", "description": "Time Management Hygiene & Preventative Measures: Implements organizational habits to ensure timely future correspondence.", "required": false, "acceptable_evidence": ["Technical keywords: Received, management, hygiene, preventative.", "Monitors application email filters and spam folders systematically during active recruitment cycles.", "Sends brief ''holding pattern'' acknowledgments (e.g., ''Received, reviewing and will reply by Wednesday'') if comprehensive answers require time.", "Keeps a dedicated interview tracking spreadsheet to monitor deadlines and pending follow-ups."]}], "critical_failures": ["Ghosts the recruiter or acts entitled when responding after significant delays.", "Fails to provide the requested information upon reconnecting, dragging out communication further."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you handle the governance and guard rails for this? Do you have any governance in place and if yes how would you?', '{"key_points": [{"id": "KP1", "description": "Layered Gateway Guardrails (Input & Output): Enforces schema validation, prompt injection defense, and content moderation at system boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, prompt injection, PII, gateway guardrails.", "Applies input safety filters scanning for prompt injection, jailbreaks, PII, and toxic language before reaching the model.", "Validates generated model outputs against Pydantic schema contracts, toxicity classifiers, and factual hallucination checks."]}, {"id": "KP2", "description": "Deploys dedicated guardrail frameworks (e.g., NeMo Guardrails, Llama Guard, Guardrails AI) with deterministic fallback behaviors.", "required": true, "acceptable_evidence": ["Technical keywords: NeMo Guardrails, Llama Guard, Guardrails AI, deterministic fallback, topical rail, moderation API.", "Deploys dedicated guardrail frameworks (e.g., NeMo Guardrails, Llama Guard, Guardrails AI) with deterministic fallback behaviors.", "Integrates NeMo Guardrails Colang flows to intercept off-topic or toxic prompts, routing policy breaches to pre-defined safe fallback responses."]}, {"id": "KP3", "description": "Governed Tool Execution & Policy Checkpoints: Enforces strict authorization and deterministic business logic prior to executing tool side effects.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, HITL, LLM, actual state.", "Separates LLM reasoning from actual state-mutating tool execution via governed middleware layers.", "Requires explicit policy checks, parameter validation, and user role-based permissions before executing tool calls.", "Implements human-in-the-loop (HITL) approval gates for high-risk actions (financial transactions, data deletion, contract publishing)."]}, {"id": "KP4", "description": "Comprehensive Audit Observability & Incident Response: Instruments end-to-end tracing, compliance reporting, and automated circuit breaking.", "required": false, "acceptable_evidence": ["Technical keywords: OpenTelemetry, LangSmith, end tracing, Arize.", "Maintains immutable audit logs capturing input prompts, guardrail scores, tool parameters, and final outputs.", "Instruments real-time observability dashboards (OpenTelemetry, Arize, LangSmith) tracking safety trigger rates and latency overhead.", "Defines automated circuit breakers to degrade safely to deterministic rule-based responses during security anomalies."]}], "critical_failures": ["Relies entirely on soft system prompts for security and guardrailing without deterministic code-level enforcement.", "Allows models to execute state-changing or financial operations autonomously without policy validation or approval gates."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'How do you handle very large datasets or document collections that are too large to fit into memory?', '{"key_points": [{"id": "KP1", "description": "Stream-Based Ingestion & Chunked Iteration: Processes documents as lazy streams rather than loading monolithic corpora into RAM.", "required": true, "acceptable_evidence": ["Technical keywords: iterators, Polars, Pandas, file chunking.", "Uses generator-based streaming (e.g., Python iterators, file chunking) to read and parse documents line-by-line or batch-by-batch.", "Employs chunked readers in data manipulation libraries (e.g., pandas chunksize, Polars lazy frames) to keep memory footprint bounded.", "Applies memory-mapped files (mmap) for high-speed sequential or random access without exhausting virtual memory."]}, {"id": "KP2", "description": "Distributed & Out-of-Core Compute Engines: Leverages scalable compute frameworks to partition and process data in parallel.", "required": true, "acceptable_evidence": ["Technical keywords: Apache Spark, parquet, generation pipelines, Ray.", "Utilizes distributed engines (Apache Spark, Ray, Dask) to distribute document parsing across multi-node clusters.", "Writes intermediate processed artifacts to columnar disk formats (Parquet, Arrow) optimized for compression and selective column projection.", "Employs batch embedding generation pipelines writing directly to disk or streaming into vector databases without in-memory buffering."]}, {"id": "KP3", "description": "Disk-Backed Vector Indexing & Memory Profiling: Configures vector databases and monitors process resource consumption.", "required": false, "acceptable_evidence": ["Technical keywords: tracemalloc, memory_profiler, HNSW, IVF.", "Configures vector search indices with disk-backed storage and memory-mapped HNSW or IVF indices.", "Profiles memory usage using memory_profiler or tracemalloc to identify memory leaks and uncollected object references.", "Implements backpressure in async queues to prevent fast producers from overwhelming downstream embedding workers."]}], "critical_failures": ["Attempts to load multi-gigabyte or terabyte datasets into RAM using simple read() or read_csv() without batching.", "Fails to manage backpressure, causing Out-Of-Memory (OOM) worker process crashes under high ingestion load."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'How do you implement logic or scoring to suggest relevant follow-up questions to a user based on conversation history and previous user queries?', '{"key_points": [{"id": "KP1", "description": "Candidate Generation & Contextual Prompting: Generates logically progressive follow-up options conditioned on conversation trajectory.", "required": true, "acceptable_evidence": ["Technical keywords: JSON, contextual prompting, generation prompting, question graph.", "Extracts unresolved entities, implicit follow-ups, and natural exploratory paths from the latest conversation turns.", "Utilizes structured JSON generation prompting with few-shot examples to produce 3-5 distinct follow-up questions.", "Retrieves frequently asked follow-ups from historical question graph transitions based on current topic clusters."]}, {"id": "KP2", "description": "Relevance Scoring & Diversity Reranking: Ranks candidates using semantic similarity, intent progression, and diversity algorithms.", "required": true, "acceptable_evidence": ["Technical keywords: cosine similarity, MMR, diversity reranking.", "Scores candidate relevance against current user context using cross-encoder models or cosine similarity of embeddings.", "Applies Maximal Marginal Relevance (MMR) to prevent proposing repetitive questions covering identical aspects.", "Penalizes suggestions that duplicate questions previously asked in the current session."]}, {"id": "KP3", "description": "User Engagement Optimization & Filtering: Filters unsafe suggestions and tracks suggestion acceptance rates.", "required": false, "acceptable_evidence": ["Technical keywords: CTR, engagement, unsafe, suggestions.", "Filters suggestions through safety guardrails to ensure generated prompts never guide users toward prohibited topics.", "Logs click-through rates (CTR) on suggested pills to train ranking models on which follow-ups drive successful resolutions.", "Adapts question complexity and technical tone to match the user''s historical interaction style."]}], "critical_failures": ["Proposes generic, static questions completely unrelated to the current conversation context.", "Generates duplicate questions that the user has already asked in preceding turns."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How does your system handle user sessions and conversation flow in real-time interactions?', '{"key_points": [{"id": "KP1", "description": "Real-Time Transport Protocol & Streaming Architecture: Evaluates and implements streaming protocols (SSE, WebSockets) matching bidirectional needs.", "required": true, "acceptable_evidence": ["Technical keywords: SSE, Server-Sent Events, WebSockets, HTTP.", "Selects Server-Sent Events (SSE) for simple client-to-server HTTP POST paired with server-to-client token streaming, or WebSockets for full-duplex interactions.", "Streams partial token chunks to clients using structured event formats with event IDs and finish reasons.", "Handles backpressure and buffering to prevent fast LLM generation from overwhelming slow client connections."]}, {"id": "KP2", "description": "Distributed Session State & Concurrency Coordination: Maintains session continuity across horizontally scaled application servers.", "required": true, "acceptable_evidence": ["Technical keywords: Kafka, Redis, session_id, session state.", "Stores active session state and message history in shared distributed caches (Redis) keyed by session_id.", "Implements session locking or idempotency keys to handle concurrent user inputs or rapid repeated clicks gracefully.", "Uses pub/sub message brokers (Redis Pub/Sub, Kafka) to route responses to the correct gateway node hosting the client connection."]}, {"id": "KP3", "description": "Connection Resilience, Reconnect & History Synchronization: Manages network drops, client reconnections, and state integrity.", "required": false, "acceptable_evidence": ["Technical keywords: exponential backoff, ID, AbortController, LLM.", "Implements client reconnect logic with exponential backoff and Last-Event-ID resumption to replay lost tokens.", "Commits completed assistant messages to durable database storage only after successful completion or stream closure.", "Cleans up dangling connection state and handles client-side cancellation signals (AbortController) to stop unnecessary LLM token generation."]}], "critical_failures": ["Maintains state solely in local server memory, causing session loss when requests hit alternative nodes behind a load balancer.", "Fails to handle user disconnection, continuing costly LLM generation and writing corrupted fragments to conversation history."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'How would you apply minimax optimization to choose the safest candidate under uncertain rejection scenarios?', '{"key_points": [{"id": "KP1", "description": "Decision Matrix Formulation & Scenario Modeling: Formulates actions, uncertain environment states (rejection scenarios), and loss matrices.", "required": true, "acceptable_evidence": ["Technical keywords: environment states, uncertain states, rejection scenarios, critical role vacancy.", "Defines candidate choices as actions A and possible outcomes/rejections as adversarial or uncertain states S.", "Constructs a payoff/loss matrix quantifying business loss or utility under each candidate-scenario pair L(a, s).", "Explicitly models extreme rejection scenarios (e.g., critical role vacancy, candidate reneging, mismatch backlash)."]}, {"id": "KP2", "description": "Minimax Optimization Criterion: Selects the action that minimizes maximum potential loss across all uncertain outcomes.", "required": true, "acceptable_evidence": ["Technical keywords: max_s, argmin_a, conservative worst-case protection, risk-neutral average.", "Computes the worst-case loss for each candidate action: max_s L(a, s).", "Selects the optimal candidate action minimizing that worst-case bound: a* = argmin_a [ max_s L(a, s) ].", "Contrasts pure minimax (conservative worst-case protection) with expected value optimization (risk-neutral average)."]}, {"id": "KP3", "description": "Minimax Regret & Sensitivity Analysis: Evaluates regret relative to optimal choices and conducts robustness validation.", "required": false, "acceptable_evidence": ["Technical keywords: min_a, robustness validation, minimax, regret.", "Formulates Minimax Regret by computing opportunity loss R(a, s) = L(a, s) - min_a'' L(a'', s) and minimizing maximum regret.", "Performs sensitivity analysis to verify whether candidate rankings remain stable across perturbed scenario loss estimates.", "Discusses trade-offs of hyper-conservatism (forfeiting high-upside candidates to avoid low-probability downsides)."]}], "critical_failures": ["Confuses minimax with simple expected value maximization without evaluating worst-case bounds.", "Fails to define a formal decision/loss matrix mapping actions to scenario outcomes."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you approach building and demonstrating an MVP to early pilot customers in a regulated domain like healthcare?', '{"key_points": [{"id": "KP1", "description": "Regulatory Compliance & Security Baseline: Enforces HIPAA compliance, Business Associate Agreements (BAAs), and end-to-end data encryption.", "required": true, "acceptable_evidence": ["Technical keywords: HIPAA, SOC 2, VPC, AI.", "Signs BAAs with all cloud infrastructure and AI model vendors prior to ingesting Protected Health Information (PHI).", "Implements stringent PHI de-identification and masking pipelines conforming to HIPAA Safe Harbor or Expert Determination methods.", "Enforces encrypted VPC boundaries, access logging, and SOC 2 / HIPAA compliance baselines from day one."]}, {"id": "KP2", "description": "Constrained Workflow Scoping & Non-Diagnostic Framing: Scopes MVP to assistive, administrative tasks with strict human oversight.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, HITL, MVP, AI.", "Focuses initial MVP on high-value, lower-risk administrative automation (clinical documentation summarizing, prior authorization drafting) rather than autonomous diagnosis.", "Mandates Human-in-the-Loop (HITL) approval where clinicians review, edit, and sign off on all AI-generated drafts.", "Integrates explicit citations linking generated summaries directly to source electronic health record (EHR) notes."]}, {"id": "KP3", "description": "Pilot Acceptance Criteria & Safe Rollout Governance: Establishes clear pilot success metrics and phased customer onboarding.", "required": false, "acceptable_evidence": ["Technical keywords: golden dataset, rollout governance, success metrics.", "Defines quantitative acceptance criteria with pilot clinicians (time saved per chart, error rate, clinical acceptance percentage).", "Conducts offline validation against a curated clinical golden dataset before initiating live pilot user trials.", "Maintains continuous feedback channels and immediate escalation mechanisms for clinicians to report inaccuracies."]}], "critical_failures": ["Proposes autonomous diagnostic medical decision-making without physician sign-off in an initial MVP.", "Ignores HIPAA/PHI legal requirements or sends health records to unvetted public cloud endpoints without BAAs."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you approach building and owning AI systems as the first AI engineer in a company?', '{"key_points": [{"id": "KP1", "description": "Business-Driven Use Case Prioritization: Identifies high-ROI, technically feasible problems rather than pursuing AI for novelty.", "required": true, "acceptable_evidence": ["Technical keywords: ROI, AI, baseline metrics, cost.", "Conducts stakeholder discovery across product, operations, and sales to map pain points with measurable business value.", "Evaluates use cases on a value vs complexity matrix, prioritizing ''low-hanging fruit'' that proves AI viability quickly.", "Defines clear baseline metrics and success criteria before writing code (e.g., latency, cost, resolution rate)."]}, {"id": "KP2", "description": "Evaluation-First & Pragmatic Architecture: Establishes evaluation benchmarks and leverages managed APIs before building custom infrastructure.", "required": true, "acceptable_evidence": ["Technical keywords: fine-tuning, Kubernetes, pragmatic architecture, scoring pipeline.", "Builds a golden evaluation dataset and scoring pipeline before deploying or fine-tuning models.", "Leverages high-quality commercial APIs and pre-existing frameworks to deliver an initial production solution rapidly.", "Avoids premature infrastructure over-engineering (e.g., spinning up custom Kubernetes clusters or fine-tuning pipelines prematurely)."]}, {"id": "KP3", "description": "AI Governance, Cost Control & Team Enablement: Establishes security baselines, token budgets, and documentation for future team scaling.", "required": false, "acceptable_evidence": ["Technical keywords: enablement, establishes, baselines, AI.", "Implements cost tracking, rate limits, and latency monitoring across model providers to prevent runaway expenses.", "Establishes security and privacy guardrails ensuring company and user data remain protected.", "Documents architectural decisions, codebase conventions, and deployment workflows to facilitate seamless future hiring."]}], "critical_failures": ["Spends months building complex custom ML infrastructure or training bespoke models without delivering any working product.", "Deploys models to production without an objective evaluation benchmark or cost monitoring."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you automatically detect and handle edge cases in AI-driven QA systems?', '{"key_points": [{"id": "KP1", "description": "Automated Edge Case Discovery & Generation: Generates boundary, malformed, and adversarial inputs systematically.", "required": true, "acceptable_evidence": ["Technical keywords: LLM, equivalence partitioning, automated, discovery.", "Applies boundary value analysis, fuzzing, and equivalence partitioning to generate extreme input lengths and formatting anomalies.", "Utilizes adversarial LLM red-teaming agents to synthesize ambiguous queries, prompt injections, and contradictory statements.", "Mines production failure traces, low-confidence queries, and user thumbs-down logs to identify unhandled real-world edge cases."]}, {"id": "KP2", "description": "Outlier Detection & Semantic Uncertainty Estimation: Flags queries that diverge from standard training or golden distributions.", "required": true, "acceptable_evidence": ["Technical keywords: OOD, syntax errors, factual contradictions.", "Computes query embedding distances from established test clusters to detect out-of-distribution (OOD) test inputs.", "Monitors model prediction entropy, token perplexity, or ensemble disagreement to identify high-uncertainty samples.", "Classifies detected anomalies into categorized failure modes (syntax errors, factual contradictions, safety violations)."]}, {"id": "KP3", "description": "Automated Handling, Regression Incorporation & Gating: Triages failures and incorporates validated edge cases into regression suites.", "required": false, "acceptable_evidence": ["Technical keywords: QA, automated, regression, incorporation.", "Routes identified edge cases to fallback deterministic logic or human review workflows.", "Automatically adds verified novel edge cases into versioned regression golden test suites.", "Generates automated QA reports highlighting coverage blind spots and regression failure trends across builds."]}], "critical_failures": ["Relies solely on standard positive happy-path test cases without automated boundary or adversarial fuzzing.", "Discards detected edge cases rather than cataloging them into regression test suites."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you communicate relocation timelines clearly and professionally during interviews?', '{"key_points": [{"id": "KP1", "description": "Upfront Transparency & Realistic Boundary Setting: States physical relocation readiness, timing constraints, and dependencies clearly from the outset.", "required": true, "acceptable_evidence": ["Technical keywords: upfront, realistic, boundary, setting.", "Discloses relocation availability and timeline constraints proactively during initial recruiter screens rather than late in the process.", "Articulates concrete factors governing timing (lease expirations, family transitions, school terms, notice periods).", "Avoids overpromising unrealistic timelines that could result in start date postponements."]}, {"id": "KP2", "description": "Phased Transition & Remote Bridge Strategy: Proposes pragmatic hybrid or temporary remote arrangements to ensure immediate productivity.", "required": true, "acceptable_evidence": ["Technical keywords: phased, transition, remote, bridge.", "Suggests working remotely during the transition window while committing to a firm target in-person date.", "Offers to travel for onboarding weeks or key team rituals prior to permanent relocation.", "Affirms full commitment to the team''s working hours and collaborative expectations during the interim period."]}, {"id": "KP3", "description": "Inquiring on Corporate Support & Written Alignment: Clarifies relocation assistance expectations and confirms agreed dates in writing.", "required": false, "acceptable_evidence": ["Technical keywords: written alignment, housing secured, moving dates scheduled.", "Inquires professionally about corporate relocation assistance, temporary housing, and moving stipends.", "Summarizes agreed milestones in writing following offer discussions to eliminate ambiguity.", "Keeps hiring managers updated on key transition milestones (e.g., housing secured, moving dates scheduled)."]}], "critical_failures": ["Conceals relocation constraints until after an offer is extended, forcing last-minute renegotiations.", "Demands immediate full-remote flexibility without acknowledging the role''s specified in-person requirements."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you contribute beyond engineering, such as in product direction or strategic decisions, as a founding engineer?', '{"key_points": [{"id": "KP1", "description": "Customer Discovery & User Feedback Synthesis: Engages directly with end-users and customers to translate real problems into product features.", "required": true, "acceptable_evidence": ["Technical keywords: customer, discovery, feedback, synthesis.", "Participates in user research and sales demo calls to observe real customer pain points and friction directly.", "Translates qualitative customer feedback into prioritized product backlog items and technical requirements.", "Champions customer empathy over technical elegance, resisting building complex systems for non-existent problems."]}, {"id": "KP2", "description": "Strategic Roadmap Alignment & Technical Feasibility: Bridges business goals with engineering reality to optimize time-to-market.", "required": true, "acceptable_evidence": ["Technical keywords: AI, roadmap alignment, speed trade-offs.", "Advises founders on technical feasibility, development costs, and speed trade-offs for proposed features.", "Identifies technical competitive moats and suggests opportunistic pivots enabled by emerging AI capabilities.", "Challenges product assumptions constructively using data, metrics, and proof-of-concept prototypes."]}, {"id": "KP3", "description": "Hiring, Culture & Cross-Functional Operations: Drives foundational culture, technical recruiting, and operational processes.", "required": false, "acceptable_evidence": ["Technical keywords: hiring, culture, cross, operations.", "Helps interview and recruit early engineering talent, defining interview standards and cultural rubrics.", "Fosters an engineering culture of psychological safety, high agency, continuous deployment, and blameless post-mortems.", "Assists sales and marketing teams by building compelling technical demos and authoring whitepapers."]}], "critical_failures": ["Maintains a strict ''code-only'' mindset, refusing to engage with product strategy, customers, or business priorities.", "Pushes for massive architectural rewrites that stall commercial product momentum without business justification."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you define and execute an AI roadmap for a product-focused organization?', '{"key_points": [{"id": "KP1", "description": "Phase-Based Strategic Structuring: Constructs a multi-horizon roadmap balancing immediate quick wins with durable core platforms.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, ROI, RICE, bespoke fine-tuned.", "Structures roadmap into Horizon 1 (immediate high-ROI quick wins using off-the-shelf APIs), Horizon 2 (bespoke fine-tuned/RAG workflows), and Horizon 3 (custom autonomous agents).", "Aligns technical milestones with product release cycles and core business KPIs (revenue, retention, cost reduction).", "Prioritizes initiatives using structured scoring frameworks (e.g., RICE or Value vs Effort matrices)."]}, {"id": "KP2", "description": "Foundational Enabler Investments: Allocates engineering resources for core data pipelines, evaluation harnesses, and observability.", "required": true, "acceptable_evidence": ["Technical keywords: data pipelines, foundational, enabler, investments.", "Invests early in shared platform foundations: centralized evaluation suites, telemetry, guardrails, and model gateways.", "Prevents duplicative ad-hoc implementations across product squads by establishing reusable internal SDKs.", "Defines clear deprecation and upgrade paths to adopt rapidly evolving foundation model releases."]}, {"id": "KP3", "description": "Iterative Execution, Governance & ROI Tracking: Measures delivery against milestones and adapts roadmap to changing AI capabilities.", "required": false, "acceptable_evidence": ["Technical keywords: unit economics, AI, ROI.", "Monitors operational cost per active user and model token expenditures against projected unit economics.", "Conducts quarterly roadmap reviews to pivot away from underperforming initiatives and capitalize on frontier AI models.", "Maintains transparent stakeholder communication via shared roadmaps, progress dashboards, and demo sessions."]}], "critical_failures": ["Presents a purely theoretical research roadmap detached from measurable customer value or product delivery timelines.", "Fails to invest in evaluation or monitoring infrastructure, resulting in unmaintainable production technical debt."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you demonstrate both conceptual clarity and practical implementation within a limited demo time?', '{"key_points": [{"id": "KP1", "description": "Top-Down Narrative & Conceptual Framing: Contextualizes the problem and high-level architecture in the first 2-3 minutes before diving into implementation.", "required": true, "acceptable_evidence": ["Technical keywords: level architecture, narrative, conceptual, framing.", "Begins with a concise executive problem statement, user persona, and architectural overview diagram.", "Establishes a clear agenda upfront outlining what will be shown and reserving time for interactive Q&A.", "Explains the ''why'' behind key design decisions before showing the ''how''."]}, {"id": "KP2", "description": "Targeted Implementation Walkthrough: Showcases working functionality and inspects critical code/infrastructure blocks selectively.", "required": true, "acceptable_evidence": ["Technical keywords: prompt pipeline, custom prompt pipeline, algorithm, guardrail filter.", "Demonstrates a seamless end-to-end happy path user journey on working software rather than static slides.", "Dives directly into 1-2 core technical innovations (e.g., custom prompt pipeline, algorithm, or guardrail filter) rather than reading boilerplate line-by-line.", "Highlights measurable outcomes: benchmark accuracy, latency benchmarks, or cost efficiencies achieved."]}, {"id": "KP3", "description": "Time Management & Demo Contingency Safeguards: Paces delivery disciplinedly and prepares fallbacks for live environment glitches.", "required": false, "acceptable_evidence": ["Technical keywords: pre-recorded demo video, cached responses, management, contingency.", "Maintains strict timekeeping, checking in with the audience at key transitions to address burning questions.", "Prepares fallback assets (pre-recorded demo video, cached responses, staging endpoints) in case live network or model APIs fail.", "Concludes with a concise summary of current limitations, trade-offs, and next milestone iterations."]}], "critical_failures": ["Spends the entire demo getting bogged down in boilerplate code or setup debugging, never showing working software.", "Presents high-level marketing slides without demonstrating technical substance or concrete implementation artifacts."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you demonstrate strong communication skills in an interview, especially when explaining complex technical concepts?', '{"key_points": [{"id": "KP1", "description": "Audience Calibration & Layered Depth: Gauges the interviewer''s familiarity and delivers explanations in structured, progressive layers.", "required": true, "acceptable_evidence": ["Technical keywords: audience, layered, depth, gauges.", "Asks calibrating questions (e.g., ''Would you prefer a high-level system overview or an algorithm-level deep dive?'') before answering.", "Applies the Pyramid Principle / top-down communication: gives the core conclusion/architecture first, then expands details."]}, {"id": "KP2", "description": "Avoids unnecessary acronyms and jargon unless defined, explaining concepts in plain English before formal technical notation.", "required": true, "acceptable_evidence": ["Technical keywords: analogies, executive summary, bottom-line-first, jargon deconstruction, pedagogical clarity.", "Avoids unnecessary acronyms and jargon unless defined, explaining concepts in plain English before formal technical notation.", "Uses the pyramid principle (stating conclusion first), intuitive physical analogies, and diagrammatic explanations before introducing formal technical jargon."]}, {"id": "KP3", "description": "Intuitive Analogies & Concrete Exemplification: Anchors abstract technical mechanisms in relatable mental models and real-world examples.", "required": true, "acceptable_evidence": ["Technical keywords: vector embeddings, example tracing, input payload, tangible trade-offs.", "Uses clear analogies (e.g., explaining vector embeddings as coordinates on a semantic concept map or locks as bathroom keys).", "Walks through a concrete, end-to-end data example tracing an input payload through every pipeline stage.", "Connects technical mechanisms to tangible trade-offs (e.g., latency vs accuracy, cost vs throughput)."]}, {"id": "KP4", "description": "Active Listening, Collaborative Pacing & Feedback Checking: Checks in with the interviewer frequently to maintain collaborative dialogue.", "required": false, "acceptable_evidence": ["Technical keywords: active, listening, collaborative, pacing.", "Pauses periodically (e.g., ''Does this align with what you were looking for, or should I go deeper on the indexing layer?'').", "Reads verbal and visual cues from the interviewer, pivoting quickly if the interviewer wants to shift topics.", "Admits knowledge boundaries honestly when unfamiliar with a niche topic rather than pretending or bluffing."]}], "critical_failures": ["Monologues for ten uninterrupted minutes without pausing to verify interviewer engagement or comprehension.", "Explains concepts in hyper-convoluted mathematical jargon while unable to articulate the core intuitive mechanism."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'How would you design a chat-based system for generating Bills of Materials (BOMs) using historical and structured data sources?', '{"key_points": [{"id": "KP1", "description": "Hybrid Knowledge Retrieval & Structured Catalog Integration: Connects conversational agents to relational ERP databases, part catalogs, and historical BOM repositories.", "required": true, "acceptable_evidence": ["Technical keywords: tool calling, hybrid search, ERP, BOM.", "Integrates with ERP/PLM systems (SAP, Teamcenter, SQL databases) via governed tool calling and structured API endpoints.", "Applies hybrid search (part number exact match + semantic description search) to locate components from historical BOM records."]}, {"id": "KP2", "description": "Extracts product specs, quantities, materials, and tolerances conversationally into validated Pydantic schemas.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic schema validation, structured output parsing, Bill of Materials (BOM), ERP import schema, tool calling.", "Extracts product specs, quantities, materials, and tolerances conversationally into validated Pydantic schemas.", "Uses OpenAI/Anthropic tool calling with Pydantic BaseModel schemas to guarantee structured JSON output matching ERP BOM import requirements."]}, {"id": "KP3", "description": "Conversational Disambiguation & Interactive Assembly: Clarifies ambiguous part specifications and guides users through configuration choices.", "required": true, "acceptable_evidence": ["Technical keywords: conversational state, replace, BOM.", "Detects ambiguous part references (e.g., multiple supplier SKUs for ''M6 stainless bolt'') and prompts the user with explicit candidate options.", "Validates assembly dependencies, part compatibility, and lead-time constraints against engineering rules.", "Maintains multi-turn conversational state tracking active BOM draft modifications (add, replace, delete component)."]}, {"id": "KP4", "description": "Draft Lifecycle, Versioning & ERP Commit Verification: Separates interactive drafts from immutable released BOMs with full auditability.", "required": false, "acceptable_evidence": ["Technical keywords: ERP, CSV, STEP, CAD.", "Maintains BOM versioning (draft vs released revision), preventing in-flight edits from corrupting released production orders.", "Requires explicit user confirmation and formal review gates before committing generated BOMs into corporate ERP systems.", "Exports generated BOMs into standardized manufacturing formats (CSV, Excel, STEP/CAD metadata) with complete component traceability."]}], "critical_failures": ["Hallucinates invented part numbers without validating existence against an ERP/catalog database.", "Directly mutates live ERP production orders from conversational LLM outputs without human verification."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'How would you design a minimax-based decision-making strategy for selecting optimal candidates under uncertainty?', '{"key_points": [{"id": "KP1", "description": "Decision Space & Uncertainty Matrix Parameterization: Maps available candidate decisions and external uncertainty states into a bounded loss matrix.", "required": true, "acceptable_evidence": ["Technical keywords: uncertainty states, space, uncertainty, matrix.", "Models candidate alternatives as action vector A and uncontrollable market/hiring outcomes as uncertainty states S.", "Constructs an explicit cost/loss matrix L(a, s) reflecting financial, operational, and opportunity costs under each scenario."]}, {"id": "KP2", "description": "Incorporates extreme tail-risk scenarios (e.g., sudden offer rejection, early attrition, severe skill deficit).", "required": true, "acceptable_evidence": ["Technical keywords: minimax regret, worst-case scenario modeling, risk mitigation, candidate hiring matrix, decision theory.", "Incorporates extreme tail-risk scenarios (e.g., sudden offer rejection, early attrition, severe skill deficit).", "Applies a minimax regret matrix that evaluates candidates by minimizing maximum potential loss (e.g. failure on critical architecture delivery vs slower onboarding)."]}, {"id": "KP3", "description": "Minimax Strategy & Worst-Case Optimization: Selects the candidate action minimizing the maximum possible loss across all states.", "required": true, "acceptable_evidence": ["Technical keywords: worst_loss, argmin_a, max_s, pessimistic.", "Identifies each candidate''s maximum vulnerability: worst_loss(a) = max_{s in S} L(a, s).", "Chooses the optimal candidate minimizing worst-case vulnerability: argmin_a [max_s L(a, s)].", "Contrasts minimax (pessimistic, risk-averse guarantee) with Laplace/Bayesian criteria (expected utility under assumed priors)."]}, {"id": "KP4", "description": "Minimax Regret & Sensitivity Thresholding: Computes opportunity regret relative to best post-hoc actions and stress-tests bounds.", "required": false, "acceptable_evidence": ["Technical keywords: minimax, regret, sensitivity, thresholding.", "Calculates minimax regret R(a, s) = L(a, s) - min_{a''} L(a'', s) to avoid extreme conservatism when one candidate dominates in most states.", "Conducts Monte Carlo sensitivity analysis varying loss entries to verify ranking stability.", "Integrates risk budgets to balance conservative guarantees against expected candidate upside."]}], "critical_failures": ["Confuses minimax with unweighted average scoring without identifying worst-case scenario bounds.", "Fails to specify how uncertainty states or rejection outcomes are quantified in the decision matrix."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How would you design a system to automate extraction of structured data from financial PDFs into a spreadsheet?', '{"key_points": [{"id": "KP1", "description": "Document Ingestion & Multi-Modal Table Extraction: Detects PDF types and applies layout-aware OCR/parsers to extract multi-column tables.", "required": true, "acceptable_evidence": ["Technical keywords: Transformer, PDF, OCR, AWS.", "Differentiates digital text PDFs (using pdfplumber, PyMuPDF) from scanned images requiring OCR (Tesseract, AWS Textract, Docling).", "Applies table structure detection (e.g., Table Transformer, LayoutLM) to extract merged cells, multi-line headers, and currency symbols."]}, {"id": "KP2", "description": "Preserves spatial bounding box coordinates (x, y, width, height) and page numbers for visual audit traceability.", "required": true, "acceptable_evidence": ["Technical keywords: bounding box coordinates, PDFPlumber, IBM Docling, openpyxl, Pandas DataFrame, table structure extraction, visual audit.", "Preserves spatial bounding box coordinates (x, y, width, height) and page numbers for visual audit traceability.", "Extracts tabular data cells using PDFPlumber/Docling with explicit bounding box metadata, mapping rows and columns directly into openpyxl or Pandas DataFrames."]}, {"id": "KP3", "description": "Financial Schema Normalization & Validation: Maps extracted line items to standard financial schemas and validates mathematical consistency.", "required": true, "acceptable_evidence": ["Technical keywords: financial schema, financial schemas, mathematical consistency, Gross Sales.", "Normalizes heterogeneous line item descriptions (e.g., ''Total Revenues'', ''Gross Sales'') into canonical accounting taxonomy.", "Enforces arithmetic balance rules (e.g., verifying Assets = Liabilities + Equity, or line items sum to subtotal).", "Parses currencies, date formats, negative parentheses notations, and scales (thousands vs millions) into typed data."]}, {"id": "KP4", "description": "Confidence Scoring, Review Workflow & Spreadsheet Export: Routes low-confidence extractions to human auditors and generates formatted Excel/CSV files.", "required": false, "acceptable_evidence": ["Technical keywords: Pandas, CSV, OCR, SQS.", "Assigns character/field-level confidence scores, routing rows with arithmetic mismatches or low OCR confidence to human review.", "Generates clean, multi-tab Excel files (openpyxl, pandas) with preserved formulas and source page hyperlinks.", "Maintains idempotent processing queues (SQS/Celery) to reprocess failed documents gracefully."]}], "critical_failures": ["Flattens multi-column financial tables into unstructured raw text strings without preserving cell/row geometry.", "Fails to validate arithmetic totals against extracted line items, allowing silent extraction errors into financial sheets."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How would you design a system to continuously adapt OCR models to new document formats, such as newly introduced tax forms?', '{"key_points": [{"id": "KP1", "description": "Format Shift Detection & Low-Confidence Routing: Identifies novel layouts, unmapped fields, and spatial drift automatically.", "required": true, "acceptable_evidence": ["Technical keywords: confidence routing, spatial drift, shift, detection.", "Computes visual layout embedding distances and field-matching confidence drops to detect uncataloged form variants.", "Flags missing expected anchors, novel field keys, or altered box coordinates characteristic of new tax year revisions."]}, {"id": "KP2", "description": "Routes newly introduced form layouts to an annotation queue for rapid human verification and schema definition.", "required": true, "acceptable_evidence": ["Technical keywords: active learning loop, Label Studio, low-confidence routing, few-shot prompt update, OCR layout adaptation, human-in-the-loop.", "Routes newly introduced form layouts to an annotation queue for rapid human verification and schema definition.", "Flags low-confidence field extractions (< 0.70) to a Label Studio review queue, triggering automated few-shot prompt updates and active learning fine-tuning."]}, {"id": "KP3", "description": "Active Learning & Few-Shot Multimodal Adaptation: Rapidly adapts extraction pipelines using few-shot vision models and layout fine-tuning.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, fine-tuning, extraction pipelines, layout fine-tuning.", "Uses few-shot visual prompting with Vision-Language Models (VLMs) by supplying 2-3 annotated sample templates of the new form.", "Fine-tunes layout models (LayoutLMv3, Donut) incrementally using human-in-the-loop validated corrections.", "Employs synthetic form generation by perturbing existing templates with synthetic fonts, skew, and dummy field data."]}, {"id": "KP4", "description": "Automated Regression Benchmarking & Shadow Deployment: Protects historical form extraction accuracy while validating new versions.", "required": false, "acceptable_evidence": ["Technical keywords: catastrophic forgetting, CER, automated, regression.", "Maintains a comprehensive historical regression suite of previous tax form years to prevent catastrophic forgetting.", "Deploys updated layout parsers in shadow mode alongside legacy models to compare extraction accuracy on live traffic.", "Tracks field-level F1 and character error rate (CER) metrics continuously across form versions in production."]}], "critical_failures": ["Retrains OCR models without evaluating against historical form datasets, causing catastrophic regression on existing forms.", "Hardcodes rigid pixel coordinate bounding boxes that shatter when form versions introduce minor margin shifts."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'How would you design an AI assistant for a betting or transactional app where users ask questions and perform actions conversationally?', '{"key_points": [{"id": "KP1", "description": "Strict Separation of Informational Q&A from Financial Actions: Isolates read-only conversational reasoning from state-mutating transactional APIs.", "required": true, "acceptable_evidence": ["Technical keywords: tool calling, grounded retrieval, odds, schedules.", "Classifies user intent into informational queries (odds, schedules, rules) vs transactional actions (placing bets, deposits, withdrawals).", "Routes informational queries to grounded retrieval pipelines and transactional intents to strictly validated tool calling."]}, {"id": "KP2", "description": "Prevents generative LLMs from executing bets autonomously without explicit user review and confirmation.", "required": true, "acceptable_evidence": ["Technical keywords: betting AI safety, human confirmation, financial transaction boundary, deterministic bet execution, state machine.", "Prevents generative LLMs from executing bets autonomously without explicit user review and confirmation.", "Enforces that the model only drafts wager slips, requiring two-factor authorization and explicit UI confirmation before executing bets against ledger APIs."]}, {"id": "KP3", "description": "Two-Phase Transaction Confirmation & Schema Validation: Implements interactive preview, balance verification, and explicit confirmation modals.", "required": true, "acceptable_evidence": ["Technical keywords: UI, phase transaction, schema validation, structures transactions.", "Structures transactions in two phases: Assistant drafts parameters (wager amount, odds, selection) -> UI renders a confirmation slip -> User confirms explicitly.", "Validates wallet balance, minimum/maximum wager limits, and active odds expiration before committing transactions.", "Uses idempotent transaction tokens (UUIDs) to prevent duplicate bet placement on double clicks or network retries."]}, {"id": "KP4", "description": "Responsible Gaming Safeguards, Compliance & Tamper-Evident Audit: Enforces regulatory guardrails and immutable logging.", "required": false, "acceptable_evidence": ["Technical keywords: rate limiting, evident audit, daily deposit caps, loss limits.", "Enforces responsible gaming limits (daily deposit caps, loss limits, self-exclusion triggers) directly in backend business logic.", "Logs full conversational traces, tool parameters, user confirmations, and transaction IDs for regulatory compliance auditing.", "Implements session-level rate limiting and fraud anomaly detection for suspicious betting patterns."]}], "critical_failures": ["Allows the conversational LLM to execute financial bets or account fund transfers directly without an explicit user confirmation step.", "Relies on prompt instructions alone to enforce wagering limits and financial authorization without server-side validation."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you design an AI platform that allows users to bring their own models while maintaining standardization and abstraction?', '{"key_points": [{"id": "KP1", "description": "Unified Model Contract & Standardized Inference Protocol: Defines universal request/response schemas and communication contracts across model backends.", "required": true, "acceptable_evidence": ["Technical keywords: gRPC, API, inference protocol, response schemas.", "Standardizes on unified API protocols (e.g., OpenAI-compatible endpoints, KServe v2 Data Plane, or standardized gRPC schemas).", "Requires user models to implement standardized lifecycle endpoints (/health, /metadata, /predict, /tokenize)."]}, {"id": "KP2", "description": "Supports diverse backends (PyTorch, ONNX, Hugging Face, custom Docker images, external third-party API endpoints) via adapter wrappers.", "required": true, "acceptable_evidence": ["Technical keywords: Triton Inference Server, ONNX Runtime, PyTorch TorchScript, multi-model serving, model repository.", "Supports diverse backends (PyTorch, ONNX, Hugging Face, custom Docker images, external third-party API endpoints) via adapter wrappers.", "Integrates Triton Inference Server with dynamic model loading, supporting ONNX Runtime, TensorRT, and PyTorch backends with GPU concurrency."]}, {"id": "KP3", "description": "Containerized Runtime Sandboxing & Resource Isolation: Isolates custom model execution environments while managing compute allocation.", "required": true, "acceptable_evidence": ["Technical keywords: Kubernetes, KEDA, runtime sandboxing, resource isolation.", "Deploys user-submitted models in isolated container runtimes (Kubernetes pods with gVisor/Kata sandboxing or dedicated serverless GPUs).", "Enforces strict compute limits (GPU memory limits, CPU quotas, maximum inference execution timeouts).", "Implements automated health checking, cold-start scaling, and replica autoscaling (KEDA) based on queue depth."]}, {"id": "KP4", "description": "Centralized Governance, Telemetry & Guardrail Enforcement: Injects platform-wide monitoring, rate limiting, and safety checks transparently.", "required": false, "acceptable_evidence": ["Technical keywords: rate limiting, p95, p99, PII.", "Injects universal platform gateway middleware enforcing authentication, per-tenant rate limits, and token quota metering.", "Collects standardized telemetry (p50/p95/p99 latency, throughput, error codes, token consumption) across all deployed models.", "Applies uniform platform guardrails (PII masking, content moderation) transparently upstream of custom model inference."]}], "critical_failures": ["Allows arbitrary user-provided model code to execute directly on host infrastructure without containerization or security sandboxing.", "Fails to define a standardized interface contract, requiring bespoke platform code changes for every newly added model."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'HARD', 'BROAD', 210, 'How would you design and improve reliability, memory, and personalization in an AI-driven chat system?', '{"key_points": [{"id": "KP1", "description": "Inference Reliability & Fault-Tolerant Orchestration: Hardens chat generation against provider outages, schema failures, and rate limits.", "required": true, "acceptable_evidence": ["Technical keywords: exponential backoff, jitter, rate limiting, SLA.", "Implements multi-provider model routing with automatic fallback cascades (e.g., primary frontier model -> secondary fallback -> local SLA model).", "Applies exponential backoff with jitter and circuit breakers to handle API rate limiting and upstream timeouts."]}, {"id": "KP2", "description": "Enforce structured output parsing (Pydantic / instructor) with automated self-correction loops when responses fail schema validation.", "required": true, "acceptable_evidence": ["Technical keywords: Instructor library, Pydantic validation, structured JSON output, retry on error, schema enforcement.", "Enforces structured output parsing (Pydantic / instructor) with automated self-correction loops when responses fail schema validation.", "Uses Instructor with Pydantic BaseModel to parse model outputs, triggering automatic validation retries with feedback when schemas fail."]}, {"id": "KP3", "description": "Multi-Tiered Memory Architecture & Context Distillation: Combines real-time session caching with long-term semantic profile stores.", "required": true, "acceptable_evidence": ["Technical keywords: tiered memory, context distillation, session caching, session memory.", "Maintains working session memory in fast low-latency key-value stores and durable user facts in semantic vector/graph stores.", "Implements asynchronous memory consolidation pipelines that extract key user facts, preferences, and recurring entities after sessions close."]}, {"id": "KP4", "description": "Use semantic relevance ranking and context compression to inject only contextually salient historical facts into prompt budgets.", "required": false, "acceptable_evidence": ["Technical keywords: cross-encoder reranker, FlashRank, context compression, LLMLingua, top-k pruning.", "Uses semantic relevance ranking and context compression to inject only contextually salient historical facts into prompt budgets.", "Applies cross-encoder reranking (e.g., FlashRank or BGE-Reranker) and token compression (LLMLingua) to eliminate irrelevant context before prompt assembly."]}, {"id": "KP5", "description": "Dynamic Personalization & Safe Boundary Enforcement: Tailors tone, depth, and actions to user preferences while preserving privacy.", "required": false, "acceptable_evidence": ["Technical keywords: user isolation, facing memory, boundary, enforcement.", "Adapts response tone, verbosity, and technical complexity dynamically based on authenticated user skill level and explicit preferences.", "Enforces hard multi-tenant user isolation so personalized context never leaks across organizational boundaries.", "Provides user-facing memory management interfaces enabling users to view, correct, or delete stored personalization attributes."]}], "critical_failures": ["Relies on a single model endpoint without retry logic, rate limit handling, or fallback mechanisms, leaving the system fragile.", "Appends uncompressed conversation history indefinitely, inevitably blowing past token limits and degrading response quality."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you design confidence thresholds and escalation mechanisms for ambiguous or low-confidence predictions?', '{"key_points": [{"id": "KP1", "description": "Confidence Metric Formulation & Uncertainty Calibration: Quantifies prediction confidence using statistical calibration and consensus techniques.", "required": true, "acceptable_evidence": ["Technical keywords: temperature, confidence, metric, formulation.", "Calculates confidence scores using log-probability aggregation, Platt scaling/temperature scaling, or classifier output probabilities.", "Uses self-consistency (multiple sampling paths) or ensemble agreement to measure model uncertainty on generative tasks."]}, {"id": "KP2", "description": "Evaluate semantic ambiguity using retrieval distance scores (low similarity in vector search) and intent classifier margin gaps.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval cosine distance, confidence scoring, negative retrieval, human escalation, uncertainty quantification.", "Evaluates semantic ambiguity using retrieval distance scores (low similarity in vector search) and intent classifier margin gaps.", "Measures top-1 chunk cosine distance and entropy of logit distributions to route uncertain answers to human customer support queues."]}, {"id": "KP3", "description": "Tiered Action Thresholds & Automated Routing: Directs requests into distinct execution paths based on calibrated confidence bands.", "required": true, "acceptable_evidence": ["Technical keywords: automated routing, financial transactions, autonomous execution, escalate to human.", "Establishes a three-tier threshold model: High Confidence (autonomous execution), Medium Confidence (prompt user for clarification), Low Confidence (escalate to human / fallback).", "Triggers interactive disambiguation dialogues when confidence is borderline, asking the user targeted multiple-choice questions.", "Enforces stricter confidence thresholds for high-stakes actions (financial transactions, healthcare advice, legal actions)."]}, {"id": "KP4", "description": "Human-in-the-Loop (HITL) Queue & Continuous Calibration: Routes unresolved low-confidence cases to human specialists and feeds corrections into active learning.", "required": false, "acceptable_evidence": ["Technical keywords: HITL, fine-tuning, human-in-the-loop.", "Enqueues low-confidence predictions into a priority review queue with pre-populated context and model rationale for human reviewers.", "Maintains continuous calibration curves (reliability diagrams) tracking expected accuracy vs observed accuracy over time.", "Feeds human-reviewed and resolved edge cases back into golden datasets for model fine-tuning and prompt refinement."]}], "critical_failures": ["Treats raw, uncalibrated model outputs as certain, executing high-stakes actions despite low semantic confidence.", "Fails to provide an escalation or fallback path, hallucinating responses when domain context is ambiguous or missing."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you design proper file validation (type, size, format) and ensure safe uploads?', '{"key_points": [{"id": "KP1", "description": "Cryptographic MIME & Content Signature Inspection: Validates file headers and magic bytes rather than trusting client filenames or MIME headers.", "required": true, "acceptable_evidence": ["Technical keywords: file.pdf, MIME, file signatures, file.pdf.exe.", "Inspects file magic bytes (e.g., using libmagic / file signatures) to verify true file format independently of file extension.", "Rejects executable formats, double-extensions (e.g., file.pdf.exe), and unapproved document types against strict allowlists."]}, {"id": "KP2", "description": "Sanitizes filenames to prevent path traversal attacks (e.g., ../../../etc/passwd) and assigns random UUID storage keys.", "required": true, "acceptable_evidence": ["Technical keywords: secure_filename, path traversal, magic bytes, MIME validation, anti-virus scanning, S3 presigned upload.", "Sanitizes filenames to prevent path traversal attacks (e.g., ../../../etc/passwd) and assigns random UUID storage keys.", "Validates file headers via libmagic (magic bytes rather than file extensions) and strips directory traversal sequences using werkzeug.secure_filename."]}, {"id": "KP3", "description": "Pre-Signed Storage Ingestion & Buffer Protection: Offloads uploads directly to isolated cloud storage with strict size and streaming constraints.", "required": true, "acceptable_evidence": ["Technical keywords: S3, GCS, API, upload payload.", "Generates short-lived, presigned upload URLs (S3, GCS) with strict Content-Length and Content-Type restrictions enforced by storage policies.", "Enforces hard upload payload size limits at both API gateway and cloud storage layers to prevent DoS attacks.", "Streams uploads directly without buffering entire multi-gigabyte files into web server application memory."]}, {"id": "KP4", "description": "Antivirus Quarantine, Sandboxing & Parsing Isolation: Quarantines uploaded files for asynchronous malware scanning and isolated parsing.", "required": false, "acceptable_evidence": ["Technical keywords: PDF, RCE, parsing isolation, parsing validation.", "Stores incoming files in an isolated quarantine bucket pending automated asynchronous antivirus/malware scanning (e.g., ClamAV).", "Executes document parsers (PDF, Office extractors) in unprivileged, network-isolated sandboxes or ephemeral containers to mitigate RCE vulnerabilities.", "Promotes files to production storage buckets only after passing security scans and parsing validation."]}], "critical_failures": ["Validates file types solely by checking the user-supplied file extension or client-provided Content-Type header.", "Executes document parsers directly in privileged backend containers without file sanitization or sandboxing."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'How would you design risk budgets and worst-case bounds to prevent repeated poor recommendations?', '{"key_points": [{"id": "KP1", "description": "Dynamic Risk Budgeting & Exploration Caps: Limits experimental recommendations per user session to bound downside churn.", "required": true, "acceptable_evidence": ["Technical keywords: rejections, skips, negative feedback.", "Defines a quantitative risk budget constraining how many low-confidence or exploratory items a user receives per session.", "Dynamically contracts the exploration budget following negative user signals (rejections, skips, negative feedback)."]}, {"id": "KP2", "description": "Balances exploration and exploitation using constrained multi-armed bandit formulations (e.g., Upper Confidence Bound with risk constraints).", "required": true, "acceptable_evidence": ["Technical keywords: contextual bandits, Upper Confidence Bound, risk budgets, conditional value at risk (CVaR), exploration vs exploitation.", "Balances exploration and exploitation using constrained multi-armed bandit formulations (e.g., Upper Confidence Bound with risk constraints).", "Implements constrained Upper Confidence Bound (UCB) algorithms with hard risk budget limits, bounding worst-case financial exposure under uncertainty."]}, {"id": "KP3", "description": "Negative Signal Propagation & Category Fatigue Dampening: Implements exponential decay and frequency capping on repeatedly rejected attributes.", "required": true, "acceptable_evidence": ["Technical keywords: recommendation cluster, negative, signal, propagation.", "Applies immediate hard penalties or temporary category cool-downs when a user explicitly rejects an item or recommendation cluster.", "Enforces frequency capping to prevent serving identical or near-identical candidates in consecutive recommendation cycles.", "Decreases the user affinity score for shared tags/features of rejected items to steer subsequent rankings away from rejected spaces."]}, {"id": "KP4", "description": "Worst-Case Fallback Bounds & SLA Circuit Breakers: Degrades gracefully to high-confidence baseline items when risk budgets are exhausted.", "required": false, "acceptable_evidence": ["Technical keywords: SLA, worst, bounds, circuit.", "Establishes worst-case fallback policies that serve proven, high-consensus popular items when recommendation confidence drops below minimum utility thresholds.", "Monitors aggregate user churn and negative feedback rates with automated circuit breakers that halt unproven ranking models.", "Maintains simulation environments to evaluate recommendation disaster scenarios before rolling out new ranking algorithms."]}], "critical_failures": ["Continues aggressively serving repeatedly rejected items or categories without frequency capping or negative feedback penalties.", "Allows exploration algorithms to operate unconstrained without a risk budget, degrading user retention."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you detect anomalies in real-time logs and trigger automated responses without human intervention?', '{"key_points": [{"id": "KP1", "description": "Real-Time Streaming Ingestion & Log Pattern Parsing: Ingests and parses unstructured logs at high throughput into structured anomaly streams.", "required": true, "acceptable_evidence": ["Technical keywords: Kafka, streaming pipelines, ingestion latency, Vector.", "Ingests distributed logs in real time via streaming pipelines (Kafka, Vector, Fluentbit) with low ingestion latency.", "Applies online log template parsing (e.g., Drain algorithm) to extract static templates and variable parameters from unstructured logs.", "Aggregates error frequency counts and rate of novel log message templates across sliding time windows."]}, {"id": "KP2", "description": "Multi-Faceted Anomaly Detection Algorithms: Identifies volumetric spikes, structural drift, and semantic errors using statistical and ML techniques.", "required": true, "acceptable_evidence": ["Technical keywords: ML, EWMA, IQR, structural drift.", "Applies adaptive statistical thresholds (z-score, EWMA, rolling IQR) to detect volumetric error rate spikes.", "Employs machine learning models (Isolation Forests, autoencoders) or embedding distance shifts to catch semantic log anomalies.", "Correlates log anomalies across multiple nodes and microservices using shared trace IDs to avoid localized false alarms."]}, {"id": "KP3", "description": "Bounded Automated Remediation & Circuit-Breaker Safety: Triggers pre-approved automated recovery actions while safeguarding against remediation storms.", "required": false, "acceptable_evidence": ["Technical keywords: SLA, reboot loops, automated, circuit.", "Executes deterministic automated remediation runbooks (e.g., restarting unhealthy pods, rotating credentials, autoscaling replicas).", "Implements remediation cooldowns, maximum execution caps, and circuit breakers to prevent infinite reboot loops.", "Dispatches high-priority alerts with automated diagnostic summaries to on-call teams if automated remediation fails within SLA."]}], "critical_failures": ["Triggers unconstrained automated actions (like mass server reboots or cluster teardowns) without rate limits or circuit breakers.", "Relies purely on batch nightly log processing rather than real-time streaming detection."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'How would you ensure efficient lookup and updates for tasks in your system?', '{"key_points": [{"id": "KP1", "description": "Database Schema Design & Strategic Indexing: Optimizes storage schemas and index structures for O(1) or O(log n) task lookups.", "required": true, "acceptable_evidence": ["Technical keywords: O(1), O(log n), user_id, created_at.", "Assigns immutable, indexed primary keys (UUIDv7, auto-increment bigint) for O(1) primary key lookup.", "Creates composite B-tree indices on frequent query combinations (e.g., (user_id, status, created_at)) to prevent full table scans.", "Chooses storage engines matching access patterns (relational with ACID guarantees vs key-value/document stores for flexible schemas)."]}, {"id": "KP2", "description": "Distributed Caching & Invalidation Architecture: Accelerates read performance using low-latency in-memory cache tiers.", "required": true, "acceptable_evidence": ["Technical keywords: Redis, TTL, cache-aside, invalidation architecture.", "Implements cache-aside or write-through caching in Redis for hot task records to achieve sub-millisecond retrieval.", "Applies atomic cache invalidation or TTL expiration to prevent stale task state after updates.", "Leverages Redis Hashes or Sorted Sets for high-speed task status querying and priority scheduling."]}, {"id": "KP3", "description": "Concurrency Control & Atomic State Mutations: Protects concurrent writes using optimistic locking or database transactions.", "required": false, "acceptable_evidence": ["Technical keywords: current_version, SELECT, atomic state, optimistic locking.", "Implements optimistic concurrency control via version numbers (version = version + 1 WHERE version = current_version) to handle write conflicts.", "Uses database-level row locking (SELECT ... FOR UPDATE) sparingly for high-contention critical state transitions.", "Batches high-volume bulk updates into single transactions to minimize connection overhead and disk I/O."]}], "critical_failures": ["Executes unindexed full table scans across millions of task records to perform routine status lookups.", "Permits concurrent task mutations without versioning or concurrency control, leading to lost updates."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How would you ensure that cards can be correctly compared and ordered when determining the highest card in a game?', '{"key_points": [{"id": "KP1", "description": "Card Data Modeling & Explicit Rank Valuations: Encapsulates card representations using strongly-typed enums and numerical mappings.", "required": true, "acceptable_evidence": ["Technical keywords: IntEnum, custom dataclass, Jack=11, Queen=12.", "Defines strongly-typed Card objects with discrete Rank and Suit attributes (e.g., IntEnum or custom dataclass).", "Assigns explicit numerical values to card ranks (e.g., 2-10 as face value, Jack=11, Queen=12, King=13, Ace=14).", "Explicitly handles game-specific rank variations (e.g., Ace low in 5-high straight vs Ace high)."]}, {"id": "KP2", "description": "Comparator Contract & Total Ordering Implementation: Implements consistent comparison operators satisfying strict weak ordering.", "required": true, "acceptable_evidence": ["Technical keywords: __lt__, __gt__, __eq__, __eq__ in Python.", "Implements comparator contracts (e.g., __lt__, __gt__, __eq__ in Python or Comparable<Card> in Java).", "Ensures the comparison satisfies irreflexivity, asymmetry, and transitivity to prevent sorting contradictions.", "Supports customizable comparator functions allowing dynamic suit ranking (e.g., trump suits in Spades or Bridge)."]}, {"id": "KP3", "description": "Tie-Breaking & Hand Evaluation Optimization: Handles identical ranks and computes highest card in O(n) or O(1).", "required": false, "acceptable_evidence": ["Technical keywords: O(1), O(n), suit precedence, declaring a draw.", "Defines explicit tie-breaking rules when card ranks are equal (suit precedence or declaring a draw).", "Finds the maximum card across a hand in O(n) time and O(1) space using a single linear scan or max() with key.", "Handles edge cases: empty hand inputs, invalid card values, duplicate deck configurations."]}], "critical_failures": ["Compares cards using raw alphanumeric string sorting (e.g., sorting ''10'' before ''2'' alphabetically).", "Fails to handle non-numerical face cards (Jack, Queen, King, Ace) in comparison logic."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How would you ensure the quality and relevance of matches generated by the system?', '{"key_points": [{"id": "KP1", "description": "Multi-Layered Candidate Matching Architecture: Combines hard constraint filtering, semantic embedding retrieval, and ranking models.", "required": true, "acceptable_evidence": ["Technical keywords: matching architecture, dual embeddings, location radius, price bounds.", "Applies deterministic pre-filtering for non-negotiable hard constraints (location radius, price bounds, availability).", "Leverages two-tower neural networks or dual embeddings to compute semantic affinity between user and target profiles.", "Ranks candidate pairs using a learned scoring model incorporating historical acceptance probabilities and interaction signals."]}, {"id": "KP2", "description": "Offline Ranking Metrics & Evaluation Harness: Evaluates match relevance using standardized recommendation benchmarks.", "required": true, "acceptable_evidence": ["Technical keywords: precision@k, NDCG, precision, MAP.", "Benchmarks ranking quality offline using NDCG@K (Normalized Discounted Cumulative Gain), MAP (Mean Average Precision), and Precision@K.", "Evaluates against historically holdout interaction datasets using walk-forward temporal splits.", "Measures match diversity and catalog coverage to prevent the system from over-recommending a tiny superstar subset."]}, {"id": "KP3", "description": "Online Feedback Loops, A/B Testing & Fairness Auditing: Verifies live match quality via conversion experiments and bias monitoring.", "required": false, "acceptable_evidence": ["Technical keywords: A/B testing, feedback loops, conversion metrics, match acceptance rate.", "Runs controlled A/B experiments measuring online conversion metrics (match acceptance rate, mutual message exchange, retention).", "Incorporates explicit user feedback (thumbs down, decline reasons) to update user preference vectors dynamically.", "Audits matching parity across demographic cohorts to prevent discriminatory bias in recommendations."]}], "critical_failures": ["Evaluates match quality purely on superficial single-attribute keyword matches without validating mutual preferences.", "Ignores hard user constraints, recommending matches that violate fundamental user requirements."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'How would you evaluate and select the best forecasting model using offline and online evaluation strategies?', '{"key_points": [{"id": "KP1", "description": "Time-Aware Offline Backtesting & Leakage Prevention: Employs expanding or rolling window validation respecting temporal causality.", "required": true, "acceptable_evidence": ["Technical keywords: sliding window, XGBoost, ML, window validation.", "Uses walk-forward (expanding or sliding window) validation, never randomly shuffling time-series data to avoid future lookahead leakage.", "Evaluates multiple horizon steps (1-day, 7-day, 30-day ahead) to measure forecast degradation over time.", "Compares complex ML/deep learning models (Prophet, XGBoost, DeepAR, Temporal Fusion Transformers) against strong naive baselines."]}, {"id": "KP2", "description": "Multi-Metric Evaluation Aligned with Business Loss: Computes scale-dependent and percentage error metrics reflecting cost asymmetries.", "required": true, "acceptable_evidence": ["Technical keywords: MAE, RMSE, WAPE, MAPE.", "Evaluates scale-dependent metrics (MAE, RMSE) and percentage/normalized metrics (WAPE, MAPE, MASE).", "Applies asymmetric loss functions when under-forecasting incurs higher business cost than over-forecasting (e.g., stockouts vs holding costs).", "Inspects residual distributions for serial autocorrelation and heteroskedasticity."]}, {"id": "KP3", "description": "Online Evaluation, Shadow Rollouts & Live Drift Tracking: Validates performance in production environments against live market shifts.", "required": false, "acceptable_evidence": ["Technical keywords: A/B testing, live drift, shadow pipelines, error drift.", "Deploys champion-challenger shadow pipelines running challenger models in parallel on real-time data feeds.", "Conducts live A/B testing on segmented regional or category cohorts, measuring business KPIs (inventory turns, fulfillment rate).", "Monitors live forecast error drift and input covariate shift to trigger automated model retraining."]}], "critical_failures": ["Uses standard randomized k-fold cross-validation on time-series data, introducing future lookahead leakage.", "Selects a forecasting model based on a single generic metric without evaluating asymmetric under/over-prediction costs."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How would you evaluate the effectiveness of the matchmaking system and iterate on improvements?', '{"key_points": [{"id": "KP1", "description": "Funnel Conversion Metrics & Success Definitions: Tracks the full engagement funnel from impression to sustained interaction.", "required": true, "acceptable_evidence": ["Technical keywords: conversion metrics, retention metrics, 30-day retention, session frequency.", "Measures key conversion rates: Match Impression -> Acceptance Rate -> Reciprocal Match Rate -> Meaningful Conversation Rate.", "Evaluates long-term retention metrics (30-day retention, session frequency) rather than vanity click counts.", "Monitors match balance and two-sided market liquidity so inbound interest is distributed sustainably across participants."]}, {"id": "KP2", "description": "Cohort Analysis & Failure Mode Diagnostics: Breaks down performance across demographic, activity, and tenure segments.", "required": true, "acceptable_evidence": ["Technical keywords: UI, power users, geographic markets, activity levels.", "Analyzes performance across user cohorts (new vs power users, geographic markets, activity levels).", "Conducts qualitative and quantitative analysis on unmatched users to identify cold-start and sparsity bottlenecks.", "Investigates confounders (seasonality, marketing campaigns, UI changes) before attributing conversion shifts solely to the algorithm."]}, {"id": "KP3", "description": "Iterative Feature Engineering & Controlled Experimentation: Leverages explicit feedback to refine embedding models and features via A/B testing.", "required": false, "acceptable_evidence": ["Technical keywords: A/B testing, response latency, negative signals, profile completion depth.", "Extracts high-signal features from user feedback (e.g., negative signals, response latency, profile completion depth).", "Executes randomized controlled A/B experiments to validate algorithm updates with statistical power analysis.", "Updates user embedding vectors dynamically using online learning or bandit exploration strategies."]}], "critical_failures": ["Optimizes purely for initial match clicks while ignoring downstream reciprocal engagement or retention.", "Attributes platform-wide conversion changes to algorithms without controlling for user growth or marketing campaign confounders."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How would you evaluate whether shifts in user segment distribution are contributing to the decline in first-month spend?', '{"key_points": [{"id": "KP1", "description": "Mix Shift Mathematical Decomposition: Deconstructs aggregate spend decline into segment-weight shifts versus within-segment behavior changes.", "required": true, "acceptable_evidence": ["Technical keywords: Weight_t * Spend_t, Weight_{t-1} * Spend_{t-1}, shift, mathematical.", "Applies mathematical decomposition: Delta Spend = Sum(Weight_t * Spend_t) - Sum(Weight_{t-1} * Spend_{t-1}).", "Isolates the ''Mix Effect'' (population shift toward historically lower-spending segments) from the ''Rate Effect'' (spend falling within fixed segments).", "Recognizes Simpson''s Paradox where aggregate spend declines even if spend within every individual segment remains flat or increases."]}, {"id": "KP2", "description": "Segment Stratification & Acquisition Channel Attribution: Segments new users by acquisition source, demographic attributes, and device types.", "required": true, "acceptable_evidence": ["Technical keywords: LTV, organic search, iOS, Android.", "Analyzes acquisition channel shifts (e.g., surge in lower-intent paid social vs high-intent organic search).", "Cross-tabulates user cohorts by geography, platform (iOS vs Android), and initial onboarding attributes.", "Evaluates whether marketing campaigns introduced low-LTV promo-hunter cohorts diluting the user base."]}, {"id": "KP3", "description": "Statistical Significance & Counterfactual Normalization: Conducts counterfactual simulations and formulates targeted mitigations.", "required": false, "acceptable_evidence": ["Technical keywords: statistical, significance, counterfactual, conducts.", "Calculates counterfactual baseline spend: what aggregate spend would have been if historical segment proportions had remained constant.", "Verifies statistical significance of spend differences using t-tests or bootstrap confidence intervals.", "Recommends targeted product or acquisition interventions based on whether the root cause is poor acquisition targeting or declining product value."]}], "critical_failures": ["Examines only overall aggregate average spend without decomposing user segments or acquisition channels.", "Fails to identify the mathematical difference between demographic mix shifts and actual behavioral spend declines."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How would you extend a text-based system to support multimodal data such as images and structured files?', '{"key_points": [{"id": "KP1", "description": "Multi-Format Ingestion & Specialized Parsing Pipeline: Ingests images, tables, PDFs, and structured data into normalized representation streams.", "required": true, "acceptable_evidence": ["Technical keywords: parquet, Transformer, OCR, BLIP-2.", "Applies OCR and visual layout parsers (Docling, Unstructured, Table Transformer) to parse tables and diagrams from complex PDFs.", "Generates automated text descriptions and metadata tags for images using vision captioning models (e.g., BLIP-2, GPT-4o-mini).", "Converts structured tabular files (CSV, Parquet) into normalized Markdown, JSON, or SQL-queryable relational tables."]}, {"id": "KP2", "description": "Unified Multimodal Vector Indexing & Joint Embeddings: Embeds diverse modalities into shared or paired embedding spaces.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, hybrid search, image_url, page_number.", "Utilizes joint multimodal embedding models (e.g., CLIP, SigLIP, or document-vision models like ColPali) to align text queries with image patches.", "Stores rich metadata payloads alongside vector embeddings (e.g., image_url, page_number, bounding_box, table_json).", "Applies hybrid search combining dense semantic multimodal search with sparse BM25 keyword matching over extracted text."]}, {"id": "KP3", "description": "Multimodal LLM Inference & Context Assembly: Prompts frontier vision-language models with interleaved text and image tokens.", "required": false, "acceptable_evidence": ["Technical keywords: LLM, image tokens, image token, response validation.", "Constructs interleaved prompt contexts passing relevant retrieved image crops and structured tables directly into multimodal LLMs.", "Optimizes image token consumption and latency by downsampling, cropping, or utilizing dynamic resolution tiling.", "Implements response validation ensuring generated citations reference specific image figures or spreadsheet rows."]}], "critical_failures": ["Discards image and layout data entirely, relying solely on unformatted OCR text without visual or tabular grounding.", "Fails to address token budget and latency implications when passing high-resolution raw images into vision LLMs."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How would you extend the program to calculate reader scores based on books read and pages, and output the top five readers by total points?', '{"key_points": [{"id": "KP1", "description": "Score Aggregation & Data Modeling: Maps input records into cumulative reader point totals using hash maps.", "required": true, "acceptable_evidence": ["Technical keywords: O(n), books_read, book_weight, pages_read.", "Aggregates total reader points using a dictionary or hash map (e.g., points = books_read * book_weight + pages_read * page_weight).", "Processes input data in a single O(N) pass over all reading records.", "Handles multiple entries per reader by accumulating points incrementally."]}, {"id": "KP2", "description": "Optimal Top-5 Selection Using Min-Heap: Selects top readers in O(N log K) time using a bounded min-heap of size K=5.", "required": true, "acceptable_evidence": ["Technical keywords: heap, time complexity, O(n log n), O(N log K).", "Maintains a min-heap of size K=5: pushes (score, reader_id); if heap size exceeds 5, pops the minimum element.", "Achieves O(N log K) time complexity and O(K) additional space rather than sorting the entire N-element list in O(N log N).", "Extracts final top 5 sorted in descending order from the heap."]}, {"id": "KP3", "description": "Tie-Breaking, Input Edge Cases & Complexity Guarantees: Resolves score ties and handles edge conditions cleanly.", "required": false, "acceptable_evidence": ["Technical keywords: top-k, O(n log n), earliest timestamp, N log N.", "Implements deterministic tie-breaking (e.g., alphabetical by reader name or earliest timestamp) when scores match.", "Handles edge cases: fewer than 5 total readers, zero pages read, negative numbers, empty input lists.", "Contrasts heap-based top-K with full sorting (O(N log N)) and Quickselect (average O(N))."]}], "critical_failures": ["Sorts the entire list of millions of readers in memory when only top 5 are needed, wasting O(N log N) time and memory.", "Fails to accumulate points correctly across multiple records for the same reader."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'How would you generate and manage unique IDs for tasks in this system?', '{"key_points": [{"id": "KP1", "description": "Unique ID Generation Strategy Evaluation: Compares centralized vs distributed generation algorithms and selects an appropriate scheme.", "required": true, "acceptable_evidence": ["Technical keywords: generators, B-tree index, Snowflake, ID.", "Evaluates UUIDv4 (random 128-bit, collision resistant but causes B-tree index fragmentation due to lack of locality).", "Recommends time-ordered 128-bit UUIDv7 or ULID (timestamp prefix + randomness) for monotonic index insertion efficiency.", "Considers distributed 64-bit ID generators (Twitter Snowflake: timestamp + worker ID + sequence number) for compact integer keys."]}, {"id": "KP2", "description": "Database Indexing & Performance Optimization: Analyzes storage footprint and B-tree page split implications.", "required": true, "acceptable_evidence": ["Technical keywords: database indexing, halve index, increment locks.", "Explains that monotonically increasing IDs prevent expensive random B-tree page splits in database clustering indices.", "Stores 128-bit UUIDs as binary(16) rather than 36-character strings to halve index memory consumption.", "Avoids single-point-of-failure database auto-increment locks in horizontally scaled, multi-region architectures."]}, {"id": "KP3", "description": "Collision Resistance, Clock Skew & Idempotency: Protects against clock drift and duplicate task creation.", "required": false, "acceptable_evidence": ["Technical keywords: NTP, clock drift, supplied idempotency.", "Addresses clock skew in Snowflake-style algorithms (handling backwards clock jumps via sequence buffering or NTP monitoring).", "Pairs unique task IDs with client-supplied idempotency keys to ensure retry safety on network timeouts.", "Ensures task IDs do not expose sensitive business volume information to external users."]}], "critical_failures": ["Proposes using non-unique human-readable task names as primary database keys.", "Relies on a single central database sequence across multi-region distributed nodes without addressing network latency or SPOF."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you handle addressing learner doubts and ensuring engagement during interactive sessions?', '{"key_points": [{"id": "KP1", "description": "Psychological Safety & Inclusive Doubt Validation: Fosters a welcoming environment where learners feel safe asking foundational questions.", "required": true, "acceptable_evidence": ["Technical keywords: doubt validation, thanks for asking!, live voice, chat.", "Normalizes confusion explicitly (e.g., ''This is a notoriously tricky concept; thanks for asking!'').", "Validates the student''s question before answering, highlighting why the doubt is insightful.", "Provides multi-channel avenues for asking questions (live voice, chat, anonymous polls, Slack channels)."]}, {"id": "KP2", "description": "Active Engagement & Socratic Scaffolding: Engages students interactively through live coding, polls, and guided discovery rather than lecturing.", "required": true, "acceptable_evidence": ["Technical keywords: active, engagement, socratic, scaffolding.", "Uses the Socratic method, guiding learners to discover answers by asking targeted stepping-stone questions.", "Incorporates quick check-for-understanding pulses (interactive polls, thumbs-up reactions, live debugging challenges).", "Alternates between conceptual explanation, visual diagrams, and hands-on coding demos every 10-15 minutes."]}, {"id": "KP3", "description": "Pacing Management & Differentiated Instruction: Balances individual doubt deep-dives against cohort syllabus pacing.", "required": false, "acceptable_evidence": ["Technical keywords: pacing, management, differentiated, instruction.", "Addresses doubts concisely; if an edge case is highly advanced or off-topic, parks it gracefully for office hours.", "Provides layered explanations (simple conceptual analogy first, followed by optional advanced architectural nuance).", "Follows up with written summaries, curated resources, and code snippets in discussion forums post-session."]}], "critical_failures": ["Belittles or condescends to learners when they ask basic or fundamental questions.", "Monologues for hours without checking student comprehension or encouraging interactive participation."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How would you handle cold-start scenarios for new products with no historical data?', '{"key_points": [{"id": "KP1", "description": "Content-Based Embedding & Metadata Bootstrapping: Generates initial representations from product descriptions, categories, and multimodal assets.", "required": true, "acceptable_evidence": ["Technical keywords: vision embeddings, content, based, metadata.", "Extracts rich text and vision embeddings from product titles, specifications, tags, and images using foundation models.", "Locates nearest neighbor products in the existing catalog using embedding similarity to inherit baseline interaction priors.", "Categorizes new products into hierarchical taxonomies to leverage category-level average conversion rates."]}, {"id": "KP2", "description": "Exploration Bandits & Uncertainty-Aware Ranking: Gives new items controlled initial exposure to collect interaction data rapidly.", "required": true, "acceptable_evidence": ["Technical keywords: Thompson Sampling, LinUCB, 5-10% of impressions, uncertainty.", "Implements contextual multi-armed bandit algorithms (e.g., Thompson Sampling, LinUCB) to balance exploration with exploitation.", "Injects new products into recommendation carousels with an allocated exploration traffic budget (e.g., 5-10% of impressions).", "Uses upper confidence bounds so items with high variance (uncertainty) are favored for initial discovery impressions."]}, {"id": "KP3", "description": "Rapid Real-Time Prior Updating & Heuristic Fallbacks: Updates preference models on early interactions and bounds downside risk.", "required": false, "acceptable_evidence": ["Technical keywords: rapid, prior, updating, heuristic.", "Transitions items rapidly from content-based priors to collaborative filtering models as early click/purchase signals arrive.", "Falls back to category-level bestsellers and trending heuristics if content metadata is sparse or uninformative.", "Monitors conversion velocity to deprioritize items that fail to convert after reaching minimum impression thresholds."]}], "critical_failures": ["Never recommends new items because collaborative filtering algorithms require existing interaction histories (rich-get-richer trap).", "Spams users exclusively with unproven new products, degrading user experience and conversion."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How would you handle conflicts when multiple users prefer the same profile while maintaining fairness and satisfaction?', '{"key_points": [{"id": "KP1", "description": "Two-Sided Matching Optimization & Capacity Constraints: Formalizes matching as a constrained optimization problem balancing mutual utility.", "required": true, "acceptable_evidence": ["Technical keywords: stable marriage, sided, matching, formalizes.", "Models the ecosystem as a two-sided matching problem using algorithms like Gale-Shapley (stable marriage) or maximum weight bipartite matching.", "Enforces capacity limits (maximum daily concurrent connections or inbound match queue caps) on popular profiles."]}, {"id": "KP2", "description": "Optimizes global platform social welfare rather than greedy first-come-first-served allocation.", "required": true, "acceptable_evidence": ["Technical keywords: distributed booking lock, Redis Redlock, auction mechanism, social welfare optimization, fair queuing.", "Optimizes global platform social welfare rather than greedy first-come-first-served allocation.", "Resolves booking conflicts using distributed Redis locks (Redlock) combined with a priority-weighted fair scheduling algorithm."]}, {"id": "KP3", "description": "Exposure Throttling & Popularity Dampening: Dampens superstar exposure and distributes visibility across long-tail candidates.", "required": true, "acceptable_evidence": ["Technical keywords: temperature, exposure, throttling, popularity.", "Throttles the recommendation frequency of heavily requested profiles once their active queue reaches capacity.", "Applies negative feedback penalties or Softmax temperature scaling to disperse recommendations across comparable profiles.", "Prevents popular profiles from being overwhelmed with hundreds of inbound messages while others receive none."]}, {"id": "KP4", "description": "Fair Alternative Diversification & User Satisfaction Retention: Provides high-quality, personalized substitutes to unselected users.", "required": false, "acceptable_evidence": ["Technical keywords: satisfaction metrics, alternative, diversification, satisfaction.", "Identifies nearest neighbor substitute profiles using semantic embeddings to serve immediately to users experiencing contention.", "Provides transparent status updates or waiting queues rather than silent rejections.", "Tracks Gini coefficients and user satisfaction metrics across percentiles to ensure fair platform-wide utility distribution."]}], "critical_failures": ["Uses an unconstrained first-come-first-served approach that routes 90% of traffic to the top 1% of profiles, collapsing two-sided market liquidity.", "Leaves disappointed users with no recommendations when their preferred profile is unavailable."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How would you handle incremental factorial computations efficiently when extending from a previously computed value?', '{"key_points": [{"id": "KP1", "description": "Mathematical Invariant & Incremental Extension Logic: Extends previous factorial states using partial product multiplication.", "required": true, "acceptable_evidence": ["Technical keywords: O(1), O(n), O(n - m), factorial states.", "Formulates the recurrence: n! = m! * prod_{i=m+1}^n i for n > m, reducing time from O(n) to O(n - m).", "Maintains a cache of previously computed factorials (hash map or precomputed array) for O(1) lookup of nearest predecessor m.", "If n < m, handles the query via direct cache lookup in O(1) or modular arithmetic where applicable."]}, {"id": "KP2", "description": "Cache Lookup & Binary Search Nearest Neighbor: Locates the optimal precomputed checkpoint to minimize multiplications.", "required": true, "acceptable_evidence": ["Technical keywords: binary search, O(log C), TreeMap, log C.", "Uses a sorted array or TreeMap of checkpoints to binary search for the largest checkpoint m <= n in O(log C) time.", "Multiplies only the delta range [m + 1, n] starting from the retrieved checkpoint value m!", "Stores intermediate results dynamically into the cache to speed up subsequent queries."]}, {"id": "KP3", "description": "Arbitrary Precision & Memory Scalability: Handles large integer growth and memory footprint.", "required": false, "acceptable_evidence": ["Technical keywords: precision, BigInteger, input validation, Java.", "Recognizes rapid factorial growth (e.g., 20! overflows 64-bit integers), using BigInteger (Java) or Python''s native arbitrary precision.", "Applies prime factorization or divide-and-conquer balanced multiplication for calculating large ranges [m + 1, n].", "Handles boundary cases cleanly: 0! = 1, negative input validation, identical repeated queries."]}], "critical_failures": ["Recomputes factorial from 1 to n from scratch on every call, ignoring the existing precomputed value m!.", "Fails to account for 64-bit integer overflow when calculating factorials beyond 20!."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How would you handle mismatches in the two-pointer approach when allowing up to two character removals?', '{"key_points": [{"id": "KP1", "description": "Two-Pointer Inward Traversal & Match Invariant: Scans from opposite ends inward while characters match.", "required": true, "acceptable_evidence": ["Technical keywords: k = 2, pointer, inward, traversal.", "Initializes pointers left = 0 and right = len(s) - 1, incrementing left and decrementing right while s[left] == s[right].", "Maintains a state tracker for remaining character deletions allowed (k = 2).", "Correctly identifies the first mismatch point where s[left] != s[right]."]}, {"id": "KP2", "description": "Branching Recursion on Mismatch: Explores both possible deletions (left or right) and decrements the deletion budget.", "required": true, "acceptable_evidence": ["Technical keywords: is_palindrome, left, right, left + 1.", "Upon mismatch s[left] != s[right], branches into two recursive checks: is_palindrome(left + 1, right, k - 1) OR is_palindrome(left, right - 1, k - 1).", "Returns True if either branch successfully converges with k >= 0 deletions used.", "If k == 0 and a mismatch occurs, immediately terminates and returns False."]}, {"id": "KP3", "description": "Branching Factor Analysis & Asymptotic Complexity: Proves O(N) time and O(k) space complexity.", "required": false, "acceptable_evidence": ["Technical keywords: time complexity, space complexity, O(1), O(n).", "Analyzes time complexity: for fixed k=2, branching depth is at most 2, yielding at most 2^2 = 4 linear passes -> O(N) total time.", "Analyzes space complexity: O(k) recursion stack depth (or O(1) iterative equivalent).", "Handles edge cases: empty strings, single character strings, already-palindromic inputs, strings requiring exactly 1 or 2 removals."]}], "critical_failures": ["Greedily chooses only one removal branch (e.g., always skipping left), missing valid palindrome paths on alternative branches.", "Allows unbounded recursion without tracking the deletion budget k, leading to exponential O(2^N) complexity."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'How would you handle missing, sparse, or inconsistent user data in the matchmaking process?', '{"key_points": [{"id": "KP1", "description": "Data Cleansing & Attribute Imputation Pipelines: Resolves inconsistent entries and imputes missing demographic/preference fields.", "required": true, "acceptable_evidence": ["Technical keywords: KNN, imputation pipelines, rule validation, birthdate.", "Applies domain-specific rule validation to clean conflicting data (e.g., birthdate vs stated age discrepancies).", "Imputes missing categorical attributes using mode imputation, cohort-level priors, or supervised KNN imputation.", "Uses dedicated ''unspecified'' indicator flags rather than arbitrary default values so models learn missingness patterns."]}, {"id": "KP2", "description": "Embedding-Based Representation for Sparse Profiles: Leverages implicit behavioral embeddings and matrix factorization.", "required": true, "acceptable_evidence": ["Technical keywords: ALS, behavioral embeddings, based, representation.", "Extracts latent user vectors using matrix factorization (ALS) or graph neural networks that naturally handle sparse interaction matrices.", "Infers missing explicit preferences from implicit behavioral clickstream and search telemetry.", "Down-weights matching confidence scores for sparse profiles to prevent overconfident recommendation mistakes."]}, {"id": "KP3", "description": "Progressive Profiling & Uncertainty-Aware Matching: Prompts users for high-impact missing attributes iteratively.", "required": false, "acceptable_evidence": ["Technical keywords: progressive, uncertainty, aware, matching.", "Prompts users with micro-questions during onboarding or active sessions to gather highest-entropy missing attributes.", "Relaxes strict filters to soft probabilistic similarity penalties when user preference fields are unpopulated.", "Monitors match acceptance rates across profile completeness tiers to measure the impact of data sparsity."]}], "critical_failures": ["Drops or excludes all users with incomplete profiles from the matchmaking pool entirely.", "Fills missing attributes with arbitrary defaults without missingness indicators, distorting user matching representations."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you handle password-protected PDFs that cannot be directly processed by standard libraries?', '{"key_points": [{"id": "KP1", "description": "Encryption Detection & Pre-Flight PDF Inspection: Detects document encryption flags before sending files to downstream parsers.", "required": true, "acceptable_evidence": ["Technical keywords: PDF, document encryption, PyPDF, pdfminer.", "Inspects PDF trailers/dictionaries for the /Encrypt key using low-level libraries (PyPDF, pdfminer, qpdf) to identify encryption upfront.", "Catches PDFPasswordIncorrect / EncryptedPDF exceptions gracefully without crashing ingestion worker processes.", "Distinguishes user-password protected documents (requires password to view) from owner-password documents (requires password to print/edit)."]}, {"id": "KP2", "description": "Secure Credential Resolution & Programmatic Decryption: Unlocks documents using secrets managers or secure user prompt workflows.", "required": true, "acceptable_evidence": ["Technical keywords: AWS, HashiCorp, UI, AWS Secrets Manager.", "Retrieves pre-registered client passwords securely from enterprise secrets managers (AWS Secrets Manager, HashiCorp Vault).", "Triggers an asynchronous notification or UI prompt requesting the authenticated user to provide the document decryption key.", "Decrypts documents in ephemeral, memory-only buffers (e.g., using qpdf or pikepdf) without saving decrypted files to unencrypted persistent disks."]}, {"id": "KP3", "description": "Dead-Letter Queue Triage & Security Compliance: Quarantines un-decryptable files and protects user-supplied passwords in memory.", "required": false, "acceptable_evidence": ["Technical keywords: Datadog, dead-letter queue, DLQ, Sentry.", "Routes persistently locked documents to a Dead-Letter Queue (DLQ) with structured error metadata for user follow-up.", "Never logs user-supplied passwords in plaintext application logs or error reporting services (Sentry/Datadog).", "Cleans up decrypted in-memory buffers immediately after text extraction to comply with zero-retention data policies."]}], "critical_failures": ["Logs customer PDF passwords in plaintext log files or persistent databases.", "Allows encrypted PDF parsing failures to crash asynchronous worker queues without catch blocks or DLQ routing."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you identify and define valid and invalid test scenarios (black-box testing) for different types of users interacting with a product?', '{"key_points": [{"id": "KP1", "description": "Equivalence Partitioning & Boundary Value Derivation: Segments input domains into valid and invalid equivalence classes.", "required": true, "acceptable_evidence": ["Technical keywords: HTTP, equivalence partitioning, normal expected inputs, out-of-range.", "Partitions input fields into valid equivalence classes (normal expected inputs) and invalid classes (empty, out-of-range, malformed).", "Identifies precise boundary values (e.g., exactly at max character limits, 0, negative values, leap days) for testing.", "Constructs negative test cases asserting expected HTTP error codes (400, 401, 403, 422) and user-friendly error messages."]}, {"id": "KP2", "description": "User Persona Modeling & Role-Based Authorization Scenarios: Defines test matrices across authenticated user roles and privilege boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: based authorization, tests state, persona, modeling.", "Defines distinct user personas: Standard User, Admin, Unauthenticated Guest, and Adversarial / Malicious User.", "Verifies vertical and horizontal privilege escalation scenarios (e.g., ensuring a regular user cannot access /admin or another user''s resources).", "Tests state transition sequences (e.g., attempting checkout before adding items, or double-submitting forms)."]}, {"id": "KP3", "description": "Automated Black-Box Test Harness & Scenario Matrix: Translates derived scenarios into automated test suites in CI pipelines.", "required": false, "acceptable_evidence": ["Technical keywords: CI, session timeout, Playwright, Cypress.", "Documents test coverage in a structured scenario matrix linking requirements to automated test case IDs.", "Automates scenarios using end-to-end black-box frameworks (Playwright, Cypress, Postman/Newman).", "Verifies system resilience against rate-limiting, session timeout expirations, and unexpected concurrent tab actions."]}], "critical_failures": ["Tests exclusively positive happy-path scenarios, completely omitting negative, boundary, or unauthorized user cases.", "Fails to test role-based permission boundaries between different user personas."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How would you identify duplicate records in a Spark DataFrame?', '{"key_points": [{"id": "KP1", "description": "Aggregation & Subset Grouping to Isolate Duplicate Records: Identifies duplicate keys by grouping and filtering counts > 1.", "required": true, "acceptable_evidence": ["Technical keywords: DataFrame, df.groupBy, subset_columns, count > 1.", "Uses df.groupBy(subset_columns).count().filter(''count > 1'') to find exact duplicate key frequencies.", "Joins duplicate keys back to the original DataFrame to inspect all duplicate record instances.", "Explains the difference between full-row duplicate detection (distinct()) and subset-key duplicate detection (dropDuplicates([''key'']))."]}, {"id": "KP2", "description": "Window Functions & Analytical Deduping: Employs Window.partitionBy() with row_number() for fine-grained duplicate inspection and filtering.", "required": true, "acceptable_evidence": ["Technical keywords: Window.partitionBy, row_number, subset_columns, timestamp.", "Defines Window.partitionBy(subset_columns).orderBy(col(''timestamp'').desc()) to rank duplicate entries.", "Filters on row_number() > 1 to view all redundant records or row_number() == 1 to deduplicate while preserving the latest entry.", "Explains that window functions provide deterministic tie-breaking compared to non-deterministic dropDuplicates()."]}, {"id": "KP3", "description": "Distributed Shuffle & Skew Optimization: Addresses performance overhead and memory skew during distributed deduplication.", "required": false, "acceptable_evidence": ["Technical keywords: spark.sql, shuffle.partitions, matches cluster.", "Explains that groupBy and dropDuplicates trigger wide distributed shuffles across cluster executors.", "Identifies data skew bottlenecks when a single key has millions of duplicates, mitigating via salting or map-side pre-aggregations.", "Tunes spark.sql.shuffle.partitions to ensure partition sizing matches cluster core capacity."]}], "critical_failures": ["Converts the distributed Spark DataFrame to a local Pandas dataframe (toPandas()), causing driver Out-Of-Memory crashes.", "Fails to specify subset columns, mistakenly checking only full-row equality when business keys define uniqueness."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How would you implement and structure test cases to validate your palindrome solution, including edge cases?', '{"key_points": [{"id": "KP1", "description": "Test Architecture & Categorical Coverage: Structures test cases into distinct functional categories using modern testing frameworks.", "required": true, "acceptable_evidence": ["Technical keywords: pytest.mark, test architecture, @pytest.mark.parametrize, racecar.", "Implements parameterized test suites using pytest (e.g., @pytest.mark.parametrize) or unittest.", "Separates standard positive cases (e.g., ''racecar'', ''madam'') from standard negative cases (e.g., ''hello'', ''palindrome'').", "Includes mixed-case and alphanumeric sentences (e.g., ''A man, a plan, a canal: Panama!'') verifying case-folding and punctuation stripping."]}, {"id": "KP2", "description": "Boundary & Extreme Edge-Case Coverage: Verifies boundary conditions, empty inputs, single characters, and long strings.", "required": true, "acceptable_evidence": ["Technical keywords: O(n), 100k+ characters, boundary, extreme.", "Tests boundary cases: empty string '''', single-character ''a'', two identical characters ''aa'', two different characters ''ab''.", "Tests strings composed entirely of non-alphanumeric characters ''.,!?'' asserting correct handling.", "Tests long strings (100k+ characters) to assert O(N) time efficiency and verify no stack overflow in recursive implementations."]}, {"id": "KP3", "description": "Unicode, Encoding & Property-Based Testing: Validates multi-byte characters and applies automated fuzzing.", "required": false, "acceptable_evidence": ["Technical keywords: accents with combining, precomposed glyphs, unicode, encoding.", "Tests multi-byte Unicode characters, emojis, and accented characters (e.g., accents with combining vs precomposed glyphs).", "Applies property-based testing (e.g., using Hypothesis) generating arbitrary strings: s + s[::-1] must always be a palindrome.", "Instruments code coverage analysis asserting 100% branch coverage across all conditional check statements."]}], "critical_failures": ["Provides only 2-3 trivial happy-path words, omitting empty strings, single characters, or punctuation handling.", "Writes tests as loose print statements rather than automated assertions within a formal test runner."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How would you implement breadth-first search (BFS) to compute the shortest path and track the path using parent relationships?', '{"key_points": [{"id": "KP1", "description": "Queue-Based BFS Exploration & Visited Tracking: Traverses unit-weight graph layer-by-layer using a FIFO queue.", "required": true, "acceptable_evidence": ["Technical keywords: BFS, O(1), collections.deque, FIFO.", "Initializes a FIFO queue (collections.deque in Python) with the start node and marks it visited.", "Pops nodes from the queue in O(1) time, iterating through adjacent unvisited neighbors.", "Marks neighbors as visited immediately upon enqueueing to prevent redundant cycles and duplicate queue entries."]}, {"id": "KP2", "description": "Parent Mapping & Backtracking Path Reconstruction: Records predecessor pointers to reconstruct the exact optimal path.", "required": true, "acceptable_evidence": ["Technical keywords: terminates search, parent, mapping, backtracking.", "Maintains a parent dictionary parent[neighbor] = current when discovering each unvisited node.", "Terminates search early once the target node is dequeued or discovered.", "Reconstructs path by backtracking from target node using parent pointers to source, then reversing the collected list: [source, ..., target]."]}, {"id": "KP3", "description": "Complexity Guarantees & Disconnected Graph Handling: Proves optimal complexity and handles unreachable targets.", "required": false, "acceptable_evidence": ["Technical keywords: time complexity, space complexity, O(V + E), O(V).", "Proves time complexity is O(V + E) and space complexity is O(V) for adjacency list representations.", "Returns an empty path or indicator when target is unreachable (queue empties without finding target).", "Handles edge cases: source equals target, disconnected graph components, self-loops, and multi-component graphs."]}], "critical_failures": ["Uses a LIFO stack or recursive DFS, which does not guarantee the shortest path in unweighted graphs.", "Fails to maintain parent pointers, computing only distance count while unable to return the actual node path."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'HARD', 'BROAD', 210, 'How would you implement operations such as adding a task, marking a task as finished/unfinished, renaming a task, and printing all tasks hierarchically?', '{"key_points": [{"id": "KP1", "description": "Task Node Data Structure & Direct Indexing: Encapsulates tree nodes and maintains a secondary hash map for O(1) task access.", "required": true, "acceptable_evidence": ["Technical keywords: O(1), id_to_node, task_id, TaskNode.", "Defines TaskNode class containing id, title, completed (bool), children (list), and parent reference.", "Maintains an index hash map id_to_node[task_id] allowing O(1) lookup for rename, status toggle, and child insertion."]}, {"id": "KP2", "description": "Supports adding root tasks or appending child subtasks under a specified parent_id.", "required": true, "acceptable_evidence": ["Technical keywords: task tree, adjacency list, parent_id pointer, recursive CTE, hierarchical graph, DAG.", "Supports adding root tasks or appending child subtasks under a specified parent_id.", "Models tasks as a directed acyclic graph (DAG) or tree with parent_id foreign keys, using recursive PostgreSQL CTEs to query task hierarchies."]}, {"id": "KP3", "description": "Status Propagation & Renaming Invariants: Handles hierarchical completion cascades and atomic property updates.", "required": true, "acceptable_evidence": ["Technical keywords: rename_task, new_title, map index, O(1).", "Implements rename_task(id, new_title) in O(1) via hash map index with validation against empty titles.", "Implements status toggling with optional cascade rules: completing a parent marks all descendants completed, or completing all children auto-completes parent.", "Unmarking a task propagates upward to unmark ancestor parent tasks appropriately."]}, {"id": "KP4", "description": "Hierarchical Pretty-Printing & Tree Traversal: Traverses the hierarchy using DFS with visual indentation and status indicators.", "required": false, "acceptable_evidence": ["Technical keywords: DFS, depth * 2, ├──, [X]'' for finished.", "Implements recursive Depth-First Search (DFS) or stack traversal applying indentation spaces (depth * 2) or tree branch symbols (''├── '').", "Prints visual completion markers (e.g., ''[X]'' for finished, ''[ ]'' for unfinished) alongside task titles.", "Detects and prevents cyclic parent-child assignments (e.g., making a task a child of its own descendant)."]}], "critical_failures": ["Performs full O(N) tree traversals for every task lookup instead of maintaining an O(1) id-to-node index map.", "Fails to handle hierarchical nesting, printing tasks as an unindented flat list."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you improve this platform further if given the opportunity?', '{"key_points": [{"id": "KP1", "description": "Latency & Cost Optimization Architecture: Proposes concrete technical optimizations reducing model inference latency and token costs.", "required": true, "acceptable_evidence": ["Technical keywords: speculative decoding, Redis, LLM, API.", "Implements semantic caching (e.g., GPTCache, Redis vector cache) to serve frequent identical queries with zero LLM API cost.", "Introduces speculative decoding or smaller fine-tuned specialist models (e.g., Llama-3-8B) to replace costly frontier models on routine tasks.", "Optimizes prompt context length through dynamic token compression, context pruning, and batch API inference."]}, {"id": "KP2", "description": "Automated Evaluation & Continuous Observability: Elevates quality benchmarking through CI/CD evaluation harnesses and production tracing.", "required": true, "acceptable_evidence": ["Technical keywords: golden dataset, OpenTelemetry, distributed tracing, CI/CD.", "Builds automated continuous evaluation harnesses running golden dataset regressions on every prompt or code release.", "Integrates OpenTelemetry distributed tracing across all agent nodes and vector search stages to monitor p95 latency bottlenecks.", "Establishes automated feedback flywheels mining production failure traces for active learning curation."]}, {"id": "KP3", "description": "Developer Experience, Multi-Agent Autonomy & Governance: Enhances platform extensibility and autonomous agent workflows.", "required": false, "acceptable_evidence": ["Technical keywords: LangGraph, PII redaction, PII, turn pipelines.", "Develops standardized internal SDKs and OpenAPI tool registries to accelerate feature onboarding by internal teams.", "Evolves single-turn pipelines into hierarchical multi-agent workflows (LangGraph) with specialized supervisor agents.", "Hardens enterprise governance with automated policy guardrails, PII redaction, and tenant-level cost metering."]}], "critical_failures": ["Suggests vague, generic ideas (''make it faster and better'') without citing concrete architectural mechanisms or tooling.", "Fails to address cost, latency, or evaluation, focusing purely on theoretical novelty."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'How would you improve weekly match quality when no new explicit user data is available?', '{"key_points": [{"id": "KP1", "description": "Implicit Behavioral Signal Extraction: Mines rich clickstream, dwell time, and interaction patterns as implicit feedback proxies.", "required": true, "acceptable_evidence": ["Technical keywords: behavioral embeddings, behavioral, signal, extraction.", "Extracts implicit signals: profile view dwell time, photo swipe depth, return visits, and search query refinements.", "Treats non-clicks on highly exposed profiles as implicit negative signals to down-weight corresponding candidate clusters.", "Converts session clickstream sequences into behavioral embeddings (e.g., using Word2Vec/Item2Vec style sequence models)."]}, {"id": "KP2", "description": "Graph Propagation & Collaborative Neighborhood Learning: Updates preference vectors through collaborative network interactions of similar peers.", "required": true, "acceptable_evidence": ["Technical keywords: user embeddings, LightGCN, graph, propagation.", "Propagates preference updates through graph collaborative filtering (e.g., LightGCN): updates user embeddings based on actions taken by behavioral twins.", "Identifies emerging category trends and popularity shifts from active peers to enrich stagnant user profiles.", "Leverages two-sided mutual affinity updates: if candidate users update their activity, the compatibility score updates without target user changes."]}, {"id": "KP3", "description": "Exploratory Diversification & Candidate Fatigue Mitigation: Refreshes candidate pools by dampening previously shown items and exploring adjacent spaces.", "required": false, "acceptable_evidence": ["Technical keywords: day of week, active hours, seasonal events.", "Penalizes candidates that have been repeatedly presented in previous weekly batches to eliminate match fatigue.", "Applies controlled epsilon-greedy or bandit exploration into adjacent semantic clusters to discover latent interests.", "Incorporates temporal and seasonal context (day of week, active hours, seasonal events) into matching scores."]}], "critical_failures": ["Asserts that match quality cannot be improved without new explicit user questionnaire data.", "Continues serving identical weekly match lists repeatedly, creating user fatigue and churn."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you manage consistency in teaching schedules across a 10·20 week cohort while handling potential unavailability?', '{"key_points": [{"id": "KP1", "description": "Proactive Planning & Curriculum Modularization: Pre-builds detailed lesson plans, modular milestones, and standardized materials.", "required": true, "acceptable_evidence": ["Technical keywords: holidays, personal commitments, conferences, pre-recorded lecture walkthroughs.", "Develops a comprehensive 10-20 week syllabus with standardized slide decks, code starter repos, and rubric milestones in advance.", "Identifies known scheduling conflicts (holidays, personal commitments, conferences) and builds them into the published calendar upfront.", "Maintains asynchronous backup materials (pre-recorded lecture walkthroughs, detailed lab guides) for every module."]}, {"id": "KP2", "description": "Contingency Protocols & Co-Instructor Handoffs: Establishes substitute instructor alignment to ensure seamless class delivery during emergencies.", "required": true, "acceptable_evidence": ["Technical keywords: instructor alignment, transparent handoff, contingency, protocols.", "Coordinates with a designated backup co-instructor or teaching assistant with shared access to lesson plans and repos.", "Maintains transparent handoff documentation capturing where the previous session ended and specific student doubt follow-ups.", "Notifies cohort coordinators and students with maximum advance notice if an unavoidable emergency arises."]}, {"id": "KP3", "description": "Transparent Communication & Learner Continuity: Prioritizes student learning momentum through asynchronous touchpoints and makeup sessions.", "required": false, "acceptable_evidence": ["Technical keywords: Slack, Discord, transparent, learner.", "Schedules dedicated makeup sessions or extended office hours to compensate for any rescheduled classes.", "Maintains continuous daily presence in cohort discussion channels (Slack/Discord) to unblock student assignments asynchronously.", "Conducts mid-cohort retrospectives to collect learner feedback and adjust teaching pacing collaboratively."]}], "critical_failures": ["Cancels classes last-minute without prior notice, backup coverage, or makeup arrangements.", "Demonstrates lack of commitment to the multi-week timeline, treating scheduled sessions as optional."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How would you model a user belief state that captures probabilistic preferences, tolerance levels, and changing behavior over time?', '{"key_points": [{"id": "KP1", "description": "Probabilistic Preference Distribution Parameterization: Models latent user affinities as continuous or categorical distributions rather than static point estimates.", "required": true, "acceptable_evidence": ["Technical keywords: gaussian embeddings, probabilistic, preference, distribution.", "Represents multi-category affinities using conjugate priors (e.g., Beta-Bernoulli for binary attributes, Dirichlet-Multinomial for categorical preferences, or Gaussian embeddings).", "Tracks both mean preference expectation and epistemic variance/uncertainty per attribute."]}, {"id": "KP2", "description": "Initializes cold-start user beliefs using population-level demographic or cohort priors.", "required": true, "acceptable_evidence": ["Technical keywords: Bayesian belief state, conjugate Dirichlet prior, demographic cold-start, preference updating, beta distribution.", "Initializes cold-start user beliefs using population-level demographic or cohort priors.", "Initializes cold-start preference parameters using demographic cohort priors, updating beliefs dynamically via Bayesian conjugate distributions with each user feedback event."]}, {"id": "KP3", "description": "Tolerance Elasticity & Hard/Soft Constraint Separation: Distinguishes non-negotiable dealbreakers from elastic trade-off boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: utility trade-offs, budget, distance, seniority.", "Encodes asymmetric loss or sigmoid penalty curves around user-stated thresholds (e.g., budget, distance, seniority).", "Estimates attribute-specific tolerance slack variables from historical acceptance of near-boundary candidates.", "Separates strict boolean eligibility filters from weighted utility trade-offs in the belief state."]}, {"id": "KP4", "description": "Non-Stationary Temporal Dynamics & State Transitions: Incorporates exponential forgetting factors or state-space transitions to adapt to preference drift.", "required": false, "acceptable_evidence": ["Technical keywords: delta_t, POMDP, preference drift, kalman state.", "Applies time-decay weights exp(-lambda * delta_t) to older observations so recent behavior dominates posterior updates.", "Models belief evolution as a Partially Observable Markov Decision Process (POMDP) or dynamic Kalman state-space filter.", "Increases posterior variance during periods of user inactivity or erratic feedback to trigger re-exploration."]}], "critical_failures": ["Represents user preferences as rigid deterministic rules or static unweighted keyword lists.", "Treats historical interactions from months ago as equally weighted with current session signals without temporal decay."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'How would you model interactions or interference between different products affecting demand?', '{"key_points": [{"id": "KP1", "description": "Substitution & Complementarity Feature Engineering: Captures cannibalization and halo dynamics across related SKUs.", "required": true, "acceptable_evidence": ["Technical keywords: view embeddings, negative cross-elasticity, cannibalization, positive cross-elasticity.", "Constructs cross-product relative price ratios, promotional overlap indicators, and stockout spillover features within product taxonomy clusters.", "Distinguishes substitutes (negative cross-elasticity / cannibalization) from complements (positive cross-elasticity / basket halo).", "Uses co-purchase or session co-view embeddings to identify latent product competition neighborhoods."]}, {"id": "KP2", "description": "Joint Multivariate & Graph Forecasting Architectures: Models interdependent SKU demand trajectories simultaneously.", "required": true, "acceptable_evidence": ["Technical keywords: overfitting, SKU, VAR, interaction graphs.", "Applies Graph Neural Networks (GNNs), cross-attention transformers, or Vector Autoregressive (VAR) models over product interaction graphs.", "Enforces hierarchical reconciliation constraints so SKU-level predictions sum consistently to category-level demand.", "Applies L1/group-lasso regularization on cross-product interaction matrices to prevent overfitting in high-dimensional catalogs."]}, {"id": "KP3", "description": "Causal Interference & SUTVA Violation Mitigation: Validates cross-product effects via cluster-randomized experiments or synthetic controls.", "required": false, "acceptable_evidence": ["Technical keywords: SUTVA, via cluster, SKU.", "Addresses Stable Unit Treatment Value Assumption (SUTVA) violations when promotions on Product A cannibalize control Product B.", "Designs market-level, store-level, or category-cluster switchback experiments to isolate net incremental category revenue.", "Evaluates portfolio-level profit optimization rather than isolated single-SKU sales lift."]}], "critical_failures": ["Forecasts each product independently in isolation, completely ignoring cannibalization and stockout substitution.", "Includes all N x N pairwise SKU interactions without regularization or taxonomy clustering, causing severe curse of dimensionality."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'BROAD', 150, 'How would you parallelize the computation of factorial for very large inputs across multiple CPUs, and what design considerations are involved?', '{"key_points": [{"id": "KP1", "description": "Balanced Range Partitioning & Binary Splitting Tree Reduction: Structures sub-products so operands have comparable bit lengths.", "required": true, "acceptable_evidence": ["Technical keywords: range partitioning, strided partitioning, i+k, i+2k.", "Explains why naive contiguous range partitioning [1..N/k], [N/k+1..2N/k] causes load imbalance because higher ranges contain larger integers with more bits.", "Uses interleaved strided partitioning (worker i computes product of i, i+k, i+2k...) or binary splitting to keep sub-product bit-lengths balanced."]}, {"id": "KP2", "description": "Combines partial products via a parallel binary reduction tree rather than sequential accumulator multiplication.", "required": true, "acceptable_evidence": ["Technical keywords: parallel binary reduction, tree reduction, divide-and-conquer, multiprocessing.Pool, Karatsuba multiplication.", "Combines partial products via a parallel binary reduction tree rather than sequential accumulator multiplication.", "Splits the range [1, N] into sub-intervals computed across worker processes, combining partial products in a balanced binary reduction tree."]}, {"id": "KP3", "description": "Asymptotic Big-Integer Multiplication & Memory Hierarchy: Accounts for super-linear multiplication cost as integer bit-size grows to O(N log N) bits.", "required": true, "acceptable_evidence": ["Technical keywords: O(n log n), O(b^1.585), O(b log b log log b), FFT.", "Recognizes that for large N, arbitrary-precision big-integer arithmetic dominates runtime over CPU loop overhead.", "Leverages sub-quadratic multiplication algorithms (Karatsuba O(b^1.585), Toom-Cook, or Schönhage-Strassen FFT O(b log b log log b)) at upper reduction tree levels.", "Uses multi-threading within shared memory (or C/Rust GMP bindings) to avoid costly IPC serialization of multi-megabyte integers."]}, {"id": "KP4", "description": "Prime Factorization & Bit-Shift Optimization: Optimizes multiplication via prime exponents and power-of-two bit shifting.", "required": false, "acceptable_evidence": ["Technical keywords: FFT, prime, factorization, shift.", "Factors out powers of 2 to replace even multiplications with a single final bitwise left-shift.", "Mentions Legendre''s formula prime factorization + parallel exponentiation by squaring for extreme scale.", "Schedules final top-level tree multiplications using parallel FFT worker threads once tree breadth narrows below core count."]}], "critical_failures": ["Assumes standard 64-bit integer multiplication O(1) cost applies to very large factorials without overflowing or requiring big-int arithmetic.", "Uses a shared mutex-locked global accumulator where every thread multiplies one number at a time, serializing execution."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How would you segment users based on behavioral characteristics, and which key metrics would you use to define these segments?', '{"key_points": [{"id": "KP1", "description": "Behavioral Metric Taxonomy & Feature Normalization: Defines quantitative engagement, conversion, and lifecycle metrics.", "required": true, "acceptable_evidence": ["Technical keywords: RFM, lifecycle metrics, responsiveness metrics.", "Selects orthogonal behavioral dimensions: Recency, Frequency, Monetary value (RFM), session duration, feature adoption breadth, and funnel conversion ratios.", "Captures responsiveness metrics such as acceptance rate, rejection velocity, and notification click-through latency."]}, {"id": "KP2", "description": "Apply log-transformations and robust scaling (IQR/rank normalization) to handle heavy-tailed power-law activity distributions.", "required": true, "acceptable_evidence": ["Technical keywords: log1p transform, robust scaling, power-law distribution, quantile transformer, k-means clustering.", "Applies log-transformations and robust scaling (IQR/rank normalization) to handle heavy-tailed power-law activity distributions.", "Applies log1p transformations and robust quantile scaling to skewed activity metrics (e.g. session count, spend) before clustering with k-means."]}, {"id": "KP3", "description": "Segmentation Methodology & Hybrid Clustering: Combines rule-based lifecycle tiers with unsupervised clustering over behavioral embeddings.", "required": true, "acceptable_evidence": ["Technical keywords: GMM, UMAP, behavioral embeddings, lifecycle states.", "Separates deterministic lifecycle states (new cold-start, active core, at-risk, churned) from latent behavioral personas.", "Applies Gaussian Mixture Models (GMM), HDBSCAN, or K-Means on UMAP/autoencoder behavioral embeddings.", "Validates cluster stability using Silhouette scores, Davies-Bouldin index, and temporal cohort migration matrices."]}, {"id": "KP4", "description": "Downstream Actionability & Segment Drift Monitoring: Ties segments to differentiated product treatments and tracks segment transitions.", "required": false, "acceptable_evidence": ["Technical keywords: A/B testing, HTE, segment drift.", "Maps each segment to a specific intervention (e.g., high-intent browsers get friction-free checkout; selective rejectors get broadened exploration).", "Monitors segment population distribution shifts weekly to detect product regressions or seasonal anomalies.", "Evaluates heterogeneous treatment effects (HTE) per segment during A/B testing."]}], "critical_failures": ["Segments users solely on static demographic attributes (age, gender) when asked for behavioral segmentation.", "Runs K-Means directly on raw unscaled count features where extreme power-users distort all cluster centroids."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How would you simulate different hypotheses or rejection scenarios to improve future recommendations?', '{"key_points": [{"id": "KP1", "description": "Latent Rejection Hypothesis Space Formulation: Decomposes ambiguous rejections into competing explanatory hypotheses.", "required": true, "acceptable_evidence": ["Technical keywords: H_k | history, latent, rejection, hypothesis.", "Models multiple latent reasons for a single rejection (e.g., Hypothesis H1: price too high; H2: disliked brand/style; H3: temporary timing mismatch).", "Maintains a posterior probability distribution over competing rejection hypotheses P(H_k | history).", "Extracts attribute-level contrast between rejected items and previously accepted baselines."]}, {"id": "KP2", "description": "Monte Carlo Rollout & Active Information-Gain Probing: Simulates candidate recommendations under each hypothesis to disambiguate user intent.", "required": true, "acceptable_evidence": ["Technical keywords: KL, accept, reject, exploration-exploitation trade-off.", "Simulates expected user response (accept/reject) across candidate items conditional on each hypothesis H_k being true.", "Selects diagnostic ''probe'' recommendations that maximize expected Kullback-Leibler (KL) divergence or Shannon entropy reduction across hypotheses.", "Balances immediate expected conversion utility against epistemic value of information (exploration-exploitation trade-off)."]}, {"id": "KP3", "description": "Off-Policy Replay & Simulator Calibration: Validates simulated trajectories against logged historical counterfactual data.", "required": false, "acceptable_evidence": ["Technical keywords: IPS, DR, policy, replay.", "Calibrates the user response simulator using Inverse Propensity Scoring (IPS) or Doubly Robust (DR) estimators on logged bandit data.", "Penalizes hypothesis simulations that stray outside the support of historical observation distributions.", "Updates hypothesis priors online after observing the user''s real reaction to the diagnostic recommendation."]}], "critical_failures": ["Assumes a rejection penalizes every single attribute of the rejected item equally, permanently blacklisting valid features.", "Proposes running uncalibrated random simulations without connecting outcomes back to ranking policy updates."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you stay engaged with a company for future opportunities if you are not immediately available?', '{"key_points": [{"id": "KP1", "description": "Upfront Timeline Transparency & Expectation Alignment: Clearly communicates availability constraints and target transition dates.", "required": true, "acceptable_evidence": ["Technical keywords: expectation alignment, upfront, timeline, expectation.", "Communicates exact notice period, contractual commitments, or academic/project completion milestones clearly and early.", "Aligns with the recruiter or hiring manager on a realistic target window to re-initiate formal interview or onboarding steps.", "Explains whether part-time advisory, pre-onboarding study, or flexible ramp-up is feasible within current obligations."]}, {"id": "KP2", "description": "Structured Periodic Touchpoints & Value-Add Updates: Maintains warm professional contact without spamming.", "required": true, "acceptable_evidence": ["Technical keywords: AI, monthly, quarterly updates.", "Establishes a mutually agreed check-in cadence (e.g., monthly or quarterly updates) with the hiring team.", "Shares relevant professional milestones, newly completed AI architectures, open-source contributions, or domain certifications.", "Engages thoughtfully with the company''s engineering blog posts, product launches, or public technical talks."]}, {"id": "KP3", "description": "Domain Skill Alignment & Readiness Preparation: Uses the interim period to deepen skills relevant to the company''s tech stack.", "required": false, "acceptable_evidence": ["Technical keywords: LangGraph, RAG, skill alignment, RAG evaluation.", "Researches the organization''s core technical challenges and sharpens relevant tooling (e.g., LangGraph, RAG evaluation, cloud infra) ahead of joining.", "Attends company-hosted webinars, hackathons, or community meetups to build rapport with future peers.", "Provides advance confirmation 4-6 weeks prior to availability date to streamline role matching."]}], "critical_failures": ["Goes completely silent with zero communication until randomly reappearing months later.", "Misleads the company about immediate availability and backs out at the offer stage."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How would you structure a concise and impactful self-introduction for a technical interview?', '{"key_points": [{"id": "KP1", "description": "Structured Narrative Arc & Time Discipline: Organizes the introduction logically within a crisp 60-to-90-second window.", "required": true, "acceptable_evidence": ["Technical keywords: narrative, discipline, organizes, introduction.", "Follows a clear progression: current engineering identity and core specialization -> flagship production achievements -> alignment with the target role.", "Avoids chronological recitation of every line on the resume, focusing on high-signal architectural themes.", "Maintains a concise 60-90 second delivery that leaves hooks for the interviewer to probe deeper."]}, {"id": "KP2", "description": "Quantified Technical Depth & Production Ownership: Highlights end-to-end systems built and measurable engineering outcomes.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, RAG, precision, rag pipelines.", "Names concrete technical stacks and architectures personally owned (e.g., hybrid RAG pipelines, LangGraph multi-agent workflows, distributed microservices).", "Anchors claims with specific production metrics (e.g., latency reduction, retrieval precision lift, throughput scale, cost savings).", "Clarifies personal architectural decision-making vs broader team responsibilities."]}, {"id": "KP3", "description": "Role-Specific Tailoring & Problem-Space Connection: Connects past engineering strengths directly to the interviewing team''s roadmap.", "required": false, "acceptable_evidence": ["Technical keywords: tailoring, problem, space, connection.", "Maps relevant domain experience directly to the job description''s primary technical challenges.", "Conveys enthusiasm for the specific engineering problems the team is solving.", "Demonstrates audience awareness (adjusting granularity for a peer staff engineer vs a hiring manager)."]}], "critical_failures": ["Rambles for 5+ minutes reciting biographical history without mentioning concrete technical impact.", "Uses vague buzzwords without naming a single system built, technical trade-off solved, or measurable outcome."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'How would you use Bayesian updates to refine user preference probabilities after each acceptance or rejection?', '{"key_points": [{"id": "KP1", "description": "Prior-to-Posterior Bayes Formulation & Conjugate Mechanics: Explicitly defines prior distribution, observation likelihood, and posterior update equations.", "required": true, "acceptable_evidence": ["Technical keywords: theta | D, y | x, theta, alpha.", "States Bayes'' update P(theta | D) proportional to P(y | x, theta) * P(theta) where theta represents latent user preference weights.", "Illustrates closed-form conjugate updates such as Beta(alpha, beta) -> Beta(alpha + 1, beta) on acceptance and Beta(alpha, beta + 1) on rejection.", "Describes Gaussian/Kalman or online Bayesian logistic regression updates for continuous multi-attribute preference vectors."]}, {"id": "KP2", "description": "Multi-Attribute Credit Assignment & Observation Noise: Prevents over-updating from noisy or confounded binary feedback.", "required": true, "acceptable_evidence": ["Technical keywords: slip, mistake probability, multi, attribute.", "Accounts for multi-attribute ambiguity (rejecting an item with 5 attributes does not mean all 5 attributes are disliked).", "Scales update magnitude by attribute salience/extremity relative to the user''s baseline.", "Incorporates an observation noise parameter epsilon (slip/mistake probability) so a single accidental rejection does not zero out posterior probability."]}, {"id": "KP3", "description": "Posterior Uncertainty Exploitation (Thompson Sampling / UCB): Uses posterior variance to drive exploration.", "required": false, "acceptable_evidence": ["Technical keywords: UCB, preference drift, Thompson Sampling.", "Samples preference weights theta ~ Posterior (Thompson Sampling) or uses Upper Confidence Bounds (mean + c * std) to rank next candidates.", "Applies exponential decay (alpha <- gamma * alpha, beta <- gamma * beta) between sessions to preserve adaptability to preference drift.", "Monitors posterior entropy convergence to detect when preferences are confidently locked in."]}], "critical_failures": ["Cannot explain how prior probabilities combine with likelihoods to form a posterior distribution.", "Updates preference probabilities to 0% or 100% deterministically after a single rejection or acceptance."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'How would you use counterfactual reasoning to evaluate whether a previously rejected candidate should be reconsidered later?', '{"key_points": [{"id": "KP1", "description": "Counterfactual State Intervention Modeling: Evaluates how the historical rejection outcome would change under current user beliefs and market context.", "required": true, "acceptable_evidence": ["Technical keywords: counterfactual state, belief state, intervened state, S = S_t1.", "Formulates the counterfactual query: given that Candidate X was rejected under belief state S_t0, what is the probability of acceptance under intervened state do(S = S_t1)?", "Identifies what changed between t0 and t1: relaxed user tolerance bounds, updated preference weights, candidate profile improvements, or shrunk remaining pool.", "Computes the counterfactual utility delta U(X | S_t1) - U(X | S_t0) to quantify reconsideration value."]}, {"id": "KP2", "description": "Causal Attribution of Original Rejection (Hard vs Soft Factors): Distinguishes immutable dealbreakers from mutable or contextual rejection causes.", "required": true, "acceptable_evidence": ["Technical keywords: Hard, Soft Factors, causal, attribution.", "Uses abduction to infer the latent cause of the original rejection (e.g., rejected due to anchoring against an unrealistic ideal early in search vs rejected for a hard violation).", "Blocks reconsideration if the rejection stemmed from an immutable hard constraint that remains active.", "Allows reconsideration when subsequent rejections proved the user''s initial threshold was overly optimistic and tolerance has since expanded."]}, {"id": "KP3", "description": "Cooldown Gating & Framing Justification: Controls re-impression fatigue and explains why the candidate is being resurfaced.", "required": false, "acceptable_evidence": ["Technical keywords: cooldown, gating, framing, justification.", "Enforces a minimum cooldown period and requires a high counterfactual acceptance threshold before resurfacing a rejected candidate.", "Surfaces explicit framing context to the user (e.g., ''Revisited based on your updated location/budget preferences'').", "Caps the ratio of reconsidered candidates per batch to preserve novelty."]}], "critical_failures": ["Randomly resurfaces rejected candidates without checking whether user preferences or candidate attributes have changed.", "Permanently hard-deletes all rejected candidates, preventing recovery when users relax unrealistic initial criteria."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How would you validate edge cases where user behavior is inconsistent or preferences shift suddenly over time?', '{"key_points": [{"id": "KP1", "description": "Adversarial & Non-Stationary Simulation Test Suites: Constructs synthetic behavioral trajectories covering abrupt regime shifts and noisy contradictions.", "required": true, "acceptable_evidence": ["Technical keywords: adversarial, stationary, simulation, suites.", "Builds synthetic test harnesses simulating sudden step-function preference reversals, oscillating multi-intent sessions, and high-noise random clicking.", "Tests stated-vs-revealed preference contradictions (e.g., user explicitly filters for X but consistently rejects X and accepts Y)."]}, {"id": "KP2", "description": "Measures recovery latency (number of interactions required for the model to adapt after a simulated 180-degree preference pivot).", "required": true, "acceptable_evidence": ["Technical keywords: recovery latency benchmark, synthetic preference pivot, recency weighting, exponential decay, online evaluation.", "Measures recovery latency (number of interactions required for the model to adapt after a simulated 180-degree preference pivot).", "Simulates abrupt preference reversals in test harnesses, measuring how many turns an exponential decay discounting factor requires to pivot recommendations."]}, {"id": "KP3", "description": "Change-Point Detection & Entropy-Based Uncertainty Reset: Detects regime shifts online and widens posterior variance.", "required": true, "acceptable_evidence": ["Technical keywords: BOCPD, CUSUM, surprise metrics, negative log-likelihood spikes.", "Implements Bayesian Online Change-Point Detection (BOCPD), CUSUM, or sliding-window surprise metrics (negative log-likelihood spikes) on user actions.", "Distinguishes isolated one-off outlier clicks (handled via robust Huber/epsilon-contamination likelihoods) from sustained regime shifts.", "Resets or inflates belief covariance/uncertainty upon confirmed change-point detection to accelerate re-learning."]}, {"id": "KP4", "description": "Fallback Exploration & Multi-Modal Disambiguation: Avoids filter bubbles during high-inconsistency states.", "required": false, "acceptable_evidence": ["Technical keywords: MMR, Determinantal Point Processes, exploration, multi.", "Switches ranking strategy to diversified portfolio exploration (MMR / Determinantal Point Processes) when belief entropy is high.", "Models multi-modal mixture distributions (e.g., user shopping for two distinct contexts) rather than collapsing to a meaningless average.", "Triggers explicit conversational clarification prompts when implicit signals remain persistently contradictory."]}], "critical_failures": ["Evaluates the recommendation model only on stationary, noise-free synthetic users.", "Allows a single inconsistent click to corrupt the entire historical profile, or conversely, locks into old history so tightly that sudden preference shifts are ignored."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How would you vertically stack two pandas DataFrames with the same structure?', '{"key_points": [{"id": "KP1", "description": "Canonical pd.concat Invocation & Axis Specification: Uses pd.concat along axis=0 with explicit index handling.", "required": true, "acceptable_evidence": ["Technical keywords: Pandas, DataFrame, pd.concat, ignore_index.", "Writes pd.concat([df1, df2], axis=0, ignore_index=True) to stack rows vertically and generate a clean 0..N-1 RangeIndex.", "Explains that omitting ignore_index=True preserves original indices, which can cause duplicate index labels and bugs in downstream .loc[] lookups.", "Notes that DataFrame.append() was deprecated and removed in modern pandas (2.0+) in favor of pd.concat()."]}, {"id": "KP2", "description": "Schema Alignment, Column Ordering & Dtype Validation: Prevents silent NaN introduction or unintended type upcasting.", "required": true, "acceptable_evidence": ["Technical keywords: verify_integrity, DataFrames, schema alignment, dtype validation.", "Verifies column name exact matching (handling whitespace/case discrepancies) so misaligned columns do not create sparse NaN columns.", "Checks dtype consistency across both DataFrames (e.g., preventing int64 + nullable column from silently upcasting to float64 or object).", "Uses verify_integrity=True when index uniqueness must be strictly enforced without resetting."]}, {"id": "KP3", "description": "Memory Efficiency & Batch Concatenation Patterns: Avoids quadratic copying in loops.", "required": false, "acceptable_evidence": ["Technical keywords: list, DFS, pd.concat, ignore_index.", "Accumulates DataFrames in a Python list and calls pd.concat(dfs, ignore_index=True) once rather than calling pd.concat repeatedly inside a loop (which is O(N^2) memory copy).", "Uses keys=[''source_a'', ''source_b''] when hierarchical MultiIndex provenance tracking is desired.", "Uses copy=False where appropriate to minimize unnecessary buffer duplication."]}], "critical_failures": ["Uses axis=1 (horizontal column join) when asked to vertically stack DataFrames.", "Suggests calling df.append() in a loop without awareness of its removal in pandas 2.0+ or O(N^2) allocation cost."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you write SystemVerilog assertions to verify a 4-phase handshake protocol with non-deterministic delays and strict cycle relationships?', '{"key_points": [{"id": "KP1", "description": "Four-Phase Transition Sequence & Level-Stability Invariants: Encodes all four req/ack transitions and stability guarantees.", "required": true, "acceptable_evidence": ["Technical keywords: until_with, SVA, data payload, req.", "Defines the 4 phases: (1) $rose(req) holds req high until ack rises, (2) $rose(ack) holds ack high until req falls, (3) $fell(req) holds req low until ack falls, (4) $fell(ack) completes cycle.", "Enforces stability using SVA temporal operators: $rose(req) |-> (req throughout ##[1:$] $rose(ack)) or req until_with ack.", "Verifies data payload stability ($stable(data)) throughout the active window while req is asserted and ack has not yet completed."]}, {"id": "KP2", "description": "Non-Deterministic Delay Windows & Strict Cycle Bounds: Parameterizes variable latency ranges and exact cycle relationships.", "required": true, "acceptable_evidence": ["Technical keywords: response latency, ack, req.", "Models bounded or unbounded non-deterministic response latency using ##[MIN_CYCLES:MAX_CYCLES] or ##[1:$] with liveness/timeout bounds.", "Enforces strict cycle relationships where required (e.g., overlapping |-> vs non-overlapping |=> implication, or exact ##N deassertion delay).", "Prevents spurious ack assertions by asserting $rose(ack) |-> $past(req) && req (no ack without active request)."]}, {"id": "KP3", "description": "Clocking, Asynchronous Reset Guarding & Cover Properties: Wraps assertions with disable iff (!rst_n) and functional coverage.", "required": false, "acceptable_evidence": ["Technical keywords: rst_n, JasperGold, VC, !rst_n.", "Includes @(posedge clk) disable iff (!rst_n) so reset transitions do not trigger false assertion failures.", "Pairs assert property statements with cover property statements to verify that minimum-delay, maximum-delay, and back-to-back handshakes were exercised.", "Uses assumption properties (assume property) when constraining input stimuli in formal verification ( JasperGold / VC Formal )."]}], "critical_failures": ["Confuses a 4-phase return-to-zero handshake with a 2-phase toggle or single-cycle valid/ready handshake.", "Allows req to drop before ack is asserted, violating the fundamental 4-phase stability contract."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'How would your system handle updates to an existing BOM versus creating a new one?', '{"key_points": [{"id": "KP1", "description": "Intent Classification & Canonical BOM State Resolution: Distinguishes greenfield BOM creation from targeted revision mutations.", "required": true, "acceptable_evidence": ["Technical keywords: BOM, ID, ERP, PLM.", "Routes user intent in the orchestration graph between a New-BOM initialization branch (template selection, full part extraction) and an Update-BOM branch (loading existing BOM ID and active revision).", "Resolves ambiguous natural-language component names against canonical ERP/PLM part numbers, units of measure, and hierarchical assembly nodes."]}, {"id": "KP2", "description": "Computes a structured semantic diff (added line items, modified quantities, substituted part IDs, removed components) rather than regenerating the entire BOM from scratch.", "required": true, "acceptable_evidence": ["Technical keywords: JSON patch, RFC 6902, semantic diff, BOM revision control, delta update, idempotent mutation.", "Computes a structured semantic diff (added line items, modified quantities, substituted part IDs, removed components) rather than regenerating the entire BOM from scratch.", "Generates RFC 6902 JSON patch deltas representing added/modified/deleted BOM line items, validating substitutions against component catalog constraints."]}, {"id": "KP3", "description": "Immutable Revision Control & Optimistic Concurrency: Preserves historical BOM versions and audit lineage.", "required": true, "acceptable_evidence": ["Technical keywords: ECO, optimistic concurrency, unit consistency, version checksum.", "Treats released BOMs as immutable snapshots, creating a new revision number (e.g., Rev A -> Rev B) or engineering change order (ECO) draft upon update.", "Enforces optimistic concurrency control (version checksum / ETag) so concurrent edits by multiple engineers do not silently overwrite each other.", "Validates cross-part compatibility, unit consistency, and minimum order constraints against business policy rules before staging."]}, {"id": "KP4", "description": "Human-in-the-Loop Diff Approval & Audit Trail: Requires explicit confirmation before committing production state changes.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, ERP, erp validation, part.", "Presents a side-by-side redline diff (old quantity/part vs proposed quantity/part) for human review before executing the write tool.", "Records an immutable audit log capturing user identity, timestamp, conversational prompt provenance, and approved delta.", "Supports instant rollback to the prior BOM revision if downstream ERP validation fails."]}], "critical_failures": ["Overwrites an existing production BOM in-place via raw LLM text generation without revision history or diff validation.", "Executes database mutations directly from an unverified model output without schema validation or user confirmation."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'MEDIUM', 'SPECIFIC', 90, 'If I want to scale this, would I just use a larger CPU, or would I modularize this into smaller pods?', '{"key_points": [{"id": "KP1", "description": "Vertical vs Horizontal Scaling Trade-Off Analysis: Evaluates when larger CPU nodes help versus when horizontal pod replication wins.", "required": true, "acceptable_evidence": ["Technical keywords: load balancer, HPA, pod replication, elastic concurrency.", "Explains that vertical scaling (larger CPU/memory) has hard hardware ceilings, single points of failure, and pod restart downtime during resizing.", "Explains that horizontal scaling (smaller stateless pods behind a load balancer/queue with HPA) provides elastic concurrency, rolling zero-downtime deploys, and fault isolation.", "Identifies when vertical scaling is still necessary (e.g., large in-memory model weights or non-partitionable single-threaded compute bottlenecks)."]}, {"id": "KP2", "description": "Workload Modularization & Heterogeneous Resource Decoupling: Separates I/O-bound orchestration from CPU/GPU-heavy workers.", "required": true, "acceptable_evidence": ["Technical keywords: Kafka, RabbitMQ, Redis, API.", "Modularizes monolithic pipelines into specialized pods when stages have asymmetric resource profiles (e.g., lightweight async API/LLM routing pods vs heavy document-parsing/embedding pods).", "Prevents CPU-intensive tasks (PDF OCR, chunking, reranking) from starving event loops in latency-sensitive API gateway pods.", "Uses asynchronous message queues (Kafka, RabbitMQ, Redis Streams) with KEDA/HPA to scale worker pods independently by queue depth."]}, {"id": "KP3", "description": "Right-Sizing & Operational Overhead Balance: Avoids premature microservice fragmentation and sets CPU requests/limits properly.", "required": false, "acceptable_evidence": ["Technical keywords: GIL, Kubernetes, p99, PodDisruptionBudgets.", "Warns against over-modularizing into dozens of tiny pods if network serialization latency and operational complexity outweigh scaling gains.", "Configures Kubernetes CPU requests, limits, and PodDisruptionBudgets based on p99 load profiling.", "Considers runtime concurrency constraints (e.g., Python GIL requiring multi-process workers or multiple smaller single-process pods)."]}], "critical_failures": ["Claims vertical CPU scaling alone can scale infinitely without availability risk or hardware limits.", "Recommends splitting into smaller pods without addressing state externalization or inter-pod communication overhead."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'If one of the parallel tasks fails, how is the checkpoint managing that state, where is that stored, and how would you trigger the retry?', '{"key_points": [{"id": "KP1", "description": "Parallel Superstep Checkpointing & Pending Write Preservation: Explains how successful sibling outputs are recorded when one parallel branch fails.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, checkpointing, operator.add, superstep checkpointing.", "Models parallel branches as a graph superstep where state channel reducers (e.g., Annotated[list, operator.add]) merge outputs deterministically.", "Explains that when one parallel task fails mid-superstep, LangGraph''s checkpointer saves the pending writes of sibling tasks that succeeded alongside the error state of the failed task."]}, {"id": "KP2", "description": "Prevents partial failed mutations from corrupting the main committed graph state snapshot until the superstep resolves or routes to a fallback handler.", "required": true, "acceptable_evidence": ["Technical keywords: transactional superstep, Pregel BSP model, LangGraph checkpointer, rollback delta, partial failure isolation.", "Prevents partial failed mutations from corrupting the main committed graph state snapshot until the superstep resolves or routes to a fallback handler.", "Isolates concurrent worker branches in ephemeral channel buffers, committing state snapshots only after all branch nodes complete or routing errors to retry handlers."]}, {"id": "KP3", "description": "Durable Checkpoint Storage Architecture: Specifies production persistence backends and composite indexing keys.", "required": true, "acceptable_evidence": ["Technical keywords: MemorySaver, PostgresSaver, Redis, thread_id.", "Stores checkpoints in a durable transactional database (e.g., PostgresSaver / AsyncPostgresSaver, Redis, or DynamoDB; MemorySaver only for local dev).", "Indexes state snapshots by thread_id (conversation/workflow session), checkpoint_ns, and monotonically ordered checkpoint_id / step counter.", "Persists serialized channel values, node execution metadata, next scheduled nodes, and pending task writes."]}, {"id": "KP4", "description": "Targeted Retry Triggering & Idempotency Guards: Resumes only the failed branch with bounded backoff.", "required": false, "acceptable_evidence": ["Technical keywords: exponential backoff, jitter, max_attempts, retry_on.", "Configures node-level RetryPolicy (max_attempts, exponential backoff + jitter, retry_on exception filter for transient 429/5xx errors).", "Triggers external resumption by invoking the graph with the existing thread_id (and None input or checkpoint_id), which reloads cached sibling writes and re-executes only the failed pending task.", "Enforces idempotency keys on external tool side effects so retries never duplicate mutations."]}], "critical_failures": ["Stores checkpoints only in ephemeral process RAM in production, losing all workflow progress upon worker crash.", "Re-executes all completed parallel sibling tasks from scratch without idempotency protection when retrying a single failed branch."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'If you needed to design online metrics for evaluating output quality, how would you approach it?', '{"key_points": [{"id": "KP1", "description": "Implicit & Explicit User Interaction Telemetry: Captures real-time behavioral indicators of answer utility and failure.", "required": true, "acceptable_evidence": ["Technical keywords: AI, interaction telemetry, thumbs up, down.", "Tracks explicit feedback (thumbs up/down, star ratings, flag reason codes) alongside implicit behavioral proxies.", "Measures implicit quality signals: task completion/acceptance rate, copy/export events, immediate query reformulation/re-prompting rate, session abandonment, and human escalation frequency.", "Tracks edit distance (Levenshtein/token diff) when users modify AI-generated drafts before saving or sending."]}, {"id": "KP2", "description": "Reference-Free Online Evaluators & Guardrail Telemetry: Runs automated faithfulness, relevance, and safety checks without ground-truth labels.", "required": true, "acceptable_evidence": ["Technical keywords: groundedness, LLM-as-a-judge, RAGAS, LLM.", "Executes asynchronous reference-free RAGAS/LLM-as-a-judge evaluators (Faithfulness/Groundedness against retrieved context, Answer Relevance to user query, Coherence).", "Monitors deterministic online guardrail signals: schema validation pass rate, citation verification rate, retrieval similarity score distributions, and refusal/fallback rates.", "Decouples heavy LLM judge scoring onto an asynchronous background queue so user-facing response latency is unaffected."]}, {"id": "KP3", "description": "Stratified Sampling, Judge Calibration & Alerting Thresholds: Controls evaluation cost and aligns online proxies with human truth.", "required": false, "acceptable_evidence": ["Technical keywords: LLM, SME, judge drift, measuring Cohen''s kappa.", "Applies stratified sampling (e.g., 5-10% of normal traffic + 100% of low-retrieval-confidence, high-latency, or negative-feedback traces) for deep evaluation.", "Periodically audits online LLM-judge scores against human SME annotations (measuring Cohen''s kappa / correlation) to prevent judge drift.", "Configures automated anomaly alerts when rolling faithfulness or acceptance rates drop across specific query cohorts."]}], "critical_failures": ["Relies on offline ground-truth reference answers (e.g., BLEU/ROUGE against gold labels) which do not exist for live unseen user queries.", "Blocks the synchronous user response path with slow multi-second LLM-as-a-judge evaluation calls."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'If you were to redesign access control using a single vector index, how would you use metadata filtering to enforce permissions?', '{"key_points": [{"id": "KP1", "description": "Chunk-Level Security Metadata Schema & Server-Side Policy Injection: Attaches tenant/role/group ACL attributes and enforces filters at the retrieval boundary.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, JWT, IAM, tenant_id.", "Stamps every indexed vector chunk with normalized access-control metadata fields (e.g., tenant_id, allowed_group_ids, classification_level, owner_id).", "Extracts principal claims (user_id, roles, security groups) strictly from a cryptographically verified server-side JWT/IAM session, never from LLM-generated tool arguments.", "Injects mandatory boolean metadata predicates (e.g., tenant_id == X AND array_contains_any(allowed_groups, user_groups)) into both vector and BM25 retrieval queries."]}, {"id": "KP2", "description": "Pre-Filtering vs Post-Filtering in ANN Search & Index Partitioning: Avoids recall starvation and cross-tenant leakage.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW, Milvus, top-k, recall.", "Uses native pre-filtering / single-stage filtered HNSW search (e.g., Milvus partition keys + bitset filtering) rather than naive post-filtering (where top-k might return 0 authorized results).", "Creates inverted/bitmap indexes on scalar security metadata fields and leverages partition_key on tenant_id to localize ANN graph traversal.", "Applies identical metadata ACL predicates to the sparse BM25 leg in hybrid retrieval so unauthorized keyword hits never leak into fusion/reranking."]}, {"id": "KP3", "description": "ACL Synchronization, Revocation Propagation & Defense-in-Depth Verification: Handles permission changes without full re-embedding.", "required": false, "acceptable_evidence": ["Technical keywords: top-k, ACL, SharePoint, CDC.", "Syncs source-system ACL changes (e.g., SharePoint/Google Drive permission revocation) via CDC/webhook pipelines that update vector metadata in-place without re-computing embeddings.", "Performs a fast authoritative permission check against the source ACL cache or policy engine (OPA/SpiceDB) before passing top-k chunks into the LLM prompt.", "Logs all access-control filter evaluations and denied document hits for security auditing."]}], "critical_failures": ["Allows the LLM agent to construct or modify the security metadata filter in the prompt (vulnerable to prompt injection privilege escalation).", "Retrieves unauthorized chunks into the LLM context window and relies on system prompt instructions (''do not mention secret docs'') to enforce access control."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'In a graph with unit-weight edges, how would you find the shortest path between a source and a target node?', '{"key_points": [{"id": "KP1", "description": "Breadth-First Search (BFS) FIFO Mechanics & Level-Order Invariant: Explains why BFS guarantees shortest path in unit-weight graphs.", "required": true, "acceptable_evidence": ["Technical keywords: BFS, collections.deque, FIFO, weight graphs.", "Uses Breadth-First Search (BFS) backed by a FIFO queue (e.g., collections.deque) starting from the source node at distance 0.", "Explains the monotonically non-decreasing distance invariant: nodes at distance d are fully explored before any node at distance d+1.", "Marks neighbor nodes as visited and records their predecessor/parent immediately when enqueuing (not when dequeuing) to prevent duplicate queue entries."]}, {"id": "KP2", "description": "Path Reconstruction, Termination & O(V + E) Complexity: Reconstructs the path and analyzes time/space bounds.", "required": true, "acceptable_evidence": ["Technical keywords: Dijkstra, time complexity, space complexity, O(V + E).", "Terminates immediately when the target node is reached, backtracking through the parent/predecessor map from target to source and reversing the sequence.", "States optimal O(V + E) time complexity and O(V) auxiliary space complexity for the queue and visited/parent structures.", "Explains why Dijkstra''s algorithm is unnecessary overhead (O((V + E) log V) with a min-heap) when all edge weights equal 1."]}, {"id": "KP3", "description": "Edge Cases & Bidirectional BFS Optimization: Handles disconnected targets, cycles, and high-branching graphs.", "required": false, "acceptable_evidence": ["Technical keywords: O(b^d), O(b^(d/2), branching graphs, disconnected graph.", "Handles edge cases cleanly: source == target (0-edge path), disconnected graph / unreachable target (returns null/-1), self-loops, and cycles.", "Proposes Bidirectional BFS (expanding frontiers simultaneously from source and target until they intersect) to reduce search complexity from O(b^d) to O(b^(d/2)).", "Notes that in directed graphs, reverse edges must be traversed for the backward frontier of Bidirectional BFS."]}], "critical_failures": ["Uses Depth-First Search (DFS) without exhaustive path relaxation, which does not find the shortest path in cyclic or general unweighted graphs.", "Marks nodes as visited only upon dequeue, causing exponential duplicate enqueues on dense graphs."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'BROAD', 150, 'In a real system, how would you decide between threads, asyncio, and multiprocessing for a service doing HTTP calls plus occasional heavy data parsing?', '{"key_points": [{"id": "KP1", "description": "Workload Decomposition (I/O-Bound HTTP vs CPU-Bound Parsing): Analyzes how asyncio, threads, and multiprocessing behave under both phases.", "required": true, "acceptable_evidence": ["Technical keywords: Global Interpreter Lock, GIL, multiprocessing, asyncio.", "Identifies HTTP calls as high-latency, network I/O-bound tasks ideally suited for single-threaded cooperative multitasking (asyncio) or OS threads.", "Identifies heavy data parsing (e.g., large JSON/XML/AST transformation in pure Python) as CPU-bound work that blocks the asyncio event loop and suffers from Global Interpreter Lock (GIL) contention in threads."]}, {"id": "KP2", "description": "Compare memory footprint and context-switching overhead: asyncio coroutines (kilobytes, thousands of concurrent sockets) vs OS threads vs separate OS processes.", "required": true, "acceptable_evidence": ["Technical keywords: asyncio event loop, thread pool executor, multiprocessing context switch, GIL bypass, memory footprint.", "Compares memory footprint and context-switching overhead: asyncio coroutines (kilobytes, thousands of concurrent sockets) vs OS threads vs separate OS processes.", "Selects asyncio for high-concurrency network I/O sockets (kilobytes per coroutine) while offloading CPU-heavy parsing to a ProcessPoolExecutor to bypass the Python GIL."]}, {"id": "KP3", "description": "Hybrid Execution Pattern (Asyncio + Bounded ProcessPool Offloading): Prevents CPU spikes from freezing HTTP concurrency.", "required": true, "acceptable_evidence": ["Technical keywords: ThreadPoolExecutor, ProcessPoolExecutor, Polars, loop.run_in_executor.", "Designs a hybrid architecture: uses asyncio (e.g., httpx/aiohttp) as the primary orchestrator for high-concurrency HTTP requests.", "Offloads the occasional heavy CPU parsing via loop.run_in_executor(process_pool, parse_fn, payload) to a bounded ProcessPoolExecutor sized to CPU core count.", "Notes that if the parser is written in a GIL-releasing native C/Rust library (e.g., Polars, PyArrow, orjson), a ThreadPoolExecutor avoids IPC pickling overhead while still freeing the event loop."]}, {"id": "KP4", "description": "Backpressure, IPC Serialization Cost & Queue Isolation: Protects against OOM and IPC bottlenecks.", "required": false, "acceptable_evidence": ["Technical keywords: asyncio.Semaphore, Kafka, IPC, OOM.", "Uses asyncio.Semaphore to bound concurrent in-flight HTTP downloads so buffered payloads awaiting CPU parsing do not exhaust memory.", "Minimizes inter-process communication (IPC) pickling overhead by passing raw byte buffers, shared memory, or file descriptors to worker processes.", "Considers decoupling extreme parsing workloads into an external worker queue (Celery/Kafka) if parsing duration is long or unpredictable."]}], "critical_failures": ["Runs heavy synchronous CPU parsing directly inside an async def coroutine, freezing the entire event loop and causing HTTP timeouts.", "Spawns a brand-new OS process for every single HTTP request, destroying throughput via process creation and memory overhead."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Is the application currently in production, and what is its user scale and usage context?', '{"key_points": [{"id": "KP1", "description": "Deployment Lifecycle Stage & Environment Rigor: Transparently distinguishes live production traffic from internal pilot or staging environments.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, container orchestration.", "States explicitly whether the system is serving live production users, running in a phased enterprise pilot/shadow deployment, or operating as a validated PoC.", "Describes the deployment topology (cloud runtime, container orchestration, authentication boundary, and CI/CD release gates).", "Distinguishes verified production telemetry from synthetic load-test benchmarks."]}, {"id": "KP2", "description": "Quantitative Scale & Workload Characterization: Specifies concrete user concurrency, request throughput, and corpus dimensions.", "required": true, "acceptable_evidence": ["Technical keywords: DAU, MAU, QPS, RPS.", "Quantifies active user base (DAU/MAU, internal enterprise seats, or tenant count) and request volume (queries per day, peak QPS/RPS, token throughput).", "Characterizes data scale (number of indexed documents/vectors, database size, average context length, and multi-turn session depth).", "Identifies traffic burstiness patterns (e.g., business-hours spikes vs batch overnight jobs)."]}, {"id": "KP3", "description": "Usage Context, Persona Workflows & SLA Constraints: Connects how end-users interact with the system to latency and reliability targets.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, TTFT, SLA, p95.", "Explains the primary user personas and how outputs integrate into their workflow (e.g., interactive copilot vs automated background triage).", "States the operational SLAs governed by that usage context (e.g., p95 TTFT < 1.5s for chat vs high-precision batch completion within 15 minutes).", "Describes blast-radius containment and human-in-the-loop review requirements dictated by the domain risk profile."]}], "critical_failures": ["Fabricates unrealistic scale numbers that contradict the described architecture (e.g., claiming 50,000 QPS on a single unindexed SQLite instance).", "Cannot explain who uses the system, how often it is invoked, or whether it is actually deployed."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What actions did your system take when evaluation scores like faithfulness or coherence were low?', '{"key_points": [{"id": "KP1", "description": "Runtime Corrective Routing (Re-Retrieval & Grounded Regeneration): Triggers bounded self-correction when faithfulness or coherence checks fail.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, top-k, corrective routing, corrective loops.", "Routes low-faithfulness drafts through a conditional LangGraph edge to a critique-and-revise node that strips unsupported claims and regenerates strictly from cited chunks.", "Triggers query rewriting or expanded hybrid retrieval (broadening top-k or relaxing metadata filters) when low faithfulness is caused by insufficient context coverage.", "Enforces a strict maximum retry counter (e.g., 1-2 corrective loops) to prevent infinite latency/token spirals."]}, {"id": "KP2", "description": "Safe Abstention, Confidence Disclaimers & Human Escalation: Prevents hallucinated outputs from reaching the user when correction fails.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, re-formatting, simplifying output structure.", "Falls back to a deterministic safe abstention response (''I do not have sufficient verified information in the knowledge base to answer this'') if faithfulness remains below threshold.", "Surfaces verified source snippets directly or routes high-risk queries to a human-in-the-loop review queue with full diagnostic context.", "Separates low-coherence handling (re-formatting/simplifying output structure) from low-faithfulness handling (blocking ungrounded factual assertions)."]}, {"id": "KP3", "description": "Offline Diagnostic Triage & Golden Dataset Flywheel: Logs low-scoring traces to drive root-cause fixes in retrieval or prompting.", "required": false, "acceptable_evidence": ["Technical keywords: chunk overlap, system prompt, golden dataset, LangSmith.", "Automatically routes low-scoring production traces into an observability failure bucket (e.g., LangSmith/Arize Phoenix) tagged by failure type (retrieval miss vs generator hallucination).", "Converts verified failure cases into regression test cases in the offline golden evaluation suite.", "Uses aggregated failure patterns to tune chunk overlap, cross-encoder reranker thresholds, or system prompt grounding instructions."]}], "critical_failures": ["Computes faithfulness/coherence scores passively in logs without taking any runtime or offline action to mitigate hallucinations.", "Retries generation in an unbounded loop until the evaluation passes, causing severe timeout failures."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What additional insights does Perfetto provide compared to Android Profiler, and why are they useful?', '{"key_points": [{"id": "KP1", "description": "Kernel CPU Scheduling & Cross-Process Visibility: Captures system-wide ftrace events, thread states, and Binder IPC outside the app process.", "required": true, "acceptable_evidence": ["Technical keywords: IPC, OS, thread states.", "Explains that Perfetto captures system-wide kernel ftrace data across all OS processes, whereas Android Profiler is primarily scoped to a single debuggable app process.", "Visualizes exact kernel thread scheduling states (Running, Runnable waiting for CPU core, Uninterruptible Sleep on I/O or lock contention) and CPU core frequency scaling."]}, {"id": "KP2", "description": "Traces cross-process Binder IPC transactions end-to-end (linking an app UI thread stall to a slow system_server or HAL service call).", "required": true, "acceptable_evidence": ["Technical keywords: Perfetto tracing, Binder IPC, ftrace kernel events, system_server stalls, HAL transaction tracking.", "Traces cross-process Binder IPC transactions end-to-end (linking an app UI thread stall to a slow system_server or HAL service call).", "Captures cross-process system calls and kernel ftrace events with Perfetto, tracking Binder IPC transactions between application UI threads and the Android system_server."]}, {"id": "KP3", "description": "End-to-End Frame Lifecycle & Hardware Pipeline Correlation: Tracks Choreographer, RenderThread, SurfaceFlinger, and GPU composition.", "required": true, "acceptable_evidence": ["Technical keywords: oom_score_adj, RenderThread, SurfaceFlinger, HWC.", "Correlates the complete display frame timeline across process boundaries: App UI Thread (Choreographer#doFrame) -> RenderThread -> SurfaceFlinger buffer latching -> GPU/HWC presentation.", "Pinpoints exact root causes of jank and dropped frames (e.g., shader compilation stalls, buffer queue stuffing, vs CPU preemption by background daemons).", "Captures hardware memory counters (LMK/oom_score_adj, page faults, ION/DMA-BUF allocations) and battery/power rail rails."]}, {"id": "KP4", "description": "Low-Overhead Production Capture & PerfettoSQL Analytics: Enables automated SQL querying over multi-gigabyte traces.", "required": false, "acceptable_evidence": ["Technical keywords: p99, SQL, CI, IDE.", "Incurs minimal ring-buffer overhead suitable for release builds and field telemetry, unlike heavy instrumentation in Android Studio Profiler.", "Provides the Trace Processor SQL engine (PerfettoSQL) to programmatically query p99 slice durations, lock contention, and jank regressions in CI.", "Supports long-duration trace recording and offline sharing without requiring an active IDE attachment."]}], "critical_failures": ["Claims Perfetto and Android Profiler provide identical data and differ only in UI theme.", "Cannot explain how system-level events (CPU preemption, Binder IPC, SurfaceFlinger) impact application performance."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What approach did you use for evaluation·sampling or full-scale evaluation·and why?', '{"key_points": [{"id": "KP1", "description": "Tiered Offline vs Online Evaluation Architecture: Combines 100% coverage where cheap/critical with sampling where expensive.", "required": true, "acceptable_evidence": ["Technical keywords: LLM-as-a-judge, CI/CD, CI, CD.", "Runs full-scale (100%) evaluation on the curated offline Golden Test Set during CI/CD pre-deployment gates to guarantee zero regression across known edge cases.", "Runs lightweight deterministic checks (schema validation, latency, citation existence, regex/PII guardrails, retrieval similarity scores) on 100% of live production traffic.", "Applies sampling for computationally expensive online LLM-as-a-judge evaluations (e.g., multi-step faithfulness and coherence grading) to control token cost and latency."]}, {"id": "KP2", "description": "Stratified & Risk-Weighted Sampling Design: Prioritizes high-uncertainty and failure-prone traces over uniform random sampling.", "required": true, "acceptable_evidence": ["Technical keywords: stratified, weighted, sampling, uncertainty.", "Explains why pure uniform random sampling misses rare tail failures and critical edge cases.", "Uses stratified and risk-weighted sampling: evaluates 100% of traces with thumbs-down feedback, tool retries, low reranker confidence, or fallback triggers, plus a 5-10% baseline random sample of normal traffic.", "Stratifies samples across user segments, query intents, and document domains to preserve statistical representativeness."]}, {"id": "KP3", "description": "Cost-Variance Trade-Off & Sample Size Justification: Quantifies token budget savings and confidence intervals.", "required": false, "acceptable_evidence": ["Technical keywords: LLM, SME, quantifies token.", "Calculates the cost multiplier of running multiple LLM judge calls on every production request (which can exceed the primary generation cost by 2-3x).", "Sizes sample cohorts to achieve target statistical confidence intervals (e.g., detecting a 2% quality drop at 95% confidence).", "Escalates a small subset of sampled LLM-judge disagreements to human SME review for continuous judge calibration."]}], "critical_failures": ["Claims to run heavy multi-prompt LLM-as-a-judge evaluations synchronously on 100% of high-QPS production traffic without acknowledging cost or latency impact.", "Uses tiny arbitrary samples without stratification, missing critical safety or hallucination regressions."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'BROAD', 150, 'What approach do you use for streaming responses, and why did you choose it over alternatives like WebSockets?', '{"key_points": [{"id": "KP1", "description": "Directionality Fit & Protocol Simplicity (SSE over HTTP vs WebSockets): Matches unidirectional token streaming to SSE.", "required": true, "acceptable_evidence": ["Technical keywords: SSE, Server-Sent Events, WebSockets, HTTP.", "Selects Server-Sent Events (SSE, text/event-stream) over standard HTTP/1.1 or HTTP/2 because LLM generation is fundamentally a request-followed-by-unidirectional-server-stream pattern.", "Contrasts with WebSockets, which provide full-duplex bidirectional channels needed for real-time voice/multiplayer gaming, but add unnecessary statefulness and protocol upgrade overhead for text streaming."]}, {"id": "KP2", "description": "Explain how SSE frames typed events (e.g., event: token, event: tool_call, event: citation, event: done) cleanly over a single HTTP response.", "required": true, "acceptable_evidence": ["Technical keywords: Server-Sent Events, SSE, EventSource, event: token, chunked transfer encoding, HTTP streaming.", "Explains how SSE frames typed events (e.g., event: token, event: tool_call, event: citation, event: done) cleanly over a single HTTP response.", "Formats SSE payloads with event headers (event: token, data: {''text'': ''...''}), terminating with an event: done signal to close the client EventSource stream."]}, {"id": "KP3", "description": "Enterprise Infrastructure, Proxy & Auth Compatibility: Evaluates load balancing, firewall traversal, and HTTP/2 multiplexing.", "required": true, "acceptable_evidence": ["Technical keywords: JWT, OpenTelemetry, rate limiting, HTTP.", "Highlights that SSE works natively over standard HTTP/HTTPS without custom L7 proxy upgrade handshakes, avoiding corporate firewall and API gateway drops common with WebSockets.", "Leverages standard HTTP middleware for Bearer/JWT auth, rate limiting, CORS, and OpenTelemetry tracing per request.", "Notes that over HTTP/2 and HTTP/3, multiple SSE streams multiplex over a single TCP/QUIC connection without head-of-line connection exhaustion."]}, {"id": "KP4", "description": "Stream Resilience, Reconnection Resume & Backpressure: Handles dropped connections, Last-Event-ID resumption, and proxy buffering.", "required": false, "acceptable_evidence": ["Technical keywords: Redis, Nginx, request.is_disconnected, ID.", "Uses sequence/event IDs (Last-Event-ID header or checkpoint offset in Redis) so a brief mobile/Wi-Fi drop resumes the stream from the last received token rather than restarting generation.", "Disables intermediate proxy response buffering (e.g., X-Accel-Buffering: no in Nginx) and sends periodic heartbeat comments (: ping) to prevent idle gateway timeouts.", "Handles client abort/cancellation signals (request.is_disconnected()) to immediately halt upstream LLM token generation and save compute cost."]}], "critical_failures": ["Claims SSE cannot stream tokens incrementally in real time or requires polling a new HTTP request per token.", "Ignores proxy buffering, disconnect cancellation, or stateful connection scaling challenges."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'BROAD', 150, 'What architectural or design improvements could have prevented the UI freezing issue during initial development?', '{"key_points": [{"id": "KP1", "description": "Strict Main-Thread Isolation & Background Worker Offloading: Decouples synchronous I/O and heavy computation from the UI rendering loop.", "required": true, "acceptable_evidence": ["Technical keywords: event loop, Dispatchers.IO, UI, JSON.", "Enforces a strict architectural boundary where network I/O, disk persistence, large JSON/markdown parsing, and cryptographic/ML operations execute on background threads or Web Workers / Coroutine Dispatchers.IO.", "Never blocks the 16.6ms (60fps) / 8.3ms (120fps) main event loop with synchronous calls or long-running loops."]}, {"id": "KP2", "description": "Use asynchronous message-passing or unidirectional data flow (UDF) to post immutable ready-to-render view states back to the UI thread.", "required": true, "acceptable_evidence": ["Technical keywords: Unidirectional Data Flow, Android Looper, Handler, StateFlow, Kotlin coroutines, Dispatchers.Main.", "Uses asynchronous message-passing or unidirectional data flow (UDF) to post immutable ready-to-render view states back to the UI thread.", "Offloads compute to Dispatchers.Default and emits immutable StateFlow data classes back to the main thread, preventing UI jank and ANRs."]}, {"id": "KP3", "description": "Render Throttling, Token Buffering & UI Virtualization: Prevents high-frequency stream updates or large DOM/view trees from saturating layout passes.", "required": true, "acceptable_evidence": ["Technical keywords: DOM, LLM, RecyclerView, LazyColumn.", "Buffers high-frequency streaming events (e.g., LLM tokens arriving every few milliseconds) and flushes UI state updates aligned with requestAnimationFrame (~30-60Hz) instead of re-rendering the entire component tree on every single token.", "Implements viewport virtualization / windowed recycling (RecyclerView, LazyColumn, react-window) for long conversation histories or large data tables.", "Memoizes expensive sub-components and incremental markdown/syntax-highlighting AST blocks so completed paragraphs are not re-parsed on every new token."]}, {"id": "KP4", "description": "Automated Frame-Budget Guardrails & StrictMode Instrumentation: Catches main-thread violations during development and CI.", "required": false, "acceptable_evidence": ["Technical keywords: ReAct, StrictMode, CI, PerformanceObserver.", "Enables StrictMode (Android) or long-task PerformanceObserver / React Profiler warnings in debug builds to fail fast on main-thread disk/network reads.", "Integrates automated frame-timing / Macrobenchmark jank tests in CI under realistic payload sizes.", "Implements optimistic UI transitions, skeleton states, and cancellable async tasks when users navigate away rapidly."]}], "critical_failures": ["Performs synchronous network requests, database queries, or heavy payload parsing directly on the main UI thread.", "Re-renders and re-parses the entire document history from scratch on every incoming character/token without throttling or memoization."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What are common imputation methods and dimensionality reduction techniques used in preprocessing?', '{"key_points": [{"id": "KP1", "description": "Missing Value Imputation Methods & Missingness Mechanisms: Matches imputation strategy to distribution skew and MCAR/MAR/MNAR assumptions.", "required": true, "acceptable_evidence": ["Technical keywords: is_missing, MCAR, MAR, MNAR.", "Covers univariate statistical imputation: Mean (symmetric numerical), Median (skewed numerical with outliers), Mode / ''Missing'' category (categorical), and Forward/Backward fill (time-series).", "Covers multivariate model-based imputation: K-Nearest Neighbors (KNNImputer) and Multivariate Imputation by Chained Equations (MICE / IterativeImputer).", "Adds binary missingness indicator columns (is_missing) when missingness itself carries predictive signal (MNAR)."]}, {"id": "KP2", "description": "Dimensionality Reduction Techniques (Feature Extraction & Selection): Distinguishes linear projection, manifold learning, and feature elimination.", "required": true, "acceptable_evidence": ["Technical keywords: TF-IDF, Lasso, SHAP, PCA.", "Explains linear projection methods: Principal Component Analysis (PCA for dense standardized data), Truncated SVD (for sparse text/TF-IDF matrices), and Linear Discriminant Analysis (supervised LDA).", "Explains non-linear manifold/embedding compression: UMAP, t-SNE (for visualization), Autoencoders, and Matryoshka Representation Learning (MRL) for vector embeddings.", "Includes feature selection methods: variance thresholding, correlation pruning, L1 (Lasso) regularization, and tree-based/SHAP importance filtering."]}, {"id": "KP3", "description": "Feature Scaling & Zero-Leakage Pipeline Fitting: Standardizes features prior to PCA/KNN and fits transformers strictly on training splits.", "required": false, "acceptable_evidence": ["Technical keywords: cross-validation, data leakage, PCA, KNN.", "Standardizes features (StandardScaler: zero mean, unit variance) before running PCA or KNNImputer so large-magnitude columns do not dominate variance or distance.", "Encapsulates imputation, scaling, and PCA inside a cross-validation Pipeline (fit on train fold only, transform on validation/test) to prevent data leakage."]}], "critical_failures": ["Fits imputer statistics or PCA components on the entire dataset before train/test splitting, causing data leakage.", "Applies PCA on unscaled features with wildly different units without standardization."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'EASY', 'SPECIFIC', 60, 'What are the differences between RNNs and LSTMs, and how do they handle sequence data?', '{"key_points": [{"id": "KP1", "description": "Sequential Recurrence & Vanilla RNN Vanishing Gradient Bottleneck: Explains step-by-step hidden state updates and BPTT gradient decay.", "required": true, "acceptable_evidence": ["Technical keywords: h_t, x_t, RNN, BPTT.", "Describes how both architectures process variable-length sequences step-by-step (t = 1..T), updating a recurrent hidden state h_t = f(W_hh * h_{t-1} + W_xh * x_t + b).", "Explains that during Backpropagation Through Time (BPTT), vanilla RNNs multiply gradients repeatedly by the recurrent weight matrix and tanh derivatives across time steps."]}, {"id": "KP2", "description": "Shows how this repeated multiplication causes gradients to vanish exponentially (losing long-term context beyond ~10-20 steps) or explode.", "required": true, "acceptable_evidence": ["Technical keywords: vanishing gradient, exploding gradient, BPTT, recurrent weight matrix, LSTM gating, long-term memory.", "Shows how this repeated multiplication causes gradients to vanish exponentially (losing long-term context beyond ~10-20 steps) or explode.", "Explains how recurrent weight multiplication over time steps drives gradient norms toward zero ($W^t -> 0$), which LSTMs mitigate via additive cell state lines and forget gates."]}, {"id": "KP3", "description": "LSTM Cell State Highway & Gating Architecture: Details the separate cell state c_t and the forget, input, and output gates.", "required": true, "acceptable_evidence": ["Technical keywords: c_t, f_t, i_t, o_t.", "Distinguishes LSTM''s dual state representation: long-term internal Cell State (c_t) and short-term working Hidden State (h_t).", "Explains the three sigmoid-controlled gates: Forget Gate f_t (what to erase from c_{t-1}), Input Gate i_t + candidate c~_t (what new info to write), and Output Gate o_t (what part of c_t to expose as h_t).", "Highlights the additive cell state update c_t = f_t * c_{t-1} + i_t * c~_t, which creates an uninterrupted gradient highway (Constant Error Carousel) when f_t is near 1."]}, {"id": "KP4", "description": "Parameter Complexity, Sequential Bottleneck & Modern Alternatives: Compares compute cost against GRUs and Transformers.", "required": false, "acceptable_evidence": ["Technical keywords: Transformer, self-attention, gradient clipping, O(T).", "Notes that an LSTM has ~4x the trainable parameters per layer compared to a vanilla RNN (and GRU simplifies this to 3 gates without a separate cell state).", "Points out that both RNNs and LSTMs process tokens sequentially O(T), preventing parallel training across time steps unlike Transformer self-attention.", "Mentions gradient clipping to guard against exploding gradients during recurrent training."]}], "critical_failures": ["Cannot name or explain the role of the cell state and gating mechanisms (forget, input, output gates) in an LSTM.", "Claims vanilla RNNs handle long-range sequence dependencies better than LSTMs."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What are the key differences between internal enterprise AI tooling and publicly available AI tools in terms of integration, security, and usability?', '{"key_points": [{"id": "KP1", "description": "Security, Data Residency & Access Governance: Contrasts enterprise zero-trust boundaries with public multi-tenant consumer endpoints.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, vLLM, GDPR, HIPAA.", "Enforces contractual zero-data-retention / no-training-on-prompts guarantees, VPC private endpoints (AWS Bedrock, Azure OpenAI, self-hosted vLLM), and data residency compliance (SOC2, HIPAA, GDPR).", "Integrates enterprise Identity & Access Management (SSO/OIDC, document-level RBAC/ABAC in RAG, and least-privilege scoped tokens for tool execution)."]}, {"id": "KP2", "description": "Implement automated DLP/PII redaction guardrails and immutable compliance audit trails logging every prompt, retrieved document, and tool invocation.", "required": true, "acceptable_evidence": ["Technical keywords: enterprise DLP, PII redaction guardrails, immutable compliance audit, SIEM forwarding, prompt logging.", "Implements automated DLP/PII redaction guardrails and immutable compliance audit trails logging every prompt, retrieved document, and tool invocation.", "Deploys local DLP proxies that scrub credentials and PII prior to model invocation, forwarding tamper-proof audit events to enterprise SIEM platforms."]}, {"id": "KP3", "description": "Deep Proprietary System Integration & Governed Actionability: Connects to internal knowledge bases and transactional APIs.", "required": true, "acceptable_evidence": ["Technical keywords: SharePoint, ERP, SAP, SQL.", "Connects directly to proprietary enterprise data silos (Confluence, SharePoint, Jira, Salesforce, ERP/SAP, internal SQL warehouses) via live connectors and hybrid RAG.", "Executes governed transactional actions (creating tickets, updating BOMs, triggering CI workflows) via schema-validated tool gateways rather than isolated copy-paste chat.", "Grounds responses in organization-specific taxonomy, internal acronyms, and proprietary engineering standards."]}, {"id": "KP4", "description": "Domain-Tailored Usability vs Generalist Consumer UX: Balances embedded workflow ergonomics against cold-start polish.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, UX, IDE, CRM.", "Embeds directly into employee surfaces (Slack/Teams bots, IDE extensions, CRM sidebars) with pre-configured domain templates, eliminating manual context uploading.", "Prioritizes verifiable citations, deterministic formatting, and human-in-the-loop approval gates over open-ended creative conversational flair.", "Acknowledges enterprise usability challenges (strict guardrail refusals, latency from security/RAG hops) and mitigates them via streaming and clear UX feedback."]}], "critical_failures": ["Addresses only one dimension (e.g., mentions security vaguely) while completely ignoring enterprise system integration and usability.", "Suggests pasting confidential enterprise source code or customer PII into unvetted public consumer AI web interfaces."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What are the key technical and operational challenges in building a production-ready prototype within a six-month timeline?', '{"key_points": [{"id": "KP1", "description": "Scope Creep Containment & Evolutionary Architecture Design: Balances rapid iteration against throwaway prototype debt.", "required": true, "acceptable_evidence": ["Technical keywords: API, MVP, evolutionary architecture, schema alignment.", "Bridges the ''PoC-to-Production chasm'' by designing modular interfaces (clean API contracts, decoupled storage/model layers) so PoC code evolves into production rather than requiring a total rewrite in month 5.", "Enforces strict MVP scope gating: locks core P0 vertical slices early and defers non-essential features to post-launch phases.", "Mitigates data quality and integration bottlenecks early (securing enterprise API access, schema alignment, and realistic evaluation data in Month 1-2)."]}, {"id": "KP2", "description": "Day-One Production Foundations (Security, Observability & CI/CD): Embeds operational guardrails without slowing velocity.", "required": true, "acceptable_evidence": ["Technical keywords: RBAC, rate limiting, CI/CD, CI.", "Builds non-negotiable production requirements in from the start rather than bolting them on in the final week: authentication/RBAC, secrets management, and input validation.", "Establishes automated CI/CD pipelines, infrastructure-as-code, structured logging/tracing, and golden evaluation suites early to prevent late integration regressions.", "Designs graceful degradation, rate limiting, and cost/latency budgets before exposing the system to real users."]}, {"id": "KP3", "description": "Phased Rollout, Stakeholder Alignment & Operational Handoff: Validates with canary/pilot users before full launch.", "required": false, "acceptable_evidence": ["Technical keywords: GA, stakeholder alignment, core pipeline.", "Structures the 6-month timeline into clear milestones (e.g., M1-2: architecture & core pipeline; M3-4: alpha dogfooding & eval hardening; M5: beta pilot & load/security testing; M6: production GA).", "Prepares runbooks, on-call alerting, and rollback mechanisms to ensure sustainable post-launch operations."]}], "critical_failures": ["Treats a ''production-ready prototype'' as a hacky notebook script with hardcoded credentials, zero tests, and no monitoring.", "Spends all 6 months over-engineering infrastructure for 100M users before validating the core functional workflow."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What are the production issues that you have faced or missed and how did you resolve that issue?', '{"key_points": [{"id": "KP1", "description": "Concrete Failure Scenario & Detection Gap Analysis: Details the exact technical symptom, blast radius, and why pre-prod checks missed it.", "required": true, "acceptable_evidence": ["Technical keywords: API, exhausting token, api schema, burst concurrency.", "Describes a specific, realistic production failure mode (e.g., silent embedding/chunking mismatch, unbounded agent retry loop exhausting token quotas, upstream API schema drift, or connection pool exhaustion under concurrent load).", "Explains candidly why pre-deployment testing missed the issue (e.g., synthetic test data lacked malformed multi-page PDFs, or staging traffic did not replicate burst concurrency)."]}, {"id": "KP2", "description": "Identify the observability signal or user symptom that surfaced the incident (p99 latency spike, faithfulness drop, error rate alert).", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus alert rule, P99 latency spike, Ragas faithfulness drop, Datadog dashboard, incident triage.", "Identifies the observability signal or user symptom that surfaced the incident (p99 latency spike, faithfulness drop, error rate alert).", "Correlates P99 latency spikes on API endpoints with upstream LLM token queue depths in Datadog, pinpointing cold-start model degradation."]}, {"id": "KP3", "description": "Root-Cause Diagnosis & Immediate Triage Remediation: Walks through systematic debugging and rapid blast-radius containment.", "required": true, "acceptable_evidence": ["Technical keywords: circuit breaker, checkpoint state, error rate recovery.", "Traces the root cause using distributed trace spans, checkpoint state inspection, or log correlation.", "Executes immediate production stabilization (e.g., circuit breaker activation, rolling back deployment, enabling strict token truncation/rate-limit caps, or routing to fallback model).", "Verifies fix efficacy against live production metrics (error rate recovery, latency normalization)."]}, {"id": "KP4", "description": "Blameless Post-Mortem & Systemic Guardrail Hardening: Implements automated regression tests and monitoring to prevent recurrence.", "required": false, "acceptable_evidence": ["Technical keywords: blameless post-mortem, CI/CD, CI, CD.", "Adds the exact failing production payload/scenario to the permanent CI/CD golden regression suite.", "Introduces new runtime guardrails or telemetry alerts specifically targeting the blind spot that allowed the issue to slip through.", "Documents architectural lessons learned (e.g., enforcing strict timeouts, idempotency keys, or schema contracts)."]}], "critical_failures": ["Claims to have never experienced or missed a single bug or production issue.", "Gives a vague, non-technical story without explaining the technical root cause or the engineering fix."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'BROAD', 150, 'What are the trade-offs between using a list, dictionary, or tree structure for storing tasks and subtasks?', '{"key_points": [{"id": "KP1", "description": "Operational Complexity Comparison (Lookup, Mutation & Traversal): Contrasts asymptotic costs across List, Dictionary, and Tree.", "required": true, "acceptable_evidence": ["Technical keywords: DFS, O(1), O(n), task_id.", "Evaluates Flat List: simple sequential iteration and O(1) append, but O(N) linear scan for ID lookup, deletion, and parent-child reconstruction.", "Evaluates Dictionary (Hash Map keyed by task_id): O(1) average lookup, status update, and rename by ID, but lacks native hierarchical ordering without explicit parent/children lists.", "Evaluates pure Pointer Tree (N-ary node hierarchy): natural O(N) pre-order DFS hierarchical printing and subtree operations (e.g., cascading delete or completion rollup), but O(N) traversal required to find an arbitrary task by ID without an auxiliary index."]}, {"id": "KP2", "description": "Hybrid Composite Architecture (Hash Map Index + Tree Adjacency): Combines O(1) point lookups with natural hierarchy traversal.", "required": true, "acceptable_evidence": ["Technical keywords: O(n), task_id, parent_id, TaskNode.", "Proposes combining a Dictionary (task_id -> TaskNode) with Tree adjacency pointers (parent_id and ordered children ID list on each node).", "Achieves O(1) point lookups for renaming, marking finished/unfinished, and attaching a new subtask to any parent ID, while retaining O(N) DFS traversal for hierarchical printing.", "Separates immutable unique task_id (UUID/monotonic int) from mutable display title so renaming never invalidates structural references."]}, {"id": "KP3", "description": "Serialization, Cycle Prevention & Database Mapping: Addresses persistence, orphan handling, and cycle invariants.", "required": false, "acceptable_evidence": ["Technical keywords: DAG, DB, JSON, redux state.", "Enforces DAG/tree invariants (preventing cycles when moving a task under its own descendant) and defines cascading vs re-parenting behavior on deletion.", "Compares in-memory structures to relational/document DB persistence (Adjacency List with recursive CTEs, Materialized Path, or Closure Table).", "Notes that normalized flat maps (id -> node) serialize cleanly to JSON/Redux state stores without circular object references."]}], "critical_failures": ["Claims a flat list or unindexed pointer tree achieves O(1) arbitrary task lookup by ID.", "Uses mutable task names as dictionary keys, causing broken subtask links whenever a task is renamed."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What are your goals for growth in the AI field, and how do you plan to expand your expertise across new domains such as construction technology?', '{"key_points": [{"id": "KP1", "description": "Concrete AI Engineering Growth Goals: Articulates a clear trajectory toward production-grade, reliable, and scalable AI architectures.", "required": true, "acceptable_evidence": ["Technical keywords: ROI, AI, concrete, engineering.", "Defines specific technical growth objectives (e.g., mastering multi-agent orchestration, multimodal document/blueprint understanding, rigorous evaluation/observability, and latency/cost optimization).", "Focuses on bridging cutting-edge AI capabilities with measurable enterprise reliability and business ROI rather than chasing hype."]}, {"id": "KP2", "description": "Demonstrate continuous learning habits (benchmarking new architectures, reading system papers, building production prototypes).", "required": true, "acceptable_evidence": ["Technical keywords: continuous learning, arXiv paper reviews, bench testing, model distillation, production prototyping.", "Demonstrates continuous learning habits (benchmarking new architectures, reading system papers, building production prototypes).", "Maintains an active engineering research cadence by benchmarking new quantization methods (AWQ, GPTQ) and prototyping agent architectures on open datasets."]}, {"id": "KP3", "description": "Systematic Domain Onboarding Methodology (Construction Tech / AEC): Explains how to translate vertical domain constraints into AI system design.", "required": true, "acceptable_evidence": ["Technical keywords: precision, AEC, BOM, RFP.", "Partners closely with domain SMEs (estimators, project managers, site engineers) to understand core workflows: Bill of Materials (BOM) takeoffs, RFP/spec compliance, building codes, and change orders.", "Analyzes domain-specific data challenges in construction tech: noisy multi-modal PDFs, CAD/BIM schedules, tabular spec sheets, part nomenclature ambiguity, and strict unit/quantity precision.", "Builds domain-specific golden evaluation datasets and ontology glossaries before iterating on retrieval or agent prompts."]}, {"id": "KP4", "description": "Pragmatic Risk Management & End-User Empathy: Designs for high-stakes domain accuracy and field usability.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, UX, feedback loops, wrong material quantities.", "Recognizes that errors in physical industries (wrong material quantities or spec violations in construction) carry high financial and safety costs, requiring strict citation traceability and human-in-the-loop verification.", "Prioritizes intuitive, low-friction UX tailored to busy field and estimating professionals.", "Establishes tight feedback loops with early pilot users to iteratively refine domain edge cases."]}], "critical_failures": ["Expresses disinterest in learning domain specifics, claiming generic LLM prompts work identically across all industries without domain adaptation.", "Provides vague, generic career clichés without concrete technical or domain learning strategies."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What business problem does your enterprise AI assistant solve for recruiters, employers, and employees?', '{"key_points": [{"id": "KP1", "description": "Persona-Specific Bottleneck Decomposition (Recruiters, Employers & Employees): Articulates distinct operational problems solved for each stakeholder group.", "required": true, "acceptable_evidence": ["Technical keywords: Recruiters, Employers & Employees, persona, bottleneck.", "For Recruiters: eliminates manual resume screening bottlenecks, automates semantic skill-gap matching, generates structured interview rubrics, and accelerates outreach scheduling.", "For Employers / Hiring Managers: reduces time-to-fill and mis-hire risk via evidence-grounded candidate synthesis, standardized evaluation calibration, and automated job requisition drafting."]}, {"id": "KP2", "description": "For Employees: provides self-service HR/IT policy Q&A, automated internal mobility/career-path matching, and onboarding knowledge retrieval without ticket delays.", "required": true, "acceptable_evidence": ["Technical keywords: HR policy RAG, employee self-service, IT ticket deflection, internal mobility search, vector chunking.", "For Employees: provides self-service HR/IT policy Q&A, automated internal mobility/career-path matching, and onboarding knowledge retrieval without ticket delays.", "Indexes employee handbooks, IT knowledge bases, and internal job postings in Milvus, providing instant policy answers with direct intranet citations."]}, {"id": "KP3", "description": "Technical Workflow Mapping & Governed Execution: Connects each persona''s business problem to concrete RAG and agentic capabilities.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, RAG, ATS, PTO.", "Maps informational queries (benefits, handbooks, compliance policies) to permission-aware hybrid RAG with verifiable document citations.", "Maps transactional workflows (scheduling interviews, updating ATS stages, filing PTO/IT requests) to schema-validated tool execution with human-in-the-loop confirmation.", "Enforces role-based tenant isolation so recruiters, hiring managers, and employees only access authorized salary/evaluation records."]}, {"id": "KP4", "description": "Quantifiable Business & Operational Outcome Metrics: Defines how value is measured across personas.", "required": false, "acceptable_evidence": ["Technical keywords: groundedness, MTTR, CSAT, outcome metrics.", "Tracks recruiter/employer productivity metrics: reduction in time-to-shortlist, screening hours saved per requisition, interview-to-offer conversion rate, and rubric consistency.", "Tracks employee support metrics: Tier-1 HR/IT ticket deflection rate, mean time to resolution (MTTR), and answer groundedness/CSAT scores."]}], "critical_failures": ["Addresses only one persona while ignoring the other two explicitly asked in the prompt.", "Describes generic LLM capabilities without tying them to concrete recruitment, employer, or employee workflows and measurable outcomes."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'BROAD', 150, 'What challenges arise when updating shared state across multiple nodes, and how can you handle append vs overwrite behavior?', '{"key_points": [{"id": "KP1", "description": "Multi-Node Concurrency Hazards (Lost Updates, Race Conditions & Non-Determinism): Identifies what goes wrong when parallel nodes mutate shared state.", "required": true, "acceptable_evidence": ["Technical keywords: node concurrency, Lost Updates, multi, concurrency.", "Explains the lost-update problem: when Node A and Node B execute concurrently in the same superstep and both return a full or partial state update to the same key, naive assignment causes one node''s write to clobber the other.", "Identifies non-deterministic execution ordering across parallel branches, schema conflicts, and duplicate message insertion during node retries."]}, {"id": "KP2", "description": "Highlight in-place mutation hazards where nodes mutate shared Python list/dict references directly instead of returning immutable state deltas.", "required": true, "acceptable_evidence": ["Technical keywords: in-place mutation hazard, immutable state delta, LangGraph channels, TypedDict state, Reducer function.", "Highlights in-place mutation hazards where nodes mutate shared Python list/dict references directly instead of returning immutable state deltas.", "Avoids mutating shared list references directly in graph node functions, instead returning dict diffs ({''messages'': [new_msg]}) that reducers handle immutably."]}, {"id": "KP3", "description": "Declarative Channel Reducers for Append vs Overwrite Semantics: Configures explicit per-field reduction functions.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, operator.add, current_step, final_decision.", "Defines Overwrite (Last-Write-Wins) semantics as the default for scalar status fields (e.g., current_step, final_decision) where only a single authoritative node writes per step.", "Defines Append/Merge reducer semantics (e.g., Annotated[list, operator.add] or LangGraph add_messages reducer) for cumulative channels like conversation history, tool outputs, and parallel sub-agent findings."]}, {"id": "KP4", "description": "Implement custom dictionary-merge or ID-keyed upsert reducers that merge list items by unique message/task ID (overwriting if ID exists, appending if ID is new).", "required": false, "acceptable_evidence": ["Technical keywords: state reducer, message deduplication, ID-keyed upsert, dictionary merge, concurrent node execution.", "Implements custom dictionary-merge or ID-keyed upsert reducers that merge list items by unique message/task ID (overwriting if ID exists, appending if ID is new).", "Implements custom reducer functions that merge updates by message ID, replacing duplicate message entries rather than appending duplicate turns."]}, {"id": "KP5", "description": "Deterministic Merge Ordering, Idempotent Retries & State Pruning: Prevents duplicate appends and unbounded state growth.", "required": false, "acceptable_evidence": ["Technical keywords: RemoveMessage, branch index, deletion tokens.", "Enforces deterministic ordering when reducing parallel branch outputs (sorting by branch index or canonical task key before committing checkpoint).", "Uses deterministic message/event UUIDs inside custom reducers so retrying a failed node overwrites its prior partial entry rather than appending duplicate entries.", "Supports explicit state compaction/deletion tokens (e.g., RemoveMessage) to trim stale history without breaking append reducers."]}], "critical_failures": ["Mutates global shared dictionaries in-place across concurrent threads/coroutines without synchronization or reducer contracts.", "Cannot distinguish when a state field requires cumulative appending versus atomic replacement."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What changes would you make to scale a system from handling millions of files per day to billions per week?', '{"key_points": [{"id": "KP1", "description": "Partitioned Event Streaming & Small-File Compaction: Eliminates object-store metadata bottlenecks and queue contention.", "required": true, "acceptable_evidence": ["Technical keywords: parquet, sharding, Kafka, S3.", "Quantifies the throughput shift: 1M/day (~12 files/sec) vs 2B-5B/week (~3,300-8,000+ files/sec average, 20k+/sec peak).", "Replaces single-queue polling or synchronous uploads with horizontally partitioned log streaming (Kafka/Kinesis/PubSub partitioned by tenant_id + content_hash).", "Solves the S3/object-store ''small-file problem'' and prefix rate limits by batching/packing small files into columnar Parquet/TAR/RecordIO bundles and sharding object key prefixes."]}, {"id": "KP2", "description": "Disaggregated Compute Pools & Vectorized Batch Processing: Separates CPU, GPU, and I/O stages with zero-copy data paths.", "required": true, "acceptable_evidence": ["Technical keywords: Redis, COPY, LSM, SHA-256.", "Decouples ingestion into independent autoscaling worker pools: lightweight validation/dedup -> CPU parsing -> batched GPU embedding/inference -> bulk index writers.", "Replaces per-file database transactions and per-file RPCs with micro-batched vectorized writes (e.g., bulk COPY, LSM-tree stores like Cassandra/ScyllaDB/RocksDB, or segmented vector index building).", "Enforces content-addressable SHA-256 deduplication at the ingress edge (Bloom filters / Redis cluster) to avoid reprocessing identical files across tenants."]}, {"id": "KP3", "description": "Backpressure, Dead-Letter Isolation & Cost-Tiered Storage: Prevents poison-pill cascades and controls infrastructure spend.", "required": false, "acceptable_evidence": ["Technical keywords: checkpointing, rate limiting, letter isolation, level token.", "Implements end-to-end backpressure, tenant-level token-bucket rate limiting, and Dead-Letter Queues (DLQs) so malformed files never stall main consumer partitions.", "Leverages spot/preemptible compute instances with fine-grained checkpointing for stateless file workers.", "Applies automated storage lifecycle tiering (hot NVMe index for active data, warm compressed storage, cold archive for raw source files)."]}], "critical_failures": ["Assumes simply adding more worker threads against a single centralized relational DB table will survive thousands of file-state writes per second.", "Ignores object storage IOPS/API costs and small-file overhead at the billion-file scale."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What components or systems have you personally designed and architected, and what decisions did you make independently?', '{"key_points": [{"id": "KP1", "description": "System Boundary & Personal Ownership Clarity:Clearly delineates the end-to-end components personally architected.", "required": true, "acceptable_evidence": ["Technical keywords: API, data schemas, boundary, personal.", "Specifies the exact subsystem boundaries, API contracts, data schemas, and execution flows personally designed from scratch or re-architected.", "Distinguishes personal technical ownership (''I architected and implemented...'') from adjacent platform or team contributions."]}, {"id": "KP2", "description": "Explain the system''s functional requirements, scale constraints, latency budgets, and failure domain.", "required": true, "acceptable_evidence": ["Technical keywords: system architecture specification, SLA latency budget, horizontal scaling, failure domain isolation, decoupled microservices.", "Explains the system''s functional requirements, scale constraints, latency budgets, and failure domain.", "Specifies architectural boundaries, establishing P99 latency budgets (< 1.2s), async Celery task queues, and automated health check endpoints."]}, {"id": "KP3", "description": "Independent Architectural Decisions & Rejected Alternatives: Defends why specific technologies and patterns were chosen over competing options.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, SSE, BM25, cross-encoder reranking.", "Details 2-3 high-consequence decisions made independently (e.g., choosing hybrid BM25+Milvus with cross-encoder reranking vs dense-only; choosing stateful LangGraph orchestration vs linear chains; choosing SSE vs WebSockets).", "Articulates the explicit engineering trade-offs evaluated (latency vs recall, consistency vs availability, build vs buy, operational complexity vs cost).", "Explains why specific alternative architectures were benchmarked and rejected."]}, {"id": "KP4", "description": "Production Outcomes, Trade-Off Retrospective & Evolution: Connects design choices to real-world metrics and lessons learned.", "required": false, "acceptable_evidence": ["Technical keywords: p99, world metrics, p99 latency.", "Quantifies the production impact of those architectural decisions (throughput, p99 latency, accuracy/faithfulness, cost per 1k requests).", "Reflects candidly on edge cases or scaling limits encountered post-launch and how the design was iterated."]}], "critical_failures": ["Speaks only in vague ''we'' statements and cannot explain the internal mechanics or trade-offs of any component claimed.", "Describes following pre-written tickets with zero independent design judgment or trade-off analysis."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'What data sources were used in the knowledge base, and how did you preprocess and normalize them before ingestion?', '{"key_points": [{"id": "KP1", "description": "Heterogeneous Data Source Connectors & Format-Aware Extraction: Details the raw enterprise sources and layout-preserving parsers.", "required": true, "acceptable_evidence": ["Technical keywords: SharePoint, SQL, ERP, PDF.", "Identifies concrete knowledge base sources (e.g., PDFs/technical manuals, Confluence/SharePoint wikis, Markdown docs, Jira/Zendesk tickets, SQL/ERP tables).", "Applies format-appropriate extraction: layout-aware PDF/OCR parsing (preserving section headers and serializing tables to Markdown/JSON), HTML boilerplate/nav stripping, and ticket thread reconstruction."]}, {"id": "KP2", "description": "Cleans encoding artifacts (UTF-8 normalization), strips repeating headers/footers/watermarks, and redacts sensitive PII prior to chunking.", "required": true, "acceptable_evidence": ["Technical keywords: UTF-8 normalization, boilerplate removal, header/footer stripping, PII scrubbing, chunk metadata enrichment.", "Cleans encoding artifacts (UTF-8 normalization), strips repeating headers/footers/watermarks, and redacts sensitive PII prior to chunking.", "Applies ftfy for Unicode normalization, regex cleaners to remove repeating headers/footers, and Presidio redaction before chunking into 512-token segments."]}, {"id": "KP3", "description": "Canonical Schema Normalization & Metadata Enrichment: Maps disparate sources into a unified document record with rich provenance.", "required": true, "acceptable_evidence": ["Technical keywords: doc_id, chunk_id, text_content, source_type.", "Normalizes all ingested sources into a canonical schema: (doc_id, chunk_id, text_content, source_type, canonical_url, created_at, updated_at, version, acl_permissions).", "Extracts and attaches hierarchical structural metadata (document title, section breadcrumb path H1 > H2 > H3, page number) directly to every chunk.", "Prepends document title and section breadcrumb headers into the chunk text before embedding so chunks retain disambiguating context."]}, {"id": "KP4", "description": "Structure-Aware Semantic Chunking, Deduplication & Dual Indexing: Prepares chunks for hybrid vector + lexical search.", "required": false, "acceptable_evidence": ["Technical keywords: dense embeddings, BM25, Milvus, SHA-256.", "Splits documents using structure-aware / semantic chunking with controlled token overlap (e.g., 10-15% overlap) so sentences, code blocks, and tables are not severed mid-unit.", "Computes content hashes (SHA-256) and MinHash/SimHash near-duplicate detection to avoid indexing redundant boilerplate chunks.", "Generates dense embeddings (Sentence Transformers) for Milvus/vector storage and tokenizes normalized text for BM25 lexical indexing."]}], "critical_failures": ["Dumps raw uncleaned PDFs or HTML with tags, navbars, and broken tables directly into fixed-character chunks without metadata.", "Omits source provenance, timestamps, or access-control metadata during normalization."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What external factors, such as market conditions or competition, would you consider when analyzing declining user spend, and how would you validate their impact?', '{"key_points": [{"id": "KP1", "description": "Taxonomy of Exogenous Spend Confounders: Enumerates competitive, macroeconomic, seasonal, and acquisition-mix factors.", "required": true, "acceptable_evidence": ["Technical keywords: taxonomy, exogenous, spend, confounders.", "Identifies competitive shocks: aggressive competitor discounting, rival product launches, or bidding wars in paid acquisition channels.", "Identifies macroeconomic and calendar effects: inflation/disposable income contraction, holiday/back-to-school seasonality, weather anomalies, or industry budget freezes."]}, {"id": "KP2", "description": "Identify platform and ecosystem shifts: iOS/Android attribution or billing changes, payment gateway outages, or shifts in top-of-funnel marketing channel quality.", "required": true, "acceptable_evidence": ["Technical keywords: SKAdNetwork attribution, payment gateway friction, macroeconomic shifts, top-of-funnel ad quality, cohort analysis.", "Identifies platform and ecosystem shifts: iOS/Android attribution or billing changes, payment gateway outages, or shifts in top-of-funnel marketing channel quality.", "Investigates iOS SKAdNetwork tracking loss and payment gateway error rates to rule out platform attribution bugs before assuming organic demand dropped."]}, {"id": "KP3", "description": "Internal vs External Decomposition & Quasi-Experimental Validation: Isolates external shocks from internal product/model bugs.", "required": true, "acceptable_evidence": ["Technical keywords: AOV, experimental validation, recommendation latency.", "Rules out internal regressions first (checking release timelines, payment funnel error rates, recommendation latency/quality metrics, and A/B holdout groups).", "Validates external hypotheses using geographic or market-level variation (Difference-in-Differences or Synthetic Control comparing regions where a competitor launched vs regions where they did not).", "Decomposes Total Spend = Active Users x Conversion Rate x Order Frequency x Average Order Value (AOV) across tenure cohorts to see if drop is broad-based or isolated to price-sensitive tiers."]}, {"id": "KP4", "description": "External Signal Triangulation & Counter-Strategy Formulation: Integrates third-party benchmarks and survey data.", "required": false, "acceptable_evidence": ["Technical keywords: ARIMAX, Prophet, signal, triangulation.", "Correlates spend dips with external telemetry: share-of-search trends, app-store ranking shifts, competitor price scraping, and churn exit-survey citations.", "Includes exogenous macro/seasonality covariates in time-series baseline models (Prophet/ARIMAX) to quantify unexplained residual spend variance."]}], "critical_failures": ["Blames declining user spend on ''the economy'' or ''competition'' by gut feel without proposing any quantitative validation or control comparison.", "Fails to separate internal product/deployment regressions from external market trends."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What fallback mechanisms did you implement when the system could not confidently generate a correct answer?', '{"key_points": [{"id": "KP1", "description": "Multi-Signal Confidence Gating: Quantifies when retrieval or generation confidence is insufficient to answer safely.", "required": true, "acceptable_evidence": ["Technical keywords: BGE, generation retrieval, generation grounding.", "Evaluates pre-generation retrieval confidence: checks whether the top BGE Cross-Encoder reranker score or hybrid similarity score falls below a calibrated minimum threshold.", "Evaluates post-generation grounding confidence: checks citation coverage, self-consistency / semantic entropy, or faithfulness verifier score.", "Detects ambiguity when user queries lack required parameters or match multiple conflicting policy documents."]}, {"id": "KP2", "description": "Tiered Fallback Execution Cascade: Routes low-confidence states through progressive recovery steps rather than hallucinating.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid search, confidence states, Automated Recovery, Interactive Clarification.", "Tier 1 (Automated Recovery): triggers query rewriting/decomposition or broadens hybrid search parameters (or falls back from a small fast model to a stronger frontier reasoning model).", "Tier 2 (Interactive Clarification): asks the user a targeted disambiguating question when the query is underspecified.", "Tier 3 (Graceful Abstention & Search Fallback): explicitly abstains from fabricating an answer and returns deterministic links to the closest verified reference documents."]}, {"id": "KP3", "description": "Human-in-the-Loop Escalation & Context Handoff: Transfers unresolved queries seamlessly to human specialists.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, SME, context handoff.", "Escalates unresolved or high-stakes queries to a live support agent or SME review queue with a structured handoff payload (conversation summary, attempted queries, top retrieved snippets, and failure reason).", "Logs all fallback activations by trigger category to identify knowledge base gaps."]}], "critical_failures": ["Forces the LLM to guess an answer even when retrieval returns zero relevant context, causing ungrounded hallucinations.", "Relies solely on uncalibrated verbalized model confidence (''I am 95% sure'') without retrieval or grounding verification."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What guardrails and mechanisms did you implement to ensure compliance and data privacy, particularly for detecting and filtering sensitive data?', '{"key_points": [{"id": "KP1", "description": "Hybrid Sensitive-Data Detection Engine (Deterministic Patterns + Contextual NER): Identifies PII, PHI, and secrets with high recall.", "required": true, "acceptable_evidence": ["Technical keywords: recall, Microsoft Presidio, NER, PII.", "Combines deterministic regex and checksum validators (SSN, credit card Luhn check, API keys/high-entropy secrets, emails, phone numbers) with contextual NER models (Microsoft Presidio, spaCy, or fine-tuned token classifiers for names, addresses, medical conditions).", "Redacts or masks sensitive entities at two distinct ingress points: during offline document ingestion before vector indexing and at the online input gateway before LLM prompt assembly.", "Replaces sensitive spans with typed reversible or non-reversible placeholders (e.g., <PERSON_1>, <ACCOUNT_ID>) so reasoning works without exposing raw PII to external LLM providers."]}, {"id": "KP2", "description": "Output Egress Filtering & Tool Argument Sanitization: Prevents sensitive data exfiltration in responses, tool calls, and logs.", "required": true, "acceptable_evidence": ["Technical keywords: context window, system prompt, RBAC, Datadog.", "Scans model-generated outputs and tool call arguments prior to egress to block cross-user PII leakage, system prompt extraction, or unauthorized external webhook exfiltration.", "Enforces document-level RBAC/tenant metadata filters during retrieval so sensitive chunks are never loaded into an unauthorized user''s context window.", "Sanitizes observability traces and application logs so raw PII/credentials are never written to Langfuse, Datadog, or disk logs."]}, {"id": "KP3", "description": "Zero-Retention Agreements, Encryption & Right-to-Erasure Compliance: Satisfies GDPR/HIPAA/SOC2 lifecycle mandates.", "required": false, "acceptable_evidence": ["Technical keywords: Zero Data Retention, GDPR, CCPA, HIPAA.", "Uses enterprise LLM endpoints with contractual zero data retention (no model training on customer data) and KMS encryption at rest and TLS 1.3 in transit.", "Supports GDPR/CCPA deletion workflows capable of purging user-linked vectors, session checkpoints, and audit references by user_id."]}], "critical_failures": ["Sends raw unredacted PII/PHI or secret keys to public third-party LLM APIs without filtering or enterprise zero-retention controls.", "Relies on prompting the LLM (''Please ignore any SSNs in the text'') instead of deterministic pre-LLM redaction."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'What imputation strategies would you use for different types of missingness in healthcare time-series data, and how would you select between them?', '{"key_points": [{"id": "KP1", "description": "Missingness Mechanism Diagnosis in Clinical Data (MCAR, MAR & Informative MNAR): Differentiates sensor dropouts from clinician ordering bias.", "required": true, "acceptable_evidence": ["Technical keywords: MCAR, MAR, MNAR, random telemetry.", "Distinguishes MCAR (random telemetry packet loss / brief sensor detachment), MAR (missingness dependent on observed patient severity/ward), and MNAR (informative absence where a lab like troponin/lactate is not ordered because the patient appears stable).", "Recognizes that in healthcare MNAR, the fact and timing of a measurement being missing carries critical diagnostic signal that naive imputation destroys."]}, {"id": "KP2", "description": "Preserves explicit binary observation masks (m_t in {0, 1}) and time-since-last-observation intervals (delta_t) as first-class model features.", "required": true, "acceptable_evidence": ["Technical keywords: missingness indicator mask, delta-t interval, GRU-D, forward fill, vital signs telemetry.", "Preserves explicit binary observation masks (m_t in {0, 1}) and time-since-last-observation intervals (delta_t) as first-class model features.", "Appends a binary observation mask ($m_t in {0, 1}$) and elapsed time interval ($delta_t$) alongside forward-filled vital sign values to inform clinical models."]}, {"id": "KP3", "description": "Physiologically & Causally Valid Time-Series Imputation Strategies: Matches imputation method to biomarker dynamics without lookahead leakage.", "required": true, "acceptable_evidence": ["Technical keywords: LOCF, GRU-D, MICE, lookahead leakage.", "Applies causal Last Observation Carried Forward (LOCF / forward-fill) with strict biomarker-specific expiration windows (e.g., carrying forward static height/weight for days, but decaying acute arterial blood gas or heart-rate vitals toward patient/population baseline over minutes/hours).", "Leverages decay-aware recurrent/state-space architectures (e.g., GRU-D, Kalman smoothing/filtering, or MICE/Gaussian Processes across correlated vitals) that decay hidden states or imputations as delta_t grows.", "Strictly forbids backward-fill or bilateral linear interpolation during online inference or causal forecasting to prevent future lookahead leakage."]}, {"id": "KP4", "description": "Selection Protocol via Artificial Masking & Downstream Clinical Calibration: Evaluates imputation choices empirically.", "required": false, "acceptable_evidence": ["Technical keywords: cross-validation, MNAR, MAE, RMSE.", "Selects between strategies by applying realistic block/MNAR artificial masking on observed clinical time series and measuring reconstruction MAE/RMSE alongside downstream task AUROC/AUPRC.", "Conducts patient-grouped temporal cross-validation (never splitting a single patient''s ICU stay across train and test).", "Verifies that imputed values respect physiological bounds (e.g., SpO2 <= 100%, positive lab concentrations)."]}], "critical_failures": ["Uses future timestamps (linear interpolation or backward fill across the whole patient stay) in a causal real-time clinical prediction model.", "Applies global population mean imputation to rare, high-acuity lab tests without missingness indicator flags, erasing informative clinical signal."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What is data drift, how do you detect it in production systems, and how would you address it?', '{"key_points": [{"id": "KP1", "description": "Formal Drift Definition (Covariate, Label & Concept Drift): Distinguishes input distribution shift from target relationship shift.", "required": true, "acceptable_evidence": ["Technical keywords: concept drift, formal drift, covariate drift, Covariate.", "Defines Data (Covariate) Drift as a change in the input feature distribution P_prod(X) != P_train(X) while P(Y|X) may remain stable.", "Contrasts Covariate Drift with Prior/Label Shift (P(Y) changes) and Concept Drift (the underlying relationship P(Y|X) changes, e.g., new fraud attack patterns)."]}, {"id": "KP2", "description": "Identify common causes: upstream data pipeline schema/unit bugs, seasonal user behavior shifts, market shocks, or adversarial adaptation.", "required": true, "acceptable_evidence": ["Technical keywords: Evidently AI, Kolmogorov-Smirnov test, Population Stability Index (PSI), Wasserstein distance, data drift.", "Identifies common causes: upstream data pipeline schema/unit bugs, seasonal user behavior shifts, market shocks, or adversarial adaptation.", "Calculates Population Stability Index (PSI) and two-sample Kolmogorov-Smirnov tests daily in Evidently AI to detect feature distribution shifts."]}, {"id": "KP3", "description": "Statistical & Embedding Drift Detection Mechanisms: Specifies concrete metrics for continuous, categorical, and unstructured inputs.", "required": true, "acceptable_evidence": ["Technical keywords: Population Stability Index, PSI, KS, MMD.", "Uses Population Stability Index (PSI), Two-Sample Kolmogorov-Smirnov (KS) test, or Wasserstein (Earth Mover''s) distance for continuous numerical features.", "Uses Chi-Square test, Jensen-Shannon divergence, or L-infinity frequency shift for categorical features and missingness rates.", "Tracks centroid cosine distance, Maximum Mean Discrepancy (MMD), or out-of-distribution reconstruction error on high-dimensional text/image embeddings and model prediction score distributions."]}, {"id": "KP4", "description": "Root-Cause Triage & Closed-Loop Remediation Workflow: Separates broken data pipelines from true domain shift and retrains safely.", "required": false, "acceptable_evidence": ["Technical keywords: SHAP, canary deployment, data pipelines, feature pipeline.", "First triages whether drift is an engineering artifact (broken feature pipeline, null spike, unit change) before triggering model retraining.", "Prioritizes drift alerts by feature importance (SHAP/permutation importance) so noise in low-impact features does not cause alert fatigue.", "Addresses true drift via time-weighted retraining on freshly labeled sliding windows, covariate importance weighting, or fallback rule activation, validated via shadow/canary deployment."]}], "critical_failures": ["Confuses data drift (input distribution P(X) shift) with software bugs or hardware latency.", "Triggers blind automated production model replacement on unverified drifted data without checking for upstream data corruption."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'What is the difference between INNER JOIN and OUTER JOIN, and when would you use each?', '{"key_points": [{"id": "KP1", "description": "Set-Theoretic Semantics & NULL-Padding Behavior: Contrasts INNER JOIN against LEFT, RIGHT, and FULL OUTER JOIN.", "required": true, "acceptable_evidence": ["Technical keywords: NULL, INNER, JOIN, LEFT.", "Explains that INNER JOIN returns only rows where the join predicate evaluates to true in both tables (unmatched rows from either table are excluded).", "Explains that OUTER JOIN preserves unmatched rows from one or both tables, populating columns from the non-matching side with NULLs."]}, {"id": "KP2", "description": "Distinguish LEFT OUTER JOIN (all left rows + matched right), RIGHT OUTER JOIN (all right rows + matched left), and FULL OUTER JOIN (all rows from both tables).", "required": true, "acceptable_evidence": ["Technical keywords: INNER JOIN, LEFT OUTER JOIN, RIGHT OUTER JOIN, FULL OUTER JOIN, NULL handling, Cartesian product.", "Distinguishes LEFT OUTER JOIN (all left rows + matched right), RIGHT OUTER JOIN (all right rows + matched left), and FULL OUTER JOIN (all rows from both tables).", "Contrasts INNER JOIN (which drops unmatched rows from both tables) with LEFT OUTER JOIN (which retains all left table rows, padding missing right table columns with NULLs)."]}, {"id": "KP3", "description": "Practical Engineering Use Cases & Anti-Join Pattern: Matches join type to business reporting and orphan-detection scenarios.", "required": true, "acceptable_evidence": ["Technical keywords: right_table.id, JOIN, IS, left anti-join.", "Uses INNER JOIN when strict referential existence is required on both sides (e.g., fetching line items only for valid completed orders).", "Uses LEFT JOIN when preserving the primary entity regardless of optional child records (e.g., listing all users and their total order count, including users with 0 orders).", "Uses LEFT JOIN ... WHERE right_table.id IS NULL (left anti-join) to identify orphaned records or entities missing an association."]}, {"id": "KP4", "description": "ON vs WHERE Predicate Placement & Optimizer Execution: Explains how filtering in WHERE silently converts a LEFT JOIN into an INNER JOIN.", "required": false, "acceptable_evidence": ["Technical keywords: ON, ACTIVE, LEFT, JOIN.", "Highlights the classic bug: placing a non-null filter on the right table in the WHERE clause (e.g., WHERE r.status = ''ACTIVE'') eliminates NULL-padded rows and implicitly turns a LEFT JOIN into an INNER JOIN; such predicates belong in the ON clause.", "Notes that INNER JOINs are commutative and associative, giving the query optimizer more freedom to reorder join trees compared to outer joins.", "Mentions 1-to-N fan-out row multiplication if join keys are not unique."]}], "critical_failures": ["Claims INNER JOIN preserves unmatched rows or confuses OUTER JOIN with CROSS JOIN (Cartesian product).", "Cannot explain what values populate the columns of the unmatched table in an OUTER JOIN (NULLs)."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'EASY', 'SPECIFIC', 60, 'What is the difference between a node versus a tool node?', '{"key_points": [{"id": "KP1", "description": "General Graph Node Role vs Specialized ToolNode Mechanics: Contrasts state transformation nodes with tool-call dispatchers.", "required": true, "acceptable_evidence": ["Technical keywords: ReAct, ToolMessage, partial_state_update, tool_calls.", "Defines a general Node as any callable function node(state) -> partial_state_update in the orchestration graph (used for LLM reasoning/planning, context assembly, query rewriting, or reflection).", "Defines a ToolNode as a specialized execution node that inspects the latest AIMessage for structured tool_calls, dispatches the corresponding registered functions/APIs, and packages results as ToolMessage objects linked by tool_call_id.", "Explains the ReAct/agent loop interaction: the LLM Agent Node decides WHICH tool to request (emitting tool_calls), while the ToolNode actually EXECUTES the side effect."]}, {"id": "KP2", "description": "Separation of Reasoning from Governed Execution: Explains why isolating tool execution in a dedicated ToolNode improves safety and control.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, human-in-the-loop, HITL, RBAC.", "Enforces strict Pydantic schema validation, input sanitization, and RBAC policy checks at the ToolNode boundary before any external API or database call runs.", "Supports human-in-the-loop (HITL) interrupts (interrupt_before=[''tools'']) to pause graph execution right before a ToolNode commits a high-risk mutation.", "Supports concurrent execution of multiple independent tool_calls emitted in a single LLM turn."]}, {"id": "KP3", "description": "Structured Error Handling & Retry Isolation: Catches tool exceptions and feeds structured error messages back to the agent.", "required": false, "acceptable_evidence": ["Technical keywords: handle_tool_errors, ToolNode, LLM, handle_tool_errors=True.", "Captures tool runtime exceptions (handle_tool_errors=True) inside the ToolNode and formats them into a ToolMessage so the LLM node can self-correct arguments on the next turn without crashing the graph.", "Applies tool-specific timeouts, rate limits, and idempotency keys independently of LLM generation nodes."]}], "critical_failures": ["Claims the LLM node executes external API calls or database queries directly during token generation.", "Cannot explain how tool_calls and ToolMessages connect an agent node to a tool node."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What is the difference between loc and iloc in pandas, and in what scenarios would each be used or fail?', '{"key_points": [{"id": "KP1", "description": "Label-Based (.loc) vs Position-Based (.iloc) Resolution & Slice Inclusivity: Contrasts index lookup mechanics and slice bounds.", "required": true, "acceptable_evidence": ["Technical keywords: row_label, col_label, row_pos, col_pos.", "Defines .loc[row_label, col_label] as index-label-based selection (and boolean Series mask filtering).", "Defines .iloc[row_pos, col_pos] as strict 0-based integer positional indexing (from 0 to length-1) regardless of index labels."]}, {"id": "KP2", "description": "Highlight the critical slicing difference: .loc[''a'':''c''] or .loc[0:5] is INCLUSIVE of both start and stop bounds, whereas .iloc[0:5] is EXCLUSIVE of the stop bound (standard Python half-open interval [0, 5)).", "required": true, "acceptable_evidence": ["Technical keywords: pandas .loc, .iloc, label-based indexing, integer position indexing, inclusive slice, half-open interval.", "Highlights the critical slicing difference: .loc[''a'':''c''] or .loc[0:5] is INCLUSIVE of both start and stop bounds, whereas .iloc[0:5] is EXCLUSIVE of the stop bound (standard Python half-open interval [0, 5)).", "Demonstrates that df.loc[0:3] selects 4 rows (indexes 0, 1, 2, 3 inclusive) whereas df.iloc[0:3] selects 3 rows (positions 0, 1, 2 exclusive), preventing off-by-one errors."]}, {"id": "KP3", "description": "Usage Scenarios & Specific Failure Modes (KeyError vs IndexError): Identifies when each indexer succeeds or throws an exception.", "required": true, "acceptable_evidence": ["Technical keywords: DataFrame, df.loc, reset_index, df.iloc.", "Explains when .loc fails: raises KeyError if a requested label is missing from the index (e.g., calling df.loc[0] after filtering/dropping row 0 without reset_index, or passing integer positions to a string/DatetimeIndex).", "Explains when .iloc fails: raises IndexError if an integer position is out of bounds (>= len(df)), raises TypeError if passed string column names (df.iloc[:, ''age'']), or raises NotImplementedError/ValueError if passed a label-aligned boolean Series.", "Explains the filtered-integer-index trap: on a DataFrame with filtered index [2, 5, 8], df.loc[2] returns the first row while df.iloc[2] returns the third row (label 8)."]}, {"id": "KP4", "description": "Safe Mutation & SettingWithCopy Prevention: Uses .loc for single-step conditional column assignment.", "required": false, "acceptable_evidence": ["Technical keywords: target_col, df.iloc, SettingWithCopy, SettingWithCopyWarning.", "Uses df.loc[condition, ''target_col''] = value to perform safe in-place assignment and avoid chained indexing SettingWithCopyWarning/Copy-on-Write bugs.", "Notes that duplicate index labels cause df.loc[label] to return a DataFrame (multiple rows) instead of a single Series, whereas df.iloc[i] always returns a single positional row."]}], "critical_failures": ["Reverses the definitions (claiming .loc is integer-position based and .iloc is label based).", "Claims .loc and .iloc have identical slice bound behavior."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'SPECIFIC', 90, 'What is the difference between supervised and unsupervised learning, and when would you use each?', '{"key_points": [{"id": "KP1", "description": "Mathematical Formulation, Label Dependency & Loss Objectives: Contrasts predictive function approximation with latent structure discovery.", "required": true, "acceptable_evidence": ["Technical keywords: f_theta, x_i, y_i, MSE.", "Defines Supervised Learning as optimizing a predictive mapping f_theta(X) -> Y over paired labeled examples {(x_i, y_i)} by minimizing empirical risk (e.g., cross-entropy for classification, MSE/Huber for regression).", "Defines Unsupervised Learning as modeling the underlying data distribution P(X) or latent structure over unlabeled data {x_i} (optimizing reconstruction error, cluster compactness, density estimation, or variance retention)."]}, {"id": "KP2", "description": "Contrasts evaluation: direct ground-truth metrics (AUROC, F1, RMSE on held-out test splits) vs intrinsic/downstream proxy metrics (Silhouette score, reconstruction loss, perplexity, human cluster audit).", "required": true, "acceptable_evidence": ["Technical keywords: ground-truth evaluation, AUROC, F1 score, Silhouette score, Davies-Bouldin index, reconstruction error.", "Contrasts evaluation: direct ground-truth metrics (AUROC, F1, RMSE on held-out test splits) vs intrinsic/downstream proxy metrics (Silhouette score, reconstruction loss, perplexity, human cluster audit).", "Evaluates supervised models using ground-truth test labels (AUROC, F1) while scoring unsupervised clustering using intrinsic geometric metrics (Silhouette score, Davies-Bouldin)."]}, {"id": "KP3", "description": "Canonical Algorithms & Practical Selection Criteria: Maps business problems and label availability to the right paradigm.", "required": true, "acceptable_evidence": ["Technical keywords: XGBoost, LightGBM, PCA, UMAP.", "Uses Supervised Learning (XGBoost, LightGBM, Logistic Regression, Neural Classifiers) when historical ground-truth targets exist and the goal is specific prediction (fraud classification, churn probability, demand forecasting).", "Uses Unsupervised Learning (K-Means/HDBSCAN clustering, PCA/UMAP dimensionality reduction, Isolation Forest/Autoencoder anomaly detection) when labels are unavailable, prohibitively expensive, or when discovering unknown patterns/segments.", "Addresses cold-start or evolving attack scenarios (e.g., zero-day fraud/intrusion detection) where unsupervised anomaly detection catches novel patterns that supervised classifiers were never trained on."]}, {"id": "KP4", "description": "Hybrid, Self-Supervised & Active Learning Pipelines: Combines unsupervised representations with supervised fine-tuning.", "required": false, "acceptable_evidence": ["Technical keywords: fine-tuning, PCA, learning pipelines, supervised fine-tuning.", "Combines both in production: uses unsupervised/self-supervised pretraining or clustering/PCA features as inputs to a downstream supervised model.", "Uses unsupervised clustering and uncertainty sampling to guide Active Learning or weak-supervision labeling when label budgets are constrained."]}], "critical_failures": ["Confuses classification with clustering (e.g., calling K-Means a supervised classifier or Logistic Regression an unsupervised algorithm).", "Cannot explain how evaluation differs when ground-truth labels are absent."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What is your approach to data preprocessing and validation, including handling missing values, outliers, and versioning?', '{"key_points": [{"id": "KP1", "description": "Automated Schema Validation & Leakage-Safe Missing Value Handling: Enforces data contracts and imputes strictly within training splits.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, Transformer, is_missing, TFDV.", "Enforces automated data validation gates (Great Expectations, Pandera, Pydantic, or TFDV) checking column types, null rate thresholds, allowed categorical domains, and referential integrity.", "Handles missing values based on missingness mechanism (median/mode/KNN/iterative imputation + binary is_missing indicator flags).", "Fits all imputation and scaling parameters strictly on the training split and serializes the fitted transformer pipeline for validation/test/production inference."]}, {"id": "KP2", "description": "Outlier Diagnosis & Robust Treatment (Errors vs True Tail Signal): Distinguishes corrupted records from informative extreme values.", "required": true, "acceptable_evidence": ["Technical keywords: IQR, RobustScaler, fraud transactions, quarantined.", "Detects outliers using robust statistical bounds (IQR * 1.5/3.0, Median Absolute Deviation / modified Z-score, or Isolation Forest).", "Separates data entry/sensor corruption (which should be filtered or quarantined) from genuine domain tail events (e.g., high-value fraud transactions, which must NOT be blindly dropped).", "Applies Winsorization (percentile clipping at 1st/99th percentiles computed on train), log1p transformation, or RobustScaler to bound outlier leverage."]}, {"id": "KP3", "description": "Immutable Dataset & Feature Pipeline Versioning: Guarantees end-to-end lineage and reproducibility.", "required": false, "acceptable_evidence": ["Technical keywords: Delta Lake, DVC, SHA, feature pipeline.", "Versions raw and preprocessed datasets using DVC, Delta Lake / Apache Iceberg time-travel snapshots, or Feature Store point-in-time views.", "Links every trained model artifact in MLflow/registry to the exact dataset SHA hash, preprocessing code commit, and fitted transformer artifact."]}], "critical_failures": ["Drops all outlier rows blindly in domains like fraud or anomaly detection where the outliers ARE the target positive class.", "Overwrites datasets in-place without versioning or fits preprocessing statistics across the entire dataset prior to splitting."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'What is your familiarity with programming fundamentals such as pointers and memory management, and how would you adapt to using C/C++ if required?', '{"key_points": [{"id": "KP1", "description": "Pointer Mechanics, Indirection & Stack vs Heap Memory Layout: Explains virtual memory addressing, value vs reference semantics, and allocation lifetimes.", "required": true, "acceptable_evidence": ["Technical keywords: heap, LIFO, heap memory, virtual memory.", "Explains pointers as variables storing virtual memory addresses, dereferencing (*ptr), address-of (&var), pointer arithmetic, and pass-by-value vs pass-by-pointer/reference.", "Contrasts Stack memory (deterministic LIFO scope-bound allocation, fast CPU cache locality, fixed frame size) with Heap memory (dynamic runtime allocation via malloc/free or new/delete, manual or ownership-tracked lifetime)."]}, {"id": "KP2", "description": "Connects high-level Python/Java object references and PyArrow/NumPy contiguous C-buffers to underlying pointer and memory-layout concepts.", "required": true, "acceptable_evidence": ["Technical keywords: pointer arithmetic, malloc/free, RAII, std::unique_ptr, PyArrow contiguous buffers, zero-copy memory.", "Connects high-level Python/Java object references and PyArrow/NumPy contiguous C-buffers to underlying pointer and memory-layout concepts.", "Connects Python''s PyArrow/NumPy contiguous C-buffers to C/C++ pointer structures and modern RAII smart pointer ownership (std::unique_ptr, std::shared_ptr)."]}, {"id": "KP3", "description": "Modern C++ Ownership Idioms (RAII, Smart Pointers & Move Semantics): Prevents leaks and dangling pointers systematically.", "required": true, "acceptable_evidence": ["Technical keywords: unique_ptr, shared_ptr, weak_ptr, string_view.", "Applies Resource Acquisition Is Initialization (RAII) so heap memory, file descriptors, and locks are automatically released when objects leave scope.", "Uses modern C++ smart pointers instead of raw owning new/delete: std::unique_ptr for zero-overhead exclusive ownership, std::shared_ptr for reference-counted shared ownership, and std::weak_ptr to break reference cycles.", "Uses const references (const T&), std::span/string_view, and move semantics (std::move / rvalue references) to avoid expensive deep copies."]}, {"id": "KP4", "description": "Memory Safety Hazards & Verification Tooling: Identifies classic C/C++ bugs and uses sanitizers/static analysis.", "required": false, "acceptable_evidence": ["Technical keywords: AddressSanitizer, UndefinedBehaviorSanitizer, ThreadSanitizer, CI.", "Identifies critical memory bugs: use-after-free (dangling pointer), memory leaks, double free, uninitialized reads, and out-of-bounds buffer overflows.", "Integrates AddressSanitizer (ASan), UndefinedBehaviorSanitizer (UBSan), ThreadSanitizer (TSan), Valgrind, and clang-tidy into CI builds."]}], "critical_failures": ["Cannot explain what a pointer is or the difference between stack and heap memory.", "Advocates scattering raw manual malloc/free calls without RAII, smart pointers, or sanitizer validation."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What is your understanding of fallback mechanisms in the system, and how are they implemented?', '{"key_points": [{"id": "KP1", "description": "Fallback Taxonomy Across Infrastructure, Retrieval & Generation Layers: Defines failure triggers and recovery targets.", "required": true, "acceptable_evidence": ["Technical keywords: LLM, schema validation, taxonomy, infrastructure.", "Defines fallbacks as deterministic resilience mechanisms that preserve system availability and safety when a primary model, tool, or retrieval step fails, times out, or produces low-confidence/invalid output.", "Distinguishes infrastructure fallbacks (LLM provider 429/5xx failover from primary endpoint to backup region/model) from semantic/workflow fallbacks (low retrieval relevance, schema validation failure, or guardrail block)."]}, {"id": "KP2", "description": "Ensures the user always receives a safe, predictable response or escalation rather than an unhandled 500 exception or hallucination.", "required": true, "acceptable_evidence": ["Technical keywords: graceful degradation, deterministic fallback, circuit breaker, cached response, human escalation queue.", "Ensures the user always receives a safe, predictable response or escalation rather than an unhandled 500 exception or hallucination.", "Implements a cascading fallback: when downstream LLM APIs time out, returns pre-cached high-confidence answers or routes queries to support ticketing without throwing 500s."]}, {"id": "KP3", "description": "Concrete Implementation Patterns (LangGraph Conditional Edges, RunnableWithFallbacks & Circuit Breakers): Explains code-level mechanics.", "required": true, "acceptable_evidence": ["Technical keywords: LangChain, LangGraph, conditional edges, exponential backoff.", "Implements model gateway fallbacks using bounded exponential backoff retries followed by automatic failover to a secondary model/provider (e.g., LiteLLM / LangChain .with_fallbacks()).", "Implements workflow-level fallbacks in LangGraph using conditional routing edges that inspect state error/confidence flags and route to an alternative tool, cached/keyword search, or safe abstention node.", "Enforces per-node execution timeouts and circuit breakers so a degraded downstream service fails fast to the fallback path."]}, {"id": "KP4", "description": "Idempotency & Fallback Observability: Prevents duplicate side effects and tracks fallback activation rates.", "required": false, "acceptable_evidence": ["Technical keywords: checkpoint state, idempotency, duplicate, effects.", "Checks checkpoint state and idempotency keys before triggering a fallback so non-idempotent side effects are never executed twice.", "Emits structured telemetry metrics and alerts whenever a fallback path is triggered to detect silent primary degradation."]}], "critical_failures": ["Implements fallbacks as an infinite retry loop against the same failing endpoint without timeouts or circuit breakers.", "Swallows exceptions silently and returns empty or corrupted state to downstream workflow nodes."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'EASY', 'SPECIFIC', 60, 'What issues arise when using task names as unique identifiers, and how would you address them?', '{"key_points": [{"id": "KP1", "description": "Collision & Referential Integrity Failure Modes of Name-Based Keys: Explains why display strings fail as primary identifiers.", "required": true, "acceptable_evidence": ["Technical keywords: parent_id, collision, referential, integrity.", "Identifies name collisions: users frequently create legitimate tasks or subtasks with identical titles (e.g., ''Write unit tests'' under three different features), causing overwrites or key errors in a name-keyed map.", "Identifies rename fragility: renaming a task''s display string changes its primary key, breaking parent_id/child references, foreign keys, URLs, and external audit logs unless expensive cascading updates are performed."]}, {"id": "KP2", "description": "Identify string-normalization hazards (case sensitivity, trailing whitespace, Unicode lookalikes) and ABA race conditions when a task is deleted and a new task is created with the same name.", "required": true, "acceptable_evidence": ["Technical keywords: UUID primary keys, surrogate key, Unicode normalization, ABA problem, unique constraint.", "Identifies string-normalization hazards (case sensitivity, trailing whitespace, Unicode lookalikes) and ABA race conditions when a task is deleted and a new task is created with the same name.", "Replaces task name keys with immutable UUIDv4 surrogate primary keys, treating user-facing names as mutable secondary attributes with unique index constraints."]}, {"id": "KP3", "description": "Immutable Surrogate Identifier Architecture: Separates internal entity identity from mutable user-facing display attributes.", "required": true, "acceptable_evidence": ["Technical keywords: Snowflake, O(1), task_id, child_id.", "Assigns every task an immutable, system-generated unique identifier upon creation (e.g., UUIDv4/UUIDv7, ULID, Snowflake ID, or database sequence integer).", "Stores tasks in a hash map / table keyed strictly by task_id, keeping title/name as a mutable property on the Task object.", "Stores parent-child relationships using parent_id and children=[child_id, ...] so renaming a task is an O(1) attribute update that never touches structural links."]}, {"id": "KP4", "description": "Secondary Name Indexing & Scoped Uniqueness Disambiguation: Supports user-friendly search by name when needed.", "required": false, "acceptable_evidence": ["Technical keywords: normalized_name, task_id, UNIQUE, CLI.", "Maintains a secondary index (normalized_name -> Set[task_id]) to support fast O(1) lookup by name while accommodating multiple tasks with the same title.", "Optionally enforces scoped uniqueness constraints (e.g., UNIQUE(parent_id, name)) or prompts the user with breadcrumb context (''Feature A > Write tests'' vs ''Feature B > Write tests'') when resolving ambiguous CLI/voice commands."]}], "critical_failures": ["Claims task names are fine as unique keys as long as you forbid users from ever renaming tasks or reusing common subtask names.", "Does not separate immutable primary identity from mutable display labels."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'What models would you consider for time-series demand forecasting, and how would you choose between them?', '{"key_points": [{"id": "KP1", "description": "Candidate Model Spectrum (Statistical, Gradient Boosted Trees & Deep Global Models): Compares strengths of each model family.", "required": true, "acceptable_evidence": ["Technical keywords: XGBoost, LightGBM, ETS, CatBoost.", "Includes classical statistical baselines: Seasonal Naive, ETS (Exponential Smoothing), SARIMAX, and Prophet for interpretable trend/seasonality on individual series.", "Includes tabular GBDTs (LightGBM, XGBoost, CatBoost) with engineered lag features, rolling window statistics, calendar/holiday encodings, and price/promo covariates."]}, {"id": "KP2", "description": "Includes global deep learning / probabilistic architectures (DeepAR, Temporal Fusion Transformer [TFT], N-BEATS/NHITS, PatchTST) for cross-learning across thousands of related series.", "required": true, "acceptable_evidence": ["Technical keywords: Temporal Fusion Transformer (TFT), DeepAR, N-BEATS, Prophet, cross-series learning, demand forecasting.", "Includes global deep learning / probabilistic architectures (DeepAR, Temporal Fusion Transformer [TFT], N-BEATS/NHITS, PatchTST) for cross-learning across thousands of related series.", "Deploys Temporal Fusion Transformers (TFT) or DeepAR for hierarchical inventory forecasting, leveraging cross-series attention across thousands of related SKUs."]}, {"id": "KP3", "description": "Data-Driven Model Selection Criteria: Matches model family to series count, history length, sparsity, and covariate richness.", "required": true, "acceptable_evidence": ["Technical keywords: SKU, TSB, promotions, price changes.", "Selects statistical/Prophet models when history is short, series count is small, and interpretability of trend/seasonality is paramount.", "Selects global LightGBM or TFT/DeepAR when forecasting thousands of SKUs with rich exogenous regressors (promotions, price changes, stockouts, cross-SKU interactions) and cold-start items.", "Uses specialized intermittent-demand models (Croston''s method, TSB, or Negative Binomial / Zero-Inflated Poisson loss) when SKU demand is sparse or lumpy."]}, {"id": "KP4", "description": "Rolling-Origin Backtesting & Business-Aligned Loss Metrics: Evaluates point and probabilistic forecasts without temporal leakage.", "required": false, "acceptable_evidence": ["Technical keywords: cross-validation, WAPE, MASE, MAPE.", "Validates models strictly via expanding-window or sliding-window time-series cross-validation (never random k-fold which leaks future demand into past lags).", "Selects business-aligned metrics: WAPE / sMAPE / MASE for point accuracy (avoiding standard MAPE which explodes when actual demand is 0) and Pinball Loss / Quantile Loss (P10/P50/P90) to optimize safety stock vs holding cost."]}], "critical_failures": ["Uses random train/test splitting on time-series data, leaking future target values into lag features.", "Proposes a single heavyweight deep transformer without benchmarking against seasonal naive or GBDT baselines."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What platforms you''re using? What kind of tools do you have? How are you using it? What are you using it for? Is it being underutilized, or do we need new tools?', '{"key_points": [{"id": "KP1", "description": "End-to-End Platform & Tooling Architecture Inventory: Details the orchestration, retrieval, serving, and observability stack and its purpose.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, checkpointing, BM25, hybrid search.", "Specifies the orchestration & agent layer (e.g., LangGraph for stateful cyclic workflows, checkpointing, and tool routing; FastAPI for async serving).", "Specifies the data & retrieval layer (e.g., Milvus/Qdrant/pgvector + BM25/Elasticsearch for hybrid search, BGE Cross-Encoder for reranking, Redis/Postgres for state and semantic caching)."]}, {"id": "KP2", "description": "Specifies the model gateway & observability layer (e.g., AWS Bedrock / Azure OpenAI / vLLM, Langfuse / LangSmith / Arize Phoenix + RAGAS for tracing and evaluation).", "required": true, "acceptable_evidence": ["Technical keywords: AWS Bedrock, vLLM, Langfuse, LangSmith, Arize Phoenix, RAGAS, model gateway observability.", "Specifies the model gateway & observability layer (e.g., AWS Bedrock / Azure OpenAI / vLLM, Langfuse / LangSmith / Arize Phoenix + RAGAS for tracing and evaluation).", "Deploys unified model gateways (AWS Bedrock / vLLM) monitored via Langfuse/LangSmith to track token consumption, latency histograms, and per-user cost allocation."]}, {"id": "KP3", "description": "Tooling Utilization Audit (Maximizing Existing Capabilities First): Identifies where existing stack features are commonly underutilized.", "required": true, "acceptable_evidence": ["Technical keywords: top-k, quantization, OpenTelemetry, CI.", "Diagnoses common underutilization in observability tools: teams collect raw Langfuse/OpenTelemetry traces for debugging but fail to utilize built-in dataset curation, prompt versioning, cost attribution, and automated CI regression evals.", "Diagnoses underutilization in vector/database platforms: using a vector DB purely for naive dense top-k while underutilizing native scalar partition keys, hybrid sparse-dense indexing, or quantization."]}, {"id": "KP4", "description": "Prioritizes unlocking existing licensed platform capabilities before introducing tool sprawl and additional operational maintenance.", "required": false, "acceptable_evidence": ["Technical keywords: tool consolidation, vendor evaluation, license optimization, operational maintenance, platform ROI.", "Prioritizes unlocking existing licensed platform capabilities before introducing tool sprawl and additional operational maintenance.", "Conducts quarterly platform audits to consolidate overlapping SaaS tools (e.g. standardizing on one observability vendor) before approving new infrastructure purchases."]}, {"id": "KP5", "description": "Gap Analysis & New-Tool Acquisition Governance: Defines objective criteria for when a new tool is genuinely justified.", "required": false, "acceptable_evidence": ["Technical keywords: ROI, PII, acquisition governance.", "Identifies genuine capability gaps that warrant new tooling (e.g., adding a layout-aware document parser like Docling/Textract for complex tables, or adding a dedicated real-time PII/guardrail proxy).", "Evaluates new tools against measurable ROI: latency overhead, integration maintenance cost, security/SOC2 posture, and benchmark lift on the golden test set."]}], "critical_failures": ["Lists a random grab-bag of overlapping buzzword tools without explaining how they fit together or what problem each solves.", "Advocates adopting new shiny tools continuously without auditing whether current tools already solve the requirement."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What safeguards would you implement to handle edge cases such as empty results in production systems?', '{"key_points": [{"id": "KP1", "description": "Defensive Null/Empty Contracts & LLM Hallucination Short-Circuiting: Prevents runtime crashes and ungrounded generation when results are empty.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, LLM, parametric memory, status=''NO_MATCH.", "Enforces strict schema and non-empty guards before indexing results (e.g., checking len(results) == 0 before accessing results[0], computing mean scores, or passing empty arrays to a cross-encoder reranker).", "Short-circuits or constrains the LLM generation node via a LangGraph conditional edge when retrieval returns 0 chunks above the relevance threshold, preventing the LLM from fabricating an answer from parametric memory.", "Returns typed empty-result envelopes (e.g., status=''NO_MATCH'', items=[], reason=...) rather than untyped None or ambiguous empty strings."]}, {"id": "KP2", "description": "Root-Cause Disambiguation & Progressive Query Relaxation: Distinguishes overly restrictive filters from missing corpus coverage.", "required": true, "acceptable_evidence": ["Technical keywords: ACL, vector search, cause, disambiguation.", "Distinguishes three causes of empty results: (1) overly strict metadata/keyword filters, (2) user ACL permissions blocking all matching docs, or (3) upstream service/index failure.", "Implements a bounded query-relaxation fallback: if exact keyword/metadata filter returns 0 hits, broadens date/category soft filters, expands synonyms, or falls back to semantic vector search while keeping hard security ACL filters intact.", "Provides actionable user feedback (e.g., ''No documents found matching [Filter X]; would you like to search across all dates?'')."]}, {"id": "KP3", "description": "Zero-Result Rate Telemetry & Anomaly Alerting: Monitors empty-result spikes to catch silent index or schema regressions.", "required": false, "acceptable_evidence": ["Technical keywords: ZRR, PagerDuty, API, rate telemetry.", "Tracks the production Zero-Result Rate (ZRR) segmented by tool, tenant, and query intent.", "Triggers automated PagerDuty/Slack alerts if ZRR spikes suddenly (which often indicates an expired API token, broken metadata field rename, or empty vector partition after a bad deployment)."]}], "critical_failures": ["Passes an empty retrieval context to the LLM without abstention guards, allowing the model to hallucinate facts.", "Relaxes security/tenant ACL metadata filters when results are empty, leaking unauthorized cross-tenant data."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What scaling strategies would you apply to ensure the system handles high query volume and large data efficiently?', '{"key_points": [{"id": "KP1", "description": "High-Query-Volume Scaling (Stateless Autoscaling, Multi-Tier Caching & Read Replicas): Absorbs high QPS with low tail latency.", "required": true, "acceptable_evidence": ["Technical keywords: vLLM, read replicas, Redis, HPA.", "Scales stateless API and orchestration tiers horizontally behind L7 load balancers using HPA on concurrency/RPS metrics, backed by connection pooling (PgBouncer).", "Implements multi-tier caching (Redis exact-match query/embedding cache + semantic vector cache for recurring queries) with request coalescing (singleflight) to prevent cache stampedes.", "Separates read and write paths (CQRS / read replicas) and uses dynamic micro-batching on GPU embedding/reranker inference servers (Triton/vLLM) to maximize throughput under high QPS."]}, {"id": "KP2", "description": "Large-Data-Volume Scaling (Horizontal Sharding, Metadata Partitioning & Vector Quantization): Keeps search complexity sub-linear as data grows.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, cross-encoder reranking, HNSW, IVF.", "Partitions and shards large datasets horizontally (e.g., consistent hashing or tenant_id/time-range partitioning in Milvus, Postgres, and Elasticsearch) so queries prune irrelevant shards immediately.", "Applies vector compression and quantization (Scalar Quantization SQ8, Product Quantization PQ, or DiskANN/MMap) with HNSW/IVF indexes to fit ratusan-million/billion vectors within RAM budgets.", "Enforces strict two-stage retrieval (fast pre-filtered ANN + BM25 retrieving top-50, followed by cross-encoder reranking only on top-50) rather than full scans."]}, {"id": "KP3", "description": "Backpressure, Load Shedding & Hot-to-Cold Storage Tiering: Protects system stability during traffic spikes.", "required": false, "acceptable_evidence": ["Technical keywords: rate limiting, p99, p99 latency.", "Implements per-tenant rate limiting, priority queues (interactive user queries prioritized over background batch jobs), and graceful degradation (skipping heavy reranker if p99 latency spikes).", "Separates hot active indexes on NVMe/RAM from warm/cold historical partitions in object storage."]}], "critical_failures": ["Addresses only compute scaling while ignoring database/index sharding for large data volumes (or vice versa).", "Performs brute-force linear scans or unbatched synchronous GPU calls at high query volume."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What security and compliance considerations are critical when evaluating third-party AI tools?', '{"key_points": [{"id": "KP1", "description": "Data Usage, Zero-Retention Guarantees & Regulatory Compliance: Verifies that enterprise data is never used for vendor model training.", "required": true, "acceptable_evidence": ["Technical keywords: Zero Data Retention, ZDR, GDPR, HIPAA.", "Requires binding contractual guarantees that customer prompts, embeddings, and outputs are never used to train foundation models and supports Zero Data Retention (ZDR) / configurable log TTLs.", "Verifies regulatory attestations and legal frameworks: SOC 2 Type II, ISO 27001/42001, GDPR Data Processing Addendum (DPA) with geographic data residency, and HIPAA Business Associate Agreement (BAA) if handling PHI.", "Audits the vendor''s sub-processor chain (e.g., which underlying LLM providers or cloud hosts receive the payload)."]}, {"id": "KP2", "description": "Identity, Network Isolation & Cryptographic Controls: Assesses enterprise IAM integration and boundary security.", "required": true, "acceptable_evidence": ["Technical keywords: RBAC, OIDC, TLS 1.3, REST.", "Requires enterprise SSO/SAML/OIDC, SCIM provisioning, fine-grained Role-Based Access Control (RBAC), and least-privilege API scoping.", "Evaluates network isolation options: AWS PrivateLink / VPC peering, IP allowlisting, TLS 1.3 in transit, and Customer-Managed Encryption Keys (CMEK / KMS) at rest.", "Verifies that the vendor exposes comprehensive, immutable audit logs for security SIEM ingestion."]}, {"id": "KP3", "description": "AI Safety Posture, IP Indemnification & Exit Portability: Evaluates adversarial robustness and vendor lock-in mitigation.", "required": false, "acceptable_evidence": ["Technical keywords: SLA, AI, IP, vendor lock.", "Reviews the vendor''s prompt-injection defenses, tenant memory isolation guarantees, and copyright/IP indemnification clauses.", "Assesses SLA/uptime guarantees, model deprecation policies, and data/prompt portability through an abstraction gateway to avoid single-vendor lock-in."]}], "critical_failures": ["Adopts a third-party AI tool that retains and trains on proprietary company data by default without legal/security review.", "Evaluates only model benchmark scores while ignoring data residency, encryption, and access control."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What specific optimizations led to the reported 10% improvement in video editing efficiency, and how did you identify and address thermal or shader-related bottlenecks?', '{"key_points": [{"id": "KP1", "description": "Diagnostic Profiling of Shader & Thermal Bottlenecks: Uses GPU/system profilers to isolate frame stalls and thermal clock throttling.", "required": true, "acceptable_evidence": ["Technical keywords: RenderDoc, AGI, ARM, causing memory.", "Profiles the end-to-end decode-render-encode pipeline using Perfetto, RenderDoc, AGI (Android GPU Inspector), Snapdragon Profiler, or ARM Mali Offline Compiler.", "Identifies shader-level bottlenecks: excessive texture fetches causing memory bandwidth saturation, dynamic branching/divergent warps in fragment shaders, high register pressure reducing occupancy, and runtime shader compilation stalls."]}, {"id": "KP2", "description": "Identify thermal bottlenecks by correlating sustained GPU/CPU power draw and skin/junction temperature rise with DVFS frequency throttling during long multi-minute video exports.", "required": true, "acceptable_evidence": ["Technical keywords: DVFS thermal throttling, GPU shader optimization, compute pass, power profile, hardware encoder.", "Identifies thermal bottlenecks by correlating sustained GPU/CPU power draw and skin/junction temperature rise with DVFS frequency throttling during long multi-minute video exports.", "Monitors Dynamic Voltage and Frequency Scaling (DVFS) curves to restructure GPU compute passes and utilize dedicated hardware video encoders (NVENC/MediaCodec)."]}, {"id": "KP3", "description": "Shader & Zero-Copy Pipeline Optimizations: Reduces GPU ALU/bandwidth load and eliminates CPU-GPU memory copies.", "required": true, "acceptable_evidence": ["Technical keywords: ALU, CPU-GPU, FBO, LUT.", "Fuses multiple sequential post-processing filter passes (color grading, LUTs, scaling, sharpening) into a single uber-shader / compute pass to eliminate intermediate FBO texture writes and reads.", "Converts unnecessary 32-bit float (highp) fragment calculations to 16-bit half-float (mediump), pre-warms/caches compiled shader binaries (Pipeline State Objects) at startup, and replaces per-pixel math with hardware-interpolated 3D LUT textures.", "Enforces a zero-copy hardware buffer path (MediaCodec decode -> SurfaceTexture / AHardwareBuffer / EGLImage -> OpenGL ES / Vulkan -> MediaCodec hardware encoder) avoiding CPU glReadPixels/ByteBuffer roundtrips."]}, {"id": "KP4", "description": "Thermal Management & Sustained Export Efficiency Validation: Paces workload to prevent thermal cliff and validates the 10% gain.", "required": false, "acceptable_evidence": ["Technical keywords: PowerManager.OnThermalStatusChangedListener, p99, OS, PowerManager.", "Monitors OS thermal headroom APIs (PowerManager.OnThermalStatusChangedListener / ADPF) to dynamically adapt preview resolution/frame rate or pace batch export queues before hitting severe thermal throttling cliffs.", "Validates the 10% efficiency improvement across standardized long-duration benchmark projects (measuring total export wall-clock time, frames-per-watt, and p99 preview frame time across cold and warm device states)."]}], "critical_failures": ["Copies decoded video frames back and forth between GPU textures and CPU byte arrays on every frame.", "Claims a 10% efficiency improvement without explaining any concrete GPU, shader, memory-bandwidth, or thermal mechanism."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What steps do you take to ensure data security and guardrails in an AI system that processes sensitive documents?', '{"key_points": [{"id": "KP1", "description": "Ingestion-Time Security, Sanitization & Indirect Prompt-Injection Defense: Protects the pipeline when parsing untrusted/sensitive files.", "required": true, "acceptable_evidence": ["Technical keywords: tokenization, prompt injection, indirect prompt injection, REST.", "Executes document parsing (PDF/Office/OCR) inside isolated, network-restricted sandboxes with file-type validation and malware scanning.", "Scans extracted text for indirect prompt injection attacks (e.g., hidden white-on-white text or metadata instructions attempting to hijack agent behavior) and strips/flags adversarial payloads.", "Runs automated PII/PHI/secret redaction or tokenization before generating embeddings, and encrypts raw documents and vector stores at rest with KMS customer-managed keys."]}, {"id": "KP2", "description": "Document-Level Access Control & Context Boundary Isolation: Prevents cross-user data leakage during RAG and agent execution.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, RAG, data leakage, tenant_id.", "Propagates source-document ACLs (tenant_id, owner, allowed_roles, classification_tier) onto every vector chunk and enforces server-side pre-filtering on every retrieval query.", "Enforces strict structural separation in the prompt between trusted system instructions and untrusted document content using XML/delimiter tagging, instructing the model to treat document content strictly as passive data.", "Requires explicit policy validation and human-in-the-loop approval before any tool can export, email, or mutate sensitive document records."]}, {"id": "KP3", "description": "Output DLP Scanning, Ephemeral Processing & Audit Lineage: Verifies responses and maintains compliance trails.", "required": false, "acceptable_evidence": ["Technical keywords: output guardrails, DLP, output, scanning.", "Applies output guardrails to verify that generated answers cite only authorized source chunks and do not leak unredacted sensitive identifiers.", "Uses zero-data-retention enterprise model endpoints and records immutable audit logs capturing who uploaded, queried, or viewed every sensitive document."]}], "critical_failures": ["Indexes sensitive documents into a global shared vector index without tenant/role metadata filtering.", "Treats text extracted from uploaded documents as trusted system instructions, enabling indirect prompt-injection data exfiltration."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Infrastructure as Code & Security', 'MEDIUM', 'SPECIFIC', 90, 'What strategies do you use to sanitize and validate user inputs from forms to prevent security vulnerabilities?', '{"key_points": [{"id": "KP1", "description": "Mandatory Server-Side Schema & Allowlist Validation: Enforces strict type, length, and domain constraints at the API boundary.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, JSON schema, API, UX.", "Enforces all validation on the server/API gateway boundary (treating client-side browser validation purely as UX convenience).", "Uses strict schema validators (Pydantic, Zod, JSON Schema) with allowlist rules: strict data types, min/max string lengths, numeric ranges, enum sets, and canonical regex formats (email, UUID).", "Canonicalizes and normalizes Unicode (NFC/NFKC) and URL/HTML encodings BEFORE running validation checks to prevent double-encoding bypasses."]}, {"id": "KP2", "description": "Context-Specific Injection Defense (SQLi, XSS, Command & Prompt Injection): Separates untrusted user data from executable interpreters.", "required": true, "acceptable_evidence": ["Technical keywords: prompt injection, XSS, SQL, HTML.", "Prevents SQL Injection by using parameterized queries / prepared statements (never string concatenation).", "Prevents Cross-Site Scripting (XSS) via context-aware output encoding, HTML sanitization allowlists (DOMPurify/Bleach for rich text), and strict Content-Security-Policy (CSP) headers.", "Prevents OS Command/SSRF/Path-Traversal and LLM Prompt Injection by forbidding shell interpolation, validating URLs against private IP blocklists, and isolating form fields in structured delimiters with input safety classifiers."]}, {"id": "KP3", "description": "Request-Level Protections (Payload Limits, CSRF, File Uploads & Safe Error Handling): Hardens the form submission endpoint.", "required": false, "acceptable_evidence": ["Technical keywords: rate limiting, CSRF, IP, SameSite.", "Enforces max request body size limits, per-IP/user rate limiting, and CSRF tokens / SameSite cookie attributes.", "Validates file uploads by inspecting magic bytes (MIME signature) rather than file extensions, renaming files to random UUIDs, and storing them outside the web root.", "Returns generic structured 400/422 validation errors without leaking stack traces or database internals."]}], "critical_failures": ["Relies solely on frontend JavaScript / HTML5 form attributes for security validation.", "Relies on naive denylists (e.g., stripping the word ''SELECT'' or ''<script>'') instead of parameterized queries and context-aware encoding."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What technical areas are evaluated in the subsequent interview rounds after the take-home assignment?', '{"key_points": [{"id": "KP1", "description": "Architectural Walkthrough, Authorship Verification & Trade-Off Defense: Explains every line of submitted code and why specific choices were made.", "required": true, "acceptable_evidence": ["Technical keywords: AI, architectural, walkthrough, authorship.", "Defends the architectural choices, data structures, model/prompt selection, and algorithmic complexity in the submitted take-home implementation.", "Articulates explicit trade-offs made due to the take-home timebox (what shortcuts were taken intentionally vs what would be required in production).", "Demonstrates complete mastery of the submitted codebase, confirming authentic understanding rather than unverified AI-generated boilerplate."]}, {"id": "KP2", "description": "Live Feature Extension, Edge-Case Hardening & Debugging: Adapts the solution in real time to new constraints.", "required": true, "acceptable_evidence": ["Technical keywords: adding concurrency, feature, extension, hardening.", "Implements or designs a live extension on top of the take-home submission (e.g., adding concurrency support, a new filtering rule, streaming, or retry logic).", "Identifies and fixes boundary conditions, malformed input edge cases, concurrency race conditions, and unit test gaps.", "Demonstrates clean, modular code organization that makes extending the take-home straightforward."]}, {"id": "KP3", "description": "Production Readiness, System Scaling & Cross-Functional Alignment: Evolves the take-home into a distributed enterprise service.", "required": false, "acceptable_evidence": ["Technical keywords: sharding, CI/CD, CI, CD.", "Discusses how to scale the single-node take-home prototype to 100x-1000x production load (caching, sharding, async queues, CI/CD, observability, and security guardrails).", "Evaluates collaboration, receptiveness to code-review feedback, and alignment with business/product goals."]}], "critical_failures": ["Assumes that once the take-home code runs on the sample input, subsequent rounds involve zero technical questioning about the code.", "Cannot explain or modify their own submitted take-home implementation when constraints change."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'What tools did you use for data extraction and preprocessing, and how did you decide when to use tools like Tika, Textract, or Docling?', '{"key_points": [{"id": "KP1", "description": "Comparative Capabilities of Tika, Textract & Docling: Contrasts extraction fidelity, layout awareness, and operational model.", "required": true, "acceptable_evidence": ["Technical keywords: DOCX, HTML, EML, AWS.", "Characterizes Apache Tika (and PyMuPDF/pdfplumber): fast, lightweight CPU extraction across hundreds of native digital file formats (DOCX, HTML, EML, simple digital PDFs), but loses complex multi-column reading order and scanned image content.", "Characterizes AWS Textract (or Azure Document Intelligence): managed cloud OCR + vision service excelling at scanned PDFs, handwritten forms, key-value pairs, and complex spanned tables with confidence scores, at higher per-page API cost and cloud egress."]}, {"id": "KP2", "description": "Characterizes Docling (or Unstructured/Marker): layout-analysis & table-structure vision models (DocLayNet / TableFormer) that convert complex PDFs into clean hierarchical Markdown/JSON while running self-hosted within private VPCs without per-page vendor fees.", "required": true, "acceptable_evidence": ["Technical keywords: IBM Docling, DocLayNet, TableFormer, layout analysis, markdown conversion, self-hosted VPC, PDF parsing.", "Characterizes Docling (or Unstructured/Marker): layout-analysis & table-structure vision models (DocLayNet / TableFormer) that convert complex PDFs into clean hierarchical Markdown/JSON while running self-hosted within private VPCs without per-page vendor fees.", "Deploys IBM Docling with TableFormer vision models inside a self-hosted Docker container, generating clean Markdown tables without recurring per-page cloud API costs."]}, {"id": "KP3", "description": "Complexity-Based Document Router & Cost-Quality Trade-Offs: Routes each document page/file to the optimal parser.", "required": true, "acceptable_evidence": ["Technical keywords: MIME, OCR, document router, extraction latency.", "Designs a pre-ingestion classifier/router inspecting MIME type, embedded text layer density, multi-column layout complexity, and presence of tables/scanned images.", "Routes clean digital text/Office/HTML files to fast CPU parsers (Tika/PyMuPDF), complex technical PDFs with tables/figures to Docling, and degraded scanned/handwritten forms to Textract OCR.", "Balances extraction latency, per-page cloud cost, and strict data-residency constraints (using self-hosted Docling/Tika when documents cannot leave on-prem/air-gapped infrastructure)."]}, {"id": "KP4", "description": "Post-Extraction Normalization, Confidence Gating & Provenance Preservation: Validates parsed tables and retains bounding-box citations.", "required": false, "acceptable_evidence": ["Technical keywords: LLM, extraction, confidence, OCR.", "Preserves page numbers, section hierarchy headers, and bounding-box coordinates in chunk metadata for visual highlight citations.", "Monitors OCR/table confidence scores and routes low-confidence pages to a vision-LLM fallback or human review queue."]}], "critical_failures": ["Uses a basic plain-text extractor like Tika on scanned image PDFs or complex financial/engineering tables, silently dropping or scrambling critical data.", "Cannot distinguish the architectural differences between Apache Tika, AWS Textract, and Docling."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What trade-offs did you consider when evolving your system from a proof of concept to a production-grade solution?', '{"key_points": [{"id": "KP1", "description": "Determinism & Bounded Orchestration vs Unconstrained PoC Autonomy: Replaces fragile free-form loops with governed state graphs.", "required": true, "acceptable_evidence": ["Technical keywords: ReAct, LangGraph, FAISS, Milvus.", "Evolves from unconstrained PoC prompt chains or autonomous ReAct loops to explicit, bounded LangGraph state machines with strict retry caps, timeouts, and deterministic conditional routing.", "Replaces ephemeral in-memory state and local vector files (FAISS/Chroma local) with durable, horizontally scalable storage (Postgres checkpointers, Redis caches, partitioned Milvus/Elasticsearch clusters)."]}, {"id": "KP2", "description": "Trades raw orchestration flexibility for predictable failure recovery, idempotency, and auditability.", "required": true, "acceptable_evidence": ["Technical keywords: idempotency, state checkpointing, error recovery, structured logging, production hardening.", "Trades raw orchestration flexibility for predictable failure recovery, idempotency, and auditability.", "Replaces quick in-memory scripts with idempotent message consumers, durable database transactions, and OpenTelemetry logging for complete production traceability."]}, {"id": "KP3", "description": "Accuracy vs Latency & Unit Economics Optimization: Balances frontier model quality against p95 SLA and token spend.", "required": true, "acceptable_evidence": ["Technical keywords: SSE, TTFT, SLA, unit economics.", "Replaces calling a single expensive frontier LLM for every step (PoC approach) with tiered model routing: fast/small models or classifiers for intent routing/extraction, reserving frontier models only for complex synthesis.", "Introduces semantic/exact caching, prompt compression, and SSE token streaming to meet strict p95 TTFT latency SLAs despite added security and reranking hops.", "Decouples heavy document ingestion and online evaluation into asynchronous background queues."]}, {"id": "KP4", "description": "Defense-in-Depth Security & Continuous CI/CD Evaluation Gates: Adds enterprise governance and regression protection.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, golden dataset, RBAC, CI/CD.", "Adds input/output PII and prompt-injection guardrails, document-level RBAC metadata filtering, and human-in-the-loop approval for write actions (accepting a slight latency cost for zero-trust safety).", "Replaces manual PoC ''vibe checks'' with automated CI/CD evaluation pipelines (golden dataset regression tests, RAGAS metrics, and live Langfuse tracing)."]}], "critical_failures": ["Deploys PoC code directly to production with in-memory state, no timeouts, no auth/RBAC, and no evaluation monitoring.", "Describes generic software refactoring without addressing concrete latency, cost, reliability, or safety trade-offs."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What trade-offs did you make while building the MVP version of your system?', '{"key_points": [{"id": "KP1", "description": "Deliberate Simplification for Hypothesis Validation: Trades premature scale optimization for fast user-value validation.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, RAG, pgvector, few-shot prompting.", "Chooses managed foundation model APIs with few-shot prompting and hybrid RAG over time-consuming custom model fine-tuning to validate core product utility first.", "Consolidates infrastructure into a clean modular monolith or single database (e.g., Postgres + pgvector/Redis) rather than Prematurely splitting into 15 microservices.", "Scopes connector/format support to the top 80% highest-volume document or workflow types while handling edge cases via human-in-the-loop review."]}, {"id": "KP2", "description": "Non-Negotiable Guardrails vs Reversible Shortcuts: Protects security and correctness while deferring scale polish.", "required": true, "acceptable_evidence": ["Technical keywords: PII redaction, API, MVP, PII.", "Distinguishes two-way doors (reversible choices like synchronous ingestion or higher per-token API cost at low MVP volume) from one-way doors (authentication, tenant data isolation, PII redaction, and audit logging, which are NEVER compromised).", "Accepts slightly higher unit token costs or manual batch triggers during MVP in exchange for zero infrastructure maintenance overhead.", "Implements baseline golden-dataset evaluation and tracing on day one so MVP quality is measured objectively."]}, {"id": "KP3", "description": "Clean Abstraction Seams & Technical Debt Paydown Triggers: Designs interfaces so MVP shortcuts can be swapped cleanly.", "required": false, "acceptable_evidence": ["Technical keywords: pgvector, Milvus, vLLM, technical debt.", "Encapsulates vector retrieval, model invocation, and task queues behind clean repository/gateway interfaces so swapping pgvector -> Milvus or OpenAI -> self-hosted vLLM requires zero business-logic rewrites.", "Defines quantitative scale triggers (e.g., >50 QPS, >10M chunks, or monthly token bill >$X) that automatically initiate the planned v2 architectural upgrade."]}], "critical_failures": ["Compromises core security, authentication, or cross-tenant data privacy as an ''MVP shortcut''.", "Cannot name any concrete technical trade-off or explain why an alternative was deferred."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'SPECIFIC', 90, 'What trade-offs would you consider when using locks (single lock vs multiple locks) in concurrent systems?', '{"key_points": [{"id": "KP1", "description": "Coarse-Grained Single Lock vs Fine-Grained Multiple Locks Trade-Off Matrix: Contrasts contention throughput against complexity.", "required": true, "acceptable_evidence": ["Technical keywords: grained lock, minimal memory, entity locks, reducing lock.", "Evaluates Single Coarse-Grained Lock: trivial to reason about invariants, minimal memory footprint, and impossible to self-deadlock across multiple resources, but serializes all threads (Amdahl''s Law bottleneck under high core counts).", "Evaluates Multiple Fine-Grained / Per-Entity Locks: allows true parallel mutation of disjoint buckets/rows, drastically reducing lock wait time under high concurrency."]}, {"id": "KP2", "description": "Identify the costs of fine-grained locking: higher memory allocation, lock acquisition/release CPU overhead, and false sharing (CPU L1/L2 cache-line bouncing if adjacent locks share a 64-byte cache line).", "required": true, "acceptable_evidence": ["Technical keywords: fine-grained locking, false sharing, CPU cache-line bouncing, lock contention, memory alignment.", "Identifies the costs of fine-grained locking: higher memory allocation, lock acquisition/release CPU overhead, and false sharing (CPU L1/L2 cache-line bouncing if adjacent locks share a 64-byte cache line).", "Pads lock structures to 64-byte CPU cache-line boundaries (e.g., using @Contended in Java or alignment attributes) to prevent false sharing cache bouncing."]}, {"id": "KP3", "description": "Deadlock Prevention & Lock Striping Architecture: Solves multi-lock circular wait and unbounded lock proliferation.", "required": true, "acceptable_evidence": ["Technical keywords: try_lock, ConcurrentHashMap, striping architecture, canonical lock.", "Identifies the primary hazard of multiple locks: Deadlock (Coffman conditions) when Thread 1 locks A then B while Thread 2 locks B then A.", "Prevents deadlocks by enforcing a strict global canonical lock acquisition order (e.g., sorting resource IDs ascending: lock(min(A,B)) then lock(max(A,B))) or using bounded try_lock with timeout backoff.", "Proposes Lock Striping (e.g., pre-allocating a fixed array of K=64 or 256 locks indexed by hash(key) % K, as in ConcurrentHashMap) to bound lock memory while maintaining high concurrency."]}, {"id": "KP4", "description": "Read-Heavy & Lock-Free Alternatives (RWLock, Optimistic CAS & Actor Queues): Matches synchronization primitive to access patterns.", "required": false, "acceptable_evidence": ["Technical keywords: MVCC, CAS, SharedMutex, RWLock.", "Uses Read-Write Locks (RWLock / SharedMutex) when workloads are read-dominated (95%+ reads) and write hold times are brief.", "Considers lock-free atomic Compare-And-Swap (CAS), MVCC/Copy-on-Write snapshots, or single-writer shard queues when lock contention remains a bottleneck."]}], "critical_failures": ["Claims using multiple locks has zero downsides and never introduces deadlock risks.", "Acquires multiple locks in arbitrary caller-supplied order without canonical ordering or timeout recovery."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'What types of problems are typically involved in automating manual business processes, and how would you approach solving them?', '{"key_points": [{"id": "KP1", "description": "Core Challenges in Manual Process Automation: Identifies unstructured data variance, undocumented tacit rules, and legacy system fragility.", "required": true, "acceptable_evidence": ["Technical keywords: RPA, manual, automation, variance.", "Identifies input heterogeneity: manual workflows rely on messy unstructured emails, non-standard PDFs, spreadsheets, and ambiguous free-text requests that break rigid RPA/regex rules.", "Identifies tacit tribal knowledge: human operators apply undocumented edge-case exceptions, cross-system lookups, and judgment calls not captured in formal SOPs."]}, {"id": "KP2", "description": "Identify downstream integration friction: legacy ERPs/CRMs lacking modern APIs, partial failure states across multi-step updates, and high financial/regulatory cost of silent automation errors.", "required": true, "acceptable_evidence": ["Technical keywords: anti-corruption layer, partial failure recovery, human escalation, legacy ERP integration, audit logging.", "Identifies downstream integration friction: legacy ERPs/CRMs lacking modern APIs, partial failure states across multi-step updates, and high financial/regulatory cost of silent automation errors.", "Constructs transactional state machines with anti-corruption layers that stage multi-step ERP updates, rolling back gracefully if downstream systems fail."]}, {"id": "KP3", "description": "Hybrid Deterministic + Agentic Workflow Architecture: Combines LLM semantic extraction/routing with deterministic policy enforcement.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, LangGraph, LLM, DB.", "Decomposes the manual process into an explicit stateful graph (LangGraph): uses LLMs/vision parsers strictly where semantic flexibility is needed (entity extraction, document normalization, intent classification) and deterministic code where rules are exact (math calculations, policy validation, DB writes).", "Enforces strict Pydantic schema validation, canonical master-data resolution (matching fuzzy vendor/part names to ERP IDs), and idempotency keys on every external action.", "Curates historical human-completed cases with SMEs to codify tacit rules and build a golden evaluation benchmark before deployment."]}, {"id": "KP4", "description": "Confidence-Tiered Autonomy & Human-in-the-Loop Flywheel:Gradually increases straight-through processing while capturing human corrections.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, confidence, tiered, HITL.", "Implements progressive autonomy: starts in ''copilot/shadow mode'' (drafting actions for human 1-click approval), then enables straight-through automation for high-confidence standard cases while routing low-confidence/high-dollar exceptions to HITL review.", "Captures human reviewer edits and overrides as structured feedback to continuously refine prompts, rules, and regression tests."]}], "critical_failures": ["Replaces an entire mission-critical financial or operational workflow with an unconstrained autonomous LLM loop with zero deterministic validation or human review.", "Ignores partial failure recovery and idempotency when automating multi-system writes."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'What types of queries did your system handle, and how did it map them to relevant data sources?', '{"key_points": [{"id": "KP1", "description": "Query Taxonomy & Data Source Modality Alignment: Categorizes user queries by structure, freshness, and domain.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, SQL, BI, modality alignment.", "Classifies Unstructured Semantic/Policy Queries (''How does our parental leave or warranty policy work?'') -> mapped to hybrid Vector + BM25 knowledge base indexes (Confluence, PDFs, SOPs).", "Classifies Structured Analytical & Quantitative Queries (''What was total defect count or spend by vendor last quarter?'') -> mapped to SQL data warehouses / BI semantic layers via validated Text-to-SQL or parameterized query tools."]}, {"id": "KP2", "description": "Classifies Live Operational/Entity Status Queries (''What is the status of ticket #402 or BOM rev B?'') -> mapped to real-time REST/GraphQL microservices (Jira, ERP, CRM).", "required": true, "acceptable_evidence": ["Technical keywords: semantic query intent classifier, tool routing, Jira API, ERP GraphQL, entity resolution.", "Classifies Live Operational/Entity Status Queries (''What is the status of ticket #402 or BOM rev B?'') -> mapped to real-time REST/GraphQL microservices (Jira, ERP, CRM).", "Uses a fast intent classifier model (e.g., fine-tuned lightweight BERT or tool-calling LLM) to map operational status queries directly to Jira/ERP REST endpoints."]}, {"id": "KP3", "description": "Semantic Router & Conditional Graph Dispatch: Explains how the orchestrator selects and parameterizes target data sources.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, LangGraph, product_line, date_range.", "Implements an explicit Router / Planner node at the entry of the LangGraph workflow using structured output (Pydantic enum/tool selection) or fast embedding/classifier routing.", "Extracts structured metadata filters (department, product_line, date_range, entity_id) from the query to scope the target vector namespace or API endpoint.", "Decomposes complex multi-hop compound queries into parallel sub-queries dispatched concurrently across both structured APIs and unstructured RAG indexes, followed by a synthesis node."]}, {"id": "KP4", "description": "Fallback Re-Routing & Ambiguity Resolution: Handles misrouted queries or cross-source conflicts.", "required": false, "acceptable_evidence": ["Technical keywords: ERP, API, collection search.", "Monitors retrieval confidence/empty results from the primary selected source and dynamically falls back to secondary indexes or broader cross-collection search.", "Applies source-authority hierarchy rules (e.g., live ERP API overrides stale wiki documentation on pricing/inventory counts) when synthesizing multi-source context."]}], "critical_failures": ["Routes exact arithmetic/aggregation or live transactional status queries only to a static vector embeddings database.", "Searches every data source and dumps all results into the prompt without routing or relevance filtering."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'What types of user queries did your system handle, and how did you support both informational Q&A; and action-oriented requests?', '{"key_points": [{"id": "KP1", "description": "Intent Routing Between Informational Read Paths and Transactional Write Paths: Separates low-risk retrieval from side-effecting tool execution.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, BM25, cross-encoder reranking, BOM.", "Routes Informational Q&A requests (''What is the refund policy?'', ''Summarize spec X'') to the read-only hybrid RAG pipeline (query expansion -> BM25 + vector search -> cross-encoder reranking -> cited generation).", "Routes Action-Oriented requests (''Create a support ticket'', ''Update BOM quantity'', ''Schedule interview'') to a governed agentic tool-execution subgraph."]}, {"id": "KP2", "description": "Supports compound read-then-act workflows (e.g., retrieving company policy via RAG first to verify eligibility before staging an action request).", "required": true, "acceptable_evidence": ["Technical keywords: read-then-act workflow, RAG policy check, action staging, two-phase commit, human confirmation.", "Supports compound read-then-act workflows (e.g., retrieving company policy via RAG first to verify eligibility before staging an action request).", "Executes compound workflows: retrieves relevant HR/travel policy via RAG to verify eligibility before staging a structured API mutation request."]}, {"id": "KP3", "description": "Multi-Turn Slot Filling, Schema Validation & Policy Guardrails for Actions: Ensures tool calls are complete and authorized.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, LangGraph, human-in-the-loop, HITL.", "Performs conversational slot-filling: if an action request is missing required parameters (e.g., part number, date, approver), the graph pauses and prompts the user to supply missing fields rather than guessing.", "Validates all extracted tool arguments against strict Pydantic schemas and server-side business policy / RBAC rules before execution.", "Enforces Human-in-the-Loop (HITL) confirmation (LangGraph interrupt_before) for state-mutating or high-impact actions, displaying a preview card for user approval."]}, {"id": "KP4", "description": "Transactional Idempotency, Rollback & Unified Session Memory: Maintains state consistency across Q&A and action turns.", "required": false, "acceptable_evidence": ["Technical keywords: ToolMessage, transactional idempotency, session memory, checkpoint memory.", "Uses idempotency keys and transactional compensation/rollback handlers so network retries never duplicate side effects.", "Persists both Q&A context and completed ToolMessage action receipts in shared session checkpoint memory so follow-up questions (''Did my update go through?'') are answered accurately."]}], "critical_failures": ["Allows the LLM to execute destructive or state-mutating external API calls with the same zero-confirmation flow as read-only Q&A.", "Hallucinates missing tool parameters instead of asking the user for clarification."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'SPECIFIC', 90, 'What were the key requirements and trade-offs in building models for edge devices like Echo?', '{"key_points": [{"id": "KP1", "description": "Edge Hardware Constraints (Memory Footprint, Real-Time Latency & Power/Thermal Envelope): Quantifies always-on embedded device limits.", "required": true, "acceptable_evidence": ["Technical keywords: SRAM, DRAM, MB, DSP.", "Identifies strict SRAM/DRAM memory ceilings (often <1-5 MB for always-on wake-word/audio DSP models) and flash storage limits.", "Identifies real-time streaming latency constraints (processing 10-20ms audio frames with <50-100ms end-to-end detection latency and zero frame drops).", "Identifies continuous power consumption and thermal limits on embedded ARM Cortex-M/A or neural DSP cores, plus offline privacy requirements (audio stays local until wake-word triggers)."]}, {"id": "KP2", "description": "Model Compression & Hardware-Aware Optimization (Quantization, Distillation & Pruning): Shrinks models with minimal accuracy loss.", "required": true, "acceptable_evidence": ["Technical keywords: quantization, INT8, INT4, knowledge distillation.", "Applies Quantization-Aware Training (QAT) or Post-Training Quantization to convert FP32 weights/activations to INT8 or INT4/mixed-precision for integer DSP/NPU acceleration.", "Uses Knowledge Distillation (training a compact student DS-CNN, TinyGRU, or small Conformer from a large teacher ensemble) and structured channel pruning / low-rank factorization.", "Compiles models with hardware-specific runtimes (TFLite Micro, ONNX Runtime Mobile, TVM, ExecuTorch) using operator fusion and static memory arena allocation."]}, {"id": "KP3", "description": "FAR vs FRR Operating Point Trade-Off & Two-Stage Edge-Cloud Cascade: Balances privacy/cost against user responsiveness.", "required": false, "acceptable_evidence": ["Technical keywords: FAR, FRR, DET, DSP.", "Navigates the False Acceptance Rate (FAR: spurious wake-ups causing privacy concern and cloud server cost) vs False Rejection Rate (FRR: device ignoring user in noisy far-field room) trade-off curve (DET curve).", "Implements a multi-stage cascade: ultra-low-power Stage-1 acoustic detector on DSP -> larger on-device Stage-2 verifier on CPU/NPU -> cloud ASR/LLM verification."]}], "critical_failures": ["Assumes edge devices like Echo can run unquantized multi-billion-parameter FP32 models directly in local RAM without constraints.", "Ignores the False Accept vs False Reject trade-off and far-field acoustic noise challenges."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What would be the first thing you would do, coming to the office? How would you handle it?', '{"key_points": [{"id": "KP1", "description": "Production Health & Alert Triage First: Verifies live system stability, overnight pipeline runs, and urgent incidents before deep work.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, overnight pipeline.", "Checks production observability dashboards, overnight batch/ingestion job statuses, error-rate/latency alerts, and on-call handoff channels first.", "Immediately triages and mitigates any active production degradation, failing CI/CD pipeline, or security alert before starting new feature code."]}, {"id": "KP2", "description": "Reviews overnight evaluation/drift metrics if a model or prompt rollout occurred the previous day.", "required": true, "acceptable_evidence": ["Technical keywords: overnight telemetry review, model drift alert, P99 latency dashboard, error budget, standup triage.", "Reviews overnight evaluation/drift metrics if a model or prompt rollout occurred the previous day.", "Inspects overnight Grafana dashboards, Evidently drift reports, and error budget consumption to verify stability following recent model deployments."]}, {"id": "KP3", "description": "Unblocking Teammates & Asynchronous Communication Triage: Clears PR reviews and cross-team dependencies early.", "required": true, "acceptable_evidence": ["Technical keywords: PR, GitHub, Slack, Jira blockers.", "Scans critical engineering channels (Slack/Teams, GitHub PR review requests, Jira blockers) to unblock teammates waiting on code reviews or architectural decisions.", "Updates sprint/task status and prepares a concise, high-signal update for daily standup (yesterday''s outcome, today''s focus, any blockers).", "If answering in the context of Day 1 on a new job: sets up local dev environment, runs the test suite, reads architecture docs, and aligns with manager on 30-60-90 day deliverables."]}, {"id": "KP4", "description": "Ruthless Priority Ranking & Protected Deep-Work Execution: Structures the day around highest-impact engineering deliverables.", "required": false, "acceptable_evidence": ["Technical keywords: ruthless, priority, ranking, protected.", "Ranks the day''s tasks by business urgency and dependency impact (P0 incidents -> unblocking peers -> core architectural/sprint milestone).", "Time-boxes communication triage so the majority of the morning is protected for deep, focused coding and system design."]}], "critical_failures": ["Shows zero awareness of production system health, team blockers, or structured prioritization.", "Jumps randomly between low-priority tasks without checking alerts or aligning with team goals."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What''s the difference between sparse and dense, and when and why do you use them?', '{"key_points": [{"id": "KP1", "description": "Structural & Mathematical Contrast (Sparse Lexical vs Dense Semantic Vectors): Compares dimensionality, non-zero density, and index structures.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, TF-IDF, HNSW, IVF.", "Defines Sparse vectors (BM25, TF-IDF, SPLADE): high-dimensional vectors (size of vocabulary, e.g., 30k-100k+ dimensions) where >99% of entries are zero and non-zero weights correspond to explicit token/term presence, searched via an Inverted Index.", "Defines Dense vectors (Sentence Transformers, BGE, OpenAI embeddings): lower-dimensional continuous real-valued vectors (e.g., 384 to 1536 dimensions) where almost all elements are non-zero, capturing latent semantic meaning and searched via Approximate Nearest Neighbor (ANN / HNSW / IVF) graphs."]}, {"id": "KP2", "description": "Complementary Strengths & When to Use Each: Explains exact token precision vs semantic paraphrase generalization.", "required": true, "acceptable_evidence": ["Technical keywords: dense embeddings, precision, exact token, paraphrase generalization.", "Uses Sparse (BM25) when exact lexical matching is critical: part numbers, SKUs, error codes, function names, legal clause citations, rare acronyms, and out-of-domain proper nouns where dense embeddings often smooth over exact characters.", "Uses Dense embeddings when semantic intent, synonyms, paraphrases, conceptual similarity, and cross-lingual queries must be matched even when query and document share zero exact keywords."]}, {"id": "KP3", "description": "Notes that sparse BM25 requires zero GPU compute and handles arbitrary domain jargon out-of-the-box, while dense captures deep contextual relationships.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, dense embeddings, zero GPU cost, domain jargon, vocabulary mismatch, hybrid search.", "Notes that sparse BM25 requires zero GPU compute and handles arbitrary domain jargon out-of-the-box, while dense captures deep contextual relationships.", "Highlights that BM25 matches exact alphanumeric part IDs and error codes without GPU compute, complementing dense embeddings that capture semantic intent."]}, {"id": "KP4", "description": "Hybrid Retrieval Fusion & Cross-Encoder Reranking: Combines both representations for production RAG.", "required": false, "acceptable_evidence": ["Technical keywords: Reciprocal Rank Fusion, RRF, cross-encoder reranking, recall.", "Combines Sparse BM25 and Dense vector search in parallel (Hybrid Retrieval) using Reciprocal Rank Fusion (RRF) or convex score normalization.", "Follows hybrid candidate retrieval with a BGE Cross-Encoder reranker to achieve superior recall and precision across both keyword and conceptual queries."]}], "critical_failures": ["Confuses sparse and dense definitions (e.g., claiming BM25 produces low-dimensional dense neural embeddings).", "Claims dense vector search completely replaces the need for exact keyword matching on IDs, SKUs, or error codes."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'When an async guardrail flags a harmful response after it''s already been shown, what rollback/containment strategy would you implement to limit impact and preserve auditability?', '{"key_points": [{"id": "KP1", "description": "Immediate Stream Termination, UI Retraction & Downstream Action Containment: Halts exposure and blocks side effects in real time.", "required": true, "acceptable_evidence": ["Technical keywords: SSE, guardrail_retract, message_id, UI.", "Immediately aborts the upstream LLM generation stream if still in flight and pushes a high-priority control event over SSE/WebSocket (e.g., event: guardrail_retract with target message_id).", "Instructs the client UI to immediately replace the rendered message bubble with a safe policy refusal notice and disables copy/share/export actions on that message."]}, {"id": "KP2", "description": "Cancels or blocks any pending downstream tool calls, webhook dispatches, or email/notification jobs triggered by that turn.", "required": true, "acceptable_evidence": ["Technical keywords: retroactive containment, tool cancellation, WebSocket message retract, incident audit log, toxic response mitigation.", "Cancels or blocks any pending downstream tool calls, webhook dispatches, or email/notification jobs triggered by that turn.", "Dispatches immediate WebSocket retraction events to redact harmful messages on client screens while canceling asynchronous background tasks triggered during the turn."]}, {"id": "KP3", "description": "Conversation Context Sanitization & Checkpoint Rollback: Prevents the flagged response from poisoning subsequent agent turns.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, context window, LLM, conversation state.", "Tombstones or replaces the flagged AIMessage in the active LangGraph conversation state / session memory with a sanitized placeholder (''[Response removed by safety policy]'').", "Reverts the workflow checkpoint to the pre-generation state or marks the branch asquarantined so subsequent user turns do not feed the harmful output back into the LLM context window.", "Invalidates any semantic or exact response cache entries keyed by that prompt."]}, {"id": "KP4", "description": "Dual-Store Separation (Sanitized User View vs Immutable Forensic Audit Log): Preserves complete evidence for compliance without exposing users.", "required": false, "acceptable_evidence": ["Technical keywords: KMS, PII, forensic audit, Sanitized User View.", "Never hard-deletes the raw incident from compliance storage: writes an immutable, access-restricted forensic audit record (encrypted with KMS) containing the original prompt, retrieved chunks, raw flagged output, guardrail classifier scores, latency timestamp, and retraction confirmation.", "Triggers severity-based alerting (e.g., critical PII leak or self-harm/security violation) and feeds the trace into offline red-teaming to tighten synchronous pre-stream/chunk buffers."]}], "critical_failures": ["Hard-deletes the flagged output from all backend logs, destroying compliance auditability and forensic evidence.", "Retracts the message visually in the frontend UI but leaves the harmful text inside the backend conversation history array passed to future LLM turns."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'BROAD', 150, 'When mixing async with multiprocessing how would you handle back pressure and prevent the process pool from being overwhelmed under load.', '{"key_points": [{"id": "KP1", "description": "Diagnosing the Unbounded Executor Queue Hazard & Asyncio Semaphore Gating: Bounds in-flight tasks before submission.", "required": true, "acceptable_evidence": ["Technical keywords: asyncio, asyncio.Semaphore, ProcessPoolExecutor, loop.run_in_executor.", "Explains the core hazard: asyncio can accept 10,000+ concurrent network requests per second, whereas ProcessPoolExecutor only has N=CPU_COUNT workers and buffers pending futures in an unbounded internal queue, quickly exhausting RAM and IPC pipes.", "Wraps executor submission with a bounded asyncio.Semaphore(MAX_IN_FLIGHT) (e.g., sized to 1x-2x worker count) acquired BEFORE reading/pickling the large request payload or calling loop.run_in_executor()."]}, {"id": "KP2", "description": "Propagates backpressure naturally up the coroutine stack so upstream socket reads or queue consumers pause until a worker slot opens.", "required": true, "acceptable_evidence": ["Technical keywords: asyncio.Semaphore, BoundedQueue, backpressure propagation, socket flow control, worker starvation prevention.", "Propagates backpressure naturally up the coroutine stack so upstream socket reads or queue consumers pause until a worker slot opens.", "Enforces concurrency limits using asyncio.Semaphore matching process pool size, pausing incoming socket reads when worker queues reach capacity."]}, {"id": "KP3", "description": "Admission Timeouts, Load Shedding & Task Cancellation: Fails fast when queue wait time exceeds SLA.", "required": true, "acceptable_evidence": ["Technical keywords: SLA, asyncio.wait_for, sem.acquire, HTTP 429.", "Applies a strict admission timeout on semaphore acquisition (asyncio.wait_for(sem.acquire(), timeout=T_queue)) so requests do not sit in a backlog long after the client has timed out.", "Implements explicit load shedding: returns HTTP 429 Too Many Requests or 503 Service Unavailable with Retry-After headers when the bounded queue is full.", "Checks client disconnect status before dispatching queued work to a CPU worker so aborted requests never waste CPU cycles."]}, {"id": "KP4", "description": "IPC Payload Minimization, Worker Lifecycle Health & Metrics: Prevents worker OOMs and tracks queue saturation.", "required": false, "acceptable_evidence": ["Technical keywords: multiprocessing, HPA, multiprocessing.shared_memory, max_tasks_per_child.", "Minimizes IPC serialization pressure by passing compact data, shared memory (multiprocessing.shared_memory), or object-store references rather than pickling multi-megabyte objects across pipes.", "Configures max_tasks_per_child on the process pool to recycle workers periodically and prevent native C-extension memory fragmentation leaks.", "Instruments queue depth, semaphore wait latency, and worker utilization metrics to drive horizontal pod autoscaling (HPA)."]}], "critical_failures": ["Calls loop.run_in_executor() unconditionally for every incoming async request without a semaphore or bounded queue.", "Spawns new OS processes dynamically beyond CPU core count under load, causing thrashing and OOM crashes."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Why are data traceability, security, and auditability critical in drug development systems, and how does a platform like Vault address these requirements?', '{"key_points": [{"id": "KP1", "description": "Regulatory, Patient Safety & Scientific Integrity Imperatives in Drug Development: Explains why traceability and security are mandatory.", "required": true, "acceptable_evidence": ["Technical keywords: FDA, CFR, EMA, GLP.", "Connects traceability and auditability to patient safety, clinical trial validity, and strict regulatory mandates (FDA 21 CFR Part 11, EMA Annex 11, GxP / GLP / GCP / GMP, and ALCOA+ data integrity principles: Attributable, Legible, Contemporaneous, Original, Accurate).", "Explains that every clinical finding, adverse event, protocol amendment, or AI-extracted summary in an NDA/BLA submission must trace back to the exact source document version, page, and author."]}, {"id": "KP2", "description": "Highlight the need for strict security to protect patient PHI/HIPAA data and high-value proprietary molecular/clinical trial IP.", "required": true, "acceptable_evidence": ["Technical keywords: Veeva Vault, 21 CFR Part 11, electronic signatures, HIPAA, audit trail, clinical trial data integrity.", "Highlights the need for strict security to protect patient PHI/HIPAA data and high-value proprietary molecular/clinical trial IP.", "Implements 21 CFR Part 11 compliant tamper-evident audit trails and cryptographic signatures to safeguard proprietary clinical trial IP and patient records."]}, {"id": "KP3", "description": "Platform Controls for Versioning, Lifecycle State & Immutable Audit Trails: Explains how Vault enforces compliance.", "required": true, "acceptable_evidence": ["Technical keywords: RBAC, HashiCorp, lifecycle state, lifecycle states.", "Explains how Veeva Vault (or equivalent regulated document/security vault) enforces strict document lifecycle states (Draft -> In Review -> Approved -> Effective -> Superseded) with immutable major/minor version lineage.", "Enforces tamper-evident, append-only audit trails logging every view, edit, metadata change, workflow transition, and electronic signature (with timestamp, user identity, and reason for change).", "Enforces granular Dynamic Access Control / RBAC (blinding/unblinding boundaries in clinical trials, study-level and site-level permissions) and cryptographic encryption/secret leasing (if also discussing HashiCorp Vault)."]}, {"id": "KP4", "description": "AI Integration Guardrails on Regulated Vault Content: Preserves provenance and approval boundaries when layering RAG/Agents.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, RAG, AI, integration guardrails.", "Restricts AI retrieval strictly to ''Approved/Effective'' document versions (preventing unapproved drafts or obsolete protocols from grounding clinical answers).", "Propagates Vault user permissions and document version IDs into every RAG citation and requires human-in-the-loop e-signature approval before committing any regulated record update."]}], "critical_failures": ["Treats drug development data like casual consumer content with no awareness of regulatory compliance, version lineage, or patient safety.", "Allows AI systems to overwrite regulated clinical records or cite unversioned/unapproved documents without audit trails."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'BROAD', 150, 'Why did you choose timeouts over event-based completion for managing long-running tasks in your system?', '{"key_points": [{"id": "KP1", "description": "Failure Modes of Pure Event-Driven Completion (Lost Signals, Zombie Workers & Silent Hangs): Explains why waiting indefinitely for an event is unsafe.", "required": true, "acceptable_evidence": ["Technical keywords: OOM, LLM, TCP, party webhook.", "Identifies the fatal flaw of pure event-based completion without timeouts: if a worker process OOM-crashes, a third-party webhook is dropped, or an LLM/tool socket hangs in a half-open TCP state, the completion event NEVER arrives.", "Explains how missing completion events create ''zombie'' workflows that leak memory, hold database/semaphore locks indefinitely, and leave end-users stuck on infinite loading spinners.", "Notes that external legacy APIs or firewall-restricted environments often cannot push inbound completion events reliably."]}, {"id": "KP2", "description": "Deterministic SLA Enforcement, Resource Reclamation & Fallback Triggering: Uses timeouts to guarantee bounded execution.", "required": true, "acceptable_evidence": ["Technical keywords: SLA, p99, workflow timeouts, p99 latency.", "Enforces strict upper-bound execution budgets (per-step and end-to-end workflow timeouts) to guarantee predictable p99 latency SLAs.", "Uses timeout expiration as a deterministic state-transition trigger in the orchestration graph to release held worker slots, cancel orphaned child tasks, and route to a retry, cached fallback, or graceful user notification.", "Simplifies state machine architecture when integrating heterogeneous synchronous/polling tools without requiring a complex distributed event broker for simple bounded tasks."]}, {"id": "KP3", "description": "Hybrid Pattern (Event Notification + Heartbeat/Lease Timeout Guard): Combines low-latency events with timeout safety nets.", "required": false, "acceptable_evidence": ["Technical keywords: lease timeout, active tokens, Lease Timeout Guard, or adaptive polling.", "Acknowledges the trade-off of hard static timeouts (prematurely killing a task that is 99% done vs waiting too long for a dead task).", "Combines event-driven completion (or adaptive polling) with periodic worker heartbeats / visibility-timeout leases (e.g., extending the lease while active tokens/progress arrive, and timing out immediately if heartbeats stop)."]}], "critical_failures": ["Claims event-based systems never drop messages or hang, so timeouts are completely unnecessary.", "Uses blocking sleep() loops on the main thread to implement timeouts instead of non-blocking async timers or lease deadlines."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Why is it important to implement guardrails at both the input (gateway) and output (model) stages in an AI system?', '{"key_points": [{"id": "KP1", "description": "Input Gateway Guardrail Responsibilities (Pre-LLM Threat Prevention & Cost Short-Circuiting): Stops malicious or invalid requests before model invocation.", "required": true, "acceptable_evidence": ["Technical keywords: prompt injection, jailbreak, LLM, PII.", "Blocks direct prompt injection, jailbreak attempts, toxic/abusive inputs, and out-of-scope topics at the perimeter gateway before they reach the LLM.", "Redacts or tokenizes sensitive user PII/PHI and secrets before sending payloads to external model providers.", "Saves significant GPU compute, token cost, and latency by rejecting malformed, oversized, or rate-limited requests upfront."]}, {"id": "KP2", "description": "Output & Tool-Boundary Guardrail Responsibilities (Post-LLM Grounding, Schema & Leakage Control): Catches failures that originate inside generation or retrieved context.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, RAG, groundedness, indirect prompt injection.", "Explains why input guardrails alone are insufficient: even a completely benign user query can trigger a hallucinated response, leak sensitive data from retrieved RAG chunks, or trigger an indirect prompt injection embedded inside a retrieved document.", "Validates model outputs for faithfulness/groundedness against cited context, brand tone/toxicity, and PII/system-prompt exfiltration before displaying to the user.", "Enforces strict Pydantic schema validation and business-policy authorization on LLM-generated tool_calls before executing any external side effect."]}, {"id": "KP3", "description": "Defense-in-Depth Redundancy & Asymmetric Latency Optimization: Balances fast perimeter checks with deep output verification.", "required": false, "acceptable_evidence": ["Technical keywords: asymmetric latency, pairs schema, <20ms.", "Implements Swiss-cheese defense-in-depth so an obfuscated adversarial prompt that slips past the input classifier is still neutralized when it attempts an unauthorized tool call or data exfiltration at the output boundary.", "Uses fast regex/lightweight classifiers at the input gateway (<20ms) and pairs schema/citation checks with streaming or async evaluators at the output stage."]}], "critical_failures": ["Claims input filtering alone guarantees safe model outputs, ignoring hallucinations and indirect prompt injections from retrieved documents.", "Claims output filtering alone is sufficient, allowing raw user PII to be sent to third-party LLM APIs and wasting compute on obvious attacks."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'Why is using a unique task ID (instead of task name) a more robust design choice?', '{"key_points": [{"id": "KP1", "description": "Immutability & Referential Integrity Under Rename Operations: Decouples permanent entity identity from mutable display labels.", "required": true, "acceptable_evidence": ["Technical keywords: immutability, O(1), webhook payloads, historical audit.", "Guarantees that a task''s primary identifier never changes over its lifecycle, making rename an isolated O(1) attribute mutation on a single record.", "Prevents cascading updates or broken pointers across parent-child adjacency lists, foreign keys, URLs, webhook payloads, and historical audit logs when a user edits a task''s title.", "Allows multiple tasks or subtasks in different branches of the hierarchy to share identical human-readable names (e.g., ''Code Review'' or ''Deploy to Staging'') without key collisions."]}, {"id": "KP2", "description": "Concurrency Correctness, ABA Prevention & Idempotency: Eliminates ambiguity in distributed state updates and retries.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, ABA, ID, aba concurrency.", "Prevents the ABA concurrency problem: if Task ''Deploy'' (ID 101) is deleted and a new Task ''Deploy'' (ID 102) is created concurrently, delayed updates or retries targeting ID 101 will safely fail rather than corrupting the new task.", "Enables deterministic idempotency keys and LangGraph/Redux state channel upsert reducers keyed by immutable ID.", "Avoids string-comparison bugs caused by case folding, whitespace trimming, or Unicode normalization discrepancies."]}, {"id": "KP3", "description": "Index Compactness, Join Performance & Security: Optimizes B-tree/hash indexing and prevents PII leakage in URLs/logs.", "required": false, "acceptable_evidence": ["Technical keywords: yield, PII, UUID, ULID.", "Provides fixed-width compact keys (64-bit integer or 128-bit UUID/ULID) that yield faster hash lookups, smaller B-tree secondary indexes, and cheaper foreign-key joins than variable-length strings.", "Prevents sensitive user-entered task descriptions from leaking into URL paths, metric labels, or unredacted system trace IDs."]}], "critical_failures": ["Argues that task names are equally robust as long as string trimming is used.", "Fails to recognize how renaming a primary key breaks parent-child hierarchy references and concurrent updates."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'BROAD', 150, 'Why would you use smaller models or lightweight infrastructure during the POC stage?', '{"key_points": [{"id": "KP1", "description": "Iteration Velocity, Developer Ergonomics & Cost Containment: Accelerates end-to-end pipeline debugging without infrastructure bloat.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, Milvus, Kubernetes, VPC.", "Drastically shortens the edit-test-evaluate feedback loop: smaller models (e.g., 7B-8B open-weight models, GPT-4o-mini, Claude Haiku, lightweight MiniLM/BGE embeddings) and embedded stores (SQLite/DuckDB/local Milvus Lite) run in milliseconds with zero cloud provisioning delay.", "Allows running hundreds of automated evaluation iterations on chunking, prompt templates, and LangGraph state transitions at negligible token/GPU cost.", "Eliminates DevOps overhead (Kubernetes clusters, multi-node GPU provisioning, complex VPC plumbing) before the core product hypothesis is even validated."]}, {"id": "KP2", "description": "Pipeline Diagnostic Signal & Lower-Bound Baseline Establishment: Exposes retrieval and context engineering flaws early.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, SLA, unit economics, exposes retrieval.", "Establishes a rigorous performance floor (baseline): if the RAG retrieval and context engineering pipeline is clean enough that a small 8B/mini model answers accurately, the architecture is fundamentally sound.", "Prevents masking bad retrieval: massive frontier models often compensate for poor chunking using pre-trained parametric memory, hiding RAG pipeline bugs until domain-specific queries fail in production.", "Validates whether the target production latency SLA and unit economics are achievable from the outset."]}, {"id": "KP3", "description": "Ceiling Calibration & Seamless Up-Scaling Architecture: Pairs small-model iteration with frontier ceiling checks and swappable interfaces.", "required": false, "acceptable_evidence": ["Technical keywords: scaling architecture, missing retrieval, ceiling, seamless.", "Compares the small model against a frontier ''oracle'' model on a small golden set to distinguish whether failures stem from model reasoning capacity (solvable by upgrading model tier) vs missing retrieval context.", "Abstracts model and storage clients behind clean interfaces so scaling up from lightweight PoC infra to distributed production infra requires only configuration changes."]}], "critical_failures": ["Spends months provisioning multi-node H100 clusters and distributed storage before testing a single end-to-end user query.", "Concludes a use case is impossible when a tiny model fails on complex reasoning, without testing whether a frontier model succeeds."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'Can you provide an example of a production-grade ML system you built that handled high-volume data and real-world usage?', '{"key_points": [{"id": "KP1", "description": "Problem Formulation, Data Scale & Feature Engineering Pipeline: Quantifies volume and prevents train-serve skew.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, class imbalance, Kafka, Redis.", "Defines a concrete production use case (e.g., real-time fraud detection, high-volume recommendation/matchmaking, demand forecasting, or enterprise document RAG) with explicit scale metrics (events/day, QPS, dataset size).", "Describes the high-volume data ingestion and feature pipeline (e.g., Kafka/Spark streaming + offline/online Feature Store like Feast/Redis) ensuring point-in-time correctness and zero train-serve skew.", "Handles real-world data realities: extreme class imbalance, delayed feedback labels, missing/corrupted fields, and out-of-order events."]}, {"id": "KP2", "description": "Model Architecture, Leakage-Safe Validation & Production Serving SLA: Explains model selection and scalable inference.", "required": true, "acceptable_evidence": ["Technical keywords: NDCG, vLLM, quantization, XGBoost.", "Justifies the chosen model architecture (e.g., LightGBM/XGBoost ensemble, two-tower retrieval + ranking neural net, or hybrid RAG + Cross-Encoder) against latency and accuracy constraints.", "Validates offline using strict temporal/group splits and task-aligned metrics (PR-AUC, Recall@FPR, NDCG, WAPE) followed by shadow deployment and online A/B testing.", "Details the serving infrastructure (horizontally autoscaled FastAPI/Triton/vLLM containers, ONNX quantization, micro-batching, or caching) meeting strict p99 latency SLAs."]}, {"id": "KP3", "description": "Measured Business Impact, Drift Observability & Retraining Lifecycle: Connects deployment to verified production outcomes.", "required": false, "acceptable_evidence": ["Technical keywords: PSI, p99, KS, feature drift.", "States verified business and operational outcomes (e.g., fraud loss reduction, conversion lift, latency p99, throughput sustained).", "Implements continuous production monitoring for feature drift (PSI/KS), prediction score shift, and automated champion/challenger retraining triggers."]}], "critical_failures": ["Describes a Kaggle/notebook experiment on a static CSV file with no production serving, data pipeline, or real-world traffic.", "Claims high-volume production scale but cannot explain how features are computed at inference time or how latency/failures are handled."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you evaluate the effectiveness of preprocessing and ensure that important information was not lost?', '{"key_points": [{"id": "KP1", "description": "Intrinsic Information-Preservation Audits (Entity, Numeric & Structural Conservation): Verifies that extraction and cleaning do not drop critical facts.", "required": true, "acceptable_evidence": ["Technical keywords: NER, EXCEPT, Entity.", "Runs automated invariant checks comparing raw source documents against preprocessed chunks: character/token length ratio bounds, page count coverage (verifying zero dropped pages), and section header hierarchy completeness.", "Performs key-entity and numeric conservation checks: extracts regex/NER anchors (part numbers, dollar amounts, dates, table row/column counts, spec codes) from source files and asserts 100% presence in the normalized output.", "Audits chunk boundary integrity to ensure tables, code blocks, and conditional rules (''Do X EXCEPT when Y'') are not severed across chunk boundaries without overlap or parent headers."]}, {"id": "KP2", "description": "Extrinsic Retrieval & RAGAS Evaluation (Context Recall & Precision): Benchmarks preprocessing variants against a golden QA test set.", "required": true, "acceptable_evidence": ["Technical keywords: MRR, top-k, precision, recall.", "Constructs a stratified Golden Evaluation Dataset containing specifically adversarial extraction cases: dense footnotes, multi-page tables, cross-referenced clauses, and edge-case specifications.", "Measures RAGAS Context Recall (whether all ground-truth facts needed to answer the query were successfully extracted and retrieved in top-k) and Hit Rate / MRR@K across preprocessing configurations.", "Runs A/B ablation experiments comparing chunk sizes, overlap percentages, and parsers (e.g., Tika vs Docling vs Textract) on downstream answer Faithfulness and Answer Correctness."]}, {"id": "KP3", "description": "Visual Diffing, Stratified Spot-Checks & Anomaly Quarantine: Catches silent parser regressions in production.", "required": false, "acceptable_evidence": ["Technical keywords: LLM, PDF, JSON, OCR.", "Conducts stratified human/LLM-assisted side-by-side visual audits (original PDF page vs rendered Markdown/JSON chunk) across document templates.", "Automatically quarantines documents that trigger anomaly heuristics (e.g., sudden drop in extracted tokens per page, high garbled-OCR character ratio, or broken table column counts) for fallback parsing or review."]}], "critical_failures": ["Assumes preprocessing is successful simply because the parser exited without throwing a Python exception.", "Never checks whether numbers, tables, or negations were silently stripped or split across chunks."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you optimize Android layouts, and what changes did you make compared to the initial layout approach?', '{"key_points": [{"id": "KP1", "description": "Flattening Nested View Hierarchies & Eliminating Double-Measure Passes: Replaces deep LinearLayout/RelativeLayout nesting with flat ConstraintLayout.", "required": true, "acceptable_evidence": ["Technical keywords: layout_weight, LinearLayout, RelativeLayout, ConstraintLayout.", "Identifies the initial bottleneck: deeply nested LinearLayouts (especially using layout_weight) and RelativeLayouts trigger exponential multi-pass onMeasure() and onLayout() traversals on the main UI thread.", "Refactors the hierarchy into a flat, single-layer ConstraintLayout (using Guidelines, Barriers, and Chains) or uses <merge> tags in reusable custom views to eliminate redundant intermediate ViewGroup wrappers."]}, {"id": "KP2", "description": "Defers inflation of rarely shown UI subtrees (error banners, complex dialogs, secondary panels) using ViewStub so initial screen inflation only creates visible views.", "required": true, "acceptable_evidence": ["Technical keywords: ViewStub, deferred view inflation, ConstraintLayout, overdraw reduction, Android view hierarchy.", "Defers inflation of rarely shown UI subtrees (error banners, complex dialogs, secondary panels) using ViewStub so initial screen inflation only creates visible views.", "Replaces rarely viewed error panels and dialogs with ViewStubs, reducing initial view hierarchy depth and avoiding main-thread layout passes."]}, {"id": "KP3", "description": "GPU Overdraw Elimination, List Recycling & Recomposition Scoping: Optimizes rendering and scrolling performance.", "required": true, "acceptable_evidence": ["Technical keywords: ScrollView, RecyclerView, ListAdapter, AsyncListDiffer.", "Eliminates GPU pixel overdraw by removing redundant window/container background drawables and using clipRect/quickReject in custom onDraw() methods (bringing Debug GPU Overdraw from 3x-4x red down to 1x blue/true color).", "Optimizes scrolling lists: replaces ScrollView/notifyDataSetChanged() with RecyclerView + ListAdapter (AsyncListDiffer / DiffUtil), shared RecycledViewPool across nested carousels, setHasFixedSize(true), and prefetching.", "If using Jetpack Compose: stabilizes state parameters (@Immutable/@Stable), uses remember/derivedStateOf, and provides explicit key() in LazyColumn to prevent unnecessary recompositions."]}, {"id": "KP4", "description": "Diagnostic Tooling & Frame-Time Verification: Quantifies layout pass reductions using Layout Inspector and Macrobenchmark.", "required": false, "acceptable_evidence": ["Technical keywords: p95, p99, FrameMetricsAggregator, 60Hz.", "Uses Android Studio Layout Inspector, Hierarchy Viewer, Debug GPU Overdraw, and Perfetto / FrameMetricsAggregator to pinpoint slow measure/layout/draw slices.", "Verifies p90/p95/p99 frame render times stay well under the 16.6ms (60Hz) / 8.3ms (120Hz) budget using Jetpack Macrobenchmark and Baseline Profiles."]}], "critical_failures": ["Cannot explain how view nesting depth impacts the measure/layout/draw passes on the Android main thread.", "Allocates new Paint/Bitmap objects inside View.onDraw() or inflates full layouts on every scroll frame without view recycling."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you preprocess large-scale unstructured data such as telemetry, chat histories, and documentation before ingestion?', '{"key_points": [{"id": "KP1", "description": "Modality-Specific Parsing & Structuring (Telemetry, Chat Threads & Docs): Tailors normalization to each unstructured source.", "required": true, "acceptable_evidence": ["Technical keywords: trace_id, JSON, Telemetry, IPs.", "For Telemetry & Logs: filters out high-frequency heartbeat noise, parses semi-structured JSON/stack traces, normalizes dynamic variables (IPs, hex pointers, request UUIDs) into canonical log templates (e.g., Drain algorithm), and groups correlated spans by trace_id / incident window.", "For Chat Histories: reconstructs asynchronous message streams into coherent conversation threads (stitching consecutive single-line messages by the same speaker, resolving reply-to threads, stripping bot greetings/chitchat, and summarizing resolved Q&A pairs)."]}, {"id": "KP2", "description": "For Documentation: strips HTML/Wiki boilerplate, preserves heading hierarchies (H1 > H2 > H3), and keeps code blocks and markdown tables intact during semantic chunking.", "required": true, "acceptable_evidence": ["Technical keywords: markdown hierarchy chunking, H1/H2 header preservation, table preservation, code block isolation, semantic boundaries.", "For Documentation: strips HTML/Wiki boilerplate, preserves heading hierarchies (H1 > H2 > H3), and keeps code blocks and markdown tables intact during semantic chunking.", "Parses technical documentation along Markdown header boundaries (H1/H2), keeping associated tables and code snippets within the same chunk payload."]}, {"id": "KP3", "description": "PII/Secret Scrubbing, Near-Duplicate Pruning & Metadata Enrichment: Cleans noise and attaches filterable attributes.", "required": true, "acceptable_evidence": ["Technical keywords: source_modality, service_version, resolution_status, tenant_acl.", "Runs automated regex + NER scrubbing to redact customer PII, API tokens, passwords, and internal URLs across chat logs and telemetry before indexing.", "Eliminates massive redundancy (e.g., 10,000 identical stack trace logs or repeated boilerplate emails) using SHA-256 exact hashing and MinHash LSH / SimHash near-duplicate clustering.", "Attaches unified metadata schemas (source_modality, timestamp, service_version, resolution_status, tenant_acl) to every chunk."]}, {"id": "KP4", "description": "Distributed Batch/Stream Processing & Incremental Watermarking: Scales preprocessing efficiently.", "required": false, "acceptable_evidence": ["Technical keywords: parquet, Kafka, PySpark, Ray Data.", "Executes preprocessing over distributed data engines (PySpark, Ray Data, or Kafka + Flink/Celery workers) using columnar Parquet checkpoints.", "Tracks high-watermarks and document checksums to process only incremental deltas rather than re-ingesting terabytes of historical logs daily."]}], "critical_failures": ["Treats telemetry logs, chat messages, and long-form docs identically with a naive fixed-character splitter (e.g., indexing individual ''ok'' or ''thanks'' chat messages as standalone vectors).", "Indexes raw unredacted telemetry or chat logs containing customer secrets/PII."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How do you handle structured information such as tables embedded within unstructured sources like PDFs during preprocessing?', '{"key_points": [{"id": "KP1", "description": "Layout-Aware Table Detection & Structured Serialization: Preserves 2D row-column semantics instead of flattening to raw text.", "required": true, "acceptable_evidence": ["Technical keywords: PDF, TableFormer, AWS, LLM.", "Explains why standard PDF text extraction breaks tables (reading across columns out of order and losing cell-to-header associations).", "Uses layout-aware vision/table-structure models (Docling TableFormer, AWS Textract, Azure Document Intelligence, or pdfplumber/Camelot) to detect table bounding boxes, merged cells (rowspan/colspan), and multi-level column headers.", "Serializes extracted tables into LLM-comprehendible structured formats: Markdown tables (for simple grids), HTML <table> (when preserving complex colspan/rowspan), or row-wise JSON objects."]}, {"id": "KP2", "description": "Table-Aware Chunking & Header Propagation: Prevents orphan rows when tables exceed chunk token limits or span pages.", "required": true, "acceptable_evidence": ["Technical keywords: aware chunking, chunk token, column schemas, PDF.", "Treats each table as an atomic structural unit rather than slicing through the middle of a row with a naive character splitter.", "Stitches multi-page continuation tables across PDF page breaks by matching column schemas.", "When a large table must be split across multiple chunks, repeats the table title, caption, and column header row at the top of every sub-table chunk so rows never become orphaned numbers."]}, {"id": "KP3", "description": "Multi-Vector Summary Indexing & Dual SQL/DataFrame Routing: Bridges semantic search with exact tabular lookup.", "required": false, "acceptable_evidence": ["Technical keywords: DataFrame, SQL, LLM, summary indexing.", "Uses a Multi-Vector / Parent-Document pattern: generates a natural-language summary of the table (describing its title, entities, columns, and date range) to embed for high-recall vector search, while linking to the raw structured table payload for the LLM prompt.", "Optionally ingests high-value structured tables into a SQL/DuckDB store alongside the vector index so aggregation/filtering queries can execute deterministically."]}], "critical_failures": ["Extracts PDFs as plain text and slices tables at arbitrary character counts, severing numerical values from their row and column headers.", "Drops tables completely during PDF preprocessing."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Infrastructure as Code & Security', 'MEDIUM', 'BROAD', 150, 'How do you handle the security for your service?', '{"key_points": [{"id": "KP1", "description": "Identity, Authentication & Least-Privilege Authorization (AuthN & AuthZ): Enforces zero-trust access at every service boundary.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, RBAC, ABAC, OAuth 2.0.", "Authenticates users at the API Gateway via OAuth 2.0 / OIDC with short-lived, cryptographically signed JWT access tokens and MFA.", "Enforces fine-grained Role-Based and Attribute-Based Access Control (RBAC/ABAC) on every endpoint, database query, and RAG vector retrieval filter (preventing BOLA/IDOR cross-tenant access).", "Secures internal service-to-service and cloud resource communication using mTLS (service mesh) and least-privilege IAM roles (IRSA / Workload Identity) rather than static long-lived credentials."]}, {"id": "KP2", "description": "Network Isolation, Cryptographic Protection & Secrets Management: Protects data in transit, at rest, and in configuration.", "required": true, "acceptable_evidence": ["Technical keywords: TLS 1.3, AES-256, REST, load balancer.", "Isolates compute and databases inside private VPC subnets behind WAF / DDoS protection, exposing only the ingress load balancer.", "Encrypts all traffic in transit via TLS 1.3 and all persistent stores (Postgres, vector indexes, S3, checkpoints) at rest using AES-256 with KMS-managed keys.", "Manages API keys and database credentials via AWS Secrets Manager or HashiCorp Vault with automated rotation and zero hardcoded secrets in Git/containers."]}, {"id": "KP3", "description": "Application Input/AI Guardrails, Supply-Chain Scanning & Audit Telemetry: Prevents injection and maintains compliance visibility.", "required": false, "acceptable_evidence": ["Technical keywords: Pydantic, PII redaction, rate limiting, CI/CD.", "Enforces strict server-side schema validation (Pydantic), parameterized queries, rate limiting, and AI-specific guardrails (prompt-injection filtering, PII redaction, governed tool execution).", "Integrates SAST/DAST and container vulnerability scanning (Trivy/Dependabot) in CI/CD alongside immutable SIEM security audit logs."]}], "critical_failures": ["Addresses only a single superficial aspect (e.g., ''we use HTTPS'') while ignoring authentication, authorization, secrets, and data isolation.", "Stores plaintext API keys in source control or trusts client-side headers without server-side verification."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Infrastructure as Code & Security', 'HARD', 'SPECIFIC', 120, 'How do you implement rate limiting and ensure system security and stability under high traffic?', '{"key_points": [{"id": "KP1", "description": "Rate-Limiting Algorithms & Atomic Distributed State (Token Bucket / Sliding Window in Redis): Prevents race conditions across horizontally scaled nodes.", "required": true, "acceptable_evidence": ["Technical keywords: sliding window, token bucket, Redis, API.", "Compares rate-limiting algorithms: Token Bucket (allows controlled short bursts up to bucket capacity while enforcing sustained refill rate R) and Sliding Window Counter (prevents the 2x boundary spike vulnerability of Fixed Window counters).", "Implements distributed state in Redis using atomic Lua scripts (EVALSHA) so check-and-decrement executes in a single atomic step without read-modify-write race conditions across multiple API pods.", "Supports multi-dimensional rate limits: per-IP (unauthenticated DDoS/brute-force defense), per-user/tenant tier (RPS fairness), and cost/token-based budgets (TPM/RPM for expensive LLM endpoints)."]}, {"id": "KP2", "description": "Multi-Layer Perimeter Defense & Graceful Load Shedding: Protects backend resources before saturation.", "required": true, "acceptable_evidence": ["Technical keywords: jitter, rate limiting, FastAPI, CDN.", "Enforces hierarchical rate limiting: coarse volumetric DDoS/bot filtering at CDN/Cloudflare/WAF edge -> fine-grained tenant/token rate limiting at the API Gateway (Envoy/Kong/FastAPI middleware).", "Returns standard HTTP 429 Too Many Requests with explicit X-RateLimit-Remaining, X-RateLimit-Reset, and Retry-After headers so well-behaved clients back off with jitter.", "Combines rate limiting with bounded concurrency limits (max concurrent in-flight requests per pod), circuit breakers, and priority load shedding (dropping low-priority background traffic first to protect core interactive SLAs)."]}, {"id": "KP3", "description": "Redis Failure Resilience & Local Token Batching: Avoids making the rate limiter itself a single point of failure or latency bottleneck.", "required": false, "acceptable_evidence": ["Technical keywords: Redis, TTL, limit cluster, pod token.", "Defines explicit fallback behavior if the Redis rate-limit cluster is unreachable: switches temporarily to local in-memory per-pod token buckets (divided by pod count) rather than failing completely open or taking down the whole service.", "Uses local short-TTL caching for blocked abusive IPs so repeat DDoS hits are dropped in-memory without hammering Redis."]}], "critical_failures": ["Stores rate-limit counters only in local process memory on a multi-pod load-balanced service without awareness that users bypass limits by hitting different pods.", "Uses non-atomic GET followed by SET in Redis, causing severe race-condition bypasses under high concurrency."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Infrastructure as Code & Security', 'MEDIUM', 'BROAD', 150, 'How have you implemented security mechanisms such as rate limiting, authentication, CSRF protection, and logging in your applications?', '{"key_points": [{"id": "KP1", "description": "Authentication & CSRF Protection Mechanics: Details token/session management, cookie security flags, and anti-CSRF tokens.", "required": true, "acceptable_evidence": ["Technical keywords: OIDC, JWT, CSRF, HttpOnly.", "Implements Authentication using OAuth2/OIDC with asymmetric RS256/ES256 short-lived JWT access tokens + rotating refresh tokens, and Argon2id/bcrypt password hashing.", "Implements CSRF Protection for cookie-authenticated sessions using HttpOnly, Secure, SameSite=Strict/Lax cookie attributes combined with Synchronizer Token Pattern or Double-Submit Cookie (X-CSRF-Token header verified server-side on POST/PUT/DELETE/PATCH)."]}, {"id": "KP2", "description": "Validates Origin and Referer headers on state-mutating requests and enforces strict CORS origin allowlists (never Access-Control-Allow-Origin: * with credentials).", "required": true, "acceptable_evidence": ["Technical keywords: CORS origin allowlist, SameSite cookie, CSRF token validation, Origin header check, credentials security.", "Validates Origin and Referer headers on state-mutating requests and enforces strict CORS origin allowlists (never Access-Control-Allow-Origin: * with credentials).", "Configures strict CORS origin allowlists with Access-Control-Allow-Credentials: true and enforces SameSite=Strict cookies to eliminate cross-site request forgery."]}, {"id": "KP3", "description": "Tiered Rate Limiting Implementation: Protects auth endpoints from brute force and API endpoints from abuse.", "required": true, "acceptable_evidence": ["Technical keywords: sliding window, token bucket, user_id, tenant_id.", "Implements Redis-backed Token Bucket or Sliding Window rate limiting middleware with differentiated policies per route.", "Applies strict low thresholds and exponential lockout/CAPTCHA on sensitive endpoints (/login, /password-reset, /otp) keyed by both IP and target username to prevent credential stuffing.", "Applies higher sustained + burst quotas on authenticated API/LLM routes keyed by user_id/tenant_id, returning HTTP 429 with Retry-After."]}, {"id": "KP4", "description": "Structured, Redacted Security & Audit Logging: Captures forensic events while stripping secrets and PII.", "required": false, "acceptable_evidence": ["Technical keywords: Datadog, trace_id, request_id, PII.", "Emits structured JSON logs correlated by W3C trace_id / request_id capturing security events: auth successes/failures, permission denials (403), rate-limit triggers (429), CSRF rejections, and privileged state mutations.", "Runs automated log-redaction filters to strip Authorization headers, session cookies, passwords, API keys, and raw PII before shipping logs to centralized SIEM/ELK/Datadog storage."]}], "critical_failures": ["Omits one or more of the four explicitly requested mechanisms (rate limiting, authentication, CSRF, logging).", "Logs plaintext passwords, JWTs, or session tokens in application log files."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How would you approach solving a large-scale data migration or transformation problem in an enterprise AI platform?', '{"key_points": [{"id": "KP1", "description": "Zero-Downtime Expand-Contract & Dual-Ingestion Architecture: Keeps production reads/writes live during historical backfill.", "required": true, "acceptable_evidence": ["Technical keywords: Kafka, AI, CDC, ingestion architecture.", "Uses the Expand-and-Contract (or Blue/Green Shadow Index) pattern rather than destructive in-place migration or long maintenance downtime.", "For AI/Vector migrations (where changing embedding models or chunking schemas invalidates existing vectors): builds a parallel V2 collection/table while V1 continues serving live traffic.", "Enables dual-writing or Change Data Capture (CDC via Debezium/Kafka) so new/updated documents arriving during the multi-day backfill are processed into both V1 and V2."]}, {"id": "KP2", "description": "Partitioned Idempotent Backfill & Resource Throttling: Transforms large historical datasets safely without starving production.", "required": true, "acceptable_evidence": ["Technical keywords: checkpointing, read replicas, tenant_id, doc_id.", "Partitions the historical backfill by tenant_id or time/ID ranges across distributed workers (Spark/Ray/Kafka) with persistent cursor checkpointing so failed shards resume without starting over.", "Makes all transformation and upsert steps strictly idempotent (keyed by deterministic doc_id + chunk_hash + model_version).", "Throttles backfill IOPS and GPU batch concurrency against read replicas/snapshots so live customer traffic experiences zero latency degradation."]}, {"id": "KP3", "description": "Data Reconciliation, Shadow Read Validation & Atomic Alias Cutover: Verifies parity and retrieval quality before switching traffic.", "required": false, "acceptable_evidence": ["Technical keywords: RAG, recall@k, recall, ACL.", "Runs automated data reconciliation comparing row/chunk counts, tenant ACL parity, and cryptographic checksums between V1 and V2.", "Runs shadow-read dark traffic and golden RAG evaluation benchmarks against V2 to verify Recall@K and Faithfulness improvements.", "Executes cutover via an atomic collection alias swap or feature flag (e.g., 1% -> 25% -> 100% canary), retaining V1 warm for instant rollback before final decommissioning."]}], "critical_failures": ["Drops or mutates the live production vector index/database in-place during a multi-hour re-embedding job, causing extended outage or mixed embedding dimensions.", "Runs a backfill without dual-writing/CDC, silently losing all data updates that occurred while the batch job was running."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'HARD', 'SPECIFIC', 120, 'How would you approach solving the problem of finding a duplicate number in a large dataset, and what are the time and space trade-offs?', '{"key_points": [{"id": "KP1", "description": "In-Memory Algorithmic Spectrum & Space-Time Trade-Offs: Compares Hash Set, Sorting, Bitset, and Constant-Space Cycle Detection.", "required": true, "acceptable_evidence": ["Technical keywords: O(1), O(n), O(n log n), MB.", "Compares Hash Set (O(N) time, O(N) space; high memory overhead per object/entry) against In-Place Sorting (O(N log N) time, O(1) auxiliary space; mutates input array).", "Uses a compact Bitset / Bit-Vector when values are bounded integers in [1..M]: requires only M/8 bytes (e.g., 1 billion ints = ~120 MB RAM) with O(N) single-pass time."]}, {"id": "KP2", "description": "Explain Floyd''s Tortoise and Hare Cycle Detection (or Binary Search on Pigeonhole range [1..N]) when given N+1 integers in [1..N] and read-only O(1) space is required: achieves O(N) time (or O(N log N) for range binary search) and O(1) space without modifying the input.", "required": true, "acceptable_evidence": ["Technical keywords: Floyd''s Tortoise and Hare, cycle detection, Pigeonhole principle, O(1) auxiliary space, O(N) time complexity.", "Explains Floyd''s Tortoise and Hare Cycle Detection (or Binary Search on Pigeonhole range [1..N]) when given N+1 integers in [1..N] and read-only O(1) space is required: achieves O(N) time (or O(N log N) for range binary search) and O(1) space without modifying the input.", "Applies Floyd''s cycle-finding algorithm treating array values as pointers (slow = nums[slow], fast = nums[nums[fast]]), finding duplicate in $O(N)$ time and $O(1)$ space."]}, {"id": "KP3", "description": "Out-of-Core / Larger-Than-RAM Dataset Strategies: Handles terabyte-scale datasets that cannot fit in single-node memory.", "required": true, "acceptable_evidence": ["Technical keywords: MapReduce, XOR, ONE, node memory.", "Uses Hash Partitioning (Grace Hash / MapReduce shuffle): streams the dataset in one pass and routes each number x to disk bucket (hash(x) % K) so identical numbers are guaranteed to land in the same small bucket, then checks each bucket in RAM independently.", "Alternatively uses External Merge Sort (k-way merge of sorted runs) followed by a linear adjacent-element scan.", "Explains why single-sum or XOR tricks only work when exactly ONE duplicate exists and all other [1..N] values appear exactly once, failing when multiple duplicates or missing values exist."]}, {"id": "KP4", "description": "Probabilistic Pre-Filtering (Bloom Filters) & Edge Cases: Optimizes memory and handles boundary conditions.", "required": false, "acceptable_evidence": ["Technical keywords: tiny memory, Bloom Filters, or Cuckoo Filter.", "Uses a Bloom Filter (or Cuckoo Filter) in Pass 1 to identify candidate duplicates with tiny memory footprint, followed by an exact verification pass on candidates (since Bloom filters have false positives but zero false negatives).", "Covers edge cases: empty/single-element dataset, negative numbers, 64-bit integer overflow in sum-based formulas, and multiple distinct duplicates."]}], "critical_failures": ["Proposes only a naive O(N^2) nested loop comparison.", "Claims a single-node in-memory Python set() works without issue on a multi-terabyte dataset that exceeds physical RAM."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How would you design a matchmaking system that scales to 100k users while generating weekly personalized matches for each active user?', '{"key_points": [{"id": "KP1", "description": "Pruning the 10-Billion Pair Space (Hard Blocking + ANN Candidate Generation): Reduces O(N^2) complexity to sub-linear retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: O(N^2), ANN, N^2.", "Quantifies the scale challenge: 100k users implies up to 10^10 pairwise evaluations if done brute-force, which is wasteful and slow for deep cross-feature models.", "Stage 1 (Blocking & Hard Filters): partitions users by mutual hard constraints (geography/timezone, role/intent, dealbreakers, and excluding previously matched/rejected pairs)."]}, {"id": "KP2", "description": "Stage 2 (Candidate Retrieval): uses Two-Tower neural embeddings + ANN vector search (Milvus/FAISS) to retrieve the top K (~100-300) viable candidates per active user in milliseconds.", "required": true, "acceptable_evidence": ["Technical keywords: Two-Tower neural network, candidate retrieval, Milvus ANN search, FAISS, user/item embeddingDotProduct.", "Stage 2 (Candidate Retrieval): uses Two-Tower neural embeddings + ANN vector search (Milvus/FAISS) to retrieve the top K (~100-300) viable candidates per active user in milliseconds.", "Uses Two-Tower neural encoders to project users into embedding space, executing ANN vector searches in Milvus to retrieve top-300 candidates per user in under 15ms."]}, {"id": "KP3", "description": "Reciprocal Compatibility Ranking & Global Congestion Control: Optimizes mutual acceptance and prevents popularity skew.", "required": true, "acceptable_evidence": ["Technical keywords: u_i, u_j, GBDT, general graph.", "Stage 3 (Bilateral Ranking): scores the top K candidates per user using a fine-grained GBDT/cross-attention ranker optimizing reciprocal utility (e.g., harmonic mean or product of P(u_i accepts u_j) and P(u_j accepts u_i)).", "Stage 4 (Global Assignment / Congestion Control): solves a capacity-constrained bipartite / general graph matching optimization (e.g., min-cost max-flow, Hungarian/b-matching, or iterative degree-penalized greedy assignment) so each user receives their weekly quota without overloading popular profiles.", "Injects calibrated exploration (Thompson Sampling / epsilon-greedy) for cold-start users and evolving belief states."]}, {"id": "KP4", "description": "Distributed Weekly Batch Orchestration, Caching & Quality Guardrails: Executes the weekly batch reliably.", "required": false, "acceptable_evidence": ["Technical keywords: Redis, batch orchestration, batch pipeline, computing embeddings.", "Orchestrates the weekly batch pipeline over distributed workers (Spark/Ray) pre-computing embeddings, scoring partitioned user blocks in parallel, and staging results in Redis/Postgres before scheduled release.", "Enforces pre-delivery quality gates (verifying 100% of active users received valid matches, zero hard-constraint violations, and balanced exposure entropy across user segments)."]}], "critical_failures": ["Ranks matches purely unilaterally (sending the exact same top 5 most popular profiles to all 100,000 users, causing complete marketplace congestion).", "Runs an expensive LLM prompt for all 10 billion user pairs."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How would you design a system for contract analysis that extracts key clauses, compares them to standard templates, and highlights risks using AI?', '{"key_points": [{"id": "KP1", "description": "Structure-Aware Legal Parsing & Clause Taxonomy Extraction: Segments contracts by legal hierarchy while preserving definitions and cross-references.", "required": true, "acceptable_evidence": ["Technical keywords: PDF, DOCX, Docling, Textract.", "Ingests PDF/DOCX contracts using layout-aware parsers (Docling/Textract/python-docx) that preserve section numbering (Article 1, Section 1.2(a)), defined terms (''Effective Date'', ''Confidential Information''), and schedules/tables.", "Chunks contracts at structural clause boundaries rather than arbitrary character counts, attaching parent section breadcrumbs and resolving internal cross-references (''subject to Section 8.4'')."]}, {"id": "KP2", "description": "Classifies extracted clauses into a canonical legal ontology (Indemnification, Limitation of Liability, Termination, Governing Law, IP Ownership, Data Privacy, Payment Terms) using structured extraction or fine-tuned classifiers.", "required": true, "acceptable_evidence": ["Technical keywords: legal ontology, clause classifier, RoBERTa-legal, indemnification extraction, risk scoring playbook.", "Classifies extracted clauses into a canonical legal ontology (Indemnification, Limitation of Liability, Termination, Governing Law, IP Ownership, Data Privacy, Payment Terms) using structured extraction or fine-tuned classifiers.", "Classifies clauses into a standardized legal taxonomy (e.g. Indemnification, Governing Law) using fine-tuned legal language models, highlighting unapproved deviation terms."]}, {"id": "KP3", "description": "Playbook Template Alignment, Semantic Diffing & Missing-Clause Detection: Compares extracted clauses against gold standards.", "required": true, "acceptable_evidence": ["Technical keywords: BGE, LLM, template alignment.", "Aligns each contract clause against the organization''s approved Legal Playbook / Standard Template clauses using hybrid retrieval + BGE Cross-Encoder matching.", "Performs both deterministic rule checks (e.g., liability cap < 12 months fees, net-30 payment terms, non-standard jurisdiction) and LLM semantic comparison to flag material obligations, uncapped liabilities, or unilateral termination rights.", "Explicitly checks for Omission Risks: identifies mandatory playbook clauses that are completely absent from the counterparty''s draft."]}, {"id": "KP4", "description": "Grounded Risk Grading, Verbatim Citation Provenance & Attorney Redline HITL: Prevents hallucinated legal advice.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, HITL, JSON, UI.", "Outputs structured JSON risk assessments (Severity: High/Medium/Low, Deviation Rationale, Recommended Fallback Clause from Playbook) anchored to exact verbatim quote spans, page numbers, and bounding boxes.", "Verifies 100% quote grounding (deterministic substring/fuzzy match against source text) and presents redline suggestions in a Human-in-the-Loop UI for legal counsel approval."]}], "critical_failures": ["Shreds legal contracts with naive fixed-size chunking, losing defined terms, negations (''notwithstanding''), and section cross-references.", "Checks only present clauses while failing to detect when a required protective clause (e.g., Limitation of Liability) is completely missing from the contract."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How would you design a system that handles peak loads efficiently while minimizing infrastructure costs during idle periods?', '{"key_points": [{"id": "KP1", "description": "Event-Driven Autoscaling & Scale-to-Zero Compute Architecture: Eliminates idle server burn while scaling rapidly on demand.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus, Kafka, Kubernetes, KEDA.", "Decouples stateless compute from storage and uses event-driven autoscalers (Kubernetes KEDA scaling on Kafka/SQS queue depth or Prometheus RPS, AWS Lambda/Fargate, or Cloud Run) that scale worker replicas down to 0 (or a minimal 1-pod warm floor) during idle periods.", "Uses Karpenter or Cluster Autoscaler to rapidly provision and deprovision underlying cloud nodes, mixing low-cost Spot/Preemptible instances for stateless batch workers with On-Demand/Reserved capacity for core control planes."]}, {"id": "KP2", "description": "For AI/GPU workloads: uses pay-per-token managed APIs during idle/low-traffic hours and autoscales dedicated GPU inference pods (or serverless GPU endpoints) only when sustained concurrency crosses the cost break-even threshold.", "required": true, "acceptable_evidence": ["Technical keywords: KEDA queue autoscaling, scale-to-zero, GPU spot instances, AWS Karpenter, serverless inference.", "For AI/GPU workloads: uses pay-per-token managed APIs during idle/low-traffic hours and autoscales dedicated GPU inference pods (or serverless GPU endpoints) only when sustained concurrency crosses the cost break-even threshold.", "Routes base traffic to serverless token APIs during off-peak hours and autoscales dedicated GPU Kubernetes nodes via Karpenter only when batch queues surge."]}, {"id": "KP3", "description": "Peak Load Shock Absorption (Queue Buffering, Caching & Micro-Batching): Smooths traffic spikes without over-provisioning.", "required": true, "acceptable_evidence": ["Technical keywords: Redis, CDN, SQS, PgBouncer.", "Places durable message queues (SQS/Kafka) in front of heavy asynchronous workloads to absorb sudden 10x traffic spikes and process them at a controlled rate as workers spin up.", "Leverages CDN edge caching and Redis exact/semantic caching to serve recurring read/inference queries at sub-millisecond latency without waking up heavy compute nodes.", "Applies dynamic request micro-batching and connection pooling (PgBouncer) to maximize hardware utilization per active node during peak windows."]}, {"id": "KP4", "description": "Cold-Start Mitigation, Predictive Pre-Warming & Serverless Storage Tiering: Prevents latency spikes when transitioning from idle to peak.", "required": false, "acceptable_evidence": ["Technical keywords: S3, start latency, distroless container.", "Mitigates cold-start latency by using lightweight distroless container images, pre-cached model weights on fast shared volumes/snapshots, and scheduled predictive pre-warming ahead of known business-hour traffic ramps.", "Uses serverless/auto-pausing database tiers (Aurora Serverless v2, Neon, S3 + object-tiered vector storage) so storage compute also scales down during nights and weekends."]}], "critical_failures": ["Provisions static 24/7 cluster capacity sized for peak annual load, wasting 80%+ of infrastructure budget during idle hours.", "Scales latency-sensitive synchronous endpoints to zero with 60-second GPU cold-start times without warm buffers or API fallback."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How would you design a system to support reprocessing of files in case of failures or outages?', '{"key_points": [{"id": "KP1", "description": "Immutable Raw Landing Zone & Granular Stage Checkpointing: Preserves source payloads and tracks per-stage progress.", "required": true, "acceptable_evidence": ["Technical keywords: checkpointing, S3, PARSED, FAILED.", "Persists every uploaded file immediately to an immutable, versioned raw object store (e.g., S3 landing zone) before any processing begins so raw data is never lost during an outage.", "Tracks each file in a persistent state-machine ledger (Postgres/DynamoDB) across granular stages: UPLOADED -> PARSED -> CHUNKED -> EMBEDDED -> INDEXED (or FAILED with error classification and stage pointer)."]}, {"id": "KP2", "description": "Caches intermediate stage artifacts (e.g., extracted Markdown/JSON in object storage) so if a downstream embedding/vector DB outage occurs, reprocessing resumes from the EMBEDDED step without re-running expensive OCR/parsing.", "required": true, "acceptable_evidence": ["Technical keywords: intermediate stage artifact caching, S3 staging, AWS Step Functions, idempotency, pipeline replay.", "Caches intermediate stage artifacts (e.g., extracted Markdown/JSON in object storage) so if a downstream embedding/vector DB outage occurs, reprocessing resumes from the EMBEDDED step without re-running expensive OCR/parsing.", "Stores extracted Markdown and JSON artifacts in S3 with pipeline run IDs, allowing recovery to resume directly from the vector embedding step after an outage."]}, {"id": "KP3", "description": "End-to-End Idempotency & Atomic Upserts: Ensures reprocessing a partially completed file never creates duplicate or corrupted state.", "required": true, "acceptable_evidence": ["Technical keywords: chunk_id, tenant_id, file_content_hash, parser_version.", "Derives deterministic idempotency keys for every file and chunk (e.g., chunk_id = SHA256(tenant_id + file_content_hash + parser_version + chunk_index)).", "Uses transactional upserts (INSERT ... ON CONFLICT DO UPDATE / vector store upsert by deterministic ID) or stages writes under a temporary ingestion_run_id that flips atomically only upon 100% file completion.", "Uses visibility timeouts / worker heartbeats on queue messages so if a worker crashes mid-file, another worker safely re-claims the task after lease expiration."]}, {"id": "KP4", "description": "Transient Retry Backoff, Dead-Letter Queues (DLQ) & Bulk Replay Tooling: Separates transient outages from poison-pill files.", "required": false, "acceptable_evidence": ["Technical keywords: exponential backoff, jitter, dead-letter queue, HTTP 429.", "Applies bounded exponential backoff with jitter + circuit breakers for transient downstream outages (HTTP 429/503, DB connection blips), while routing permanent failures (corrupted PDF, password-protected file) directly to a Dead-Letter Queue (DLQ).", "Provides an operator replay API/CLI capable of re-enqueuing failed files filtered by time window, error code, tenant_id, or pipeline_version with rate-limited throttling so post-outage replay does not DDOS the recovering system."]}], "critical_failures": ["Processes files solely in ephemeral memory without saving raw inputs to durable storage first, losing files permanently on crash.", "Appends records blindly during reprocessing without idempotent keys, creating duplicate chunks and corrupted aggregates."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'HARD', 'BROAD', 210, 'How would you design and use cohort analysis to compare new user behavior over time and identify potential drivers of declining spend?', '{"key_points": [{"id": "KP1", "description": "Cohort Matrix Construction & Age-Period-Cohort (APC) Disentanglement: Aligns user cohorts by acquisition window and relative lifecycle tenure.", "required": true, "acceptable_evidence": ["Technical keywords: APC, signup week, month, Day.", "Constructs a 2D longitudinal cohort table where rows represent user acquisition cohorts (e.g., signup week/month) and columns represent relative lifecycle tenure (Day/Week 0, 1, 2, ... N since signup).", "Distinguishes three fundamentally different dynamics in the cohort triangular matrix: Cohort Effect (newer signup cohorts start lower at Week 0 due to worse acquisition channel mix or onboarding bug), Age/Tenure Effect (natural lifecycle retention decay as tenure increases), and Period/Calendar Effect (a vertical diagonal shock hitting all cohorts simultaneously on a specific calendar date due to a buggy release or competitor promo)."]}, {"id": "KP2", "description": "Segments cohorts further by acquisition channel, device platform, pricing tier, and geography to control for Simpson''s Paradox (composition shift).", "required": true, "acceptable_evidence": ["Technical keywords: Simpson''s paradox, multi-dimensional cohort slice, acquisition channel mix, device platform segmentation.", "Segments cohorts further by acquisition channel, device platform, pricing tier, and geography to control for Simpson''s Paradox (composition shift).", "Decomposes cohort retention by device and marketing channel, preventing Simpson''s paradox where shifts in traffic acquisition mix mask genuine product performance."]}, {"id": "KP3", "description": "Multiplicative Spend Decomposition & Funnel Behavioral Diagnostics: Isolates whether spend decline stems from conversion, retention, frequency, or basket size.", "required": true, "acceptable_evidence": ["Technical keywords: LTV, AOV, Activated, Payer | Retained.", "Decomposes Cohort Cumulative LTV / Weekly Spend per User = P(Activated) x P(Retained at Week t) x P(Payer | Retained) x (Orders per Payer) x (Average Order Value / AOV).", "Compares early leading behavioral indicators across cohorts (onboarding completion rate, time-to-first-match/purchase, search zero-result rate, recommendation acceptance rate, checkout error rate)."]}, {"id": "KP4", "description": "Identify whether declining spend is driven by fewer users converting (extensive margin) or active payers spending less per transaction (intensive margin).", "required": false, "acceptable_evidence": ["Technical keywords: intensive vs extensive margin, payer conversion rate, ARPPU, transaction frequency, spend decomposition.", "Identifies whether declining spend is driven by fewer users converting (extensive margin) or active payers spending less per transaction (intensive margin).", "Isolates whether spend declines stem from falling payer conversion rates (extensive margin) or lower spend per paying customer (intensive margin)."]}, {"id": "KP5", "description": "Statistical Driver Validation & Experimental Confirmation: Quantifies driver contributions and tests targeted interventions.", "required": false, "acceptable_evidence": ["Technical keywords: driver validation, controlling for channel, geo covariates, Day-7.", "Applies Oaxaca-Blinder decomposition, Cox proportional hazards survival analysis, or hurdle/zero-inflated regression models (controlling for channel/geo covariates) to quantify how much of the spend drop is explained by user mix vs product experience.", "Handles right-censoring properly so immature recent cohorts are only compared against mature cohorts at matching tenure horizons (e.g., Day-7 or Day-30 spend).", "Validates the top identified driver via a targeted A/B test or holdout rollback before committing to a full-scale product pivot."]}], "critical_failures": ["Compares total cumulative spend of a 1-week-old cohort directly against a 6-month-old cohort without normalizing for tenure age (ignoring right-censoring).", "Looks only at blended aggregate platform spend, failing to separate acquisition mix shifts (Simpson''s Paradox) from within-cohort behavioral degradation."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'BROAD', 150, 'How would you design fine-grained locking or sharding strategies to improve concurrency without sacrificing correctness?', '{"key_points": [{"id": "KP1", "description": "Lock Decomposition & Contention Partitioning: Replaces global mutexes with striped, bucket-level, or row-level locks.", "required": true, "acceptable_evidence": ["Technical keywords: ConcurrentHashMap, SELECT, CAS, level locks.", "Partitions shared state into independent buckets or shards (lock striping, e.g., ConcurrentHashMap segment locks or `hash(key) % N` mutex arrays) so unrelated keys execute concurrently.", "Uses database row-level locking (`SELECT ... FOR UPDATE`) or optimistic concurrency control (version columns / CAS) instead of table-wide locks."]}, {"id": "KP2", "description": "Minimizes critical section duration by moving network I/O, serialization, and heavy computation outside lock acquisition boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: critical section minimization, lock striping, non-blocking I/O, ConcurrentHashMap, mutex scope.", "Minimizes critical section duration by moving network I/O, serialization, and heavy computation outside lock acquisition boundaries.", "Pre-computes serializations and fetches network payloads outside the synchronized block, holding the lock only for instantaneous in-memory pointer updates."]}, {"id": "KP3", "description": "Deadlock Prevention & Canonical Ordering Invariants: Enforces strict lock acquisition order across multi-entity operations.", "required": true, "acceptable_evidence": ["Technical keywords: exponential backoff, MVCC, grained locks, acquisition timeouts.", "Acquires multiple fine-grained locks in a deterministic canonical order (e.g., sorting account/resource IDs ascending before locking) to eliminate circular wait conditions.", "Configures bounded lock acquisition timeouts with randomized exponential backoff to recover gracefully from lock contention spikes.", "Employs read-write locks (`RWLock`) or MVCC snapshot isolation where read-heavy workloads can proceed without blocking concurrent readers."]}, {"id": "KP4", "description": "Sharding Alignment & Cross-Shard Correctness: Co-locates related data on the same shard and handles cross-shard updates safely.", "required": false, "acceptable_evidence": ["Technical keywords: sharding, tenant_id, customer_id, `tenant_id`.", "Chooses a shard key (e.g., `tenant_id` or `customer_id`) that co-locates 95%+ of transactional mutations within a single shard boundary.", "Avoids distributed locks across shards when possible by using single-writer actor/queue affinity per partition key.", "Uses sagas with idempotent compensating actions or Outbox patterns when operations must span multiple shards."]}], "critical_failures": ["Acquires multiple fine-grained locks in arbitrary request-dependent order, introducing classic AB-BA deadlocks under concurrent load.", "Splits atomic invariants across separate shards or locks without any synchronization, ordering, or transactional compensation."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'BROAD', 150, 'How would you design the system to handle failures during streaming, such as user disconnections, while ensuring consistency in stored chat history?', '{"key_points": [{"id": "KP1", "description": "Decoupled Stream Buffering & Offset Resumption: Buffers generated tokens independently of the client socket to allow seamless reconnects.", "required": true, "acceptable_evidence": ["Technical keywords: SSE, Redis, message_id, LLM.", "Decouples upstream LLM token consumption from the client HTTP/SSE socket by writing streamed chunks to an intermediate buffer (e.g., Redis Streams or pub/sub ring buffer) keyed by `message_id`.", "Assigns monotonic sequence numbers/event IDs to token chunks so a disconnecting client can reconnect with `Last-Event-ID` and replay missed tokens without re-invoking the LLM."]}, {"id": "KP2", "description": "Distinguish accidental network drop (continue background generation for a grace window) from explicit user ''Stop Generating'' cancellation (abort upstream LLM stream).", "required": true, "acceptable_evidence": ["Technical keywords: client disconnect grace window, abort signal, Redis token stream buffer, atomic state commit.", "Distinguishes accidental network drop (continue background generation for a grace window) from explicit user ''Stop Generating'' cancellation (abort upstream LLM stream).", "Detects client TCP disconnects while maintaining generation in a background buffer for a 30-second reconnection window before marking the turn complete."]}, {"id": "KP3", "description": "Transactional Chat History State Machine: Persists deterministic message lifecycle states to prevent corrupted or orphaned turns.", "required": true, "acceptable_evidence": ["Technical keywords: PostgreSQL, client_message_id, FAILED, history state.", "Creates the user turn and a placeholder assistant turn (`status = GENERATING`) atomically before starting the stream.", "Atomically flushes the accumulated response text to PostgreSQL with `status = COMPLETED`, `INTERRUPTED`, or `FAILED` once the stream finishes or times out.", "Uses idempotency keys (`client_message_id`) so client retries on a flaky mobile network attach to the in-flight generation rather than creating duplicate chat turns."]}, {"id": "KP4", "description": "Heartbeat Detection, Periodic Checkpointing & Resource Cleanup: Detects half-open connections and bounds orphaned stream memory.", "required": false, "acceptable_evidence": ["Technical keywords: checkpointing, WebSocket, DB, periodic checkpointing.", "Sends periodic SSE comment heartbeats (`: ping`) or WebSocket ping/pong frames to detect dead client connections behind proxies.", "Checkpoints partial token buffers every N tokens or T seconds so a worker crash loses minimal generated progress.", "Sets strict TTLs on Redis stream buffers after final DB persistence to prevent memory leaks."]}], "critical_failures": ["Couples database persistence strictly to the client staying connected until the final token, losing the entire paid LLM generation and leaving chat history inconsistent on network drop.", "Re-triggers a brand new LLM completion call on every automatic client SSE reconnect without idempotency or stream resumption."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'HARD', 'SPECIFIC', 120, 'How would you efficiently update a column in a large dataframe based on row-wise operations, and what are the trade-offs of using methods like pandas apply?', '{"key_points": [{"id": "KP1", "description": "Root-Cause Overhead of `df.apply(axis=1)`: Explains Python-level iteration, Series boxing, and loss of SIMD vectorization.", "required": true, "acceptable_evidence": ["Technical keywords: PyObject, GIL, vectorization, df.apply.", "Explains that `df.apply(fn, axis=1)` is syntactic sugar for a Python `for` loop that instantiates a new `pd.Series` object for every single row.", "Identifies type boxing/unboxing overhead between contiguous C/NumPy arrays and boxed Python `PyObject` pointers, plus single-threaded GIL execution."]}, {"id": "KP2", "description": "Notes that row-wise `apply` across heterogeneous columns often triggers hidden dtype upcasting (e.g., ints cast to float64 or `object`).", "required": true, "acceptable_evidence": ["Technical keywords: dtype upcasting, pandas object series, vectorized numpy, Series.map, memory explosion.", "Notes that row-wise `apply` across heterogeneous columns often triggers hidden dtype upcasting (e.g., ints cast to float64 or `object`).", "Avoids row-wise apply which silently converts integers to float64 or object dtypes, using native vectorized Pandas expressions to maintain tight memory alignment."]}, {"id": "KP3", "description": "Vectorized & Compiled Alternatives: Replaces row loops with array broadcasting, `np.select`/`np.where`, or JIT/Polars kernels.", "required": true, "acceptable_evidence": ["Technical keywords: str, Polars, Pandas, np.select.", "Rewrites conditional multi-column logic using vectorized `np.where`, `np.select`, `df.loc[mask, col] = ...`, or native Pandas/NumPy array arithmetic.", "Uses `@numba.njit` on underlying `.to_numpy()` arrays or switches to Polars lazy expressions (`pl.when().then().otherwise()`) for complex custom logic.", "Uses `.map()` or vectorized `.str` / `.dt` accessors or categorical dictionary joins instead of row-by-row string/lookup callbacks."]}, {"id": "KP4", "description": "When `apply` Is Acceptable & Memory Trade-Offs: Recognizes valid edge cases and manages intermediate array allocations.", "required": false, "acceptable_evidence": ["Technical keywords: df.eval, JSON, DataFrames, SettingWithCopyWarning.", "Acknowledges `apply` is acceptable only on small dataframes or when calling non-vectorizable external Python libraries (e.g., complex regex/JSON parsing) where readability outweighs speed.", "Uses `df.eval()` / `numexpr` or chunked/in-place assignment to reduce peak memory from temporary boolean mask arrays on multi-gigabyte DataFrames.", "Avoids chained indexing (`df[mask][''col''] = val`) that triggers `SettingWithCopyWarning` or silent no-op updates."]}], "critical_failures": ["Claims `df.apply(..., axis=1)` executes in parallel C/Cython speed or recommends `df.iterrows()` as a fast optimization for large DataFrames.", "Cannot write or explain any vectorized replacement (`np.where`, `np.select`, boolean indexing) for conditional column updates."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you ensure data privacy, security, and compliance when handling sensitive healthcare data in such a system?', '{"key_points": [{"id": "KP1", "description": "HIPAA Safe Harbor De-Identification & Zero-Retention Model Boundaries: Protects PHI before external inference or storage.", "required": true, "acceptable_evidence": ["Technical keywords: tokenization, Zero Data Retention, ZDR, HIPAA.", "Routes clinical workloads exclusively through HIPAA-eligible model endpoints backed by a signed Business Associate Agreement (BAA) and Zero Data Retention (ZDR), or self-hosted VPC models.", "Scrubs the 18 HIPAA Safe Harbor identifiers (patient names, MRNs, DOBs, SSNs, addresses) via NER/Presidio tokenization before embedding or non-BAA processing."]}, {"id": "KP2", "description": "Forbids logging raw prompts, retrieved clinical notes, or completions containing PHI into general application logs or third-party observability SaaS.", "required": true, "acceptable_evidence": ["Technical keywords: PHI logging prohibition, HIPAA audit boundary, log sanitization filter, Presidio scrubber, zero-data-retention SaaS.", "Forbids logging raw prompts, retrieved clinical notes, or completions containing PHI into general application logs or third-party observability SaaS.", "Configures logging appenders with regex and NER filters to strip clinical notes from application logs, sending only anonymized request IDs to observability SaaS."]}, {"id": "KP3", "description": "Encryption, Patient-Scoped Access Control & Tenant Isolation: Enforces least-privilege clinical access across storage and RAG.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, RBAC, ABAC, mTLS.", "Enforces encryption in transit (TLS 1.3 / mTLS) and at rest (AES-256 with customer-managed KMS keys) across databases, object stores, and vector indices.", "Applies strict RBAC/ABAC pre-filtering at the vector/database layer so clinicians or patients only retrieve records linked to their authorized `patient_id` or care team.", "Segregates sensitive re-identification mapping tables in an isolated vault separate from RAG chunk stores."]}, {"id": "KP4", "description": "Immutable Compliance Audit Trails & Breach Controls: Tracks every PHI access event for regulatory inspection.", "required": false, "acceptable_evidence": ["Technical keywords: ID, evident audit, PHI.", "Maintains append-only, tamper-evident audit logs recording actor identity, patient record ID, timestamp, clinical purpose, and action taken.", "Enforces automated data retention/purging schedules and patient consent revocation workflows.", "Implements break-glass emergency access monitoring with immediate security alerting."]}], "critical_failures": ["Sends unredacted patient PHI to standard consumer LLM APIs without a signed BAA or Zero Data Retention guarantee.", "Relies on prompt instructions (''only show records for this patient'') instead of deterministic database/vector pre-filtering to isolate patient records."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'SPECIFIC', 90, 'How would you handle high concurrency in a hit counter system, including thread safety and synchronization?', '{"key_points": [{"id": "KP1", "description": "Lock-Free Atomics & Striped Counter Cells: Eliminates single-variable contention under concurrent writes.", "required": true, "acceptable_evidence": ["Technical keywords: AtomicLong, LongAdder, own lock, Compare-And-Swap.", "Replaces coarse-grained `synchronized`/global mutexes with CPU hardware atomic operations (Compare-And-Swap / `AtomicLong`) or striped cell arrays (`LongAdder` pattern).", "Hashes writer threads across $K$ independent counter shards so concurrent increments do not contend on the same CPU cache line, summing the $K$ shards on read.", "For sliding-window hit counters (e.g., last 300s), uses a fixed-size circular array of 300 buckets where each bucket has its own lock or atomic `(timestamp, count)` pair."]}, {"id": "KP2", "description": "Window Rollover Correctness & Race-Free Bucket Reset: Prevents lost increments when time buckets wrap around.", "required": true, "acceptable_evidence": ["Technical keywords: bucket.timestamp, current_second, window_size, CAS.", "Checks `bucket.timestamp == current_second` atomically before incrementing; if stale, resets count to 1 and updates timestamp inside the bucket''s fine-grained lock or CAS loop.", "Avoids unbounded queue growth (pushing every single timestamp into a list) which exhausts memory and causes lock contention under millions of hits per second.", "Ensures `getHits(now)` iterates the fixed-size ring buffer and sums only buckets where `now - bucket.timestamp < window_size`."]}, {"id": "KP3", "description": "Distributed Scaling & Asynchronous Flush Aggregation: Scales beyond a single node using local buffering and Redis/DB batching.", "required": false, "acceptable_evidence": ["Technical keywords: Redis, shard_0, DB, INCRBY.", "Buffers increments in local worker memory and flushes aggregated deltas (`INCRBY key delta`) to Redis or storage every 100ms–1s instead of one network call per hit.", "Uses sharded Redis keys (`counter:{id}:{shard_0..N}`) for ultra-hot keys to avoid saturating a single Redis shard.", "Discusses probabilistic structures (HyperLogLog) when counting unique visitors rather than raw total hits."]}], "critical_failures": ["Uses an unsynchronized `count += 1` or non-atomic read-modify-write across threads, causing lost updates under race conditions.", "Executes a synchronous database `UPDATE counters SET hits = hits + 1` row lock on every incoming request at high QPS."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How would you identify bottlenecks in an existing system and deliver measurable improvements using AI within a short timeframe?', '{"key_points": [{"id": "KP1", "description": "Quantitative Bottleneck Profiling & Baseline Instrumentation: Locates actual latency or human-throughput constraints using telemetry.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, distributed tracing, p95, LLM.", "Profiles system execution using distributed tracing (OpenTelemetry), flame graphs, queue depth metrics, and step-level workflow timing before proposing changes.", "Identifies whether the dominant bottleneck is system compute/IO (e.g., sequential LLM calls, unindexed queries) or manual human toil (e.g., document triage, ticket classification).", "Records concrete baseline metrics (p50/p95 latency, throughput, error/escalation rate, cost per task) on a representative benchmark dataset."]}, {"id": "KP2", "description": "High-Leverage Quick-Win AI & Architectural Interventions: Prioritizes bounded, fast-to-ship improvements over multi-month rewrites.", "required": true, "acceptable_evidence": ["Technical keywords: asyncio, asyncio.gather, RAG, AI.", "Applies high-ROI technical fixes first: parallelizing independent LLM/tool calls (`asyncio.gather`), adding semantic/exact caching, or routing simple intents to smaller/faster models.", "Targets a narrow, high-volume workflow step (e.g., automated structured field extraction or draft generation with human review) using off-the-shelf models + RAG rather than custom training.", "Integrates behind a feature flag or shadow pipeline so existing production workflows are not disrupted during validation."]}, {"id": "KP3", "description": "Controlled Verification & Guardrailed Rollout: Validates measurable lift without quality regression.", "required": false, "acceptable_evidence": ["Technical keywords: alongside latency, 5–10% traffic, controlled, guardrailed.", "Runs automated evaluation (accuracy/faithfulness on golden test cases) alongside latency and token-cost comparisons against the baseline.", "Deploys via shadow mode or canary slice (5–10% traffic) to measure real-world cycle-time reduction or deflection rate.", "Implements confidence thresholds and deterministic fallback to the legacy path when model confidence is low."]}], "critical_failures": ["Proposes a multi-month custom model training project or full architectural rewrite when asked for measurable improvements in a short timeframe.", "Applies AI blindly without first profiling where the bottleneck actually resides or establishing baseline metrics."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'HARD', 'SPECIFIC', 120, 'How would you implement a multi-threaded solution where four threads run concurrently, one specific thread is terminated when any thread completes, and the system waits for the remaining threads before finishing?', '{"key_points": [{"id": "KP1", "description": "First-Completion Detection & Race-Free Triggering: Detects the earliest finishing thread and triggers cancellation exactly once.", "required": true, "acceptable_evidence": ["Technical keywords: ThreadPoolExecutor, threading.Thread, concurrent.futures, return_when.", "Launches the 4 tasks concurrently via `ThreadPoolExecutor` / `threading.Thread` and detects the first completion using `concurrent.futures.wait(futures, return_when=FIRST_COMPLETED)`, a `CountDownLatch(1)`, or a completion callback.", "Uses a thread-safe `threading.Event` (`cancel_target_event.set()`) or atomic once-flag so that even if two threads finish simultaneously, the termination signal for the designated target thread is triggered idempotently without race conditions."]}, {"id": "KP2", "description": "Handle the edge case where the designated target thread itself is the first thread to finish naturally (no-op cancellation).", "required": true, "acceptable_evidence": ["Technical keywords: threading.Event, concurrent.futures.wait, FIRST_COMPLETED, cooperative cancellation, thread join.", "Handles the edge case where the designated target thread itself is the first thread to finish naturally (no-op cancellation).", "Monitors thread completion with concurrent.futures.wait(return_when=FIRST_COMPLETED), checking if the designated thread completed naturally before setting the cancel event."]}, {"id": "KP3", "description": "Cooperative Thread Termination vs Unsafe Force-Kill: Stops the target thread safely without corrupting locks or resources.", "required": true, "acceptable_evidence": ["Technical keywords: cancel_event.is_set, pthread_cancel, Thread.stop, corrupting locks.", "Implements cooperative cancellation in the designated target thread by polling `cancel_event.is_set()` inside its work loop or passing a cancellation token/timeout to blocking I/O waits.", "Explains why forceful thread termination (`pthread_cancel` asynchronous kill, `Thread.stop()`) is dangerous because it leaves held mutexes locked, corrupts shared state, and leaks file/socket descriptors.", "Ensures the target thread executes its `finally` / context-manager cleanup block before exiting upon observing the cancellation flag."]}, {"id": "KP4", "description": "Full Barrier Synchronization & Exception Handling: Waits for all remaining threads and propagates errors cleanly.", "required": false, "acceptable_evidence": ["Technical keywords: return_when, thread.join, futures, return_when=ALL_COMPLETED.", "Waits for all remaining active threads (plus the cooperatively stopping target thread) to finish using `wait(futures, return_when=ALL_COMPLETED)` or `thread.join()` before returning.", "Decides explicitly whether an unhandled exception in a worker counts as ''completion'' to trigger the signal and captures exceptions from all futures so none are silently swallowed.", "Supports a top-level safety timeout on the final join to prevent indefinite hangs if a worker blocks on unresponsive external I/O."]}], "critical_failures": ["Uses unsafe OS-level forceful thread killing that aborts the target thread mid-instruction without releasing locks or resources.", "Exits the main program immediately after the first thread completes without joining/waiting for the remaining threads to finish."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'HARD', 'SPECIFIC', 120, 'How would you implement a program to print numbers from 1 to 100 with substitutions for multiples of three and five, and what common pitfalls should be avoided?', '{"key_points": [{"id": "KP1", "description": "Correct Divisibility Logic & Range Bounds: Implements inclusive 1–100 iteration and proper LCM (15) handling.", "required": true, "acceptable_evidence": ["Technical keywords: LCM, accumulates tokens, 101.", "Iterates accurately over the inclusive range `1` to `100` (e.g., `range(1, 101)` in Python).", "Checks the composite condition (`i % 15 == 0` or `(i % 3 == 0 and i % 5 == 0)`) first in an `if/elif/else` chain, or accumulates tokens into a buffer so multiples of both 3 and 5 output the combined substitution."]}, {"id": "KP2", "description": "Prints the numeric value `i` only when no substitution rule matches.", "required": true, "acceptable_evidence": ["Technical keywords: FizzBuzz ordering, modulo 15, default fallback print, string concatenation, control flow hygiene.", "Prints the numeric value `i` only when no substitution rule matches.", "Constructs an explicit fallback branch `else: print(i)` only after evaluating combined divisibility conditions (i % 15 == 0, i % 3 == 0, i % 5 == 0)."]}, {"id": "KP3", "description": "Identification of Common Pitfalls: Calls out branch shadowing, off-by-one bounds, and operator precedence bugs.", "required": true, "acceptable_evidence": ["Technical keywords: 100, i % 3, identification, common.", "Explains the classic branch-shadowing bug: placing `if i % 3 == 0` before `elif i % 15 == 0`, which makes the 15-branch dead/unreachable code.", "Highlights off-by-one boundary errors (`range(100)` starting at 0, which falsely triggers `0 % 15 == 0`, or stopping at 99 instead of 100).", "Notes language-specific pitfalls such as bitwise/equality precedence (`i % 3 == 0` vs `!(i % 3)`) or printing both the word and the number due to missing `elif`/`else`."]}, {"id": "KP4", "description": "Extensible Rule Design & Complexity Analysis: Avoids $2^k$ combinatorial `elif` branches when adding new divisors.", "required": false, "acceptable_evidence": ["Technical keywords: time complexity, space complexity, O(1), O(n).", "Demonstrates a data-driven rule list (`rules = [(3, ''Fizz''), (5, ''Buzz''), (7, ''Bazz'')]`) with string concatenation (`''''.join(word for div, word in rules if i % div == 0) or str(i)`) so adding a 3rd divisor doesn''t require $2^3 = 8$ hardcoded branches.", "States $O(N)$ time complexity and $O(1)$ auxiliary space complexity.", "Separates pure transformation logic (`format_number(i) -> str`) from `print()` side effects for clean unit testing."]}], "critical_failures": ["Places `if n % 3 == 0` before `elif n % 15 == 0` in a mutually exclusive `if/elif` block, never printing the combined substitution for multiples of 15.", "Uses `range(1, 100)` in Python without realizing `100` is excluded, or starts at `0`."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How would you implement a solution to find the top K most frequent elements in an array, and what approach would you use to optimize it?', '{"key_points": [{"id": "KP1", "description": "Frequency Aggregation & Bounded Min-Heap ($O(N log K)$): Counts occurrences in $O(N)$ and maintains a size-$K$ heap.", "required": true, "acceptable_evidence": ["Technical keywords: heap, O(n), O(N log K), collections.Counter.", "Builds a hash map (`collections.Counter`) mapping each unique element to its frequency count in $O(N)$ time and $O(U)$ space ($U <= N$ unique elements).", "Maintains a Min-Heap of capacity $K$ keyed by `(frequency, element)`: pushes elements and pops the minimum whenever heap size exceeds $K$, achieving $O(N + U log K)$ time instead of sorting all $U$ elements in $O(U log U)$."]}, {"id": "KP2", "description": "Explain why a Min-Heap (evicting the smallest of the top $K$ candidates) uses $O(K)$ heap space rather than a Max-Heap of size $U$.", "required": true, "acceptable_evidence": ["Technical keywords: min-heap O(K) space, heapq.heappushpop, frequency map, top-k frequent, time complexity O(N log K).", "Explains why a Min-Heap (evicting the smallest of the top $K$ candidates) uses $O(K)$ heap space rather than a Max-Heap of size $U$.", "Maintains a min-heap of size K using heapq.heappushpop(), evicting the smallest element when capacity is exceeded to bound heap memory to O(K)."]}, {"id": "KP3", "description": "Linear-Time Optimization via Bucket Sort or Quickselect ($O(N)$): Eliminates the $log K$ factor for optimal asymptotic runtime.", "required": true, "acceptable_evidence": ["Technical keywords: O(U), Hoare''s selection algorithm, freq, num.", "Designs a frequency Bucket Sort in $O(N)$ time and $O(N)$ space: allocates an array `buckets[0..N]` where index `f` holds a list of elements appearing `f` times (since max frequency $<= N$), then scans buckets from $N$ down to $1$ until $K$ elements are collected.", "Alternatively explains Quickselect (Hoare''s selection algorithm) on the array of unique `(freq, num)` pairs to partition the top $K$ in $O(U)$ average time and $O(U)$ space.", "Compares trade-offs: Bucket Sort is strictly $O(N)$ worst-case, whereas Min-Heap is preferred for streaming/unbounded $N$ with small $K$."]}, {"id": "KP4", "description": "Edge Cases & Tie-Breaking Semantics: Handles boundary values of $K$ and frequency ties.", "required": false, "acceptable_evidence": ["Technical keywords: hash table, lexicographical order, arbitrary order, heap.", "Handles $K >= U$ (returns all unique keys in $O(N)$ without heap/sorting work) and validates $K <= 0$ or empty input arrays.", "Clarifies tie-breaking requirements when multiple elements share the $K$-th highest frequency (e.g., lexicographical order vs arbitrary order).", "Mentions Count-Min Sketch + Min-Heap when the stream is too massive to fit the exact hash table in memory."]}], "critical_failures": ["Computes frequencies by scanning the entire array for each element in nested loops ($O(N^2)$ time).", "Cannot improve beyond full $O(N log N)$ sorting when asked how to optimize the solution."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you implement guardrails to handle toxicity, unprofessional tone, or off-topic responses?', '{"key_points": [{"id": "KP1", "description": "Input Topicality Routing & Pre-Inference Filtering: Blocks off-topic and abusive queries before invoking heavy LLMs.", "required": true, "acceptable_evidence": ["Technical keywords: cosine similarity, jailbreak, NeMo, API.", "Uses fast semantic routers (embedding cosine similarity against allowed/disallowed canonical intents) or lightweight classifiers (NeMo Guardrails Colang rails, fine-tuned DeBERTa) to reject off-topic queries (e.g., politics, coding help in a banking bot) at the input gate.", "Runs low-latency toxicity/moderation checks (Llama Guard, OpenAI Moderation, Perspective API) on user inputs to block harassment and jailbreak bait.", "Returns a deterministic, polite canned scope reminder when an input is classified as out-of-domain, saving LLM token spend."]}, {"id": "KP2", "description": "Output Safety, Tone Validation & Rewrite/Fallback Policies: Verifies generated responses before user delivery.", "required": true, "acceptable_evidence": ["Technical keywords: tone validation, topic drift, output, rewrite.", "Passes generated responses through output guardrail classifiers checking for toxicity, profanity, competitor disparagement, and brand-tone violations.", "Enforces system-level persona guidelines (e.g., objective, empathetic, non-judgmental tone, no slang or unverified promises) paired with few-shot exemplars.", "Triggers a self-correction rewrite prompt or falls back to a safe templated response when the output classifier flags unprofessional tone or topic drift."]}, {"id": "KP3", "description": "Threshold Calibration, Red-Teaming & Telemetry: Tunes false-positive rates and monitors guardrail interventions.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, `OFF_TOPIC`.", "Calibrates classifier thresholds on domain-specific test sets so legitimate user frustration (e.g., ''this billing charge is ridiculous'') is routed to support rather than falsely blocked as toxic.", "Logs every guardrail intervention with reason codes (`OFF_TOPIC`, `TOXICITY`, `TONE_VIOLATION`) for observability and red-team dataset expansion.", "Runs automated adversarial red-teaming (Promptfoo / Garak) in CI/CD before updating prompts or guardrail models."]}], "critical_failures": ["Relies solely on a system prompt instruction (''be polite and stay on topic'') without any independent input or output guardrail classifiers.", "Blocks frustrated customers reporting genuine product bugs because of naive keyword blocklists."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'BROAD', 210, 'How would you implement streaming responses in a chat system, and how do you handle guardrails and safety filtering in a streaming setup?', '{"key_points": [{"id": "KP1", "description": "Asynchronous Streaming Transport & Non-Blocking Pipeline: Streams tokens via SSE/WebSockets with backpressure control.", "required": true, "acceptable_evidence": ["Technical keywords: event loop, SSE, Server-Sent Events, prompt injection.", "Implements Server-Sent Events (SSE) for unidirectional token streaming or WebSockets for bidirectional chat over an async event loop (FastAPI `StreamingResponse` / `AsyncGenerator`).", "Executes synchronous input guardrails (prompt injection, toxicity, ACL retrieval pre-filtering) before opening the LLM stream to block unsafe generations upfront."]}, {"id": "KP2", "description": "Formats streamed payloads as structured JSON events (`event: token_delta`, `event: citation`, `event: guard_abort`, `event: done`) rather than raw unframed text.", "required": true, "acceptable_evidence": ["Technical keywords: SSE structured event, event: token_delta, event: guard_abort, framed JSON streaming, EventSource.", "Formats streamed payloads as structured JSON events (`event: token_delta`, `event: citation`, `event: guard_abort`, `event: done`) rather than raw unframed text.", "Frames token deltas as structured SSE JSON events (`event: token_delta`, `data: {''delta'': ''...''}`), sending an explicit `event: guard_abort` if safety rails trigger."]}, {"id": "KP3", "description": "Lookahead Token Buffering & Sliding-Window Stream Guardrails: Intercepts unsafe content or PII split across token boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: sliding window, TTFT, previous_tail, current_buffer.", "Explains why single-token checking fails (a toxic phrase or SSN like `123-45-6789` spans multiple subword tokens) and why waiting for the full completion destroys streaming TTFT.", "Implements a small lookahead buffer (e.g., 15–30 tokens or clause/sentence boundaries) and runs fast regex/Presidio PII scanners and lightweight classifier checks over an overlapping sliding window (`previous_tail + current_buffer`) before flushing the buffer to the client."]}, {"id": "KP4", "description": "Runs parallel asynchronous moderation checks on accumulated text every $N$ tokens so heavy semantic evaluators do not block every single token flush.", "required": false, "acceptable_evidence": ["Technical keywords: sliding window moderation, async guardrail check, token buffer, latency-neutral safety filtering.", "Runs parallel asynchronous moderation checks on accumulated text every $N$ tokens so heavy semantic evaluators do not block every single token flush.", "Accumulates streaming tokens in a 10-token sliding window and runs asynchronous moderation checks in parallel, avoiding latency pauses on every individual token."]}, {"id": "KP5", "description": "Mid-Stream Circuit Breaker & Client Retraction Protocol: Aborts compromised streams cleanly and sanitizes stored history.", "required": false, "acceptable_evidence": ["Technical keywords: circuit breaker, stream_aborted, retract_message, LLM.", "Cancels the upstream LLM stream immediately when a sliding-window or async guardrail triggers, halting further token generation and cost.", "Emits an explicit `event: stream_aborted` / `retract_message` control frame instructing the UI to replace the partial streamed bubble with a safe fallback message.", "Overwrites or redacts the partial output in the persistent chat history database and logs the safety violation event for security review."]}], "critical_failures": ["Buffers the entire LLM response to completion before running guardrails, completely eliminating streaming and spiking user-perceived latency.", "Flushes raw tokens directly to the browser with zero buffering or mid-stream retraction mechanism, leaking PII or toxic text that cannot be unsent."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How would you preprocess and categorize users into meaningful groups or segments to improve matchmaking quality?', '{"key_points": [{"id": "KP1", "description": "Multi-Modal User Feature Preprocessing & Representation: Combines structured attributes, text profiles, and behavioral telemetry.", "required": true, "acceptable_evidence": ["Technical keywords: behavioral telemetry, response latency, bios, skills.", "Cleans and normalizes structured attributes (numerical scaling, missing-value imputation, cyclical/geospatial encoding for timezones/locations, target or one-hot encoding for categories).", "Encodes unstructured profile text (bios, skills, goals, past interactions) into dense semantic vectors using sentence/domain embedding models.", "Incorporates implicit behavioral signals (historical match acceptance, response latency, dwell time, Elo/skill rating) weighted by recency decay."]}, {"id": "KP2", "description": "Segmentation Architecture & Two-Stage Matchmaking: Separates hard compatibility rules from latent cluster/embedding affinity.", "required": true, "acceptable_evidence": ["Technical keywords: UMAP, PCA, segmentation architecture, latent cluster.", "Applies hard deterministic pre-filters first (e.g., language, timezone overlap, role complementarity, dealbreaker constraints) to partition valid candidate pools.", "Segments users into latent cohorts using clustering (K-Means, HDBSCAN, Gaussian Mixture Models on dimensionality-reduced UMAP/PCA embeddings) or learns Two-Tower / Graph Neural Network representations trained on successful historical matches.", "Distinguishes similarity matching (shared interests) from complementary matching (e.g., mentor-mentee, buyer-seller, balanced game matchmaking)."]}, {"id": "KP3", "description": "Cold-Start Onboarding, Cluster Stability & Online Evaluation: Handles new users and prevents stagnant segments.", "required": false, "acceptable_evidence": ["Technical keywords: success metrics, silhouette score, segment population balance, mutual match rate.", "Assigns cold-start users to coarse demographic/onboarding-questionnaire segments and uses contextual bandits to explore matches until behavioral history accumulates.", "Monitors cluster quality (silhouette score, segment population balance) and schedules periodic re-segmentation as user behavior evolves.", "Evaluates matchmaking quality via bilateral success metrics (mutual match rate, conversation depth, post-match retention) rather than one-sided clicks."]}], "critical_failures": ["Feeds raw unscaled numerical features alongside high-dimensional text vectors into K-Means without normalization, causing distance metrics to be dominated by scale artifacts.", "Optimizes only for one-sided similarity without accounting for bilateral compatibility or hard constraints."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How would you scale a prototype built with Pandas to handle large-scale production data?', '{"key_points": [{"id": "KP1", "description": "Columnar I/O, Dtype Downcasting & Single-Node Query Engines: Eliminates CSV/memory bloat and leverages Polars/DuckDB.", "required": true, "acceptable_evidence": ["Technical keywords: Polars, parquet, scan_parquet, CSV.", "Replaces row-based CSV/JSON ingestion with partitioned Apache Parquet + PyArrow, using column projection (`columns=[...]`) and predicate pushdown (`filters=[...]`) to read only required data.", "Reduces memory footprint by 50–80% via dtype optimization (`int64` -> `int32`/`int16`, low-cardinality `object` strings -> `category` or PyArrow string arrays) and eliminating row-wise `.apply()`.", "Migrates to multi-threaded, lazy out-of-core engines like Polars (`scan_parquet` streaming mode) or DuckDB before paying the operational tax of a distributed cluster."]}, {"id": "KP2", "description": "Distributed Data Processing Architecture: Scales across cluster nodes with PySpark, Ray Data, or Dask for TB-scale datasets.", "required": true, "acceptable_evidence": ["Technical keywords: PySpark, TB, SQL, processing architecture.", "Transitions to PySpark, Dask, or Ray Data when dataset volume or shuffle memory exceeds vertical single-node limits.", "Minimizes expensive cross-node network shuffles by partitioning data on join/group keys, using broadcast joins for small lookup tables, and avoiding Python UDFs in favor of native Spark SQL/Arrow expressions.", "Uses chunked/streaming batch processing for embarrassingly parallel row transformations."]}, {"id": "KP3", "description": "Production Hardening: Schema Enforcement, Idempotency & Orchestration: Turns notebook scripts into reliable pipelines.", "required": false, "acceptable_evidence": ["Technical keywords: Pydantic, Delta Lake, YYYY-MM, DD.", "Validates input/output schemas and data quality constraints at pipeline boundaries (Pandera, Great Expectations, Pydantic).", "Designs idempotent partitioned writes (e.g., overwriting by `dt=YYYY-MM-DD` in Delta Lake / Iceberg) so failed jobs can retry safely without duplicating rows.", "Schedules and monitors pipeline execution with orchestrators (Airflow, Prefect, Dagster) and OOM/spill alerts."]}], "critical_failures": ["Attempts to load a multi-hundred-gigabyte CSV directly into a single in-memory `pd.read_csv()` call by only adding swap space.", "Ports slow Python `iterrows()` / row-by-row UDF loops directly into PySpark without vectorization or native expressions."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'BROAD', 210, 'How would you scale and parallelize ingestion for large volumes of documents using distributed systems and asynchronous processing?', '{"key_points": [{"id": "KP1", "description": "Decoupled Stage-Specific Worker Pools: Separates CPU/GPU parsing, chunking, and async I/O embedding generation via queues.", "required": true, "acceptable_evidence": ["Technical keywords: asyncio, Kafka, RabbitMQ, S3.", "Stores raw documents in object storage (S3/GCS) and publishes lightweight metadata pointers (`doc_id`, `s3_uri`, `version`) to a durable queue (Kafka, RabbitMQ, SQS) rather than passing multi-MB files through broker messages.", "Decomposes ingestion into independently autoscaled worker pools: CPU/GPU-heavy workers (Ray / KEDA-scaled pods) for OCR and layout-aware parsing (Docling), and async I/O-bound workers for batched embedding API/inference calls.", "Uses asynchronous micro-batching (accumulating e.g. 128–512 chunks per request with `asyncio` + semaphore rate-limiting) to maximize embedding throughput while respecting provider TPM/RPM quotas."]}, {"id": "KP2", "description": "Idempotent Content-Hash Deduplication & Bulk Vector Indexing: Prevents duplicate embedding compute and optimizes index writes.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW, Pinecone, Qdrant, Milvus.", "Computes deterministic content hashes (`SHA-256` of normalized chunk text + metadata version) to skip re-embedding unchanged chunks across document updates or worker retries.", "Uses deterministic chunk IDs (`{doc_id}:{chunk_index}:{hash}`) and performs bulk batched upserts into the vector database (Milvus/Pinecone/Qdrant) rather than single-vector inserts.", "For massive initial backfills, writes vectors to bulk segments/files or pauses expensive HNSW index rebuilds until batch ingestion completes."]}, {"id": "KP3", "description": "Backpressure, Dead-Letter Queues & Zero-Downtime Index Updates: Handles poison documents and atomic version swaps.", "required": false, "acceptable_evidence": ["Technical keywords: exponential backoff, jitter, dead-letter queue, DLQ.", "Implements exponential backoff with jitter on HTTP 429/503 embedding errors and routes corrupted/encrypted PDFs to a Dead-Letter Queue (DLQ) after max retries without blocking healthy documents.", "Tracks per-document ingestion state (`PENDING`, `PARSED`, `EMBEDDED`, `INDEXED`, `FAILED`) in PostgreSQL for observability and resumability.", "Prevents partial/stale search results during document replacement by indexing new version chunks first and atomically flipping metadata filter pointers or deleting old chunk IDs."]}], "critical_failures": ["Processes large document uploads synchronously inside the user-facing HTTP request thread, causing gateway timeouts and OOM crashes.", "Calls the embedding model API and vector database one chunk at a time sequentially without batching or idempotency keys."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How would you scale this system if the number of tasks grows significantly?', '{"key_points": [{"id": "KP1", "description": "Partitioned Queueing & Competing Consumer Autoscaling: Scales worker fleets horizontally based on backlog telemetry.", "required": true, "acceptable_evidence": ["Technical keywords: Kafka, RabbitMQ, Kubernetes, backlog_per_worker.", "Decouples task ingestion from execution via partitioned message queues/streams (Kafka, SQS, RabbitMQ) with stateless competing worker consumers.", "Autoscales worker pods horizontally (e.g., Kubernetes KEDA) driven by queue depth / consumer lag (`backlog_per_worker`) and task processing latency rather than CPU alone.", "Separates fast interactive tasks from heavy long-running batch tasks into dedicated priority queues and worker pools to prevent head-of-line blocking."]}, {"id": "KP2", "description": "Idempotent Execution, Lease Timeouts & Noisy-Neighbor Fairness: Ensures at-least-once safety and tenant fairness at scale.", "required": true, "acceptable_evidence": ["Technical keywords: rate limiting, task_id, lease timeouts, DLQs.", "Enforces idempotent task handlers keyed by `task_id` with visibility timeouts / heartbeats so crashed workers'' tasks are safely retried without duplicate side effects.", "Implements per-tenant rate limiting, token-bucket quotas, or fair-share weighted scheduling so a single tenant submitting 1M tasks cannot starve other users.", "Uses Dead-Letter Queues (DLQs) and circuit breakers when downstream dependencies degrade."]}, {"id": "KP3", "description": "Database Contention Mitigation & Storage Sharding: Prevents the state store from becoming the new bottleneck.", "required": false, "acceptable_evidence": ["Technical keywords: parquet, read replicas, sharding, S3.", "Eliminates database polling (`SELECT ... WHERE status=''PENDING''`) in favor of push/broker delivery, and batches task status updates to reduce write IOPS.", "Uses connection pooling (PgBouncer), read replicas for status queries, and partitions/shards the task history table by `tenant_id` or time range.", "Archives completed historical task payloads to cold storage (S3/Parquet) to keep hot operational tables small."]}], "critical_failures": ["Scales only by vertically resizing a single monolithic server or having hundreds of workers poll the same unpartitioned SQL table without `SKIP LOCKED` or a message broker.", "Allows unbounded task ingestion without backpressure, priority isolation, or idempotency, crashing downstream databases."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'How would you use historical support tickets at large scale to build an AI-powered support assistant?', '{"key_points": [{"id": "KP1", "description": "Ticket Curation, PII Redaction & Canonical Knowledge Synthesis: Distills noisy raw ticket threads into clean, current knowledge.", "required": true, "acceptable_evidence": ["Technical keywords: PII redaction, PII, NER, CSAT.", "Scrubs customer PII, credentials, and account-specific secrets (Presidio / NER + regex) before any ticket text enters embedding or training pipelines.", "Filters historical tickets by quality signals (resolved status, high CSAT, non-reopened, recent product versions) to exclude failed troubleshooting guesses and deprecated product workflows.", "Clusters recurring ticket intents (HDBSCAN/K-Means on embeddings) and synthesizes canonical `{Issue, Root Cause, Verified Resolution, Product Version}` knowledge articles rather than indexing raw back-and-forth chat noise."]}, {"id": "KP2", "description": "Hybrid RAG, Triage Routing & Tool-Augmented Agent Design: Combines grounded retrieval with live diagnostic actions.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, BM25, hybrid search, cross-encoder reranking.", "Uses historical ticket taxonomies to train or prompt an intent/urgency router (category, severity, product area, routing queue).", "Implements hybrid search (BM25 for exact error codes/SKUs + dense vector search + cross-encoder reranking) with metadata filters for product version and customer tier.", "Equips the support agent with read-only diagnostic tools (order/subscription status lookup) and human-approval gates for mutating actions (refunds, account changes)."]}, {"id": "KP3", "description": "Evaluation Golden Set Construction & Human-in-the-Loop Escalation: Benchmarks on real held-out tickets and escalates safely.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, recall, score retrieval, copilot draft.", "Constructs an offline golden evaluation benchmark from held-out resolved historical tickets to score retrieval recall, answer faithfulness, and routing accuracy.", "Deploys initially in agent-assist (copilot draft) mode for human reps before enabling autonomous customer-facing deflection on high-confidence intents.", "Triggers structured handoff to human agents (passing conversation summary, retrieved articles, and customer context) when retrieval confidence is low or user sentiment is angry."]}], "critical_failures": ["Dumps raw, unredacted historical support tickets directly into a vector store or fine-tuning dataset, causing the bot to leak other customers'' PII and repeat outdated or incorrect troubleshooting replies.", "Provides no escalation path or confidence gating when the assistant encounters novel product outages or account-specific billing disputes."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How would your solution handle an empty array, and what safeguards would you implement to prevent runtime errors?', '{"key_points": [{"id": "KP1", "description": "Upfront Guard Clauses & Safe Indexing Invariants: Prevents `IndexError`, `NullPointerException`, and `ZeroDivisionError`.", "required": true, "acceptable_evidence": ["Technical keywords: heap, IndexError, NullPointerException, ZeroDivisionError.", "Validates `if arr is None or len(arr) == 0:` at function entry before accessing `arr[0]`, `arr[-1]`, or popping from a collection/heap.", "Avoids initializing accumulators with `arr[0]` before checking emptiness, and guards mean/ratio calculations against division by `len(arr) == 0`."]}, {"id": "KP2", "description": "In two-pointer or sliding-window loops, ensures loop conditions (`left < right` or `for right in range(len(arr))`) naturally short-circuit to zero iterations on empty input.", "required": true, "acceptable_evidence": ["Technical keywords: loop short-circuiting, empty array guard clause, zero iteration boundary, defensive programming.", "In two-pointer or sliding-window loops, ensures loop conditions (`left < right` or `for right in range(len(arr))`) naturally short-circuit to zero iterations on empty input.", "Ensures pointer boundaries (left = 0, right = len(arr) - 1) and range loops naturally terminate on len(arr) == 0 without triggering IndexError."]}, {"id": "KP3", "description": "Explicit Return Contracts & Algebraic Identity Defaults: Chooses unambiguous return semantics for empty inputs.", "required": true, "acceptable_evidence": ["Technical keywords: top-k, ValueError, existential search, finding the minimum.", "Returns the mathematically sound identity element when appropriate (e.g., `0` for sum/count/max-length, `[]` for filtering/top-K, `True` for universal quantification `all()`, `False` for existential search `any()`).", "Uses explicit `Optional[T]` / `None` or raises a descriptive `ValueError(''Input array cannot be empty'')` when no valid identity exists (e.g., finding the minimum/median of an empty array), rather than returning a magic number like `-1` that collides with valid negative integers.", "Avoids mutating a shared mutable default argument (`def fn(arr=[]):`) in Python."]}, {"id": "KP4", "description": "Static Type Annotations & Boundary Unit Testing: Enforces contracts across callers and edge-case test suites.", "required": false, "acceptable_evidence": ["Technical keywords: `Sequence[int]`, `Optional[int]`, Hypothesis, arr.", "Uses static type annotations (`Sequence[int]`, `Optional[int]`) and `mypy`/compiler checks to force callers to handle nullable results.", "Includes dedicated unit tests and property-based tests (Hypothesis) covering `None`, `[]`, single-element `[x]`, all-duplicate, and nested empty `[[]]` arrays.", "Validates secondary parameters against array length (e.g., handling `k > len(arr)` or `k <= 0` safely)."]}], "critical_failures": ["Accesses `arr[0]` unconditionally on line 1 (e.g., `max_val = arr[0]`), crashing with `IndexError: list index out of range` on empty input.", "Returns an ambiguous sentinel like `0` or `-1` for a min/max function over signed integers without distinguishing it from a valid result."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'BROAD', 210, 'If there are 50,000 users using the system and it is horizontally scaled, how would you track what queries went where, and implement the explainability part?', '{"key_points": [{"id": "KP1", "description": "Distributed Context Propagation across Horizontally Scaled Nodes: Tracks every query hop via W3C Trace Context and OpenTelemetry.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, Kafka, load balancer, trace_id.", "Generates a globally unique `trace_id` and `request_id` at the API Gateway/Load Balancer and propagates W3C `traceparent` headers across all horizontally scaled stateless pods, async queues (Kafka headers), vector DB queries, and LLM gateway calls.", "Attaches structured span attributes to every hop: `user_id`, `tenant_id`, `session_id`, `pod_id`/`node_ip`, `model_version`, `prompt_template_hash`, latency, and token counts."]}, {"id": "KP2", "description": "Use non-blocking asynchronous telemetry export (OpenTelemetry Collector batching to ClickHouse / Langfuse / Arize Phoenix / Tempo) so tracing 50,000 concurrent users adds near-zero latency to the request path.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry Collector, async batch export, ClickHouse telemetry, non-blocking tracing, 50k concurrency.", "Uses non-blocking asynchronous telemetry export (OpenTelemetry Collector batching to ClickHouse / Langfuse / Arize Phoenix / Tempo) so tracing 50,000 concurrent users adds near-zero latency to the request path.", "Batches trace spans asynchronously via OpenTelemetry Collector daemonsets writing to ClickHouse, keeping tracing overhead under 1ms per request at 50,000 user concurrency."]}, {"id": "KP3", "description": "End-to-End AI Explainability & Decision Lineage: Records why a route, document, or answer was produced.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, chunk_id, doc_id, AI.", "Logs the exact decision lineage per trace: semantic router classification scores, rewritten sub-queries, retrieved `chunk_id`s with dense/BM25/reranker scores, and tool call arguments/results.", "Enforces inline source citations (`[doc_id, page, section]`) in generated responses and stores a structured provenance artifact linking each claim to its supporting context chunk."]}, {"id": "KP4", "description": "For classical/tabular ML components in the pipeline, records feature snapshot values and local feature attributions (SHAP / top contributing factors) alongside model version.", "required": false, "acceptable_evidence": ["Technical keywords: SHAP values, feature attribution snapshot, model explainability, decision provenance, audit trail.", "For classical/tabular ML components in the pipeline, records feature snapshot values and local feature attributions (SHAP / top contributing factors) alongside model version.", "Logs top-5 SHAP feature contribution values alongside model version and request ID for each prediction, providing instant audit explainability for compliance reviews."]}, {"id": "KP5", "description": "Tail-Based Sampling, Tiered Storage & Privacy-Safe Query Replay: Controls observability cost while preserving auditability.", "required": false, "acceptable_evidence": ["Technical keywords: parquet, columnar storage, S3, trace_id.", "Stores lightweight metadata and lineage indices for 100% of requests in fast columnar storage (ClickHouse) while archiving bulky raw prompt/context payloads to compressed object storage (S3/Parquet) keyed by `trace_id`.", "Uses tail-based priority sampling for deep debug traces (retaining 100% of errors, high-latency outliers, guardrail triggers, and negative user feedback).", "Redacts PII in telemetry spans and provides a deterministic trace-replay UI for engineers and compliance auditors to inspect any historical query."]}], "critical_failures": ["Logs only to local pod files (`stdout`/disk) without a correlation `trace_id`, making it impossible to reconstruct a query that hopped across load-balanced instances.", "Equates explainability with asking the LLM ''why did you say that?'' in a follow-up turn rather than recording actual retrieval scores, routing metadata, and cited source chunks."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'What design decisions led you to use polling for pull request detection, and what trade-offs did you consider?', '{"key_points": [{"id": "KP1", "description": "Architectural Drivers for Polling: Explains security/network isolation, self-healing state reconciliation, and backpressure.", "required": true, "acceptable_evidence": ["Technical keywords: VPC, CI, NAT, HTTPS.", "Explains network/security constraints: internal CI/review workers running inside a private VPC or behind corporate NAT/firewalls can make outbound HTTPS calls to GitHub/GitLab without exposing a public inbound webhook endpoint.", "Highlights reliability against dropped events: webhooks are fire-and-forget when the receiver is briefly down, whereas polling compares current remote PR head SHAs against processed state and automatically catches missed updates."]}, {"id": "KP2", "description": "Notes natural consumer-controlled backpressure: workers poll and pull at their own processing capacity rather than being overwhelmed by webhook bursts.", "required": true, "acceptable_evidence": ["Technical keywords: consumer-controlled backpressure, worker rate limit, GitHub API polling, webhook burst mitigation.", "Notes natural consumer-controlled backpressure: workers poll and pull at their own processing capacity rather than being overwhelmed by webhook bursts.", "Allows worker fleets to pull pull-request events at their own processing throughput, preventing server overload during surge hours when hundreds of PRs merge simultaneously."]}, {"id": "KP3", "description": "Trade-Off Analysis (Latency vs Rate Limits & Wasted Calls): Quantifies the downsides of polling.", "required": true, "acceptable_evidence": ["Technical keywords: GitHub, GitLab, API, PR.", "Contrasts detection latency: polling introduces a delay bounded by the poll interval (e.g., 30–60s average lag) compared to sub-second push webhooks.", "Identifies GitHub/GitLab API rate-limit consumption (e.g., 5,000 req/hr per token) and wasted empty polls during idle off-hours across many repositories.", "Addresses duplicate processing risks if polling interval is shorter than PR analysis duration without state locking."]}, {"id": "KP4", "description": "Polling Optimizations & Hybrid Evolution: Uses conditional HTTP headers, cursor watermarks, and webhook reconciliation.", "required": false, "acceptable_evidence": ["Technical keywords: GraphQL, updated_since, pr_number, head_sha.", "Uses HTTP conditional requests (`If-None-Match` / `ETag` or `If-Modified-Since`) which return `304 Not Modified` without consuming GitHub primary rate-limit quota.", "Queries with `updated_since` watermarks or GraphQL batched repo queries, and tracks `(pr_number, head_sha)` in a database to trigger jobs only when the commit SHA actually changes.", "Proposes the production gold standard: event-driven webhooks for instant low-latency triggers paired with a periodic slow reconciliation poller (e.g., every 10 min, ArgoCD style) to heal missed events."]}], "critical_failures": ["Claims polling is always faster and more real-time than webhooks without acknowledging polling interval latency or API rate limits.", "Re-runs expensive CI/AI review pipelines on every poll tick without checking whether the PR''s `head_sha` has already been processed."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What guardrails and security measures did you implement to handle untrusted user input and sensitive data?', '{"key_points": [{"id": "KP1", "description": "Input Sanitization & Structural Prompt Isolation: Defends against direct and indirect prompt injection.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, prompt injection, jailbreak, indirect prompt injection.", "Enforces strict request validation at the API boundary: payload size/token caps, Unicode normalization, stripping invisible control characters, and escaping delimiter tags.", "Isolates untrusted user inputs and retrieved external documents inside explicit structural delimiters (e.g., `<untrusted_user_input>...</untrusted_user_input>`) separated from privileged system instructions.", "Screens inputs and retrieved RAG chunks with prompt-injection/jailbreak classifiers (Llama Guard, Prompt Guard, NeMo Guardrails) before model invocation."]}, {"id": "KP2", "description": "Bidirectional PII/Secret Redaction & Data-Layer Access Control: Prevents sensitive data ingestion or exfiltration.", "required": true, "acceptable_evidence": ["Technical keywords: Microsoft Presidio, RBAC, ABAC, PII.", "Redacts or masks sensitive PII and credentials (SSNs, API keys, credit cards, emails) using Microsoft Presidio / NER + regex on both incoming prompts and outgoing LLM completions.", "Enforces tenant and role-based access control (RBAC/ABAC) via database/vector pre-filtering so unauthorized sensitive data never enters the prompt context.", "Scrubs sensitive fields from application logs, traces, and error telemetry before export."]}, {"id": "KP3", "description": "Governed Tool Execution & Output Validation: Prevents untrusted input from triggering unauthorized side effects.", "required": false, "acceptable_evidence": ["Technical keywords: Pydantic, user_id, LLM, SQL.", "Validates LLM-generated tool arguments against strict Pydantic schemas, parameterized SQL queries (never raw LLM SQL execution), and allowlisted URLs to prevent SSRF/command injection.", "Binds tool permissions to the authenticated user''s cryptographic session token rather than letting the LLM choose the `user_id` parameter.", "Blocks markdown image/link rendering to untrusted external domains in the chat UI to prevent silent data exfiltration via image URL query strings."]}], "critical_failures": ["Concatenates raw untrusted user input directly into privileged system prompts or executes LLM-generated SQL/shell commands without parameterization or sandboxing.", "Assumes retrieved third-party documents/emails are trusted and fails to guard against indirect prompt injection."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What guardrails did you implement to ensure compliance, security, and safe outputs in a healthcare domain?', '{"key_points": [{"id": "KP1", "description": "Clinical Groundedness & Zero-Hallucination Verification: Ensures medical facts and numbers strictly match source records.", "required": true, "acceptable_evidence": ["Technical keywords: groundedness, temperature, EHR, NLI.", "Restricts generation strictly to retrieved authoritative clinical guidelines or the patient''s verified EHR context (`temperature=0`, extractive/citation-mandated prompting).", "Runs automated NLI/entailment faithfulness checks and deterministic entity verification (checking that medication names, dosages, lab values, and allergies in the output appear verbatim in the source context).", "Blocks and replaces any response that fabricates clinical citations, alters dosage units, or contradicts documented patient allergies/contraindications."]}, {"id": "KP2", "description": "Clinical Scope Guardrails & Emergency Red-Flag Escalation: Prevents unauthorized medical diagnosis and handles acute risk.", "required": true, "acceptable_evidence": ["Technical keywords: LLM, FDA, CDS, AI.", "Implements pre-inference red-flag classifiers for acute medical emergencies (chest pain, stroke symptoms, self-harm/suicidal ideation) that immediately bypass the LLM and display deterministic emergency instructions (911/988/on-call clinician).", "Enforces regulatory scope rails (FDA CDS / clinical policy) preventing the assistant from issuing definitive autonomous diagnoses or prescribing treatments to patients.", "Requires clinician-in-the-loop review and sign-off before AI-drafted clinical summaries or patient messages are committed to the medical record."]}, {"id": "KP3", "description": "HIPAA Output Sanitization & Auditable Traceability: Prevents PHI leakage and logs full clinical provenance.", "required": false, "acceptable_evidence": ["Technical keywords: HIPAA, PHI, EHR, BAA.", "Verifies patient identity binding at retrieval and output layers so another patient''s PHI can never appear in the response.", "Attaches clickable inline citations to specific EHR note IDs or peer-reviewed clinical guidelines for rapid physician verification.", "Logs immutable compliance records (model version, prompt hash, retrieved chunk IDs, guardrail pass/fail results) under a HIPAA BAA boundary."]}], "critical_failures": ["Allows unconstrained creative LLM generation for medication dosages or clinical advice without strict source-entailment verification.", "Fails to intercept acute emergency/self-harm queries with a deterministic escalation path."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'BROAD', 150, 'What is the difference between open-source and closed-source models, and how does that impact your design decisions?', '{"key_points": [{"id": "KP1", "description": "Control, Data Residency & Customization vs Frontier Capability: Contrasts self-hosted weight control with managed APIs.", "required": true, "acceptable_evidence": ["Technical keywords: vLLM, LoRA, QLoRA, VPC.", "Explains that open-weights models allow full VPC/air-gapped deployment, pinned immutable model weights (zero surprise vendor deprecations), deep customization (LoRA/QLoRA, custom tokenizers, logit/constrained decoding via vLLM/TGI), and predictable tail latency.", "Explains that closed frontier APIs provide state-of-the-art zero-shot reasoning, massive context windows, multimodal capabilities, and zero GPU infrastructure ops overhead for fast time-to-market."]}, {"id": "KP2", "description": "Distinguish truly permissive open-source licenses (Apache 2.0 / MIT) from restricted open-weights community licenses (Llama commercial thresholds or non-commercial research clauses).", "required": true, "acceptable_evidence": ["Technical keywords: Apache 2.0 license, Llama community license, commercial thresholds, open-weights governance, vendor lock-in.", "Distinguishes truly permissive open-source licenses (Apache 2.0 / MIT) from restricted open-weights community licenses (Llama commercial thresholds or non-commercial research clauses).", "Analyzes licensing constraints, distinguishing truly permissive Apache 2.0 open-source code from open-weights models (e.g. Llama''s 700M monthly active user threshold)."]}, {"id": "KP3", "description": "Unit Economics & Infrastructure Trade-Offs: Analyzes pay-per-token vs dedicated GPU utilization breakeven.", "required": true, "acceptable_evidence": ["Technical keywords: TensorRT-LLM, quantization, AWQ, unit economics.", "Analyzes cost structure: closed APIs charge variable cost per input/output token (cheaper at low/spiky volume), whereas self-hosted open models incur fixed hourly GPU costs (A100/H100) that become significantly cheaper only above sustained high throughput utilization.", "Accounts for the hidden engineering TCO of self-hosting: vLLM/TensorRT-LLM serving, KV-cache management, quantization (FP8/AWQ), autoscaling cold starts, and multi-AZ failover.", "Evaluates latency trade-offs: small distilled/quantized open models (7B–14B) hosted locally achieve sub-100ms latency for classification/extraction compared to remote frontier API calls."]}, {"id": "KP4", "description": "Hybrid Model Routing & Model-Agnostic Abstraction: Designs systems that combine both paradigms cleanly.", "required": false, "acceptable_evidence": ["Technical keywords: DPO, PII, custom router, standardized schemas.", "Implements a model gateway / unified abstraction layer (LiteLLM / custom router) with standardized schemas so prompts and tools are decoupled from a single vendor.", "Uses tiered routing: sends high-volume classification, reranking, embedding, and PII extraction to fast open models while routing complex multi-step reasoning to frontier closed models.", "Uses frontier closed models as teacher/judge models to generate synthetic datasets or DPO pairs to fine-tune smaller open student models."]}], "critical_failures": ["Assumes self-hosting an open-source 70B+ model on dedicated GPUs is always cheaper than commercial APIs regardless of request volume or GPU idle time.", "Hardcodes vendor-specific SDK payloads across the entire codebase without a model routing abstraction or evaluation benchmark."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'BROAD', 150, 'What responsible AI practices did you implement to ensure compliance, security, and safe usage of generative AI systems?', '{"key_points": [{"id": "KP1", "description": "Counterfactual Bias Auditing & Pre-Deployment Red-Teaming: Tests systematically for demographic skew and harmful behaviors.", "required": true, "acceptable_evidence": ["Technical keywords: jailbreak, OWASP, LLM, Garak.", "Conducts counterfactual fairness evaluations (e.g., perturbing gender, ethnicity, age, or socioeconomic indicators in test prompts/resumes to verify scoring and tone parity).", "Runs automated adversarial red-teaming suites (Garak, Promptfoo, OWASP LLM Top 10 benchmarks) testing for bias, hate speech, self-harm, and jailbreak susceptibility before release."]}, {"id": "KP2", "description": "Strips protected demographic attributes or proxy variables when ranking or scoring candidates/customers.", "required": true, "acceptable_evidence": ["Technical keywords: demographic parity, protected attribute removal, proxy feature detection, disparate impact analysis.", "Strips protected demographic attributes or proxy variables when ranking or scoring candidates/customers.", "Strips protected attributes (race, gender, age) and audits proxy variables (ZIP code, school names) to enforce disparate impact ratios above 0.80 across candidate rankings."]}, {"id": "KP3", "description": "Transparency, Source Provenance & Human-in-the-Loop Agency: Prevents deceptive automation and unchecked high-risk actions.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, HITL, NIST, RMF.", "Clearly discloses to end users when they are interacting with AI-generated content and surfaces verifiable source citations and uncertainty indicators.", "Classifies workflows by risk tier (aligned with NIST AI RMF / EU AI Act) and enforces mandatory Human-in-the-Loop (HITL) approval for consequential decisions (hiring, credit, medical, legal, destructive actions).", "Provides accessible user feedback, dispute/appeal mechanisms, and one-click escalation to a human representative."]}, {"id": "KP4", "description": "Data Governance, Model Cards & Kill-Switch Operations: Maintains regulatory documentation and operational control.", "required": false, "acceptable_evidence": ["Technical keywords: RAG, GDPR, data governance, licensing compliance.", "Verifies training/RAG data provenance, copyright/licensing compliance, and user opt-out / GDPR right-to-be-forgotten policies.", "Maintains versioned Model/System Cards documenting intended use cases, known failure modes, evaluation metrics, and guardrail thresholds.", "Implements production drift monitors and an immediate feature-flag kill switch to roll back or disable generative features if safety metrics degrade."]}], "critical_failures": ["Treats Responsible AI as a purely philosophical mission statement without implementing concrete bias tests, HITL gates, or audit logs.", "Allows fully autonomous AI decision-making in high-stakes domains (hiring, lending, healthcare) without human oversight or bias auditing."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What security and guardrail mechanisms did you implement for enterprise readiness?', '{"key_points": [{"id": "KP1", "description": "Enterprise Identity (SSO/RBAC) & Multi-Tenant Data Isolation: Enforces strict cryptographic tenant and document boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: RBAC, OIDC, JWT, tenant_id.", "Integrates enterprise SSO (SAML 2.0 / OIDC via Okta/Entra ID) and propagates verified JWT claims (`tenant_id`, `user_id`, `groups`) to every microservice and retrieval query.", "Enforces hard multi-tenant isolation across databases and vector stores (dedicated tenant namespaces/partitions + mandatory pre-filtering on document ACLs).", "Guarantees zero cross-tenant cache pollution in semantic/exact caches by keying all cache entries with `tenant_id` and ACL scope."]}, {"id": "KP2", "description": "Private Model Connectivity, Zero Data Retention & Runtime Guardrails: Protects corporate IP and controls model behavior.", "required": true, "acceptable_evidence": ["Technical keywords: Zero Data Retention, ZDR, IP, LLM.", "Routes LLM traffic over private cloud backbones (AWS PrivateLink / Azure Private Endpoints / VPC-hosted models) under enterprise Zero Data Retention (ZDR) contracts guaranteeing customer data is never used for model training.", "Deploys centralized AI Gateway guardrails: PII/secret DLP scanning, prompt-injection defense, and tool-execution allowlists.", "Enforces per-tenant and per-user token budgets, rate limits, and cost quotas to prevent runaway spend or denial-of-wallet attacks."]}, {"id": "KP3", "description": "SOC2/ISO Compliance Auditing, KMS Encryption & Admin Controls: Provides enterprise governance visibility.", "required": false, "acceptable_evidence": ["Technical keywords: TLS 1.3, Datadog, REST, ISO.", "Supports customer-managed encryption keys (CMEK / BYOK via KMS) for data at rest and TLS 1.3 in transit.", "Exports immutable, tamper-evident audit logs (who queried what, which documents were cited, which tools executed) to the customer''s SIEM (Splunk/Datadog).", "Provides tenant administrators with configurable retention policies, guardrail sensitivity toggles, and data purge APIs."]}], "critical_failures": ["Stores multiple enterprise customers'' embeddings in a shared index without tenant partitioning or mandatory `tenant_id` pre-filtering.", "Uses consumer-tier LLM API keys where enterprise prompts may be retained by the vendor for model training."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What strategies have you used to implement guardrails for security and compliance in AI systems?', '{"key_points": [{"id": "KP1", "description": "Tiered Latency-Aware Guardrail Cascade: Orders checks from sub-millisecond deterministic rules to neural classifiers.", "required": true, "acceptable_evidence": ["Technical keywords: asyncio, asyncio.gather, Pydantic, RAG.", "Designs a multi-tier cascade: Tier 1 runs sub-5ms deterministic checks (regex PII/secret scanners, blocklists, length/schema validation, RBAC checks); Tier 2 runs 15–40ms specialized encoder/safety models (Presidio NER, DeBERTa/Llama Guard); Tier 3 runs heavy LLM-as-a-judge checks only when needed or asynchronously.", "Executes independent input guardrails and RAG retrieval concurrently via `asyncio.gather` so safety checks add minimal wall-clock overhead to p95 latency.", "Uses grammar-constrained decoding / structured outputs (JSON Schema / Pydantic) so outputs cannot deviate from compliant structural formats."]}, {"id": "KP2", "description": "Decoupled Policy-as-Code & Deterministic Execution Sandboxes: Separates compliance rules from model prompts.", "required": true, "acceptable_evidence": ["Technical keywords: AI, OPA, NeMo, LLM.", "Centralizes guardrail policies in an AI Gateway or declarative policy-as-code layer (OPA / NeMo Colang / Guardrails AI validators) so compliance rules are versioned and updated independently of application services.", "Enforces hard business invariants (e.g., refund limits, prohibited jurisdictions, regulatory disclosures) in deterministic post-processing code rather than relying on probabilistic LLM adherence.", "Defines explicit remediation strategies per rule (`BLOCK`, `REDACT`, `REWRITE`, `ESCALATE_TO_HUMAN`, or `LOG_ONLY` shadow mode)."]}, {"id": "KP3", "description": "Shadow Deployment Calibration & CI/CD Regression Gates: Validates precision/recall of guardrails before enforcing blocks.", "required": false, "acceptable_evidence": ["Technical keywords: precision, recall, OpenTelemetry, CI/CD.", "Deploys new compliance guardrails in shadow mode (`LOG_ONLY`) first to measure false-positive refusal rates on real traffic before enabling hard blocking.", "Maintains a versioned benchmark of adversarial attacks and benign look-alike prompts in CI/CD, failing builds if guardrail recall drops or false-positive rate spikes.", "Monitors production guardrail trigger rates and latency overhead per rail via OpenTelemetry dashboards."]}], "critical_failures": ["Implements every guardrail as a sequential full frontier-LLM prompt call, multiplying inference cost and latency by 3x–5x.", "Encodes regulatory compliance rules exclusively inside natural-language system prompts with no deterministic code verification."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'Are you using mostly proprietary LLMs or are you using other models?', '{"key_points": [{"id": "KP1", "description": "Right-Sized Polyglot Model Selection: Matches task complexity to frontier LLMs, open SLMs, encoders, or classical ML.", "required": true, "acceptable_evidence": ["Technical keywords: XGBoost, LightGBM, ML, GPT.", "Uses proprietary frontier LLMs (e.g., Claude 3.5/3.7 Sonnet, GPT-4o, Gemini 1.5 Pro) for complex multi-step reasoning, agent orchestration, synthesis, and synthetic eval generation.", "Pairs them with specialized non-generative models across the pipeline: bi-encoders (BGE/text-embedding-3) for retrieval, cross-encoders (BGE-Reranker) for reranking, NER/DeBERTa classifiers for fast guardrails/routing, and layout models (Docling) for document parsing.", "Uses fine-tuned open-weights SLMs (Llama-3 8B, Qwen 7B, Mistral) or classical gradient-boosted trees (XGBoost/LightGBM) for high-QPS, low-latency classification, extraction, or tabular scoring where frontier LLMs are overkill."]}, {"id": "KP2", "description": "Quantitative Routing & Cost/Latency/Privacy Justification: Explains the engineering metrics behind model placement.", "required": true, "acceptable_evidence": ["Technical keywords: unit economics, LLM, quantitative routing, engineering metrics.", "Justifies model selection using concrete trade-offs: latency budgets (15ms encoder vs 2s frontier LLM), token unit economics at scale, and data privacy/residency constraints.", "Implements complexity or confidence-based routing (sending 70–80% of routine queries to fast/cheap models and escalating hard queries to frontier models).", "Benchmarks candidate models on task-specific golden evaluation sets before swapping or adopting a model."]}, {"id": "KP3", "description": "Multi-Provider Failover & Unified Gateway Abstraction: Avoids single-vendor lock-in and outage downtime.", "required": false, "acceptable_evidence": ["Technical keywords: vendor lock, custom router, output schema, LiteLLM.", "Abstracts model calls behind a unified gateway interface (LiteLLM / custom router) with automatic cross-provider failover (e.g., OpenAI <-> Anthropic / Bedrock / Vertex) during regional rate-limit or outage events.", "Maintains model-specific prompt adapters and regression tests so fallback models preserve output schema contracts.", "Monitors per-model token spend, latency percentiles, and quality drift in production."]}], "critical_failures": ["Uses a single flagship frontier LLM for every trivial task (embeddings, keyword routing, tabular prediction, regex-level extraction) without considering latency or cost.", "Cannot explain why specific model families were chosen for different stages of their system architecture."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'HARD', 'BROAD', 210, 'As the internal AI expert for the firm, how do you keep up-to-date with the rapidly changing AI landscape, and what methods do you use to guide attorneys on AI best practices and prompt writing?', '{"key_points": [{"id": "KP1", "description": "Disciplined AI Landscape Tracking & Legal-Specific Sandbox Benchmarking: Filters hype via empirical legal evaluations.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, golden dataset, ZDR, AI.", "Maintains a structured intelligence pipeline tracking frontier model releases, legal-tech benchmarks (LegalBench), RAG/agentic research, and bar association ethics opinions on AI.", "Evaluates new models and vendor tools in a sandboxed environment against an internal legal golden dataset (contract clause extraction, deposition summarization, issue spotting, multi-doc synthesis) measuring hallucination rate, citation accuracy, latency, and security posture (ZDR/SOC2) before recommending firm adoption."]}, {"id": "KP2", "description": "Separates durable capability breakthroughs from vendor marketing claims through blind side-by-side outputs reviewed by practice-group attorneys.", "required": true, "acceptable_evidence": ["Technical keywords: blind side-by-side evaluation, legal domain benchmarking, attorney review panel, model hallucination audit.", "Separates durable capability breakthroughs from vendor marketing claims through blind side-by-side outputs reviewed by practice-group attorneys.", "Runs blind side-by-side output evaluations where senior partners rate legal draft quality and statutory accuracy between frontier models without knowing model identities."]}, {"id": "KP3", "description": "Attorney Enablement, Structured Prompt Frameworks & Reusable Libraries: Translates prompt engineering into practical legal workflows.", "required": true, "acceptable_evidence": ["Technical keywords: IRAC, NDA, authoritative grounding, attached exhibits.", "Teaches attorneys structured prompting frameworks tailored to legal work: defining Role/Jurisdiction, supplying authoritative Grounding Context (attached exhibits/statutes), specifying Task & Analytical Standard (e.g., IRAC format, counterparty risk posture), and enforcing Output Constraints (table of redlines, exact pinpoint citations, ''state if not found in record'').", "Builds and curates a version-controlled, practice-group-specific Prompt & Workflow Library (M&A due diligence, litigation chronology extraction, NDA markup) embedded directly in the firm''s internal AI portal."]}, {"id": "KP4", "description": "Runs hands-on workshops, office hours, and ''before vs after'' live redlining clinics using anonymized matter documents rather than abstract theory.", "required": false, "acceptable_evidence": ["Technical keywords: interactive prompt clinic, matter document redlining, few-shot legal templates, practical attorney enablement.", "Runs hands-on workshops, office hours, and ''before vs after'' live redlining clinics using anonymized matter documents rather than abstract theory.", "Leads interactive hands-on redlining clinics with real anonymized matter briefs, showing attorneys how few-shot citations and structured prompt constraints eliminate hallucinations."]}, {"id": "KP5", "description": "Privilege Protection, Hallucination Verification & Ethical Governance: Enforces professional responsibility and duty of supervision.", "required": false, "acceptable_evidence": ["Technical keywords: ZDR, LLM, ABA, ethical governance.", "Establishes non-negotiable governance rules: strictly prohibiting use of unapproved public AI tools with client-confidential or attorney-client privileged material, enforcing firm-approved ZDR enterprise environments.", "Trains attorneys on LLM failure modes (fabricated case citations like Mata v. Avianca, sycophancy, subtle statutory misquoting) and mandates independent citation/record verification under ABA Model Rules (competence & supervisory duties).", "Collects attorney feedback and failure cases to iteratively refine firm system prompts, RAG connectors, and training playbooks."]}], "critical_failures": ["Advises attorneys to rely on ungrounded LLM memory for case-law citations without RAG grounding or mandatory primary-source verification.", "Adopts new AI tools based on social media hype without testing client-confidentiality/privilege protections or benchmarking on actual legal tasks."]}', 1);
